var e={"nav.overview":`Επισκόπηση`,"nav.collector":`Συλλέκτης συνδέσμων`,"nav.downloads":`Λήψεις`,"nav.instances":`Στιγμιότυπα`,"nav.accounts":`Λογαριασμοί`,"settings.accounts.setupTitle":`Πλαϊνή γραμμή`,"settings.accounts.showInSidebar":`Εμφάνιση και στην πλαϊνή γραμμή`,"settings.accounts.showInSidebarHint":`Αυτή η καρτέλα και η καταχώριση Λογαριασμοί στην πλαϊνή γραμμή δείχνουν την ίδια σελίδα. Απενεργοποίησέ το αν σου φαίνεται περιττό να υπάρχουν και τα δύο.`,"settings.instances.showInSidebarHint":`Αυτή η καρτέλα και η καταχώριση Στιγμιότυπα στην πλαϊνή γραμμή δείχνουν την ίδια σελίδα. Απενεργοποίησέ το αν σου φαίνεται περιττό να υπάρχουν και τα δύο ή αν τρέχεις μόνο ένα στιγμιότυπο.`,"settings.instances.showInSidebar":`Εμφάνιση και στην πλαϊνή γραμμή`,"settings.instances.setupTitle":`Πλαϊνή γραμμή`,"settings.nav.instances":`Στιγμιότυπα`,"nav.settings":`Ρυθμίσεις`,"nav.workingTitle":`προσωρινός τίτλος`,"theme.dark":`Σκούρο`,"theme.light":`Ανοιχτό`,"theme.toggle":`Εναλλαγή θέματος`,"lang.label":`Γλώσσα`,"lang.open":`Αλλαγή γλώσσας`,"lang.close":`Κλείσιμο επιλογέα γλώσσας`,"status.collected":`Συλλεγμένο`,"status.queued":`Σε αναμονή`,"status.running":`Γίνεται λήψη`,"status.paused":`Σε παύση`,"status.extracting":`Αποσυμπίεση`,"status.done":`Ολοκληρώθηκε`,"status.error":`Σφάλμα`,"task.pause":`Παύση`,"task.resume":`Συνέχιση`,"task.start":`Έναρξη`,"task.restart":`Επανεκκίνηση`,"task.remove":`Αφαίρεση`,"task.left":`απομένουν`,"task.file":`αρχείο`,"task.files":`αρχεία`,"task.ungrouped":`Χωρίς ομάδα`,"task.reason.gone":`Δεν υπάρχει πια`,"task.reason.auth":`Απαιτείται σύνδεση`,"task.reason.limit":`Όριο του hoster`,"task.reason.unavailable":`Ο hoster δεν απαντά`,"task.reason.network":`Δίκτυο`,"task.reason.diskFull":`Γεμάτος δίσκος`,"task.reason.unsupported":`Χωρίς μηχανή`,"task.reason.captcha":`Captcha`,"task.reason.cancelled":`Ακυρώθηκε`,"task.reason.unknown":`Χωρίς κατηγορία`,"overview.title":`Επισκόπηση`,"overview.totalSpeed":`Συνολική ταχύτητα λήψης`,"overview.active":`Ενεργά`,"overview.queued":`Σε αναμονή`,"overview.inCollector":`Στον συλλέκτη`,"overview.done":`Ολοκληρωμένα`,"overview.errors":`Σφάλματα`,"overview.recent":`Πρόσφατα`,"overview.noDownloads":`Δεν υπάρχουν λήψεις ακόμη.`,"overview.instances":`Στιγμιότυπα`,"overview.idle":`αδρανές`,"common.loading":`Φόρτωση…`,"common.loadFailed":`Δεν ήταν δυνατή η φόρτωση. Είναι προσβάσιμος ο διακομιστής;`,"common.retry":`Δοκιμάστε ξανά`,"hint.collector.title":`Οι σύνδεσμοι προετοιμάζονται εδώ, δεν έχουν κατέβει ακόμη`,"hint.collector.body":`Ό,τι προσθέτεις καταλήγει πρώτα σε αυτόν τον συλλέκτη, όπου μπορείς να ελέγξεις ονόματα και μεγέθη πριν ξεκινήσει οτιδήποτε. Ξεκίνησέ το από εδώ, ή ενεργοποίησε την αυτόματη έναρξη στις ρυθμίσεις αν δεν θέλεις ποτέ αυτή την παύση.`,"hint.downloads.title":`Τι εκτελείται πραγματικά`,"hint.downloads.body":`Αυτή είναι η ουρά μεταφορών: οι σύνδεσμοι που έχεις ξεκινήσει, είτε εκτελούνται, είτε περιμένουν τη σειρά τους, είτε έχουν ήδη ολοκληρωθεί. Ό,τι έχεις απλώς ετοιμάσει στον συλλέκτη δεν εμφανίζεται ακόμα εδώ.`,"empty.downloadsTitle":`Δεν κατεβαίνει τίποτα ακόμη`,"empty.downloadsHint":`Προσθέστε συνδέσμους στον συλλέκτη και μετά ξεκινήστε τους.`,"collector.title":`Συλλέκτης`,"collector.listTitle":`Λίστα συνδέσμων`,"collector.placeholder":`Επικόλλησε συνδέσμους, ένα URL ανά γραμμή, ή άφησέ τους εδώ…  (Ctrl+Enter για προσθήκη)`,"collector.package":`Πακέτο (προαιρετικό)`,"collector.add":`Προσθήκη συνδέσμων`,"collector.addTitle":`Συλλέκτης συνδέσμων`,"collector.empty":`Ο συλλέκτης είναι άδειος. Επικολλήστε συνδέσμους παραπάνω για να ετοιμαστούν.`,"collector.startSelected":`Έναρξη επιλεγμένων`,"collector.startAll":`Έναρξη όλων`,"collector.toastStaged":`Ετοιμάστηκαν {n} σύνδεσμοι`,"collector.toastSkipped":`Ετοιμάστηκαν {n} σύνδεσμοι, {skipped} ήταν ήδη γνωστοί`,"collector.toastNone":`Δεν βρέθηκαν έγκυροι σύνδεσμοι`,"collector.toastStarted":`Ξεκίνησαν {n} λήψεις`,"collector.toastStartDisabled":`{n} σύνδεσμοι είναι απενεργοποιημένοι και δεν ξεκίνησαν.`,"collector.toastStartedSomeDisabled":`{n} ξεκίνησαν, {disabled} απενεργοποιημένα.`,"collector.toastStartBlocked":`Η ουρά είναι σε παύση λόγω χρονοδιαγράμματος.`,"collector.selectAll":`Επιλογή όλων`,"collector.movePrompt":`Σε ποιο πακέτο να μετακινηθούν οι επιλεγμένοι σύνδεσμοι;`,"downloads.title":`Λήψεις`,"downloads.listTitle":`Λίστα λήψεων`,"downloads.thisInstance":`Αυτό το στιγμιότυπο`,"downloads.pauseAll":`Παύση όλων`,"downloads.resumeAll":`Συνέχιση όλων`,"downloads.retryFailed":`Επανάληψη αποτυχημένων`,"downloads.retryCause":`Δοκιμή ξανά για τις {n} με αυτή την αιτία: {reason}`,"downloads.clearFinished":`Καθαρισμός ολοκληρωμένων`,"downloads.noMatch":`Τίποτα δεν ταιριάζει με το φίλτρο.`,"downloads.finished":`Το {name} ολοκληρώθηκε`,"downloads.failed":`Το {name} απέτυχε`,"instances.title":`Στιγμιότυπα`,"instances.moduleOff":`Τα αδελφά στιγμιότυπα είναι απενεργοποιημένα, οπότε αυτό το στιγμιότυπο ούτε εμφανίζει τα άλλα ούτε επικοινωνεί μαζί τους.`,"instances.thisInstance":`Αυτό το στιγμιότυπο`,"instances.foundTitle":`Βρέθηκαν στο δίκτυό σας`,"instances.foundHint":`Στιγμιότυπα KnightLoader που ανακοινώνουν την παρουσία τους σε αυτό το δίκτυο. Τίποτα δεν συνδέεται μέχρι να προσθέσεις κάποιο, και η προσθήκη απλώς αποθηκεύει τη διεύθυνσή του. Το να βρίσκεσαι στο ίδιο δίκτυο δεν μετράει ως άδεια. Ένα στιγμιότυπο με κωδικό πρόσβασης χρειάζεται επιπλέον κωδικό σύζευξης πριν δεχτεί οτιδήποτε.`,"instances.foundAdd":`Προσθήκη`,"instances.foundKnown":`ήδη προστέθηκε`,"instances.connectButton":`Σύνδεση στιγμιότυπου`,"instances.connectWhere":`Πρόσθεσε ή κάνε σύζευξη με ένα ακόμη KnightLoader στη σελίδα Απομακρυσμένη πρόσβαση.`,"instances.offlineWarning":`Προστέθηκε, αλλά το στιγμιότυπο δεν απάντησε (εκτός σύνδεσης;).`,"instances.open":`Άνοιγμα`,"instances.online":`Σε σύνδεση`,"instances.refused":`Άρνηση`,"instances.refusedByPassword":`Είναι προσβάσιμο, αλλά απέρριψε αυτό το στιγμιότυπο επειδή το ίδιο έχει ορίσει κωδικό πρόσβασης. Δώσε και στα δύο την ίδια φράση σύνδεσης στη σελίδα Απομακρυσμένη πρόσβαση και θα εμπιστεύονται το ένα το άλλο.`,"instances.offline":`Εκτός σύνδεσης`,"instances.viaRelay":`Συνδέθηκε μέσω αναμεταδότη`,"instances.metricActive":`Ενεργά`,"instances.metricTasks":`Εργασίες`,"instances.metricSpeed":`Ταχύτητα`,"instances.removeTitle":`Αφαίρεση {name}`,"accounts.title":`Λογαριασμοί`,"accounts.connected":`Συνδεδεμένο`,"accounts.saved":`Αποθηκεύτηκε.`,"accounts.keyLabel":`Κλειδί API για {service}`,"accounts.keyHint":`Ισχύει αμέσως· αποθηκεύεται κρυπτογραφημένο σε αυτό το στιγμιότυπο.`,"accounts.placeholder":`Επικολλήστε το κλειδί σας…`,"settings.title":`Ρυθμίσεις`,"settings.maxConcurrent":`Ταυτόχρονες λήψεις`,"settings.maxConcurrentHint":`Πόσες λήψεις τρέχουν ταυτόχρονα. Οι υπόλοιπες περιμένουν τη σειρά τους.`,"settings.maxPerHost":`Ταυτόχρονες λήψεις ανά πάροχο`,"settings.maxPerHostHint":`Το ανώτατο όριο για έναν πάροχο, πέρα από το σύνολο παραπάνω. Οι περισσότεροι επιτρέπουν ελάχιστες ταυτόχρονα.`,"settings.speedHint":`Το όριο για όλες τις λήψεις μαζί, που ισχύει όσο εκτελούνται.`,"settings.autoStart":`Άμεση έναρξη των συνδέσμων που προστίθενται`,"settings.autoStartHint":`Οι σύνδεσμοι που προσθέτεις αρχίζουν να κατεβαίνουν χωρίς να περιμένουν να τους επιβεβαιώσεις στον συλλέκτη. Πόσο περιμένουν πρώτα το ορίζει η αντίστροφη μέτρηση πιο κάτω, στην ενότητα Συλλέκτης.`,"settings.save":`Αποθήκευση`,"settings.saved":`Αποθηκεύτηκε.`,"settings.downloadDir":`Φάκελος λήψεων`,"settings.downloadDirHint":`Απόλυτη διαδρομή. Αφήστε το κενό για τον ενσωματωμένο φάκελο.`,"settings.subfolderByPackage":`Κάθε πακέτο σε δικό του υποφάκελο`,"settings.maxRetries":`Αυτόματες επαναλήψεις`,"settings.resumeOnStart":`Μετά από επανεκκίνηση`,"settings.resumeOnStartHint":`Μια μεταφορά που ξεκινά ξανά αρχίζει από την αρχή, και το ήδη υπάρχον μερικό αρχείο συναντά τον κανόνα σύγκρουσης. Γι’ αυτό η προσεκτική ρύθμιση είναι η προεπιλογή.`,"settings.resume.never":`Τίποτα`,"settings.resume.running":`Ό,τι εκτελούνταν`,"settings.resume.all":`Ό,τι δεν ολοκληρώθηκε`,"settings.keepFinishedDays":`Διατήρηση ολοκληρωμένων (ημέρες)`,"settings.keepFinishedDaysHint":`Το 0 τα κρατά στη λίστα για πάντα. Το αρχείο στον δίσκο δεν αγγίζεται και το ιστορικό κρατά την εγγραφή.`,"settings.historyMax":`Εγγραφές ιστορικού`,"settings.historyMaxHint":`Το 0 κρατά κάθε εγγραφή.`,"settings.maxRetriesHint":`Μια αποτυχημένη λήψη επαναλαμβάνεται με αυξανόμενη καθυστέρηση.`,"settings.archivePasswords":`Κωδικοί αρχείων`,"settings.archivePasswordsHint":`Ένας ανά γραμμή. Δοκιμάζονται με τη σειρά όταν ένα αρχείο είναι κρυπτογραφημένο.`,"settings.lockOn":`Έχει οριστεί κωδικός.`,"settings.lockOff":`Δεν έχει οριστεί κωδικός πρόσβασης.`,"settings.lockHint":`Προστατεύει αυτό το στιγμιότυπο από οποιονδήποτε μπορεί να το προσεγγίσει: στο ίδιο δίκτυο, μέσω domain ή μέσω relay. Μόλις οριστεί, πρέπει να εισαχθεί προτού ανοίξει καν αυτό το στιγμιότυπο, για οποιονδήποτε, ακόμη και για εσάς την επόμενη φορά. Χωρίς κωδικό, όποιος βρει τη διεύθυνση μπορεί να δει κάθε λήψη και να προσθέσει, να θέσει σε παύση ή να διαγράψει δικές του.`,"settings.passwordCurrent":`Τρέχων κωδικός`,"settings.passwordNew":`Νέος κωδικός`,"settings.passwordHint":`Τουλάχιστον 8 χαρακτήρες. Αφήστε το κενό για να αφαιρέσετε το κλείδωμα.`,"settings.setPassword":`Ορισμός κωδικού`,"settings.passwordSaved":`Ο κωδικός ενημερώθηκε.`,"auth.title":`Αυτό το στιγμιότυπο είναι κλειδωμένο`,"auth.password":`Κωδικός`,"auth.signIn":`Σύνδεση`,"auth.signOut":`Αποσύνδεση`,"auth.wrong":`Λάθος κωδικός.`,"accounts.ok":`Λειτουργεί`,"accounts.failed":`Δεν λειτουργεί`,"accounts.unchecked":`Δεν ελέγχθηκε`,"accounts.hosts":`υποστηριζόμενοι πάροχοι`,"task.recheck":`Νέος έλεγχος`,"task.online":`Διαθέσιμο`,"task.offline":`Μη διαθέσιμο`,"task.retryPending":`Θα επαναληφθεί αυτόματα`,"task.forced":`Ορίστηκε «Έναρξη τώρα»`,"task.held":`Σε αναμονή`,"task.folder":`Φάκελος`,"task.password":`Κωδικός αρχείου`,"task.priorityUp":`Αύξηση προτεραιότητας`,"task.priorityDown":`Μείωση προτεραιότητας`,"task.moveTop":`Μετακίνηση στην κορυφή`,"task.moveBottom":`Μετακίνηση στο τέλος`,"task.removeWithFiles":`Αφαίρεση και διαγραφή αρχείων`,"task.applied":`Εφαρμόστηκε.`,"select.all":`Επιλογή όλων`,"select.none":`Καθαρισμός επιλογής`,"select.count":`επιλεγμένα`,"settings.removePassword":`Αφαίρεση κωδικού`,"common.cancel":`Άκυρο`,"common.close":`Κλείσιμο`,"pkg.moveTitle":`Μετακίνηση σε πακέτο`,"pkg.name":`Όνομα πακέτου`,"pkg.merge":`Συγχώνευση σε ένα πακέτο`,"pkg.splitByHost":`Διαχωρισμός ανά πάροχο`,"pkg.menu":`Πακέτο`,"settings.pathVars":`Μεταβλητές: <jd:packagename>, <jd:hoster>, <jd:filename>, <jd:date>`,"settings.pathProblem.notAbsolute":`Γράψε μια πλήρη διαδρομή, για παράδειγμα /downloads ή D:\\Downloads.`,"settings.pathProblem.cannotCreate":`Δεν ήταν δυνατή η δημιουργία του {dir}.`,"settings.pathProblem.cannotWrite":`Δεν ήταν δυνατή η εγγραφή στο {dir}.`,"settings.crawl":`Άνοιγμα σελίδων και συλλογή των αρχείων στα οποία παραπέμπουν`,"settings.crawl.depth":`Βάθος σάρωσης`,"settings.crawl.depthHint":`Πόσο βαθιά θα πάει. Το 1 είναι μόνο η σελίδα που επικολλήσατε, το 2 ανοίγει και τις σελίδες που συνδέει, το 3 τις δικές τους. Μια σελίδα δεν ανοίγει ποτέ δύο φορές, οπότε αμοιβαίοι σύνδεσμοι τερματίζουν τη σάρωση αντί να την κάνουν κύκλους.`,"settings.crawl.maxPages":`Όριο σελίδων`,"settings.crawl.maxPagesHint":`Πόσες σελίδες μπορεί να ανοίξει το πολύ μία σάρωση. Μετρά τις σελίδες που ζητήθηκαν, όχι τους συνδέσμους που βρέθηκαν. Στο βάθος 1 υπάρχει μία μόνο σελίδα, οπότε δεν κάνει τίποτα.`,"settings.crawl.sameHost":`Παραμονή στον ίδιο κόμβο`,"settings.crawl.sameHostHint":`Ακολούθησε μόνο σελίδες του κόμβου που επικόλλησες. Ο κόμβος συγκρίνεται ακριβώς, οπότε ένας υποτομέας μετρά ως αλλού. Τα αρχεία δεν περιορίζονται ποτέ έτσι, γιατί οι λήψεις βρίσκονται συχνά σε ξεχωριστό διακομιστή.`,"settings.crawl.include":`Μόνο αυτοί οι σύνδεσμοι`,"settings.crawl.includeHint":`Μία κανονική έκφραση ανά γραμμή, συγκρίνεται με ολόκληρη τη διεύθυνση. Ένας σύνδεσμος πρέπει να ταιριάζει σε μία από αυτές για να συλλεχθεί. Οι σελίδες δεν φιλτράρονται, οπότε αυτό δεν εμποδίζει ποτέ τη σάρωση να πάει βαθύτερα.`,"settings.crawl.exclude":`Ποτέ αυτοί οι σύνδεσμοι`,"settings.crawl.excludeHint":`Μία κανονική έκφραση ανά γραμμή, συγκρίνεται με ολόκληρη τη διεύθυνση. Ό,τι ταιριάζει παραλείπεται, μαζί με τις σελίδες, οπότε μια αποκλεισμένη διεύθυνση δεν ανοίγει ποτέ.`,"task.checksumOk":`Το άθροισμα ελέγχου επαληθεύτηκε`,"task.checksumFail":`Το άθροισμα ελέγχου δεν ταιριάζει`,"settings.verifyChecksums":`Έλεγχος ολοκληρωμένης λήψης με το άθροισμα ελέγχου που τη συνόδευε`,"settings.shape":`Γωνίες`,"settings.shapeHint":`Ισχύει ταυτόχρονα για κάρτες, κουμπιά, καρτέλες, πεδία και σήματα.`,"settings.shape.round":`Στρογγυλές`,"settings.shape.slightlyRounded":`Απαλές`,"settings.shape.square":`Ορθές`,"settings.shape.leaf":`Φύλλο`,"settings.accent":`Χρώμα τονισμού`,"settings.accentHint":`Το μοναδικό χρώμα δραστηριότητας. Το κείμενο πάνω επιλέγεται με βάση την αντίθεση.`,"settings.accentRainbowOwns":`Η λειτουργία ουράνιου τόξου μοιράζει τώρα τα χρώματα ανά θέση. Αυτό το χρώμα ισχύει ακόμη παντού όπου δεν υπάρχει θέση.`,"settings.colours":`Χρώματα`,"settings.accentReset":`Προεπιλογή`,"queue.stop":`Διακοπή ουράς`,"queue.start":`Έναρξη ουράς`,"queue.stopMark":`Διακοπή μετά από αυτό`,"queue.stopMarkOn":`Θα σταματήσει μετά από αυτό`,"queue.order":`Σειρά ουράς`,"queue.play":`Αναπαραγωγή`,"queue.pause":`Παύση`,"queue.hardStop":`Διακοπή`,"queue.hardStopConfirmTitle":`Διακοπή όλων των μεταφορών τώρα;`,"queue.hardStopConfirmBody":`{n} ενεργή(-ές) μεταφορά(-ές) θα διακοπεί(-ούν) αμέσως αντί να ολοκληρωθεί(-ούν). {detail}`,"queue.hardStopConfirmLoss":`{bytes} που έχουν ήδη ληφθεί δεν μπορούν να συνεχιστούν και θα πρέπει να ληφθούν ξανά.`,"queue.hardStopConfirmUnknown":`{n} ακόμη δεν έχουν ελεγχθεί για υποστήριξη συνέχισης.`,"queue.hardStopConfirmSafe":`Οτιδήποτε εκτελείται μπορεί να συνεχιστεί από εκεί που σταμάτησε.`,"queue.hardStopConfirmCancel":`Ακύρωση`,"queue.hardStopConfirmProceed":`Διακοπή τώρα`,"settings.rainbow":`Λειτουργία ουράνιου τόξου`,"settings.rainbowHint":`Αντί για ένα χρώμα τονισμού, μια παλέτα οκτώ χρωμάτων ανά θέση, ώστε μια μεγάλη λίστα να διαβάζεται ως ξεχωριστές γραμμές.`,"settings.rainbowOn":`Χρήση παλέτας`,"settings.rainbowReactive":`Αντιδραστική λειτουργία`,"settings.rainbowReactiveHint":`Ήσυχο μέχρι να το αγγίξεις: χρώμα στο πέρασμα και σε ό,τι τρέχει`,"settings.rainbowRotate":`Περιστροφή χρωμάτων`,"settings.rainbowRotateHint":`Ανακάτεμα του σημείου εκκίνησης της παλέτας`,"settings.rainbowDisco":`Λειτουργία ντίσκο`,"settings.rainbowDiscoGlideHint":`Όσο είναι ενεργή η λειτουργία ουράνιου τόξου, κάθε χρωματιστό στοιχείο γλιστρά μαζί με τα άλλα μέσα από την παλέτα, ένα χρώμα κάθε 2,4 δευτερόλεπτα. Αν η «Κίνηση» είναι στο «Ανενεργό» ή αν στο σύστημά σου είναι ενεργή η μειωμένη κίνηση, το χρώμα απλώς περνά στο επόμενο.`,"settings.rainbowPalette":`Χρώμα παλέτας`,"settings.rainbowPaletteLabel":`Παλέτα χρωμάτων`,"settings.rainbowPaletteHint":`Τα οκτώ χρώματα που αποδίδονται ανά θέση. Επεξεργάσιμα μεμονωμένα.`,"settings.look.saveFailed":`Δεν ήταν δυνατή η αποθήκευση: {error}`,"settings.theme":`Θέμα`,"settings.motion.wild":`Έντονο`,"settings.motion.storm":`Καταιγίδα`,"settings.motion.subtle":`Διακριτικό`,"settings.motion.off":`Ανενεργό`,"settings.motion.hint":`Το Ανενεργό σβήνει κάθε μη απαραίτητη κίνηση· το Διακριτικό κρατά σύντομες τις εμφανίσεις· το Έντονο έχει την περισσότερη κίνηση.`,"settings.motion.title":`Κίνηση`,"settings.navLabels.title":`Ετικέτες πλοήγησης`,"settings.navLabels.titleHint":`Πόσο από κάθε καταχώριση σχεδιάζεται: στην πλαϊνή γραμμή, στη στήλη ρυθμίσεων, στις γραμμές εργαλείων των λιστών και στα κουμπιά του ίδιου του συλλέκτη. Στο πέρασμα του δείκτη το πλακίδιο κρατά το μέγεθός του και το όνομα εμφανίζεται κάτω από τον δείκτη.`,"settings.navLabels.both":`Εικονίδιο και κείμενο`,"settings.navLabels.glyph":`Μόνο εικονίδιο`,"settings.navLabels.text":`Μόνο κείμενο`,"settings.navLabels.hover":`Στο πέρασμα του δείκτη`,"settings.bottomBarLabels.title":`Ετικέτες κάτω γραμμής`,"settings.bottomBarLabels.titleHint":`Πόσο από κάθε καταχώριση δείχνει η γραμμή στο κάτω μέρος του παραθύρου. Η γραμμή αντικαθιστά την πλαϊνή γραμμή μόνο στη διάταξη τηλεφώνου, σε παράθυρο στενότερο από 768 pixel, οπότε σε πλατύτερη οθόνη αυτή η ρύθμιση δεν αλλάζει τίποτα. Το «Όπως η πλαϊνή γραμμή» χρησιμοποιεί τη ρύθμιση «Ετικέτες πλοήγησης».`,"settings.bottomBarLabels.follow":`Όπως η πλαϊνή γραμμή`,"common.show":`Εμφάνιση`,"common.hide":`Απόκρυψη`,"common.showPassword":`Εμφάνιση κωδικού`,"common.hidePassword":`Απόκρυψη κωδικού`,"common.dismiss":`Κλείσιμο`,"columns.name":`Όνομα`,"columns.size":`Μέγεθος`,"columns.progress":`Πρόοδος`,"columns.speed":`Ταχύτητα`,"columns.eta":`Απομένουν`,"columns.status":`Κατάσταση`,"columns.availability":`Διαθεσιμότητα`,"columns.host":`Πάροχος`,"columns.added":`Προστέθηκε`,"columns.finished":`Ολοκληρώθηκε`,"columns.comment":`Σχόλιο`,"columns.resolver":`Backend`,"columns.source":`Προέλευση`,"columns.enabled":`Ενεργό`,"columns.menuTitle":`Στήλες`,"columns.reset":`Επαναφορά στηλών`,"columns.headerHint":`Κάντε κλικ σε μια επικεφαλίδα για ταξινόμηση, σύρετέ την για αναδιάταξη της στήλης, σύρετε την άκρη της για αλλαγή μεγέθους, διπλό κλικ στην άκρη επαναφέρει το πλάτος. Δεξί κλικ στην επικεφαλίδα για τη λίστα στηλών.`,"columns.alwaysShown":`Αυτή η στήλη εμφανίζεται πάντα.`,"columns.lastVisible":`Μια λίστα χρειάζεται τουλάχιστον μία στήλη.`,"columns.resizeHint":`Σύρετε για αλλαγή πλάτους, διπλό κλικ για επαναφορά`,"list.sortedView":`Ταξινομημένη σειρά`,"list.sortedViewTip":`Η ταξινόμηση αλλάζει τη σειρά που βλέπεις, όχι τη σειρά εκτέλεσης. Οι λήψεις ξεκινούν πάντα με τη σειρά της ουράς. Ένα τρίτο κλικ στην ίδια επικεφαλίδα στήλης δείχνει ξανά τη σειρά της ουράς.`,"list.dragNeedsQueueOrder":`Η μεταφορά λειτουργεί μόνο στη σειρά της ουράς. Για να μετακινήσεις γραμμές με το χέρι, κάνε κλικ στην επικεφαλίδα της ταξινομημένης στήλης μέχρι να σβήσει η ταξινόμηση.`,"list.dragNotInQueue":`Αυτό δεν μετακινείται με το χέρι: μόνο σύνδεσμοι που περιμένουν ακόμη στην ουρά, και ένας φάκελος μόνο όσο οι σύνδεσμοί του έχουν την ίδια προτεραιότητα.`,"list.controls":`Χειριστήρια λίστας`,"list.actions":`Ενέργειες λίστας`,"list.failed":`Αυτό δεν πέτυχε: {error}`,"task.waiting.slot":`Όλες οι θέσεις κατειλημμένες`,"task.waiting.host":`Όριο αυτού του hoster`,"task.waiting.forced":`Οι θέσεις άμεσης εκκίνησης γεμάτες`,"task.waiting.disabled":`Απενεργοποιημένο`,"task.waiting.hold":`Σταματημένο χειροκίνητα`,"task.waiting.captcha":`Περιμένει captcha`,"task.waiting.account":`Ο λογαριασμός δεν είναι διαθέσιμος`,"task.waiting.halted":`Η ουρά είναι σταματημένη`,"list.dropChangedPriority":`Μετακινήθηκε: {n} λήψεις πήραν την προτεραιότητα της γραμμής όπου έπεσαν.`,"list.optionsFailed":`Δεν φορτώθηκαν οι καταχωρίσεις εκκαθάρισης από τον διακομιστή.`,"task.enable":`Ενεργοποίηση`,"task.disable":`Απενεργοποίηση`,"task.switchFailed":`Ο διακόπτης δεν άλλαξε.`,"task.uncheckable":`Ο πάροχος δεν απάντησε`,"task.expand":`Ανάπτυξη`,"task.collapse":`Σύμπτυξη`,"search.placeholder":`Αναζήτηση σε αυτή τη λίστα…`,"search.in":`Αναζήτηση σε`,"search.any":`Παντού`,"search.name":`Όνομα`,"search.host":`Πάροχος`,"search.package":`Πακέτο`,"search.comment":`Σχόλιο`,"search.url":`Σύνδεσμος`,"search.clear":`Καθαρισμός αναζήτησης`,"search.hint":`Διαλέξτε ένα πεδίο για αναζήτηση ή «Παντού» για να ψάξετε σε όλα μαζί.`,"search.syntax":`Πολλές λέξεις πρέπει να ταιριάζουν όλες, ένα μείον μπροστά αποκλείει μία. Τα host:, package: και name: ψάχνουν σε ένα μόνο πεδίο, τα >500mb και older:7d ρωτούν για μέγεθος και ηλικία. Οτιδήποτε άλλο αναζητείται ως απλό κείμενο.`,"search.shown":`{n} από {total} εμφανίζονται`,"filter.label":`Γρήγορα φίλτρα`,"filter.clear":`Εμφάνιση όλων`,"filter.running":`Γίνεται λήψη`,"filter.queued":`Στην ουρά`,"filter.paused":`Σε παύση`,"filter.finished":`Ολοκληρωμένα`,"filter.failed":`Απέτυχαν`,"filter.online":`Διαθέσιμα`,"filter.offline":`Μη διαθέσιμα`,"filter.uncheckable":`Δεν ελέγχονται`,"filter.unchecked":`Χωρίς έλεγχο`,"filter.disabled":`Απενεργοποιημένα`,"filter.held":`Σε αναμονή`,"filter.stalled":`Κολλημένο`,"cleanup.menu":`Εκκαθάριση…`,"cleanup.menuLabel":`Καταχωρίσεις εκκαθάρισης`,"cleanup.finished":`Αφαίρεση ολοκληρωμένων`,"cleanup.offline":`Αφαίρεση μη διαθέσιμων`,"cleanup.disabled":`Αφαίρεση απενεργοποιημένων συνδέσμων`,"cleanup.duplicates":`Αφαίρεση διπλότυπων`,"cleanup.incompleteArchives":`Αφαίρεση ημιτελών αρχειοθηκών`,"cleanup.what.finished":`Κάθε λήψη σε αυτή την εγκατάσταση που έχει ολοκληρωθεί.`,"cleanup.what.offline":`Κάθε σύνδεσμος σε αυτό το στιγμιότυπο για τον οποίο ο hoster απάντησε ότι δεν υπάρχει πια. Οι σύνδεσμοι που δεν μπόρεσε να ελέγξει κανείς μένουν ανέγγιχτοι.`,"cleanup.what.disabled":`Κάθε σύνδεσμος αυτής της εγκατάστασης που είναι απενεργοποιημένος.`,"cleanup.what.duplicates":`Δεύτερα αντίγραφα μιας λήψης που ήδη βρίσκεται στη λίστα. Κρατιέται το αντίγραφο που έχει προχωρήσει περισσότερο.`,"cleanup.what.incompleteArchives":`Σετ πολλών τόμων με ένα νεκρό μέρος. Τα υπόλοιπα δεν θα αποσυμπιεστούν ποτέ.`,"cleanup.finishedKeepsFiles":`Οι ολοκληρωμένες λήψεις απλώς βγαίνουν από τη λίστα. Αυτή η επιλογή δεν σβήνει ποτέ τίποτα από τον δίσκο.`,"cleanup.localOnly":`Η εκκαθάριση τρέχει πάντα σε αυτή την εγκατάσταση, όχι σε αυτή που βλέπετε. Γυρίστε στο «Αυτή η εγκατάσταση» για να τη χρησιμοποιήσετε.`,"cleanup.nothing":`Τίποτα δεν ταιριάζει με «{what}» αυτή τη στιγμή, οπότε δεν αφαιρέθηκε τίποτα.`,"cleanup.failed":`Δεν βρέθηκε τι θα αφαιρούσε αυτό: {error}`,"remove.title":`Να διαγραφούν και τα ληφθέντα αρχεία;`,"remove.count":`{n} λήψεις θα βγουν από τη λίστα.`,"remove.fromList":`Αφαίρεση από τη λίστα`,"remove.withFiles":`Αφαίρεση και διαγραφή αρχείων`,"remove.filesKept":`Τα αρχεία που βρίσκονται ήδη στον δίσκο μένουν εκεί που είναι.`,"remove.filesGone":`Αυτό σβήνει επίσης {files} αρχεία, {bytes} στον δίσκο. Δεν αναιρείται.`,"remove.noFiles":`Δεν έχει γραφτεί ακόμη τίποτα στον δίσκο.`,"remove.done":`Αφαιρέθηκαν {n} λήψεις.`,"remove.keys":`Το Del βγάζει τις επιλεγμένες γραμμές από τη λίστα. Το Shift+Del σβήνει και τα αρχεία τους.`,"remove.undo":`Αναίρεση`,"remove.undone":`{n} λήψεις πίσω στη λίστα.`,"remove.undoTooLate":`Πολύ αργά, αυτές οι γραμμές χάθηκαν οριστικά.`,"menu.label":`Ενέργειες για τις επιλεγμένες λήψεις`,"menu.packageLabel":`Ενέργειες για αυτό το πακέτο`,"menu.more":`Περισσότερα`,"menu.enable":`Ενεργοποίηση`,"menu.disable":`Απενεργοποίηση`,"menu.hold":`Κράτηση`,"menu.release":`Αποδέσμευση`,"menu.unforce":`Ακύρωση «Έναρξη τώρα»`,"menu.setFolder":`Ορισμός φακέλου λήψεων…`,"menu.collapseAll":`Σύμπτυξη όλων των πακέτων`,"menu.expandAll":`Ανάπτυξη όλων των πακέτων`,"collector.checkAll":`Έλεγχος όλων`,"search.toggle":`Αναζήτηση`,"skipped.summary":`{n} σύνδεσμοι δεν προστέθηκαν`,"skipped.info":`Links and files that did not become downloads, each with its reason. A link that was already in the list, or that the link filter is holding, is only noted here, since that copy is the one that downloads. Nothing was downloaded for the others: a container or Click'n'Load that gave no links, entries left out of a playlist, an .nzb that TorBox or Premiumize.me gave up on, or a file from the watch folder that could not be taken. Clearing forgets these notes and adds nothing back.`,"skipped.clear":`Καθαρισμός`,"skipped.clearFailed":`Δεν έγινε καθαρισμός της λίστας. Είναι προσβάσιμος ο διακομιστής;`,"container.choose":`Επιλογή αρχείου`,"container.uploading":`Μεταφόρτωση…`,"container.tooBig":`είναι μεγαλύτερο από {max}, και κανένα container δεν είναι`,"container.staged":`Ετοιμάστηκαν {n} σύνδεσμοι από {file}.`,"container.stagedIn":`Ετοιμάστηκαν {n} σύνδεσμοι από {file} στο «{pkg}».`,"container.alsoKnown":`Άλλοι {n} ήταν ήδη στη λίστα.`,"container.allKnown":`Και οι {n} σύνδεσμοι στο {file} ήταν ήδη στη λίστα.`,"container.handed":`Το {file} είναι κρυπτογραφημένο. Παραδόθηκε στο backend του JDownloader· οι σύνδεσμοί του εμφανίζονται εδώ μόλις το πάρει (εντός {n} δευτ.).`,"container.failed":`Το {file} δεν έγινε δεκτό: {reason}`,"settings.nav.modules":`Λειτουργικές μονάδες`,"settings.nav.collector":`Συλλέκτης συνδέσμων`,"settings.nav.downloads":`Λήψεις`,"settings.nav.archives":`Συμπιεσμένα αρχεία`,"settings.nav.rules":`Κανόνες και κατηγορίες`,"settings.nav.network":`Δίκτυο`,"settings.nav.accounts":`Λογαριασμοί`,"settings.nav.captcha":`Captcha`,"settings.nav.automation":`Αυτοματοποίηση`,"settings.nav.look":`Γενικά`,"settings.nav.appearance":`Εμφάνιση`,"settings.nav.access":`Απομακρυσμένη πρόσβαση`,"settings.nav.advanced":`Για προχωρημένους`,"settings.railLabel":`Ενότητες ρυθμίσεων`,"settings.empty":`Εδώ δεν υπάρχει ακόμη κάτι να ρυθμιστεί.`,"settings.emptyHint":`Η σελίδα είναι δηλωμένη ώστε η διεύθυνσή της να συνεχίσει να δουλεύει και ώστε τα χειριστήρια να προσγειωθούν εδώ μόλις υπάρξει το υποσύστημα.`,"settings.downloads.autoConfirmOff":`Η επιλογή «Άμεση έναρξη των συνδέσμων που προστίθενται» είναι απενεργοποιημένη στην ενότητα «Είσοδος συνδέσμων» παραπάνω, γι’ αυτό δεν τρέχει καμία αντίστροφη μέτρηση εδώ.`,"settings.downloads.locationTitle":`Τοποθεσία`,"settings.downloads.limitsTitle":`Όρια & συμπεριφορά`,"settings.downloads.watchTitle":`Παρακολούθηση φακέλου`,"settings.downloads.idleTitle":`Αδράνεια`,"settings.downloads.idleAction":`Ενέργεια στο τέλος της ουράς`,"settings.downloads.idleActionNone":`Καμία ενέργεια`,"settings.downloads.idleActionPause":`Παύση της ουράς`,"settings.downloads.idleActionHint":`Τι γίνεται μόλις δεν μένει τίποτα σε εξέλιξη, στην ουρά ή σε αναμονή εκκίνησης. Ένας σύνδεσμος που έχεις απενεργοποιήσει δεν μετράει ποτέ ως δουλειά που απομένει, οπότε δεν μπορεί να το καθυστερεί για πάντα. Ένας σύνδεσμος σε χειροκίνητη παύση ή κράτηση μετράει ακόμα: και τα δύο σημαίνουν «περίμενε λίγο», όχι «ποτέ».`,"settings.downloads.idleCountdown":`Αντίστροφη μέτρηση (δευτερόλεπτα)`,"settings.downloads.idleCountdownHint":`Πόσο χρόνο έχεις για ακύρωση πριν εκτελεστεί η ενέργεια, μόλις η ουρά αδειάσει πραγματικά.`,"settings.modules.fixedAtBuild":`Το σύνολο των μονάδων καθορίζεται όταν χτίζεται το εκτελέσιμο. Σε ένα στιγμιότυπο που τρέχει δεν εγκαθίσταται τίποτα, άρα αυτή η λίστα είναι όλο κι όλο.`,"settings.modules.sectionShipped":`Σε αυτή την έκδοση`,"settings.modules.sectionDesktop":`Μόνο εκδόσεις για υπολογιστή`,"settings.modules.sectionNotBuilt":`Δεν υπάρχει σε αυτή την έκδοση`,"settings.modules.off":`Ανενεργό`,"settings.modules.notBuilt":`Δεν χτίστηκε`,"settings.modules.desktopOnly":`Μόνο σε υπολογιστή`,"settings.modules.configuredOn":`Ρυθμίζεται στη σελίδα {page}`,"settings.modules.alsoOn":`Επίσης στη σελίδα {page}`,"settings.modules.detail.cnlListening":`Ακούει στο {address}`,"settings.modules.detail.cnlOff":`Απενεργοποιημένο`,"settings.modules.detail.cnlOffByEnv":`Απενεργοποιημένο με KL_CNL=0`,"settings.modules.detail.cnlUnavailable":`Δεν ήταν δυνατό να ανοίξει το {address}. Συνήθως τη θύρα την κρατά ήδη ένας JDownloader που τρέχει.`,"settings.modules.detail.extractionOff":`Ανενεργό. Μια αποσυμπίεση που έχει ήδη ξεκινήσει ολοκληρώνεται.`,"settings.modules.detail.extractionKeep":`Τα συμπιεσμένα αρχεία κρατιούνται μετά την αποσυμπίεση.`,"settings.modules.detail.extractionDelete":`Τα συμπιεσμένα αρχεία διαγράφονται μετά από επιτυχή αποσυμπίεση.`,"settings.modules.detail.extractionTrash":`Μετά από επιτυχή αποσυμπίεση τα συμπιεσμένα αρχεία μετακινούνται στο {folder}.`,"settings.modules.detail.watchFolder":`Παρακολουθεί το {folder}`,"settings.modules.detail.watchFolderMissing":`Ο φάκελος δεν υπάρχει ακόμη. Τα αρχεία που μπαίνουν μέσα του παραλαμβάνονται μόλις υπάρξει: {folder}`,"settings.modules.detail.watchNone":`Δεν έχει οριστεί φάκελος`,"settings.modules.detail.subscriptions":`{n} συνδρομές`,"settings.modules.detail.subscriptionsOne":`1 συνδρομή`,"settings.modules.detail.targetsSending":`{n} προορισμοί στέλνουν`,"settings.modules.detail.targetsSendingOne":`1 προορισμός στέλνει`,"settings.modules.detail.windows":`{n} χρονικά παράθυρα`,"settings.modules.detail.windowsOne":`1 χρονικό παράθυρο`,"settings.modules.detail.reconnectMethod":`Μέθοδος: {method}`,"settings.modules.detail.packagizerOff":`Ανενεργό. Οι νέοι σύνδεσμοι δεν ταξινομούνται με βάση τους κανόνες.`,"settings.modules.detail.linkfilterOff":`Ανενεργό. Κάθε σύνδεσμος γίνεται δεκτός.`,"settings.modules.detail.rules":`{n} κανόνες`,"settings.modules.detail.rulesOne":`1 κανόνας`,"settings.modules.detail.connectionsOff":`Ανενεργό. Οι νέες λήψεις βγαίνουν από τη δική διεύθυνση αυτού του υπολογιστή.`,"settings.modules.detail.connectionsInUse":`{n} συνδέσεις σε χρήση`,"settings.modules.detail.connectionsInUseOne":`1 σύνδεση σε χρήση`,"settings.modules.detail.federationOff":`Ανενεργό. Τα αδελφά στιγμιότυπα μένουν αποθηκευμένα, αλλά αυτό το στιγμιότυπο ούτε τα εμφανίζει ούτε επικοινωνεί μαζί τους.`,"settings.modules.detail.peers":`{n} αδελφά στιγμιότυπα`,"settings.modules.detail.peersOne":`1 αδελφό στιγμιότυπο`,"settings.modules.detail.jdMissing":`Τα κρυπτογραφημένα containers απορρίπτονται, και οι σύνδεσμοι των hoster πηγαίνουν σε μια υπηρεσία debrid ή αποτυγχάνουν.`,"settings.modules.detail.jdOff":`Ανενεργό. Οι λήψεις που είναι ήδη στον JDownloader ολοκληρώνονται, και οι νέοι σύνδεσμοι hoster περιμένουν μέχρι να ενεργοποιηθεί ξανά.`,"settings.modules.detail.jdReachable":`Προσβάσιμο. Τα κρυπτογραφημένα containers μπορούν να ανοιχτούν.`,"settings.modules.detail.ytdlpNotFound":`Το yt-dlp δεν βρέθηκε (αναζητήθηκαν ένα αντίγραφο που κατέβηκε στη σελίδα Επιλυτές, το KL_YTDLP και το «yt-dlp» στο PATH). Οι σελίδες πολυμέσων αποτυγχάνουν τότε με το σφάλμα του ίδιου του ιστότοπου.`,"settings.modules.detail.ytdlpOff":`Ανενεργό. Μια λήψη που τρέχει ολοκληρώνεται, και οι σύνδεσμοι βίντεο περιμένουν μέχρι να ενεργοποιηθεί ξανά.`,"settings.modules.detail.ytdlpQuality":`Ποιότητα: {quality}`,"settings.modules.detail.ytdlpVersion":`yt-dlp {version} ({source}), ποιότητα: {quality}`,"settings.modules.detail.torrentsOff":`Ανενεργό. Τα torrents που τρέχουν συνεχίζουν και κάνουν seeding κανονικά. Τα νέα περιμένουν μέχρι να ενεργοποιηθεί ξανά.`,"settings.modules.detail.torrentsUnregistered":`Η μηχανή torrent δεν είναι στον πίνακα δρομολόγησης, οπότε οι σύνδεσμοι magnet και τα ανεβασμένα αρχεία .torrent απορρίπτονται ως μη υποστηριζόμενα.`,"settings.modules.detail.torrentsRouted":`Οι σύνδεσμοι magnet και τα ανεβασμένα αρχεία .torrent πηγαίνουν στην ενσωματωμένη μηχανή torrent.`,"settings.modules.detail.captchaOff":`Ανενεργό. Δεν ανοίγει καμία ερώτηση, και ο JDownloader εγκαταλείπει έναν σύνδεσμο μόλις λήξει το captcha του.`,"settings.modules.detail.challenges":`{n} captcha περιμένουν αυτή τη στιγμή`,"settings.modules.detail.challengesOne":`1 captcha περιμένει αυτή τη στιγμή`,"settings.modules.detail.downloadclientOff":`Ανενεργό. Το Sonarr και το Radarr παίρνουν από αυτό 404, όπως από μια διεύθυνση που δεν υπάρχει.`,"settings.modules.detail.downloadclientNoToken":`Δεν υπάρχει ακόμη διακριτικό API, οπότε κάθε κλήση απορρίπτεται. Δημιούργησε ένα στη σελίδα Απομακρυσμένη πρόσβαση.`,"settings.modules.detail.downloadclientNoSubfolders":`Το «Κάθε πακέτο σε δικό του υποφάκελο» είναι ανενεργό, οπότε όλες οι λήψεις καταλήγουν σε έναν φάκελο και η εισαγωγή δεν μπορεί να τις ξεχωρίσει.`,"settings.modules.detail.downloadclientNoTokenNoSubfolders":`Δεν υπάρχει ακόμη διακριτικό API, οπότε κάθε κλήση απορρίπτεται. Δημιούργησε ένα στη σελίδα Απομακρυσμένη πρόσβαση. Επιπλέον το «Κάθε πακέτο σε δικό του υποφάκελο» είναι ανενεργό, οπότε όλες οι λήψεις καταλήγουν σε έναν φάκελο και η εισαγωγή δεν μπορεί να τις ξεχωρίσει.`,"settings.modules.detail.metricsOff":`Ανενεργό. Το {path} απαντά 404, σαν διεύθυνση που δεν υπάρχει.`,"settings.modules.detail.metricsNoToken":`Αυτό το στιγμιότυπο έχει κωδικό πρόσβασης αλλά ακόμη κανένα διακριτικό API, οπότε ένα σύστημα παρακολούθησης δεν έχει με τι να συνδεθεί. Δημιούργησε ένα στη σελίδα Απομακρυσμένη πρόσβαση.`,"settings.modules.detail.metricsReady":`Προσβάσιμο στο {path}. Σε στιγμιότυπο με κωδικό πρόσβασης, το σύστημα παρακολούθησης στέλνει ένα από τα διακριτικά API του ως κεφαλίδα Bearer.`,"settings.modules.detail.scriptingOff":`Ανενεργό. Κανένα συμβάν δεν ξεκινά σενάριο, και ένα σενάριο που τρέχει ήδη ολοκληρώνεται.`,"settings.modules.detail.scriptsEnabled":`{n} ενεργά σενάρια`,"settings.modules.detail.scriptsEnabledOne":`1 ενεργό σενάριο`,"settings.modules.reason.cnlSwitch":`Ακούει στο 127.0.0.1:9666, εκτός αν το KL_CNL ορίζει άλλη θύρα. Αν το απενεργοποιήσεις εδώ, το KL_CNL μένει όπως είναι, οπότε μετά από επανεκκίνηση η θύρα ανοίγει όπως λέει το περιβάλλον.`,"settings.modules.reason.cnlNoListener":`Αυτή η διεργασία δεν ανοίγει θύρα Click'n'Load.`,"settings.modules.reason.jdNotConfigured":`Δεν έχει ρυθμιστεί backend του JDownloader. Όρισε το KL_JD σε έναν JDownloader που φτάνει αυτό το στιγμιότυπο και κάνε επανεκκίνηση.`,"settings.modules.reason.ytdlpMissing":`Δεν βρέθηκε yt-dlp. Κατέβασέ το στη σελίδα Επιλυτές ή όρισε το KL_YTDLP.`,"settings.modules.reason.captchaNoJD":`Τα captcha έρχονται μόνο από το backend του JDownloader, και δεν έχει ρυθμιστεί κανένα (KL_JD).`,"settings.modules.reason.captchaJDOff":`Τα captcha έρχονται μόνο από τον JDownloader, που είναι απενεργοποιημένος. Ενεργοποίησέ τον πρώτα ξανά.`,"settings.modules.reason.tray":`Ένα εικονίδιο στην περιοχή ειδοποιήσεων χρειάζεται συνεδρία επιφάνειας εργασίας, που το build του container δεν έχει. Εκεί τα ίδια δείχνουν ο τίτλος και το εικονίδιο της καρτέλας του περιηγητή.`,"settings.modules.reason.windowpolicy":`Το τι κάνει το κλείσιμο ή η ελαχιστοποίηση του παραθύρου αφορά μία εγκατάσταση σε ένα μηχάνημα, γι’ αυτό αυτό το στιγμιότυπο δεν το παρέχει.`,"settings.modules.reason.updaterDesktop":`Ρωτά το GitHub για νεότερη έκδοση όταν το ζητάς στη σελίδα Γενικά, και κατά την εκκίνηση, αν είναι ενεργό το «Αυτόματος έλεγχος κατά την εκκίνηση». Εγκαθιστά ό,τι βρει μόνο αν είναι ενεργό το «Εγκατάσταση αυτόματα όταν βρεθεί». Αλλιώς την εγκατάσταση την κάνεις εσύ εκεί.`,"settings.modules.reason.updaterContainer":`Ένα container δεν μπορεί να αντικαταστήσει τον εαυτό του από μέσα. Ο έλεγχος ενημερώσεων στη σελίδα Γενικά σου λέει μόνο ότι υπάρχει νεότερη έκδοση και δίνει σύνδεσμο προς αυτήν. Για να ενημερώσεις, τράβηξε τη νέα εικόνα με τον τρόπο που ανέπτυξες αυτή (docker pull, Unraid Community Applications, Watchtower και ούτω καθεξής).`,"settings.modules.switchFailed":`Ο διακόπτης απορρίφθηκε: {reason}`,"settings.modules.configureFirst":`Δεν υπάρχει ακόμη κάτι να ανάψει. Ρυθμίστε το πρώτα στη σελίδα {page}· μετά ο διακόπτης εδώ το σταματά και το ξεκινά ξανά χωρίς να χαθεί ό,τι ορίσατε.`,"settings.modules.setUpBelow":`Δεν υπάρχει ακόμη κάτι να ενεργοποιηθεί. Ρύθμισέ το παρακάτω και ο διακόπτης ανάβει μόνος του.`,"settings.modules.parkedBelow":`Αν το ενεργοποιήσεις ξανά, επιστρέφει ό,τι είχε ρυθμιστεί εδώ.`,"settings.module.extraction":`Αποσυμπίεση αρχείων`,"settings.module.watch":`Παρακολουθούμενος φάκελος`,"settings.module.crawler":`Σάρωση σελίδων`,"settings.module.checksums":`Έλεγχος αθροισμάτων ελέγχου`,"settings.module.scheduler":`Χρονοδιαγράμματα`,"settings.module.reconnect":`Επανασύνδεση`,"settings.module.packagizer":`Packagizer`,"settings.module.linkfilter":`Φίλτρο συνδέσμων`,"settings.module.connections":`Εξερχόμενες συνδέσεις`,"settings.module.cnl":`Click'n'Load`,"settings.module.federation":`Αδελφά στιγμιότυπα`,"settings.module.jd":`Υποδομή JDownloader`,"settings.module.captcha":`Captcha`,"settings.module.scripting":`Σενάρια συμβάντων`,"settings.module.tray":`Εικονίδιο στην περιοχή ειδοποιήσεων`,"settings.module.windowpolicy":`Συμπεριφορά παραθύρων`,"settings.module.updater":`Ενημερώσεις μέσα στην εφαρμογή`,"settings.advanced.search":`Φιλτράρισμα κατά όνομα ή τιμή`,"settings.advanced.allSettings":`Όλες οι ρυθμίσεις`,"settings.advanced.onlyModified":`Μόνο ό,τι διαφέρει από την προεπιλογή`,"settings.advanced.resetTitle":`Επαναφορά αυτού του κλειδιού στην προεπιλογή του`,"settings.look.updatesTitle":`Ενημερώσεις`,"settings.look.updatesAuto":`Αυτόματος έλεγχος κατά την εκκίνηση`,"settings.look.updatesCheck":`Έλεγχος για ενημερώσεις`,"settings.look.updatesChecking":`Έλεγχος…`,"settings.look.updatesFailed":`Δεν ήταν δυνατός ο έλεγχος για ενημερώσεις.`,"settings.look.updatesCurrent":`Η έκδοση {version} είναι η πιο πρόσφατη.`,"settings.look.updatesAvailable":`Η έκδοση {version} είναι διαθέσιμη`,"settings.look.updatesAvailableContainer":`Η έκδοση {version} είναι διαθέσιμη: ενημέρωσε την εικόνα του container σου με τον τρόπο που την ανέπτυξες (docker pull, Unraid Community Applications, ...)`,"settings.look.updatesReleaseNotes":`Σημειώσεις έκδοσης`,"settings.look.updatesContainerHint":`Ενημέρωσε την εικόνα του container σου με τον τρόπο που την ανέπτυξες, για παράδειγμα με docker pull ή μέσω του Unraid Community Applications.`,"settings.look.updatesAutoInstall":`Εγκατάσταση αυτόματα όταν βρεθεί`,"settings.look.updatesAutoInstallHint":`Κατεβάζει, επαληθεύει και εφαρμόζει μια νεότερη έκδοση μόλις ο αυτόματος έλεγχος τη βρει, και μετά κάνει επανεκκίνηση. Απαιτεί ενεργοποιημένο το "Αυτόματος έλεγχος κατά την εκκίνηση" παραπάνω.`,"settings.look.updatesAutoInstallContainerHint":`Δυνατό μόνο στην έκδοση για υπολογιστή: ένα container δεν μπορεί να αντικαταστήσει τον εαυτό του από μέσα. Ενημέρωσέ το αντί γι' αυτό με τον τρόπο που το ανέπτυξες (docker pull, Unraid Community Applications, Watchtower, ...).`,"settings.look.updatesAutoInstalling":`Εγκατάσταση {version}…`,"settings.look.updatesInstalling":`Εγκατάσταση…`,"settings.look.updatesInstallNow":`Εγκατάσταση τώρα`,"settings.look.updatesInstalled":`Εγκαταστάθηκε, γίνεται επανεκκίνηση…`,"settings.look.updatesInstallFailed":`Δεν ήταν δυνατή η εγκατάσταση της ενημέρωσης: {error}`,"settings.look.updatesHint":`Συγκρίνει την έκδοση αυτού του build με την πιο πρόσφατη έκδοση στο GitHub. Το desktop build μπορεί επίσης να κατεβάσει και να εγκαταστήσει αυτόματα μια νεότερη έκδοση· ένα container ενημερώνεται αντ' αυτού με τον τρόπο που αναπτύχθηκε (docker pull, Unraid Community Applications, Watchtower, ...).`,"settings.advanced.modified":`άλλαξε`,"settings.advanced.noMatch":`Κανένα κλειδί δεν ταιριάζει.`,"settings.advanced.badJson":`Αυτό πρέπει να είναι έγκυρο JSON, γι’ αυτό δεν εφαρμόζεται.`,"settings.advanced.secret":`Ένα αποθηκευμένο μυστικό δεν στέλνεται ποτέ στον περιηγητή. Αφήστε το σύμβολο κράτησης για να το κρατήσετε, ή γράψτε νέα τιμή για να το αντικαταστήσετε.`,"settings.advanced.listHint":`Εδώ επεξεργάζεται ως JSON. Η δική του σελίδα έχει τον κανονικό επεξεργαστή.`,"settings.advanced.defaultsUnavailable":`Οι εργοστασιακές τιμές δεν μπόρεσαν να ανακτηθούν, οπότε από εδώ δεν γίνεται καμία επαναφορά.`,"settings.advanced.type.boolean":`ναι / όχι`,"settings.advanced.type.number":`αριθμός`,"settings.advanced.type.text":`κείμενο`,"settings.advanced.type.list":`λίστα`,"settings.advanced.type.object":`ομάδα`,"settings.sectionLinkIntake":`Είσοδος συνδέσμων`,"settings.linkIntakeHint":`Οι τρόποι με τους οποίους ένας σύνδεσμος φτάνει μόνος του στον συλλέκτη, χωρίς να τον επικολλήσεις εδώ.`,"settings.linkIntake.cnlHint":`Δέχεται τους συνδέσμους που στέλνει το κουμπί Click'n'Load ενός ιστότοπου, όπως ακριβώς ο JDownloader. Ό,τι αλλάξεις εδώ ισχύει μέχρι την επόμενη επανεκκίνηση, μετά αποφασίζει ξανά το KL_CNL.`,"settings.linkIntake.watchParked":`Αν το ενεργοποιήσεις ξανά, επανέρχεται ο φάκελος που παρακολουθούσε πριν.`,"settings.linkIntake.watchPickFolder":`Διάλεξε φάκελο παρακάτω και ο διακόπτης ανάβει μόνος του.`,"settings.connections.add":`Προσθήκη σύνδεσης`,"settings.connections.import":`Εισαγωγή λίστας`,"settings.connections.empty":`Όλα βγαίνουν από αυτό το μηχάνημα`,"settings.connections.emptyHint":`Δεν έχει ρυθμιστεί καμία εξερχόμενη σύνδεση, οπότε κάθε λήψη χρησιμοποιεί τη δική του γραμμή αυτού του μηχανήματος. Προσθέστε έναν διαμεσολαβητή για να περνούν οι λήψεις, ή μια απευθείας γραμμή για να μένουν ορισμένοι πάροχοι εκτός.`,"settings.connections.use":`Χρήση αυτής της σύνδεσης`,"settings.connections.moveUp":`Μετακίνηση πάνω`,"settings.connections.moveDown":`Μετακίνηση κάτω`,"settings.connections.remove":`Αφαίρεση αυτής της σύνδεσης`,"settings.connections.edit":`Επεξεργασία αυτής της σύνδεσης`,"settings.connections.type":`Τύπος`,"settings.connections.typeHint":`Το «Καμία» και το «Απευθείας» σημαίνουν διαφορετικά πράγματα. Το «Καμία» είναι αδρανές: δεν ορίζει καμία σύνδεση και δεν χρησιμοποιείται ποτέ, οπότε μένει μόνο μέχρι να τελειώσεις τη συμπλήρωσή του. Το «Απευθείας» είναι πραγματική επιλογή: η κίνηση βγαίνει από τη σύνδεση αυτού του μηχανήματος και παρακάμπτει κάθε proxy για τους hosts που αναφέρονται παρακάτω. Έτσι εξαιρείς ένα NAS από ένα proxy για όλη την εφαρμογή. Μια γραμμή της οποίας το φίλτρο ταιριάζει με τον host κερδίζει μια γραμμή χωρίς φίλτρο, οπότε μια γραμμή «Απευθείας» με φίλτρο κερδίζει πάντα ένα proxy που τα πιάνει όλα.`,"settings.connections.kind.none":`Καμία`,"settings.connections.kind.direct":`Απευθείας`,"settings.connections.warnDirectCatchAll":`Αυτή η απευθείας γραμμή δεν έχει φίλτρο παρόχων, οπότε παίρνει τη σειρά της στην εναλλαγή και στέλνει λήψεις έξω χωρίς διαμεσολαβητή στην τύχη. Ονομάστε τους παρόχους που πρέπει να αναλαμβάνει.`,"settings.connections.stateSocks4":`Το SOCKS4 μεταφέρει αναγνωριστικό χρήστη και δεν έχει καθόλου πεδίο κωδικού, οπότε για αυτή τη γραμμή δεν αποθηκεύεται κωδικός.`,"settings.connections.host":`Πάροχος`,"settings.connections.port":`Θύρα`,"settings.connections.username":`Όνομα χρήστη`,"settings.connections.usernameHint":`Τα διαπιστευτήρια του ίδιου του διαμεσολαβητή, όχι λογαριασμός παρόχου. Αν σβήσετε το όνομα χρήστη, σβήνεται μαζί και ο αποθηκευμένος κωδικός.`,"settings.connections.password":`Κωδικός`,"settings.connections.passwordStored":`αποθηκευμένος (άφησέ το κενό για να τον κρατήσεις)`,"settings.connections.passwordHint":`Ένας αποθηκευμένος κωδικός δεν στέλνεται ποτέ σε αυτή τη σελίδα, γι’ αυτό το πλαίσιο είναι κενό. Αφήστε το κενό και ο αποθηκευμένος διατηρείται. Ένας αποθηκευμένος κωδικός δεν ακολουθεί τη γραμμή σε άλλον υπολογιστή, θύρα ή τύπο: αν αλλάξετε κάποιο από αυτά, πρέπει να οριστεί ξανά.`,"settings.connections.filter":`Φίλτρο παρόχων`,"settings.connections.filterHint":`Ένας πάροχος ανά γραμμή. Ένας γυμνός τομέας καλύπτει ό,τι βρίσκεται από κάτω του, οπότε το example.org αρκεί για το dl2.example.org, και τα * ? [ ] λειτουργούν ως μπαλαντέρ. Κενό σημαίνει ότι αυτή η γραμμή τα πιάνει όλα, κάτι πιο αδύναμο από μια γραμμή της οποίας το φίλτρο ταιριάζει με τον πάροχο.`,"settings.connections.filterAll":`όλοι οι πάροχοι`,"settings.connections.filterCount":`{n} πάροχοι`,"settings.connections.cap":`Ταυτόχρονες λήψεις`,"settings.connections.capHint":`Πόσες λήψεις μπορούν να μοιράζονται αυτή τη σύνδεση ταυτόχρονα. Το 0 χρησιμοποιεί την προεπιλογή 2. Η λίστα υπάρχει για να μοιράζει τις λήψεις, και μια σύνδεση που θα έπαιρνε όλη την ουρά θα το ακύρωνε.`,"settings.connections.capDefault":`προεπιλογή`,"settings.connections.test":`Δοκιμή`,"settings.connections.testing":`Γίνεται δοκιμή…`,"settings.connections.testTarget":`Δοκιμή προς`,"settings.connections.testTargetHint":`Προαιρετικό. Αν μείνει κενό, η δοκιμή δείχνει μόνο ότι ο διαμεσολαβητής απαντά. Ονομάστε έναν προορισμό και ζητείται από τον διαμεσολαβητή να προωθήσει εκεί, κάτι που ελέγχει στ’ αλήθεια τα διαπιστευτήρια και δείχνει αν απορρίπτεται συγκεκριμένα εκείνος ο πάροχος.`,"settings.connections.testFailed":`Η δοκιμή δεν μπόρεσε να εκτελεστεί: {error}`,"settings.connections.importTitle":`Εισαγωγή λίστας διαμεσολαβητών`,"settings.connections.importLabel":`Λίστα διαμεσολαβητών`,"settings.connections.importHint":`Ένας ανά γραμμή, ως socks5://user:pass@host:port. Δουλεύουν και τα https, socks4 και socks4a, και μια γραμμή που δεν διαβάζεται εμφανίζεται πιο κάτω με τον λόγο αντί να πεταχτεί.`,"settings.connections.importPlaceholder":`socks5://user:pass@proxy.example.org:1080`,"settings.connections.importRead":`Ανάγνωση λίστας`,"settings.connections.importReading":`Γίνεται ανάγνωση…`,"settings.connections.importReady":`{n} έτοιμα για προσθήκη`,"settings.connections.importAdd":`Προσθήκη {n}`,"settings.connections.importRefused":`{n} απορρίφθηκαν`,"settings.connections.importNothing":`Από αυτή τη λίστα δεν διαβάστηκε τίποτα.`,"settings.connections.importLine":`Γραμμή {n}`,"settings.connections.importFailed":`Η λίστα δεν μπόρεσε να διαβαστεί: {error}`,"settings.connections.cancel":`Άκυρο`,"collector.filtered.restore":`Επαναφορά`,"collector.filtered.restoreAll":`Επαναφορά όλων`,"collector.filtered.clear":`Καθάρισμα`,"collector.filtered.originTitle":`Από πού ήρθε αυτός ο σύνδεσμος`,"collector.filtered.origin.paste":`επικολλήθηκε`,"collector.filtered.origin.crawl":`από σάρωση σελίδας`,"collector.filtered.origin.cnl":`Click'n'Load`,"collector.filtered.origin.watch":`παρακολουθούμενος φάκελος`,"collector.filtered.origin.container":`περιέκτης`,"collector.filtered.restoreFailed":`Δεν έγινε επαναφορά αυτών των συνδέσμων. Είναι προσβάσιμος ο διακομιστής;`,"collector.filtered.clearFailed":`Δεν έγινε καθάρισμα αυτών των συνδέσμων. Είναι προσβάσιμος ο διακομιστής;`,"settings.rules.flavourLabel":`Ποια λίστα κανόνων`,"settings.rules.setupTitle":`Σύνολο κανόνων`,"settings.rules.packagizerHint":`Τρέχει σε κάθε σύνδεσμο καθώς προετοιμάζεται και ξαναγράφει ό,τι μπορεί: πακέτο, φάκελο, σχόλιο, προτεραιότητα, συνδέσεις, αυτόματη αποσυμπίεση. Κάθε κανόνας που ταιριάζει συνεισφέρει, και ανά πεδίο κερδίζει ο μεταγενέστερος κανόνας.`,"settings.rules.filterHint":`Αποφασίζει αν ένας σύνδεσμος θα μπει καν στον συλλέκτη. Ένας σύνδεσμος που απορρίπτεται δεν διαγράφεται: κρατείται μαζί με τον κανόνα και τον λόγο που τον σταμάτησαν, ώστε τίποτα να μην εξαφανίζεται χωρίς να λέει γιατί.`,"settings.rules.setOff":`Αυτή η λίστα είναι ανενεργή`,"settings.rules.setSwitchHint":`Ο κεντρικός διακόπτης όλης της λίστας. Όταν είναι ανενεργός, κανένας κανόνας παρακάτω δεν τρέχει, αλλά κάθε κανόνας μπορεί ακόμα να επεξεργαστεί και να δοκιμαστεί κανονικά, ώστε να βρεις και να διορθώσεις ό,τι δεν πάει καλά όσο η λίστα είναι ανενεργή.`,"settings.rules.stopAfterMatch":`Σταμάτα στον πρώτο κανόνα που ταιριάζει`,"settings.rules.stopHint":`Όταν είναι ανενεργό, κάθε κανόνας που ταιριάζει συνεισφέρει και ανά πεδίο κερδίζει ο μεταγενέστερος, κάτι που θέλει ο Packagizer. Όταν είναι ενεργό, η αξιολόγηση σταματά στο πρώτο ταίριασμα, κάτι που συνήθως θέλει ένα φίλτρο: μια αποδοχή πάνω από μια πλατιά απόρριψη προστατεύει τότε πραγματικά τον σύνδεσμο.`,"settings.rules.listTitle":`Κανόνες, με τη σειρά που τρέχουν`,"settings.rules.add":`Προσθήκη κανόνα`,"settings.rules.import":`Εισαγωγή`,"settings.rules.export":`Εξαγωγή`,"settings.rules.exportTitle":`Αποθήκευση αυτής της λίστας ως αρχείο JSON`,"settings.rules.importTitle":`Αντικατάσταση αυτής της λίστας από αρχείο JSON`,"settings.rules.importFailed":`Αυτό το αρχείο δεν είναι λίστα κανόνων: {reason}`,"settings.rules.importedCount":`Φορτώθηκαν {n} κανόνες. Τίποτα δεν αποθηκεύεται μέχρι να αποθηκεύσετε τη σελίδα.`,"settings.rules.empty":`Δεν υπάρχουν κανόνες ακόμη`,"settings.rules.emptyPackagizer":`Κάθε σύνδεσμος κρατά το πακέτο, τον φάκελο και τις επιλογές με τα οποία ήρθε. Προσθέστε κανόνα για να τακτοποιούνται καθώς μπαίνουν.`,"settings.rules.emptyFilter":`Όλοι οι σύνδεσμοι γίνονται δεκτοί. Προσθέστε κανόνα για να κρατηθούν κάποιοι.`,"settings.rules.unnamed":`Κανόνας {n}`,"settings.rules.duplicate":`Διπλασιασμός αυτού του κανόνα`,"settings.rules.remove":`Αφαίρεση αυτού του κανόνα`,"settings.rules.moveUp":`Μετακίνηση πάνω`,"settings.rules.moveDown":`Μετακίνηση κάτω`,"settings.rules.ruleOn":`Αυτός ο κανόνας τρέχει`,"settings.rules.ruleOff":`Αυτός ο κανόνας είναι ανενεργός`,"settings.rules.problemCount":`{n} προβλήματα`,"settings.rules.problemOne":`1 πρόβλημα`,"settings.rules.notRunning":`Αυτός ο κανόνας δεν εφαρμόζεται. Διορθώστε όσα αναφέρονται και αρχίζει πάλι να δουλεύει.`,"settings.rules.matchedCount":`ταίριαξαν {n} από {total}`,"settings.rules.name":`Όνομα`,"settings.rules.namePlaceholder":`Για τι χρησιμεύει αυτός ο κανόνας`,"settings.rules.nameHint":`Φαίνεται μόνο σε σένα: σε αυτή τη λίστα, σε ένα πρόβλημα και στον λόγο για τον οποίο κρατήθηκε ένας σύνδεσμος. Ένας κανόνας χωρίς όνομα αναφέρεται με τη θέση του, η οποία αλλάζει όταν αναδιατάσσεις τη λίστα.`,"settings.rules.sectionIf":`Αν ισχύουν όλα αυτά`,"settings.rules.ifHint":`Κάθε συνθήκη πρέπει να ισχύει. Ένα «είτε το ένα είτε το άλλο» γράφεται ως δύο κανόνες, κι έτσι η λίστα διαβάζεται εύκολα από πάνω προς τα κάτω. Ένας κανόνας χωρίς συνθήκες ταιριάζει σε κάθε σύνδεσμο. Έτσι γράφεται ένας φάκελος για όλα τα υπόλοιπα ή μια γενική απόρριψη στο τέλος.`,"settings.rules.fieldPicker":`Τι να κοιτάξει`,"settings.rules.opPicker":`Πώς να το συγκρίνει`,"settings.rules.sectionThen":`Τότε`,"settings.rules.thenHintPackagizer":`Ένα άδειο πλαίσιο σημαίνει «άφησέ το ήσυχο», ποτέ «σβήσ’ το»: ένας κανόνας που ορίζει μόνο τον φάκελο δεν πρέπει να σβήνει το όνομα πακέτου που διάλεξε προηγούμενος κανόνας.`,"settings.rules.thenHintFilter":`Ένας κανόνας που απορρίπτει κρατά τον σύνδεσμο στην άκρη με τον λόγο του. Αξίζει και ένας κανόνας που δέχεται: τοποθετημένος πάνω από μια πλατιά απόρριψη, με ενεργό το «Σταμάτα στον πρώτο κανόνα που ταιριάζει», έτσι αφήνεις να περάσει ένας συγκεκριμένος hoster.`,"settings.rules.addCondition":`Προσθήκη συνθήκης`,"settings.rules.removeCondition":`Αφαίρεση αυτής της συνθήκης`,"settings.rules.noConditions":`Χωρίς συνθήκες, οπότε αυτός ο κανόνας ταιριάζει σε κάθε σύνδεσμο.`,"settings.rules.value":`Τιμή`,"settings.rules.min":`Τουλάχιστον`,"settings.rules.max":`Το πολύ`,"settings.rules.noUpperBound":`χωρίς άνω όριο`,"settings.rules.sizeHint":`Ένας σκέτος αριθμός είναι byte. Δουλεύουν και μονάδες (700 MB, 1.5 GiB), και οι δύο διαβάζονται με βάση το 1024, όπως κάθε μέγεθος που δείχνει η υπόλοιπη εφαρμογή.`,"settings.rules.badSize":`Αυτό δεν είναι μέγεθος.`,"settings.rules.pattern":`Μοτίβο`,"settings.rules.patternHint":`Μια κανονική έκφραση της Go, χωρίς αγκύρωση. Είναι ο μόνος τελεστής που δεν αγνοεί πεζά και κεφαλαία· βάλε (?i) μπροστά αν θέλεις να τα αγνοεί. Ένα μοτίβο που δεν αναλύεται απορρίπτεται με τον λόγο, αντί να μην ταιριάζει σιωπηλά με τίποτα.`,"settings.rules.category":`Τύπος αρχείου`,"settings.rules.categoryCustom":`Δικό σας μοτίβο`,"settings.rules.categoryHint":`Μια συντόμευση που συμπληρώνει το μοτίβο για μια ολόκληρη οικογένεια καταλήξεων. Αποθηκεύεται ως κανονικό μοτίβο, οπότε μπορείς να διαλέξεις μία και μετά να επεξεργαστείς το μοτίβο. Μετά από αυτό, εδώ εμφανίζεται ξανά «Δικό σας μοτίβο», γιατί η συντόμευση δεν λέει πια τι κάνει ο κανόνας.`,"settings.rules.categoryExtensions":`Καλύπτει: {list}`,"settings.rules.unchanged":`Αμετάβλητο`,"settings.rules.yes":`Ενεργό`,"settings.rules.no":`Ανενεργό`,"settings.rules.reject":`Απόρριψη του συνδέσμου`,"settings.rules.accept":`Αποδοχή του συνδέσμου`,"settings.rules.priorityHint":`Ψηλότερη τρέχει νωρίτερα. Το εύρος είναι αυτό που δέχεται η ίδια η ουρά, οπότε ένας κανόνας δεν μπορεί να δώσει σε μια εργασία προτεραιότητα που δεν έχετε τρόπο να αναιρέσετε. Αφήστε το κενό για να μην αλλάξει τίποτα.`,"settings.rules.chunksHint":`Με πόσες συνδέσεις κατεβαίνει αυτό το ένα αρχείο. Αφήστε το κενό για να χρησιμοποιηθεί η γενική ρύθμιση. Πάνω από λίγες δεν προσφέρουν τίποτα σε πάροχο που βάζει όριο ανά αρχείο και είναι σίγουρος τρόπος να επισημανθεί ένας λογαριασμός.`,"settings.rules.emptyMeansUnchanged":`κενό = αμετάβλητο`,"settings.rules.variables":`Μεταβλητές`,"settings.rules.variablesTitle":`Εισαγωγή μεταβλητής`,"settings.rules.variablesHint":`Καθεμία από αυτές αναλύεται με βάση τον σύνδεσμο όπως έφτασε, οπότε οι κανόνες δεν αλυσοδένονται: ένα πρότυπο φακέλου στον τέταρτο κανόνα βλέπει το όνομα που έδωσε ο hoster, όχι αυτό που του έδωσε ο δεύτερος κανόνας. Το τι κάνει ένας κανόνας διαβάζεται μόνο από τον ίδιο τον κανόνα.`,"settings.rules.varParams":`αντικαταστήστε {params}`,"settings.rules.field.filename":`Όνομα αρχείου`,"settings.rules.field.url":`Διεύθυνση συνδέσμου`,"settings.rules.field.hoster":`Πάροχος`,"settings.rules.field.source":`Σελίδα προέλευσης`,"settings.rules.field.filetype":`Τύπος αρχείου`,"settings.rules.field.filesize":`Μέγεθος αρχείου`,"settings.rules.field.package":`Πακέτο`,"settings.rules.op.contains":`περιέχει`,"settings.rules.op.contains-not":`δεν περιέχει`,"settings.rules.op.equals":`είναι`,"settings.rules.op.equals-not":`δεν είναι`,"settings.rules.op.matches":`ταιριάζει σε μοτίβο`,"settings.rules.op.is-between":`είναι ανάμεσα`,"settings.rules.action.packageName":`Όνομα πακέτου`,"settings.rules.action.downloadDir":`Φάκελος λήψεων`,"settings.rules.action.extractDir":`Μετακίνηση των αποσυμπιεσμένων αρχείων σε`,"settings.rules.action.comment":`Σχόλιο`,"settings.rules.action.priority":`Προτεραιότητα`,"settings.rules.action.autoExtract":`Αυτόματη αποσυμπίεση`,"settings.rules.action.chunks":`Συνδέσεις`,"settings.rules.action.reject":`Ετυμηγορία`,"settings.rules.action.reason":`Λόγος`,"settings.rules.action.reasonHint":`Εμφανίζεται δίπλα στον σύνδεσμο που κρατήθηκε. Αν το αφήσεις κενό, γράφεται ένας για σένα, γιατί μια απόρριψη που κανείς δεν μπορεί να εξηγήσει είναι ακριβώς αυτό που θέλει να αποφύγει αυτή η λίστα.`,"settings.rules.action.downloadDirHint":`Πού κατεβαίνει ένας σύνδεσμος που ταιριάζει. Μόνο αυτό το πλαίσιο και το «Μετακίνηση των αποσυμπιεσμένων αρχείων σε» επιτρέπεται να γράφουν επίπεδα διαδρομής. Κάθε άλλο πλαίσιο κόβεται σε ένα σκέτο όνομα, γιατί μια κάθετος σε όνομα αρχείου είναι δρόμος έξω από τον φάκελο που διάλεξες.`,"settings.rules.action.extractDirHint":`Πού πηγαίνουν τα αποσυμπιεσμένα αρχεία ενός συνδέσμου που ταιριάζει μόλις τελειώσει η αποσυμπίεση. Για αυτούς τους συνδέσμους αντικαθιστά το «Μετακίνηση των αποσυμπιεσμένων αρχείων σε» της σελίδας Συμπιεσμένα αρχεία. Οι μεταβλητές λειτουργούν εδώ.`,"settings.rules.category.video":`Βίντεο`,"settings.rules.category.audio":`Ήχος`,"settings.rules.category.image":`Εικόνες`,"settings.rules.category.archive":`Συμπιεσμένα`,"settings.rules.category.document":`Έγγραφα και βιβλία`,"settings.rules.category.subtitle":`Υπότιτλοι`,"settings.rules.category.disc":`Είδωλα δίσκων`,"settings.rules.category.program":`Προγράμματα και πακέτα`,"settings.rules.var.packagename":`Το πακέτο στο οποίο ήρθε ο σύνδεσμος`,"settings.rules.var.hoster":`Ο πάροχος, χωρίς www.`,"settings.rules.var.filename":`Το όνομα αρχείου όπως ήρθε`,"settings.rules.var.orgfilename":`Το όνομα αρχείου όπως ήρθε`,"settings.rules.var.orgfilenamewithoutext":`Το όνομα αρχείου χωρίς την κατάληξή του`,"settings.rules.var.orgfiletype":`Η κατάληξη χωρίς την τελεία, κενή όταν δεν υπάρχει`,"settings.rules.var.date":`Σήμερα, ως YYYY-MM-DD`,"settings.rules.var.year":`Το έτος, ως YYYY`,"settings.rules.var.month":`Ο μήνας, ως MM`,"settings.rules.var.day":`Η ημέρα, ως DD`,"settings.rules.var.simpledate":`Η ημερομηνία σε μοτίβο που γράφετε εσείς, στη σύνταξη ημερομηνιών της Java`,"settings.rules.var.source":`Το N-οστό τμήμα διαδρομής του URL της σελίδας προέλευσης, μετρώντας από το 1: στο https://site.org/tv/s01/list.html το 1 είναι tv και το 2 είναι s01. Ο JDownloader εννοεί κάτι άλλο με αυτή την ετικέτα· το (i) δίπλα στο «Εισαγωγή μεταβλητής» εξηγεί τη διαφορά.`,"settings.rules.var.match":`Η ομάδα σύλληψης N του μοτίβου «ταιριάζει σε μοτίβο» αυτού του κανόνα στο FIELD. Αυτό είναι το <jd:source:N> του JDownloader, με όνομα που λέει ποιο μοτίβο διαβάζει. Κανόνας χωρίς μοτίβο που ταιριάζει σε αυτό το πεδίο απορρίπτεται στην αποθήκευση, αντί να παράγει σιωπηλά φάκελο με όνομα <jd:match:url:1>.`,"settings.rules.var.append":`Τίποτα την πρώτη φορά που εμφανίζεται αυτή η τιμή, μετά _2, _3 και ούτω καθεξής`,"settings.rules.sourceDivergence":`Αντιγράφεις πρότυπο από ρυθμίσεις του JDownloader; Το <jd:source:N> σημαίνει εδώ κάτι άλλο: ένα τμήμα διαδρομής του URL προέλευσης, όχι ομάδα σύλληψης. Η σημασία του JD γράφεται <jd:match:FIELD:N>. Τα δύο συμπίπτουν αρκετά συχνά ώστε να είναι επικίνδυνο, οπότε αξίζει να δοκιμάσεις ένα αντιγραμμένο πρότυπο παρακάτω πριν το αποθηκεύσεις.`,"settings.rules.testTitle":`Δοκιμάστε το σε έναν σύνδεσμο`,"settings.rules.testHint":`Τίποτα εδώ δεν κατεβαίνει, δεν αποθηκεύεται και δεν καταγράφεται. Η λίστα όπως είναι σε αυτή τη σελίδα τρέχει πάνω σε αυτά τα δείγματα, με τον ίδιο κώδικα που τρέχει όταν παραλαμβάνονται οι σύνδεσμοι.`,"settings.rules.testUrl":`Διεύθυνση συνδέσμου`,"settings.rules.testFilename":`Όνομα αρχείου`,"settings.rules.testSource":`Σελίδα προέλευσης`,"settings.rules.testSourceHint":`Η σελίδα όπου μια σάρωση βρήκε τον σύνδεσμο. Αξίζει να συμπληρωθεί μόνο για κανόνα που ελέγχει το πεδίο προέλευσης ή χρησιμοποιεί το <jd:source:N>.`,"settings.rules.testSize":`Μέγεθος`,"settings.rules.testPackage":`Πακέτο`,"settings.rules.testPackageHint":`Το πακέτο στο οποίο θα έφτανε ο σύνδεσμος, πριν τρέξει οποιοσδήποτε κανόνας. Σε αυτό αναλύεται το <jd:packagename>, γιατί ένα πρότυπο φακέλου δεν βλέπει το όνομα πακέτου που ορίζει ένας κανόνας στο ίδιο πέρασμα.`,"settings.rules.testAdd":`Προσθήκη δείγματος`,"settings.rules.testRemove":`Αφαίρεση αυτού του δείγματος`,"settings.rules.testEmpty":`Επικολλήστε έναν σύνδεσμο και ένα όνομα αρχείου για να δείτε πού θα κατέληγε.`,"settings.rules.testRunning":`Γίνεται έλεγχος…`,"settings.rules.testFailed":`Η δοκιμή στα ξηρά δεν ήταν προσβάσιμη: {reason}`,"settings.rules.resultMatched":`Ταιριάσματα, με σειρά`,"settings.rules.resultNone":`Κανένας κανόνας δεν ταίριαξε`,"settings.rules.resultPackage":`Πακέτο`,"settings.rules.resultFolder":`Φάκελος`,"settings.rules.resultFilename":`Όνομα αρχείου`,"settings.rules.resultRejected":`Κρατήθηκε`,"settings.rules.resultAccepted":`Έγινε δεκτός`,"settings.rules.resultBy":`από {rule}`,"settings.rules.folderFromSettings":`από τις ρυθμίσεις λήψης`,"settings.rules.folderFromSettingsHint":`Κανένας κανόνας δεν όρισε φάκελο, οπότε ο σύνδεσμος καταλήγει στον ρυθμισμένο φάκελο λήψεων, ίσως μέσα σε υποφάκελο ανά πακέτο αν αυτή η ρύθμιση είναι ενεργή. Αυτή η σελίδα δεν μαντεύει την πλήρη διαδρομή. Το μόνο που μπορεί να πει με βεβαιότητα είναι ότι κανένας κανόνας δεν την άλλαξε.`,"settings.rules.alsoSets":`Ορίζει επίσης`,"settings.reconnect.method":`Μέθοδος`,"settings.reconnect.methodHint":`Ο τρόπος με τον οποίο λέγεται στον δρομολογητή να ρίξει τη γραμμή και να επιστρέψει με νέα διεύθυνση. Η «Εντολή» τρέχει ένα πρόγραμμα, τα «Αιτήματα» αναπαράγουν μια καταγεγραμμένη συνομιλία HTTP, το UPnP ρωτά την πύλη μέσω δικτύου χωρίς καμία σύνδεση, και το «Σενάριο» παραδίδει ένα αρχείο σε έναν διερμηνέα. Εμφανίζονται μόνο τα πεδία που χρειάζεται η μέθοδος που επιλέξατε· τα υπόλοιπα κρατούν ό,τι πληκτρολογήσατε και επανέρχονται όταν γυρίσετε σε αυτά.`,"settings.reconnect.method.command":`Εντολή`,"settings.reconnect.method.http":`Αιτήματα`,"settings.reconnect.method.upnp":`UPnP`,"settings.reconnect.method.script":`Σενάριο`,"settings.reconnect.offState":`Η επανασύνδεση είναι ανενεργή. Τίποτα δεν ζητά νέα διεύθυνση από τον δρομολογητή, και ένα όριο του hoster αφήνεται στη συνηθισμένη αναμονή μεταξύ των προσπαθειών.`,"settings.reconnect.command":`Πρόγραμμα`,"settings.reconnect.commandHint":`Η πλήρης διαδρομή του προγράμματος που θα εκτελεστεί. Ξεκινά απευθείας και όχι μέσω κελύφους, άρα μια διοχέτευση, μια ανακατεύθυνση ή δύο εντολές στη σειρά ανήκουν στη μέθοδο «Σενάριο». Τα %%router%%, %%username%%, %%password%% και %%ip%% συμπληρώνονται πριν την εκκίνηση.`,"settings.reconnect.args":`Ορίσματα`,"settings.reconnect.argsHint":`Ένα ανά γραμμή, ώστε ένα όρισμα με κενό να παραμείνει ένα όρισμα. Εδώ συμπληρώνονται οι ίδιες τέσσερις μεταβλητές.`,"settings.reconnect.upnpState":`Δεν χρειάζεται τίποτε άλλο. Η πύλη εντοπίζεται ρωτώντας το δίκτυο, οπότε αυτή είναι η μέθοδος που λειτουργεί χωρίς να ξέρεις τίποτα για τον δρομολογητή.`,"settings.reconnect.upnpLocation":`URL περιγραφής της πύλης`,"settings.reconnect.upnpLocationHint":`Προαιρετικό, και κανονικά κενό. Συμπληρώστε το μόνο εκεί όπου η αναζήτηση multicast φιλτράρεται ενώ η ίδια η πύλη είναι μια χαρά προσβάσιμη, κάτι που η ανίχνευση από μόνη της δεν μπορεί ποτέ να διορθώσει.`,"settings.reconnect.interpreter":`Διερμηνέας`,"settings.reconnect.interpreterHint":`Το πρόγραμμα στο οποίο παραδίδεται το σενάριο, με πλήρη διαδρομή: /bin/sh, /bin/bash, /usr/bin/python3.`,"settings.reconnect.interpreterArgs":`Ορίσματα διερμηνέα`,"settings.reconnect.interpreterArgsHint":`Ένα ανά γραμμή, τοποθετούνται πριν από το αρχείο του σεναρίου. Συνήθως κενό.`,"settings.reconnect.script":`Σενάριο`,"settings.reconnect.scriptHint":`Γράφεται σε ιδιωτικό προσωρινό αρχείο και στον διερμηνέα δίνεται η διαδρομή του, οπότε τίποτα από εδώ δεν καταλήγει ποτέ μέσα σε εισαγωγικά σε γραμμή εντολών. Οι μεταβλητές συμπληρώνονται πριν γραφτεί το αρχείο, που σημαίνει ότι ένας κωδικός πληκτρολογημένος σε αυτό το πλαίσιο φτάνει σε εκείνο το αρχείο: με %%password%% μένει στο πεδίο του κωδικού.`,"settings.reconnect.router":`Διεύθυνση δρομολογητή`,"settings.reconnect.routerHint":`Ο δρομολογητής στο δικό σας δίκτυο, χωρίς σχήμα: 192.168.1.1, όχι http://192.168.1.1/. Σε αυτό αναπτύσσεται το %%router%%. Δεν είναι η δημόσια διεύθυνση, και οι δύο δεν πρέπει ποτέ να μπερδευτούν: ένα αίτημα σύνδεσης στραμμένο στη δημόσια στέλνει τον κωδικό του δρομολογητή σας στο διαδίκτυο.`,"settings.reconnect.routerFind":`Βρες τον δρομολογητή μου`,"settings.reconnect.routerFinding":`Αναζήτηση…`,"settings.reconnect.routerFound":`Βρέθηκε {address}.`,"settings.reconnect.routerFoundVia":`Βρέθηκε {address} μέσω {iface}. Αξίζει μια ματιά: σε κοντέινερ αυτό είναι συχνά η γέφυρα και όχι ο δρομολογητής.`,"settings.reconnect.routerFailed":`Δεν διαβάστηκε καμία διεύθυνση δρομολογητή εδώ: {reason}`,"settings.reconnect.username":`Όνομα χρήστη δρομολογητή`,"settings.reconnect.usernameHint":`Τα στοιχεία σύνδεσης στον δρομολογητή, όχι λογαριασμός σε hoster. Σε αυτό αναπτύσσεται το %%username%%.`,"settings.reconnect.password":`Κωδικός δρομολογητή`,"settings.reconnect.passwordStored":`αποθηκευμένος, και δεν επιστρέφει ποτέ εδώ`,"settings.reconnect.passwordHint":`Ένας αποθηκευμένος κωδικός δεν στέλνεται ποτέ πίσω σε αυτή τη σελίδα, γι' αυτό και το πλαίσιο είναι κενό: αφήστε το κενό και ο αποθηκευμένος διατηρείται. Πληκτρολογήστε νέον για να τον αντικαταστήσετε. Για να τον αφαιρέσετε εντελώς, γράψτε κάτι και μετά αδειάστε ξανά το πλαίσιο.`,"settings.reconnect.requests":`Αιτήματα`,"settings.reconnect.requestsHint":`Αναπαράγονται με τη σειρά, και η εκτέλεση σταματά στο πρώτο που δεν απαντά ο δρομολογητής. Είναι η μέθοδος LiveHeader του JDownloader: συνήθως μια σύνδεση και μετά η επανεκκίνηση ή η αποσύνδεση. Κάθε πεδίο δέχεται τις μεταβλητές.`,"settings.reconnect.requestsEmpty":`Δεν υπάρχουν ακόμη αιτήματα. Προσθέστε ένα, ή επικολλήστε ένα καταγεγραμμένο σενάριο.`,"settings.reconnect.requestAdd":`Προσθήκη αιτήματος`,"settings.reconnect.requestStep":`Βήμα {n}`,"settings.reconnect.requestUp":`Μετακίνηση αυτού του αιτήματος πάνω`,"settings.reconnect.requestDown":`Μετακίνηση αυτού του αιτήματος κάτω`,"settings.reconnect.requestRemove":`Αφαίρεση αυτού του αιτήματος`,"settings.reconnect.requestMethod":`Μέθοδος`,"settings.reconnect.requestUrl":`URL`,"settings.reconnect.requestUrlHint":`Ολόκληρο το URL, μαζί με το σχήμα. Το http://%%router%%/login.cgi είναι η συνηθισμένη μορφή.`,"settings.reconnect.requestHeaders":`Κεφαλίδες`,"settings.reconnect.requestHeadersHint":`Μία ανά γραμμή, ως Όνομα: τιμή. Μια κεφαλίδα Host τηρείται και φτάνει όντως στο καλώδιο, κάτι που χρειάζονται τα firmware δρομολογητών που σερβίρουν τη σελίδα διαχείρισης ως εικονικό host.`,"settings.reconnect.requestBody":`Σώμα`,"settings.reconnect.requestBodyHint":`Στέλνεται όπως είναι. Ένα σώμα χωρίς δικό του τύπο περιεχομένου φεύγει ως υποβολή φόρμας, και αυτό ακριβώς είναι μια καταγεγραμμένη σύνδεση σε δρομολογητή.`,"settings.reconnect.import":`Εισαγωγή σεναρίου`,"settings.reconnect.importLabel":`Σενάριο LiveHeader ή curl`,"settings.reconnect.importHint":`Επικολλήστε ένα σενάριο επανασύνδεσης του JDownloader, μαζί με τους δείκτες του. Οι μεταβλητές του μεταφράζονται κατά την είσοδο, και το %%%routerip%%% γίνεται η διεύθυνση του δρομολογητή αντί για τη δημόσια, γιατί εδώ αυτά είναι δύο διαφορετικά πράγματα.`,"settings.reconnect.importRead":`Ανάγνωση σεναρίου`,"settings.reconnect.importReading":`Γίνεται ανάγνωση…`,"settings.reconnect.importClose":`Κλείσιμο`,"settings.reconnect.importMapped":`{n} αντιστοιχίστηκαν`,"settings.reconnect.importRefusedCount":`{n} απορρίφθηκαν`,"settings.reconnect.importUse":`Αντικατάσταση της λίστας με {n}`,"settings.reconnect.importLine":`Γραμμή {n}`,"settings.reconnect.importBlocked":`Από σενάριο που έχει μέσα μια απορριφθείσα γραμμή δεν κρατιέται τίποτα. Μισό σενάριο δρομολογητή είναι μια σύνδεση χωρίς επανεκκίνηση, και αυτό φαίνεται μέρες αργότερα, ως διεύθυνση που δεν αλλάζει ποτέ.`,"settings.reconnect.importFailed":`Το σενάριο δεν μπόρεσε να διαβαστεί: {reason}`,"settings.reconnect.checkTitle":`Έλεγχος της διεύθυνσης`,"settings.reconnect.checkUrl":`URL ελέγχου IP`,"settings.reconnect.checkUrlHint":`Ανακτάται πριν τρέξει η μέθοδος και ξανά μετά· η εκτέλεση θεωρείται ολοκληρωμένη μόλις αλλάξει η διεύθυνση που εμφανίζει. Δεν υπάρχει προεπιλογή: ένας διαχειριστής λήψεων που φιλοξενείς μόνος σου δεν πρέπει να αρχίσει να αναφέρει τη διεύθυνσή σου σε μια υπηρεσία που δεν διάλεξες ποτέ. Αυτό που εμφανίζει πρέπει να είναι η διεύθυνση που βλέπει το διαδίκτυο, γιατί μια σελίδα που επιστρέφει τη διεύθυνση του δικού σου δικτύου δεν μπορεί να ξεχωρίσει μια επανασύνδεση από μια εκτέλεση που δεν έκανε τίποτα.`,"settings.reconnect.checkPresets":`Γνωστές υπηρεσίες`,"settings.reconnect.checkPresetsHint":`Μια συντόμευση για όποιον δεν έχει προτίμηση, όχι προεπιλογή: καμία τους δεν επιλέγεται για εσάς, και οποιαδήποτε σελίδα τυπώνει τη δημόσια διεύθυνσή σας κάνει την ίδια δουλειά.`,"settings.reconnect.interval":`Δευτερόλεπτα μεταξύ των ελέγχων (1 έως 60)`,"settings.reconnect.intervalHint":`Πόσο αναμονή ανάμεσα σε δύο ματιές στο URL ελέγχου, αφού τρέξει η μέθοδος. Υπάρχει κατώτατο όριο, γιατί ένας βρόχος χωρίς αυτό μετατρέπει την υπηρεσία ελέγχου σε στόχο.`,"settings.reconnect.timeout":`Δευτερόλεπτα συνεχούς ελέγχου (5 έως 900)`,"settings.reconnect.timeoutHint":`How long to keep looking before the run is called a failure. A reconnect still waiting a quarter of an hour later has failed whatever this says. A timeout below the interval is raised to it, or the run would be over before a single check happened. The Command and Script methods give their program the same number of seconds to finish before the checking starts; one still running then is stopped, and the run fails.`,"settings.reconnect.clamped":`Αποθηκεύτηκε ως {n}.`,"settings.reconnect.runTitle":`Εκτέλεση μιας τώρα`,"settings.reconnect.runNow":`Επανασύνδεση τώρα`,"settings.reconnect.running":`Εκτελείται…`,"settings.reconnect.runMoved":`Η διεύθυνση πήγε από {from} σε {to}.`,"settings.reconnect.runDetail":`{n} έλεγχοι, {secs} δευτ.`,"settings.reconnect.runBusy":`Μια επανασύνδεση εκτελείται ήδη, οπότε αυτή δεν ξεκίνησε. Το αποτέλεσμα ανήκει σε όποιον ζήτησε την πρώτη.`,"settings.reconnect.runFailed":`Η επανασύνδεση δεν ολοκληρώθηκε: {reason}`,"settings.reconnect.stateConfigured":`Ρυθμισμένη`,"settings.reconnect.stateNotConfigured":`Μη ρυθμισμένη`,"settings.reconnect.stateIdle":`Αδρανής`,"settings.reconnect.stateBusy":`Εκτελείται τώρα`,"settings.reconnect.stateUnreadable":`Η κατάσταση της επανασύνδεσης δεν διαβάστηκε. Είναι προσβάσιμος ο διακομιστής;`,"settings.reconnect.notReady":`Δεν είναι έτοιμη: {reason}`,"settings.reconnect.reason.off":`Η επανασύνδεση είναι απενεργοποιημένη`,"settings.reconnect.reason.noCommand":`Η μέθοδος εντολής δεν έχει πρόγραμμα προς εκτέλεση`,"settings.reconnect.reason.noRequests":`Η μέθοδος αιτημάτων δεν έχει κανένα αίτημα`,"settings.reconnect.reason.requestNoURL":`Το αίτημα {n} δεν έχει URL`,"settings.reconnect.reason.noInterpreter":`Η μέθοδος σεναρίου δεν έχει διερμηνέα για να το εκτελέσει`,"settings.reconnect.reason.noScript":`Η μέθοδος σεναρίου δεν έχει σενάριο`,"settings.reconnect.reason.noCheckURL":`Δεν υπάρχει URL για τον έλεγχο IP`,"settings.reconnect.reason.unknownMethod":`Άγνωστη μέθοδος «{method}»`,"settings.reconnect.reason.noRouter":`Το σενάριο χρησιμοποιεί %%{var}%% αλλά δεν έχει οριστεί διεύθυνση δρομολογητή`,"settings.reconnect.runUsesSaved":`Εκτελείται το αποθηκευμένο, όχι αυτό που βλέπετε. Αποθηκεύστε πρώτα.`,"settings.reconnect.policy":`Πότε γίνεται από μόνη της`,"settings.reconnect.policyHint":`Οι αυτόματες επανασυνδέσεις πυροδοτούνται σε ένα και μόνο σημείο, και αυτή η σελίδα δεν είναι εκείνο. Μία ξεκινά όταν μια μηχανή λήψης ζητήσει η ίδια νέα προσπάθεια μετά από αναμονή, που είναι ο τρόπος με τον οποίο ένας hoster λέει ότι το όριο είναι δεμένο σε αυτή τη διεύθυνση. Δεν τρέχει ποτέ όσο η ουρά είναι σταματημένη, γιατί η επανεκκίνηση του δρομολογητή ρίχνει τις λήψεις που ακόμη τρέχουν. Δεν τρέχει ποτέ όσο η επανασύνδεση δεν είναι πλήρως ρυθμισμένη. Τρέχει μόνο μία κάθε φορά: ένα δεύτερο αίτημα περιμένει την ετυμηγορία του πρώτου αντί να του διεκδικεί τον δρομολογητή. Και αν η διεύθυνση δεν αλλάξει, τίποτα δεν επισπεύδεται και η συνηθισμένη αναμονή μεταξύ των προσπαθειών αφήνεται να τρέξει.`,"shell.bar":`Ουρά και γραμμή κατάστασης`,"shell.scope":`Ελέγχει`,"shell.scopeHint":`Η σελίδα από κάτω δείχνει αυτό το αδελφό στιγμιότυπο, οπότε και η γραμμή στοχεύει σε αυτό. Ένα αδελφό στιγμιότυπο κρατά τη δική του ουρά και το δικό του όριο ταχύτητας, γι’ αυτό ό,τι δεν μπορεί να προωθήσει αυτό εδώ το στιγμιότυπο εμφανίζεται ως μη διαθέσιμο αντί να εφαρμοστεί σε αυτό το μηχάνημα.`,"task.moveUp":`Μετακίνηση πάνω`,"task.moveDown":`Μετακίνηση κάτω`,"menu.priority":`Προτεραιότητα`,"menu.move":`Μετακίνηση`,"menu.forceStart":`Έναρξη τώρα`,"pkg.queueOrder":`Μετακίνηση όλου του πακέτου`,"priority.highest":`Ύψιστη`,"priority.higher":`Υψηλότερη`,"priority.high":`Υψηλή`,"priority.default":`Προεπιλογή`,"priority.low":`Χαμηλή`,"priority.lower":`Χαμηλότερη`,"priority.lowest":`Ελάχιστη`,"settings.chunks":`Συνδέσεις ανά λήψη (0 = αυτόματα)`,"settings.chunksHint":`Πόσες συνδέσεις ανοίγει μία λήψη όταν δεν ισχύει κάτι πιο συγκεκριμένο. Ένας κανόνας, ή μια μεμονωμένη λήψη, μπορεί να ορίσει δικό του αριθμό και υπερισχύει αυτού. Ένας πάροχος που αντέχει λιγότερες παίρνει έτσι κι αλλιώς λιγότερες: το όριο του παρόχου μπορεί μόνο να μειώσει τον αριθμό, ποτέ να τον αυξήσει. Με 0 αποφασίζει η εφαρμογή. Πάνω από μια χούφτα συνδέσεις δεν κερδίζουν τίποτα σε πάροχο που περιορίζει ανά αρχείο και είναι σίγουρος τρόπος να επισημανθεί ένας λογαριασμός.`,"task.chunks":`Συνδέσεις (0 = η γενική ρύθμιση)`,"task.chunksHint":`Πόσες συνδέσεις ανοίγει αυτή η μία λήψη. Υπερισχύει της γενικής ρύθμισης και κάθε κανόνα που την όρισε, αλλά ποτέ του παρόχου: ένας πάροχος που αντέχει λιγότερες παίρνει έτσι κι αλλιώς λιγότερες. Με 0 η εξαίρεση αίρεται και ο αριθμός αποφασίζεται ξανά αλλού.`,"columns.connection":`Σύνδεση`,"props.title":`Ιδιότητες`,"props.mixed":`Πολλές τιμές`,"props.mixedHint":`Αυτές οι γραμμές δεν συμφωνούν, γι’ αυτό το πλαίσιο είναι κενό. Αν δεν το αγγίξετε δεν αλλάζει τίποτα. Γράψτε μέσα και κάθε επιλεγμένη γραμμή παίρνει ό,τι γράψατε.`,"props.name":`Όνομα`,"props.nameHint":`Ένα όνομα αρχείου, ποτέ διαδρομή: ένα όνομα με / ή \\ απορρίπτεται. Μια ολοκληρωμένη λήψη μετονομάζεται και στον δίσκο, ώστε η λίστα και ο φάκελος να μην μπορούν να διαφωνούν. Μια λήψη σε εξέλιξη κρατά το αρχείο που έχει ανοιχτό το backend της και παίρνει το νέο όνομα όταν τελειώσει. Μια λήψη που δεν έχει ξεκινήσει το παίρνει αμέσως. Ένα όνομα ανήκει σε ένα αρχείο, οπότε αυτό το πεδίο προσφέρεται μόνο για μία γραμμή.`,"props.comment":`Σχόλιο`,"props.commentHint":`Η δική σου σημείωση για αυτόν τον σύνδεσμο. Αποθηκεύεται και εμφανίζεται στη λίστα· τίποτα στην εφαρμογή δεν ενεργεί βάσει αυτής.`,"props.priority":`Προτεραιότητα`,"props.priorityHint":`Η υψηλότερη τρέχει πρώτη. Αναδιατάσσει ό,τι περιμένει ακόμη. Μια λήψη που ήδη τρέχει δεν στέλνεται πίσω στην ουρά.`,"props.autoExtract":`Αποσυμπίεση αρχείων`,"props.autoExtractHint":`Αν ένα αρχείο αποσυμπιέζεται μόλις τελειώσει η λήψη. Η «Κληρονόμηση» αφήνει την απόφαση στη σελίδα ρυθμίσεων αρχείων, που δεν είναι το ίδιο με το «Ανενεργό». Ο διακόπτης διαβάζεται τη στιγμή της αποσυμπίεσης, οπότε αν τον ανάψεις τώρα αποσυμπιέζεται και κάτι που τελείωσε νωρίτερα.`,"props.inherit":`Κληρονόμηση`,"props.on":`Ενεργό`,"props.off":`Ανενεργό`,"strip.label":`Σύνολα λήψεων`,"strip.of":`από`,"strip.hint":`Byte που ήρθαν έναντι byte που οφείλονται. Οι ολοκληρωμένοι, οι αποτυχημένοι και οι συλλεγμένοι σύνδεσμοι μένουν εκτός συνόλου, όπως και ό,τι δεν έχει ακόμα δηλώσει ο hoster το μέγεθός του, γιατί μια εκτίμηση εκεί θα ήταν ένας αριθμός με τον οποίο κανείς δεν μπορεί να κάνει τίποτα.`,"strip.scope":`Τι καλύπτουν οι αριθμοί`,"strip.total":`Σύνολο`,"strip.visible":`Ορατά`,"strip.selected":`Επιλεγμένα`,"strip.includeDisabled":`Να μετρώνται και τα ανενεργά`,"strip.includeDisabledHint":`Μετρά τα byte των συνδέσμων που είναι σβηστοί. Από τον χρόνο που απομένει μένουν εκτός έτσι κι αλλιώς: κανείς δεν πρόκειται να τους φέρει, οπότε καμία αναμονή δεν τους ξεμπερδεύει.`,"quick.title":`Γρήγορες ρυθμίσεις`,"quick.reconnectHint":`Ζητά από τον δρομολογητή νέα δημόσια διεύθυνση με τον τρόπο που ορίζει η σελίδα Δίκτυο.`,"quick.reconnectOff":`Η Επανασύνδεση είναι απενεργοποιημένη στη σελίδα Λειτουργικές μονάδες.`,"quick.reconnectUnset":`Δεν έχει ρυθμιστεί ακόμη επανασύνδεση. Διάλεξε πρώτα μέθοδο στη σελίδα Δίκτυο.`,"quick.schedulesOff":`Τα «Χρονοδιαγράμματα» είναι απενεργοποιημένα στη σελίδα Λειτουργικές μονάδες.`,"quick.autoStartHint":`Οι σύνδεσμοι που προσθέτεις αρχίζουν να κατεβαίνουν χωρίς να περιμένουν να τους επιβεβαιώσεις στον συλλέκτη. Πόσο περιμένουν πρώτα ορίζεται στη σελίδα {page}.`,"quick.idleCommandSetup":`Ρύθμιση της εντολής στη σελίδα Αυτοματοποίηση`,"quick.openPage":`Άνοιγμα σελίδας {page}`,"folders.title":`Επιλέξτε φάκελο`,"folders.browse":`Περιήγηση στους φακέλους`,"folders.path":`Διαδρομή`,"folders.up":`Ένα επίπεδο επάνω`,"folders.use":`Χρήση αυτού του φακέλου`,"folders.empty":`Δεν υπάρχουν υποφάκελοι εδώ.`,"folders.new":`Αυτός ο φάκελος δεν υπάρχει ακόμη. Δημιουργείται μόλις προσγειωθεί μέσα του η πρώτη λήψη.`,"folders.newWatch":`Αυτός ο φάκελος δεν υπάρχει ακόμη, και δεν τον δημιουργεί τίποτα από μόνο του. Τα αρχεία που θα μπουν μέσα του παραλαμβάνονται μόλις υπάρξει. Με το «Νέος φάκελος» τον δημιουργείς αμέσως.`,"folders.tail":`Διατηρείται`,"folders.tailHint":`Η περιήγηση αντικαθιστά μόνο το σταθερό μέρος του φακέλου. Οι μεταβλητές μπαίνουν ξανά στο τέλος, οπότε το σχήμα ονομασίας σας δεν χάνεται.`,"folders.roots":`Ρίζες`,"folders.truncated":`Εμφανίζονται μόνο οι πρώτοι {n} φάκελοι. Πληκτρολογήστε μια διαδρομή για να πάτε κατευθείαν σε έναν.`,"folders.newFolder":`Νέος φάκελος`,"folders.newFolderHint":`Δημιουργεί έναν κενό φάκελο μέσα σε αυτόν που φαίνεται παραπάνω, στο μηχάνημα όπου τρέχει το KnightLoader.`,"folders.newName":`Όνομα του νέου φακέλου`,"folders.create":`Δημιουργία`,"folders.error.exists":`Υπάρχει ήδη εδώ κάτι με το όνομα «{name}».`,"folders.error.denied":`Το KnightLoader δεν επιτρέπεται να γράψει εδώ. Έλεγξε σε ποιον ανήκει αυτός ο φάκελος και τα δικαιώματά του.`,"folders.error.outside":`Αυτός ο φάκελος βρίσκεται έξω από τις ρίζες που επιτρέπεται να χρησιμοποιεί αυτό το στιγμιότυπο.`,"folders.error.missing":`Αυτός ο φάκελος δεν υπάρχει πια. Ανέβα ένα επίπεδο και δοκίμασε ξανά.`,"folders.error.separator":`Ένα όνομα δεν μπορεί να περιέχει / ή \\. Δημιούργησε ένα επίπεδο κάθε φορά.`,"folders.error.dots":`Τα «.» και «..» δεν μπορούν να είναι ονόματα φακέλων.`,"folders.error.character":`Ένα όνομα δεν μπορεί να περιέχει < > : " | ? * ή χαρακτήρες ελέγχου.`,"folders.error.trailing":`Ένα όνομα δεν μπορεί να τελειώνει σε τελεία ή κενό.`,"folders.error.reserved":`Το «{name}» είναι δεσμευμένο στα Windows και δεν μπορεί να είναι όνομα φακέλου.`,"folders.error.tooLong":`Αυτό το όνομα είναι πολύ μεγάλο. Το όριο είναι 255 byte.`,"folders.error.relative":`Πληκτρολόγησε πλήρη διαδρομή που ξεκινά από την κορυφή, όπως / ή C:\\.`,"folders.error.unreachable":`Ούτε σε αυτή τη διαδρομή ούτε πιο πάνω υπάρχει φάκελος που μπορεί να ανοίξει το KnightLoader.`,"folders.error.unreadable":`Το KnightLoader δεν επιτρέπεται να ανοίξει αυτόν τον φάκελο. Έλεγξε σε ποιον ανήκει και τα δικαιώματά του.`,"folders.error.roots":`Το KL_BROWSE_ROOTS έχει οριστεί αλλά δεν ονομάζει κανέναν απόλυτο φάκελο, οπότε δεν υπάρχει τίποτα για περιήγηση. Διόρθωσε τη μεταβλητή και κάνε επανεκκίνηση.`,"archive.menu":`Συμπιεσμένο`,"archive.unpackNow":`Αποσυμπίεση τώρα`,"archive.stop":`Διακοπή αποσυμπίεσης`,"archive.queued":`Αναμένει αποσυμπίεση`,"archive.failed":`Δεν αποσυμπιέστηκε`,"archive.volumes":`{volumes} τόμοι`,"archive.needsPassword":`Χρειάζεται κωδικό`,"settings.archives.handles":`Ανοίγει`,"settings.archives.destination":`Αποσυμπίεση σε`,"settings.archives.destinationHint":`Πού προσγειώνονται τα αποσυμπιεσμένα αρχεία. Αφήστε το κενό και μπαίνουν δίπλα στο συμπιεσμένο.`,"settings.archives.besideArchive":`Δίπλα στο συμπιεσμένο`,"settings.archives.subfolder":`Ένας φάκελος ανά πακέτο`,"settings.archives.subfolderHint":`Βάζει κάθε πακέτο σε δικό του φάκελο κάτω από τον προορισμό. Δεν κάνει τίποτα όσο τα αρχεία προσγειώνονται δίπλα στο συμπιεσμένο, όπου ο φάκελος του πακέτου είναι ήδη ο προορισμός τους.`,"settings.archives.collision":`Αν υπάρχει ήδη αρχείο`,"settings.archives.collisionHint":`Τι κάνει ο αποσυμπιεστής όταν στον φάκελο υπάρχει ήδη αρχείο με αυτό το όνομα. Αποφασίζει μόνος του, και για ολόκληρο τον φάκελο: στη μέση μιας αποσυμπίεσης δεν υπάρχει κανείς να ρωτήσει.`,"settings.archives.collision.overwrite":`Αντικατάσταση`,"settings.archives.collision.rename":`Διατήρηση και των δύο`,"settings.archives.collision.skip":`Παράλειψη`,"settings.archives.afterwards":`Μετά`,"settings.archives.disposal":`Το ίδιο το συμπιεσμένο`,"settings.archives.disposalHint":`Τι απογίνεται το συμπιεσμένο μόλις αποσυμπιεστεί. Σε ένα container δεν υπάρχει κάδος ανακύκλωσης, οπότε η μεσαία απάντηση είναι μια μετακίνηση στο {folder} δίπλα στα αρχεία, που σαρώνεται αργότερα κατά ηλικία.`,"settings.archives.disposal.keep":`Διατήρηση`,"settings.archives.disposal.trash":`Μετακίνηση στον κάδο`,"settings.archives.disposal.delete":`Διαγραφή`,"settings.archives.retention":`Άδειασμα του κάδου μετά από (ημέρες)`,"settings.archives.retentionHint":`Πόσο μένει ένα συμπιεσμένο στο {folder} πριν το πάρει η σάρωση. Με 0 δεν σαρώνεται τίποτα, οπότε ο φάκελος αδειάζει με το χέρι.`,"settings.archives.infoFiles":`Πάρε και τις σημειώσεις δίπλα`,"settings.archives.infoFilesHint":`Αρχεία που ήρθαν μαζί με το συμπιεσμένο και όχι από μέσα του, όπως .nfo, .sfv και .txt. Αγγίζονται μόνο τα αρχεία του ίδιου του πακέτου και ποτέ ολόκληρος ο φάκελος: στην προεπιλεγμένη διάταξη ένας φάκελος κρατά πολλές κυκλοφορίες, και μια σάρωση που διάβαζε τον φάκελο θα έπαιρνε τις σημειώσεις των γειτόνων.`,"settings.archives.optionsFailed":`Δεν ήταν δυνατή η λήψη των λιστών του ίδιου του αποσυμπιεστή, οπότε οι επιλογές που προέρχονται από αυτόν δεν εμφανίζονται.`,"accounts.accountLabel":`Όνομα λογαριασμού`,"accounts.accountLabelHint":`Αυτή η υπηρεσία έχει ήδη έναν προεπιλεγμένο λογαριασμό. Ονομάστε αυτόν για να προσθέσετε μια δεύτερη σύνδεση δίπλα του.`,"accounts.accountLabelPlaceholder":`π.χ. δουλειά`,"accounts.buyPremium":`Αγορά Premium`,"accounts.changeAccount":`Επιλογή άλλου λογαριασμού`,"accounts.col.enabled":`Ενεργό`,"accounts.col.expiry":`Λήξη`,"accounts.col.label":`Ετικέτα`,"accounts.col.service":`Υπηρεσία`,"accounts.col.status":`Κατάσταση`,"accounts.col.tier":`Πλάνο`,"accounts.col.traffic":`Απομένουσα κίνηση`,"accounts.tier.premium":`Premium`,"accounts.tier.free":`Δωρεάν`,"accounts.trafficLeftOf":`Απομένουν {left} από {total}`,"accounts.trafficLeftPercent":`Απομένει {n}%`,"accounts.trafficUsedTotal":`{used} έχουν ληφθεί`,"accounts.trafficUnknown":`Αυτή η υπηρεσία δεν αναφέρει όγκο.`,"accounts.credentialFromEnv":`Ορίζεται από τη μεταβλητή περιβάλλοντος {env} του container. Αφαιρέστε τη εκεί για να το αλλάξετε.`,"accounts.debrid.empty":`Δεν υπάρχουν ακόμη λογαριασμοί debrid`,"accounts.debrid.emptyHint":`Πρόσθεσε έναν λογαριασμό σε μία από τις υποστηριζόμενες υπηρεσίες debrid για να ξεκλειδώνονται αυτόματα οι σύνδεσμοι των hoster.`,"accounts.debrid.title":`Λογαριασμοί debrid`,"accounts.debrid.viaJD":`μέσω JDownloader`,"accounts.debrid.hint":`Μια υπηρεσία debrid είναι ένας πληρωμένος λογαριασμός που ξεκλειδώνει πολλούς filehoster μαζί. Το KnightLoader της στέλνει τον σύνδεσμο και κατεβάζει τον απευθείας σύνδεσμο που παίρνει πίσω, με πλήρη ταχύτητα και χωρίς αναμονή ή captcha. Είναι ο προτεινόμενος τρόπος, γιατί η εναλλακτική είναι ξεχωριστός premium λογαριασμός σε κάθε hoster. Ορισμένες υπηρεσίες είναι προσβάσιμες μόνο μέσω του ενσωματωμένου JDownloader, που τότε αναλαμβάνει τη σύνδεση. Οι γραμμές τους το αναφέρουν.`,"accounts.edit":`Επεξεργασία διαπιστευτηρίου`,"accounts.editCredentialTitle":`Επεξεργασία διαπιστευτηρίου για {service}`,"accounts.enableAccount":`Ενεργοποίηση {account}`,"accounts.hoster.empty":`Δεν υπάρχουν ακόμη λογαριασμοί hoster`,"accounts.hoster.title":`Λογαριασμοί hoster`,"accounts.hoster.hint":`Ο δικός σου premium λογαριασμός σε έναν μόνο hoster. Τα στοιχεία δίνονται στον ενσωματωμένο JDownloader, που κάνει τη σύνδεση. Χρησιμοποίησέ το για hoster που δεν καλύπτει καμία από τις debrid υπηρεσίες σου. Απενεργοποίησε μια γραμμή για να μείνει η σύνδεση αποθηκευμένη και να μη χρησιμοποιείται.`,"accounts.newAccount":`Προσθήκη λογαριασμού`,"accounts.addAccountTitle":`Προσθήκη του λογαριασμού σου στο {service}`,"accounts.noServicesFound":`Καμία υπηρεσία δεν ταιριάζει με την αναζήτησή σας.`,"accounts.passwordField":`Κωδικός`,"accounts.pickDebridAccount":`Επιλογή λογαριασμού debrid`,"accounts.refresh":`Ανανέωση`,"accounts.refreshing":`Ανανέωση…`,"accounts.remove":`Αφαίρεση`,"accounts.removeConfirm":`Τα αποθηκευμένα στοιχεία σύνδεσης για {name} διαγράφονται από αυτό το στιγμιότυπο και δεν μπορούν να ανακτηθούν, οπότε θα έπρεπε να εισαχθούν ξανά.`,"accounts.removed":`Αφαιρέθηκε.`,"accounts.rename":`Μετονομασία`,"accounts.renew":`Ανανέωση συνδρομής`,"accounts.rowActions":`Ενέργειες λογαριασμού`,"accounts.save":`Αποθήκευση`,"accounts.saveAnyway":`Αποθήκευση ούτως ή άλλως`,"accounts.saving":`Αποθήκευση…`,"accounts.usernameField":`Όνομα χρήστη`,"accounts.field.email":`Διεύθυνση email`,"accounts.field.customerId":`Αριθμός πελάτη`,"accounts.field.apiKey":`Κλειδί API`,"accounts.field.apiUser":`Όνομα χρήστη API`,"accounts.verifyFailed":`Δεν ήταν δυνατή η επαλήθευση: {detail}`,"accounts.verifying":`Επαλήθευση…`,"accounts.whereToFind":`Από πού το βρίσκω αυτό;`,"accounts.hostsRefreshed":`Η λίστα hoster ανανεώθηκε {when}`,"accounts.routing.priorityTitle":`Σειρά προτεραιότητας`,"accounts.routing.orderHint":`Ποια υπηρεσία ρωτιέται πρώτη όταν περισσότερες από μία μπορούν να κατεβάσουν τον ίδιο σύνδεσμο. Σύρε μια γραμμή για να τη μετακινήσεις.

Η σειρά αποφασίζει μόνο ανάμεσα σε υπηρεσίες που μπορούν καθόλου να πάρουν τον σύνδεσμο. Ένας σύνδεσμος filehoster δεν πηγαίνει ποτέ στην «Άμεση λήψη» ή στην «Απλή εναλλακτική HTTP», όπου κι αν βρίσκονται, αφού και οι δύο θα αποθήκευαν μόνο τη σελίδα του hoster.`,"accounts.routing.priorityEmpty":`Δεν έχουν καταχωριστεί ακόμη resolvers.`,"accounts.routing.moveUp":`Μετακίνηση πάνω`,"accounts.routing.moveDown":`Μετακίνηση κάτω`,"accounts.routing.priorityAuto":`Αυτόματα`,"accounts.routing.priorityAutoHint":`Απορρίπτει τη δική σου σειρά και επιστρέφει στην αυτόματη. Η αυτόματη σειρά ακολουθεί τις αλλαγές, όπως ένα νέο κλειδί debrid ή έναν λογαριασμό που γίνεται premium, ενώ η δική σου μένει ακριβώς όπως την άφησες.`,"accounts.routing.dragHandle":`Μετακίνηση {name}`,"accounts.routing.jdHint":`Ο ενσωματωμένος, αόρατος JDownloader που ανοίγει κρυπτογραφημένα containers και καλύπτει hosts που κανένας άλλος resolver δεν καλύπτει.`,"accounts.routing.jdNotConfigured":`Μη ρυθμισμένο`,"accounts.routing.jdReachable":`Προσβάσιμο, αναθεώρηση {version}`,"accounts.routing.jdUnreachable":`Μη προσβάσιμο`,"resolver.direct":`Άμεση λήψη`,"resolver.http":`Απλή εναλλακτική HTTP`,"resolver.torrent":`Torrent και magnet`,"accounts.routing.tip.jd":`Κατεβάζει συνδέσμους filehoster χωρίς λογαριασμό, με την αναμονή και το captcha, και παίρνει κάθε σύνδεσμο που δεν μπορεί να ανοίξει καμία άλλη υπηρεσία.`,"accounts.routing.tip.ytdlp":`Κατεβάζει βίντεο και ήχο από ιστότοπους όπως το YouTube, στην ποιότητα που διαλέγεις.`,"accounts.routing.tip.direct":`Κατεβάζει έναν σύνδεσμο που δείχνει κατευθείαν σε αρχείο. Οι σύνδεσμοι filehoster δεν έρχονται ποτέ εδώ, ούτε οι ιστότοποι βίντεο όσο τρέχει το yt-dlp, όπου κι αν βάλεις αυτή τη γραμμή.`,"accounts.routing.tip.login":`Ο δικός σου λογαριασμός σε αυτόν τον hoster. Ο JDownloader συνδέεται με αυτόν.`,"accounts.hoster.col.host":`Hoster`,"accounts.hoster.col.username":`Όνομα χρήστη`,"accounts.hoster.status.active":`Ενεργό`,"accounts.hoster.detail.adding":`Περιμένει να δεχτεί ο JDownloader αυτή τη σύνδεση.`,"accounts.hoster.detail.checking":`Ο JDownloader ελέγχει ακόμη αυτή τη σύνδεση.`,"accounts.hoster.detail.invalid":`Ο JDownloader δεν μπόρεσε να επιβεβαιώσει αυτή τη σύνδεση. Έλεγξε το όνομα χρήστη και τον κωδικό πρόσβασης.`,"accounts.hoster.detail.off":`Απενεργοποιημένο, οπότε ο JDownloader δεν χρησιμοποιεί αυτή τη σύνδεση.`,"accounts.hoster.detail.waiting":`Περιμένει τον επόμενο έλεγχο.`,"accounts.hoster.enableLogin":`Χρήση της σύνδεσης για το {host}`,"accounts.hoster.status.off":`Ανενεργό`,"accounts.hoster.status.queued":`Σε αναμονή`,"accounts.hoster.status.rejected":`Απορρίφθηκε`,"accounts.hoster.removed":`Αφαιρέθηκε.`,"accounts.hoster.pickAccount":`Επιλογή λογαριασμού hoster`,"accounts.hoster.searchHosts":`Αναζήτηση hoster…`,"accounts.hoster.passwordCustody":`Ο κωδικός πρόσβασης πηγαίνει στο backend του JDownloader, που τον αποθηκεύει και κάνει την ίδια τη σύνδεση. Το ίδιο το KnightLoader δεν τον κρατά.`,"captcha.title":`Απαιτείται captcha`,"captcha.titleMore":`Απαιτείται captcha (ακόμη {n} σε αναμονή)`,"captcha.forHost":`Το {host} ζητά captcha πριν αυτή η λήψη μπορέσει να συνεχίσει.`,"captcha.answerLabel":`Απάντηση`,"captcha.answerPlaceholder":`Πληκτρολογήστε ό,τι βλέπετε…`,"captcha.clickHint":`Κάντε κλικ σε κάθε σημείο που ζητά η εικόνα και μετά πατήστε Συνέχεια.`,"captcha.clickCount":`Σημεία που έχουν επισημανθεί: {n}`,"captcha.clickClear":`Εκκαθάριση σημείων`,"captcha.widgetHint":`Λύσε την πρόκληση παρακάτω. Η διαδικασία συνεχίζει μόνη της μόλις το κάνεις.`,"captcha.widgetScoreHint":`Δεν χρειάζεται να πατήσεις τίποτα. Η υπηρεσία captcha ελέγχει αυτόν τον περιηγητή και παραδίδει μόνη της την απάντησή της.`,"captcha.widgetUnavailable":`Αυτή η πρόκληση δεν μπόρεσε να φορτωθεί.`,"captcha.widgetUnreachable":`Ο περιηγητής σου δεν μπόρεσε να φτάσει στην υπηρεσία captcha. Ίσως την μπλοκάρει ένα πρόγραμμα αποκλεισμού διαφημίσεων ή ένα φίλτρο δικτύου. Η «Ανανέωση» δοκιμάζει ξανά.`,"captcha.widgetRefused":`Η υπηρεσία captcha αρνήθηκε να τρέξει εδώ και ανέφερε {code}. Πολλοί hoster δένουν το captcha τους με τον δικό τους ιστότοπο, οπότε μπορεί να μη φορτώνει καθόλου στο KnightLoader. Η «Ανανέωση» δοκιμάζει ξανά, και το «Άκυρο» παραλείπει αυτό το captcha.`,"captcha.unsupported":`Το KnightLoader δεν μπορεί να εμφανίσει αυτό το είδος πρόκλησης (αναφέρθηκε ως {vendor}).`,"captcha.unsolvable":`Το KnightLoader δεν μπορεί να λύσει αυτό το captcha.`,"captcha.unsolvableVendor":`Ο JDownloader δεν είπε ποια υπηρεσία captcha είναι αυτή, και το KnightLoader δεν μαντεύει. Το «Άκυρο» παραλείπει αυτό το captcha.`,"captcha.unsolvableAction":`Αυτός είναι έλεγχος reCAPTCHA v3, και ο JDownloader δεν μετέφερε την ενέργεια που ζητά ο hoster. Μια απάντηση χωρίς αυτήν θα απορριπτόταν. Το «Άκυρο» παραλείπει αυτό το captcha.`,"captcha.unsupportedHint":`Χρησιμοποιήστε το Άκυρο παρακάτω, ή αποκλείστε τα captcha αυτού του hoster για αυτήν τη συνεδρία.`,"captcha.continue":`Συνέχεια`,"captcha.cancel":`Άκυρο`,"captcha.refresh":`Ανανέωση`,"captcha.moreOptions":`Περισσότερες επιλογές`,"captcha.blockHoster":`Να σταματήσει επίσης η ερώτηση για {host} σε αυτήν τη συνεδρία`,"captcha.blockEverywhere":`Να σταματήσει επίσης η ερώτηση για κάθε hoster σε αυτήν τη συνεδρία`,"captcha.tooLate":`Αυτή η απάντηση έφτασε πολύ αργά.`,"captcha.networkError":`Δεν ήταν δυνατή η επικοινωνία με τον διακομιστή. Δοκιμάστε ξανά.`,"captcha.timedOut":`Το captcha για το {host} έληξε.`,"captcha.resolvedElsewhere":`Το captcha για το {host} λύθηκε αλλού.`,"settings.captcha.title":`Captcha`,"settings.captcha.orderTitle":`Σειρά επιλυτών`,"settings.captcha.orderHint":`Κάθε ενεργοποιημένος επιλυτής παρακάτω δοκιμάζεται με τη σειρά που φαίνεται, από πάνω προς τα κάτω. Αν κανένας δεν είναι ενεργοποιημένος, ή αν όλοι αποτύχουν ή αρνηθούν, θα ερωτηθείτε απευθείας.`,"settings.captcha.orderEmpty":`Δεν είναι ενεργός κανένας επιλυτής, οπότε κάθε captcha έρχεται κατευθείαν σε σένα.`,"settings.captcha.enableSolver":`Αυτόματη δοκιμή {service}`,"settings.captcha.moveUp":`Μετακίνηση πάνω`,"settings.captcha.moveDown":`Μετακίνηση κάτω`,"settings.captcha.set":`Το κλειδί έχει οριστεί`,"settings.captcha.notSet":`Δεν έχει οριστεί κλειδί`,"settings.captcha.setKey":`Ορισμός κλειδιού`,"settings.captcha.change":`Αλλαγή`,"settings.captcha.remove":`Αφαίρεση`,"settings.captcha.cancel":`Άκυρο`,"settings.captcha.save":`Αποθήκευση`,"settings.captcha.saving":`Αποθήκευση…`,"settings.captcha.placeholder":`Επικολλήστε το κλειδί API`,"settings.captcha.saved":`Το κλειδί API αποθηκεύτηκε.`,"settings.captcha.removed":`Το κλειδί API αφαιρέθηκε.`,"settings.captcha.saveFailed":`Δεν ήταν δυνατή η αποθήκευση του κλειδιού: {error}`,"collector.options":`Επιλογές`,"collector.destination":`Φάκελος προορισμού`,"collector.destinationRecent":`Πρόσφατα χρησιμοποιημένα`,"collector.archivePasswordHint":`Δοκιμάζεται πριν από τη λίστα που είναι αποθηκευμένη στις Ρυθμίσεις, όταν ένα αρχείο σε αυτήν την παρτίδα είναι κρυπτογραφημένο.`,"collector.linkPassword":`Κωδικός συνδέσμου`,"collector.linkPasswordHint":`Ο κωδικός που ζητά η ίδια η σελίδα του hoster πριν δώσει το αρχείο. Ο κωδικός αρχείου συμπίεσης παραπάνω είναι άλλος.`,"collector.overrule":`Παράκαμψη αντίστοιχου κανόνα Packagizer`,"collector.overruleHint":`Όταν είναι ανενεργό, ένας κανόνας Packagizer που ταιριάζει υπερισχύει της προτεραιότητας, της αποσυμπίεσης και του σχολίου παραπάνω. Όταν είναι ενεργό, υπερισχύουν αυτές οι τιμές. Ο προορισμός δεν επηρεάζεται ποτέ: ισχύει πάντα όπως πληκτρολογήθηκε.`,"collector.facets.title":`Φίλτρα`,"collector.facets.hint":`Περιορίζει τη συγκεντρωμένη λίστα ανάλογα με το πού οδηγεί ένας σύνδεσμος, τι τύπος αρχείου είναι ή σε ποιο πακέτο κατέληξε.`,"collector.facets.fileType":`Τύπος αρχείου`,"collector.facets.clearAll":`Καθαρισμός`,"collector.facets.unknownHost":`Άγνωστος πάροχος`,"collector.facets.type.archive":`Συμπιεσμένα`,"collector.facets.type.video":`Βίντεο`,"collector.facets.type.audio":`Ήχος`,"collector.facets.type.image":`Εικόνες`,"collector.facets.type.document":`Έγγραφα`,"collector.facets.type.other":`Άλλο`,"collector.stats.label":`Σύνολα συλλέκτη`,"collector.stats.packages":`Πακέτα`,"collector.stats.links":`Σύνδεσμοι`,"collector.stats.totalSize":`Συνολικό μέγεθος`,"collector.stats.hosts":`Πάροχοι`,"settings.preParser":`Αναζήτηση συνδέσμων στο επικολλημένο ή αφημένο κείμενο`,"settings.preParserHint":`Βρίσκει συνδέσμους οπουδήποτε σε ό,τι επικολλάς ή αφήνεις, όχι μόνο ένα καθαρό URL ανά γραμμή. Ενώνει ξανά έναν σύνδεσμο που ένα πρόγραμμα αλληλογραφίας έσπασε σε δύο γραμμές και διαβάζει ως σύνδεσμο και ένα σκέτο όνομα host με διαδρομή χωρίς http:// μπροστά. Όταν είναι ανενεργό, παίρνει κάθε γραμμή ακριβώς όπως πληκτρολογήθηκε, όπως λειτουργούσε πάντα.`,"intake.pasteButton":`Επικόλληση από το πρόχειρο`,"intake.clipboardWatch":`Παρακολούθηση προχείρου`,"intake.clipboardWatchHint":`Κάθε σύνδεσμος που αντιγράφεις οπουδήποτε πηγαίνει κατευθείαν στον συλλέκτη, όσο αυτή η καρτέλα είναι ανοιχτή και σε πρώτο πλάνο. Το Ctrl+V μέσα στο KnightLoader δουλεύει πάντα και δεν χρειάζεται τίποτα από αυτά.`,"intake.clipboardWatchUnavailable":`Δεν είναι διαθέσιμο εδώ: ο περιηγητής επιτρέπει σε μια σελίδα να διαβάσει το πρόχειρο μόνο μέσω HTTPS ή σε localhost. Το Ctrl+V μέσα στο KnightLoader δουλεύει ούτως ή άλλως.`,"intake.clipboardWatchDenied":`Η παρακολούθηση προχείρου απενεργοποιήθηκε: {reason}`,"collector.hosterPresetHint":`Ποιες παραλλαγές των συνδέσμων από το {host} δείχνει ο συλλέκτης και με ποια μορφή και ποιότητα ξεκινούν οι νέοι σύνδεσμοι. Μόλις ελεγχθεί ένας σύνδεσμος, περνά στο δικό του κομμάτι που είναι πιο κοντά στην επιλογή. Ένας σύνδεσμος χωρίς αυτή τη μορφή βίντεο παίρνει το καλύτερο βίντεό του έως αυτή την ποιότητα, και σε έναν χωρίς αυτή τη μορφή ήχου ο ήχος μετατρέπεται.`,"activity.crawl":`Σάρωση σελίδων`,"activity.linkcheck":`Έλεγχος συνδέσμων`,"activity.captcha":`Captcha`,"activity.autoconfirm":`Αυτόματη επιβεβαίωση`,"activity.container":`Κοντέινερ`,"activity.pending":`{n} σε αναμονή`,"activity.ofTotal":`{n} από {total}`,"activity.tooltipHint":`{active} ενεργά από {total} σε αυτόν τον γύρο`,"activity.stop":`Διακοπή αυτής της εκτέλεσης`,"activity.autoconfirmStop":`Διακοπή αντίστροφης μέτρησης`,"activity.autoconfirmCountdown":`Αυτοί οι σύνδεσμοι μεταφέρονται στη λίστα λήψεων όταν λήξει η αντίστροφη μέτρηση. Σταμάτησέ την και μένουν στον συλλέκτη.`,"notifications.quiet":`Αθόρυβη λειτουργία`,"notifications.quietHint":`Αποκρύπτει τις ειδοποιήσεις επιτυχίας και ενημέρωσης. Ένα σφάλμα, ένα captcha που σας περιμένει ή ένας λογαριασμός σε αναστολή εξακολουθούν να εμφανίζονται.`,"task.tooltip.url":`URL`,"task.tooltip.changed":`Τελευταία τροποποίηση`,"task.tooltip.infoHash":`Hash`,"task.tooltip.trackers":`Trackers`,"task.tooltip.swarm":`Ομότιμοι / seeds / αναλογία`,"task.tooltip.swarmDetail":`{peers} ομότιμοι, {seeds} seeds, αναλογία {ratio}`,"task.tooltip.uploaded":`Μεταφορτώθηκε`,"task.tooltip.seeding":`Συνεχίζει το seeding`,"columns.peers":`Ομότιμοι`,"columns.seeds":`Seeds`,"columns.ratio":`Αναλογία`,"columns.variant":`Παραλλαγή`,"columns.variant.video":`Βίντεο`,"columns.variant.audio":`Ήχος`,"columns.variant.thumbnail":`Μικρογραφία`,"columns.variant.subtitle":`Υπότιτλοι`,"columns.variant.description":`Περιγραφή`,"columns.variant.auto":`Αυτόματο`,"columns.variant.kbps":`{kbps} kbit/s`,"file.open":`Άνοιγμα`,"file.openNatively":`Άνοιγμα με την προεπιλεγμένη εφαρμογή`,"file.revealInFolder":`Εμφάνιση στον φάκελο`,"file.desktopOnly":`Μόνο στην εφαρμογή επιφάνειας εργασίας`,"settings.schedule.subtitle":`Παύση, συνέχιση ή περιορισμός της ταχύτητας λήψης σύμφωνα με χρονοδιάγραμμα.`,"settings.schedule.statusTitle":`Κατάσταση χρονοδιαγραμμάτων`,"settings.schedule.orderHint":`Τα χρονοδιαγράμματα εφαρμόζονται με τη σειρά, από πάνω προς τα κάτω, και όπου δύο επικαλύπτονται κερδίζει αυτό που είναι πιο κάτω. Έτσι, ένα ευρύ «παύση κάθε βράδυ» πάνω από μια στενή εξαίρεση αφήνει την εξαίρεση σε ισχύ, ενώ τα ίδια δύο ανάποδα όχι.`,"settings.schedule.add":`Δημιουργία χρονοδιαγράμματος`,"settings.schedule.empty":`Δεν υπάρχουν ακόμα χρονοδιαγράμματα`,"settings.schedule.emptyHint":`Τίποτα δεν θέτει σε παύση ούτε περιορίζει την ουρά με βάση την ώρα. Δημιούργησε ένα χρονοδιάγραμμα για να κρατάς τις λήψεις τη νύχτα ή να περιορίζεις την ταχύτητα όσο χρησιμοποιείς εσύ τη σύνδεση.`,"settings.schedule.use":`Χρήση αυτού του χρονοδιαγράμματος`,"settings.schedule.moveUp":`Μετακίνηση επάνω`,"settings.schedule.moveDown":`Μετακίνηση κάτω`,"settings.schedule.remove":`Αφαίρεση αυτού του χρονοδιαγράμματος`,"settings.schedule.edit":`Επεξεργασία αυτού του χρονοδιαγράμματος`,"settings.schedule.name":`Όνομα`,"settings.schedule.namePlaceholder":`π.χ. Νυχτερινή παύση`,"settings.schedule.days":`Ημέρες`,"settings.schedule.daysHint":`Οι ημέρες της εβδομάδας που ξεκινά αυτό το χρονοδιάγραμμα. Για ένα που περνά τα μεσάνυχτα, τσέκαρε την ημέρα που ξεκινά: το «Παρ 22:00-06:00» τελειώνει το πρωί του Σαββάτου χωρίς να είναι τσεκαρισμένο το Σάββατο.`,"settings.schedule.preset.every":`Κάθε ημέρα`,"settings.schedule.preset.weekdays":`Καθημερινές`,"settings.schedule.preset.weekends":`Σαββατοκύριακα`,"settings.schedule.preset.custom":`Προσαρμοσμένο`,"settings.schedule.start":`Έναρξη`,"settings.schedule.end":`Λήξη`,"settings.schedule.endHint":`Μια ώρα λήξης πριν από την ώρα έναρξης σημαίνει ότι το χρονοδιάγραμμα περνά τα μεσάνυχτα και τελειώνει το επόμενο πρωί. Μια ώρα λήξης ίδια με την ώρα έναρξης απορρίπτεται, γιατί θα μπορούσε να σημαίνει ολόκληρη ημέρα ή καθόλου χρόνο.`,"settings.schedule.action":`Ενέργεια`,"settings.schedule.action.pause":`Παύση`,"settings.schedule.action.resume":`Συνέχιση`,"settings.schedule.action.limit":`Περιορισμός ταχύτητας`,"settings.schedule.limit":`Όριο ταχύτητας`,"settings.schedule.disabledOff":`Αυτό το χρονοδιάγραμμα είναι απενεργοποιημένο και δεν εκτελείται ποτέ. Η ουρά συμπεριφέρεται σαν να μην υπήρχε.`,"settings.schedule.activeNow":`Ενεργό τώρα, έως {time}`,"settings.schedule.next":`Επόμενο: {when}`,"settings.schedule.never":`Δεν ενεργοποιείται ποτέ όπως έχει ρυθμιστεί`,"settings.schedule.stateNow.paused":`Ένα χρονοδιάγραμμα κρατά την ουρά σε παύση αυτή τη στιγμή.`,"settings.schedule.stateNow.limited":`Ένα χρονοδιάγραμμα περιορίζει την ουρά στα {rate} αυτή τη στιγμή.`,"settings.schedule.stateNow.running":`Κανένα χρονοδιάγραμμα δεν ισχύει αυτή τη στιγμή.`,"settings.schedule.nextChange":`Επόμενη αλλαγή: {when}`,"settings.schedule.noNextChange":`Όπως έχουν ρυθμιστεί, κανένα από τα χρονοδιαγράμματα δεν θα αλλάξει ποτέ την ουρά.`,"settings.schedule.stateNow.suspendedUntil":`Τα χρονοδιαγράμματα έχουν ανασταλεί έως {when}.`,"settings.schedule.stateNow.suspendedOpen":`Τα χρονοδιαγράμματα έχουν ανασταλεί μέχρι να τα ενεργοποιήσεις ξανά.`,"settings.schedule.suspend":`Αναστολή χρονοδιαγραμμάτων`,"settings.schedule.suspendHint":`Βάζει όλα τα χρονοδιαγράμματα στην άκρη για λίγο, χωρίς να αλλάξει κανένα. Στο μεταξύ η ουρά τρέχει με τις δικές σου ρυθμίσεις, και μόλις περάσει ο χρόνος τα χρονοδιαγράμματα ισχύουν ξανά από μόνα τους. Μια επανεκκίνηση δεν τερματίζει την αναστολή.`,"settings.schedule.suspend.off":`Χωρίς αναστολή`,"settings.schedule.suspend.hour":`Για μία ώρα`,"settings.schedule.suspend.threeHours":`Για τρεις ώρες`,"settings.schedule.suspend.midnight":`Μέχρι τα μεσάνυχτα`,"settings.schedule.suspend.open":`Μέχρι να τα ενεργοποιήσεις ξανά`,"settings.schedule.suspend.until":`Έως {when}`,"settings.schedule.suspendNone":`Δεν έχει ρυθμιστεί ακόμη κανένα χρονοδιάγραμμα, οπότε δεν υπάρχει τίποτα για αναστολή.`,"settings.schedule.suspendParked":`Ο διακόπτης «Χρονοδιαγράμματα» παρακάτω είναι σβηστός, οπότε δεν υπάρχει τίποτα για αναστολή.`,"settings.schedule.saveFailed":`Δεν ήταν δυνατή η αποθήκευση των χρονοδιαγραμμάτων: {error}`,"settings.schedule.rowError":`Γραμμή {row}: {error}`,"idleAction.title":`Η ουρά είναι ανενεργή`,"idleAction.action.pause":`Τίθεται σε παύση`,"idleAction.actionFallback":`«{action}» σε εξέλιξη`,"idleAction.in":`σε {countdown}`,"idleAction.cancel":`Ακύρωση`,"idleAction.cancelling":`Ακύρωση σε εξέλιξη…`,"idleAction.cancelFailed":`Η ακύρωση απέτυχε: ο διακομιστής δεν απάντησε.`,"settings.nav.diagnostics":`Διαγνωστικά`,"settings.diagnostics.subtitle":`Τι είναι αυτό το build, σε τι τρέχει και η πρόσφατη έξοδος καταγραφής του, για επισύναψη σε αναφορά σφάλματος.`,"settings.diagnostics.version":`Έκδοση`,"settings.diagnostics.deployment":`Build`,"settings.diagnostics.deployment.container":`Κοντέινερ`,"settings.diagnostics.deployment.desktop":`Επιφάνεια εργασίας`,"settings.diagnostics.goVersion":`Go`,"settings.diagnostics.platform":`Πλατφόρμα`,"settings.diagnostics.goroutines":`Goroutines`,"settings.diagnostics.download":`Λήψη πακέτου διαγνωστικών`,"settings.diagnostics.downloading":`Προετοιμασία…`,"settings.diagnostics.downloadHint":`Ένα αρχείο JSON με τα παραπάνω πεδία, τις ρυθμίσεις σας με κάθε κωδικό πρόσβασης αφαιρεμένο, και τις γραμμές καταγραφής παρακάτω.`,"settings.diagnostics.downloadFailed":`Δεν ήταν δυνατή η δημιουργία του πακέτου: {error}`,"settings.diagnostics.logTitle":`Πρόσφατες γραμμές καταγραφής`,"settings.diagnostics.logHint":`Οι τελευταίες {n} γραμμές που έχει καταγράψει αυτή η διεργασία, οι παλαιότερες πρώτα. Τίποτα εδώ δεν γράφεται στον δίσκο.`,"settings.diagnostics.logEmpty":`Δεν έχει καταγραφεί ακόμη τίποτα.`,"settings.diagnostics.refresh":`Ανανέωση`,"settings.diagnostics.loadFailed":`Δεν ήταν δυνατή η φόρτωση των διαγνωστικών. Είναι προσβάσιμος ο διακομιστής;`,"settings.nav.help":`Βοήθεια`,"settings.help.intake.title":`Προσθήκη λήψεων`,"settings.help.intake.body":`Επικόλλησε συνδέσμους στον Συλλέκτη, έναν ανά γραμμή ή ως ακατάστατο κείμενο. Μια σάρωση βρίσκει συνδέσμους όπου κι αν βρίσκονται: μέσα σε μια πρόταση, πολλούς σε μία γραμμή ή σπασμένους σε δύο γραμμές από ένα πρόγραμμα αλληλογραφίας.`,"settings.help.intake.b1":`Αφήστε ένα αρχείο κοντέινερ συνδέσμων (.dlc, .ccf, .rsdf) ή μια απλή λίστα συνδέσμων.`,"settings.help.intake.b2":`Τα κουμπιά Click'n'Load σε σελίδες hoster και φόρουμ λειτουργούν χωρίς αλλαγές. Το KnightLoader απαντά στο 127.0.0.1:9666, την ίδια θύρα που χρησιμοποιεί κάθε άλλος διαχειριστής λήψεων.`,"settings.help.intake.b3":`Επικολλήστε ένα URL σελίδας αντί για σύνδεσμο αρχείου και ενεργοποιήστε την Ανίχνευση για να εξαγάγετε κάθε αρχείο στο οποίο παραπέμπει, αντί να κατεβάσετε την ίδια τη σελίδα.`,"settings.help.intake.link1":`Άνοιγμα ρυθμίσεων Συλλέκτη συνδέσμων`,"settings.help.collector.title":`Ο Συλλέκτης, πριν κατέβει οτιδήποτε`,"settings.help.collector.body":`Οι νέοι σύνδεσμοι φτάνουν πρώτα στον Συλλέκτη, όχι στην ουρά: μια ενδιάμεση ζώνη για τον έλεγχο ονομάτων, μεγεθών και προειδοποιήσεων διπλότυπων πριν ξεκινήσει οτιδήποτε. Η αυτόματη επιβεβαίωση μπορεί να παραλείψει αυτό το βήμα, με προαιρετική καθυστέρηση· μόλις επιβεβαιωθεί, ένας σύνδεσμος είτε ξεκινά αμέσως είτε περιμένει στην ουρά, ανάλογα με την αυτόματη εκκίνηση.`,"settings.help.collector.link":`Άνοιγμα ρυθμίσεων Συλλέκτη συνδέσμων`,"settings.help.rules.title":`Κανόνες: πακέτα, φάκελοι και τι διατηρείται`,"settings.help.rules.body":`Ο Packagizer μετονομάζει έναν σύνδεσμο, διαλέγει τον φάκελό του και ορίζει τις επιλογές λήψης του καθώς φτάνει, με βάση συνθήκες που γράφεις εσύ. Το Φίλτρο συνδέσμων αποφασίζει αν ένας σύνδεσμος κρατιέται καθόλου. Μια απόρριψη αναφέρει πάντα τον κανόνα που την προκάλεσε και γιατί.`,"settings.help.rules.link":`Άνοιγμα Κανόνων`,"settings.help.queue.title":`Διαχείριση ουράς`,"settings.help.queue.body":`Θέσε σε παύση, συνέχισε ή αναδιάταξε οποιονδήποτε σύνδεσμο, μόνο του ή ως ολόκληρο πακέτο. Η ουρά σταματά με δύο τρόπους. Η αναστολή αφήνει ανέγγιχτο ό,τι ήδη τρέχει, ώστε να τελειώσει μόνο του. Η άμεση διακοπή όλων των μεταφορών δείχνει πρώτα τι θα χαθεί και προχωρά μόνο όταν επιβεβαιώσεις. Η προειδοποίηση υπάρχει για μεταφορές που δεν μπορούν να συνεχίσουν από εκεί που σταμάτησαν.`,"settings.help.queue.b1":`Ένας μεμονωμένος σύνδεσμος μπορεί να παρακάμψει τον γενικό αριθμό συνδέσεων ή τον διακόπτη εξαγωγής μετά τη λήψη.`,"settings.help.queue.b2":`Ένα διπλότυπο ενός συνδέσμου που ήδη υπάρχει στη λίστα απορρίπτεται πάντα, πριν καν φτάσει στον Συλλέκτη.`,"settings.help.limits.title":`Παράκαμψη ορίων φιλοξενίας`,"settings.help.limits.body":`Τρεις ανεξάρτητοι τρόποι για να μην αποτελεί ένα δωρεάν όριο το ταβάνι:`,"settings.help.limits.b1":`Συνδέσεις: μοίρασε τις λήψεις σε περισσότερες από μία εξερχόμενες διαδρομές (μια δεύτερη γραμμή, ένα proxy, SOCKS) αντί να βγαίνεις πάντα από τη διεύθυνση αυτού του μηχανήματος.`,"settings.help.limits.b2":`Επανασύνδεση: ζήτα από τον δρομολογητή νέα δημόσια διεύθυνση, το μόνο που αίρει ένα όριο δεμένο στην ίδια τη διεύθυνση. Γίνεται μέσω UPnP, ενός εξωτερικού προγράμματος, ενός σεναρίου ή με επανάληψη αιτημάτων HTTP προς τη σελίδα διαχείρισης του δρομολογητή. Τα υπάρχοντα σενάρια LiveHeader/curl του JDownloader λειτουργούν χωρίς αλλαγές.`,"settings.help.limits.b3":`Λογαριασμοί: αποθήκευσε στοιχεία σύνδεσης premium ή debrid (Real-Debrid, AllDebrid, TorBox και άλλα) ώστε ένας σύνδεσμος που το επιτρέπει να κατεβαίνει με πλήρη ταχύτητα αντί για το όριο των δωρεάν χρηστών.`,"settings.help.limits.link1":`Άνοιγμα Δικτύου`,"settings.help.limits.link3":`Άνοιγμα Λογαριασμών`,"settings.help.captcha.title":`Captcha`,"settings.help.captcha.body":`Όταν ένας hoster ζητά captcha, δοκιμάζονται πρώτα οι αυτόματοι επιλυτές που έχεις ρυθμίσει, με τη σειρά που όρισες. Αν δεν έχει ρυθμιστεί κανένας ή κανένας δεν μπορεί να το λύσει, το captcha εμφανίζεται σε σένα αντί να αποτύχει σιωπηλά.`,"settings.help.captcha.link":`Άνοιγμα ρυθμίσεων Captcha`,"settings.help.after.title":`Μετά τη λήψη`,"settings.help.after.body":`Τα αρχεία συμπίεσης αποσυμπιέζονται αυτόματα: zip (και κρυπτογραφημένα, τόσο WinZip AES όσο και το παλιό ZipCrypto), rar με σύνολα πολλαπλών τόμων, 7z, tar, καθώς και gzip/bzip2/xz/zstd, είτε περιέχουν tar είτε όχι. Η αποσυμπίεση είναι καθαρή Go και δεν χρειάζεται εξωτερικό πρόγραμμα unrar ή 7z. Για ένα κρυπτογραφημένο αρχείο δοκιμάζεται μια λίστα κωδικών με τη σειρά. Ένα ολοκληρωμένο αρχείο ελέγχεται με όποιο checksum το συνοδεύει: μια λίστα .sfv, ένα αρχείο md5/sha1/sha256sum ή ένα CRC32 που περιέχει το ίδιο το όνομα της κυκλοφορίας.`,"settings.help.after.link1":`Άνοιγμα ρυθμίσεων Αρχείων συμπίεσης`,"settings.help.after.link2":`Άνοιγμα ρυθμίσεων Λήψεων`,"settings.help.schedule.title":`Λειτουργία χωρίς επίβλεψη`,"settings.help.schedule.body":`Ένα εβδομαδιαίο χρονοπρόγραμμα θέτει σε παύση ή περιορίζει την ουρά με βάση την ώρα, για παράδειγμα σε ένα νυχτερινό παράθυρο, και μένει σωστό και κατά την αλλαγή της ώρας. Είναι η ίδια ιδέα με τον Scheduler του JDownloader.`,"settings.help.schedule.link":`Άνοιγμα Αυτοματοποίησης`,"settings.help.instances.title":`Εκτέλεση περισσότερων από μία περιπτώσεων`,"settings.help.instances.body":`Πρόσθεσε ένα ακόμη KnightLoader ως ομότιμο και η ουρά του εμφανίζεται και σε αυτόν τον πίνακα. Στο ίδιο δίκτυο πρόκειται για απευθείας κλήση στο API της άλλης εγκατάστασης, όπως θα έκανε ένας περιηγητής. Ανάμεσα σε δίκτυα, δώδεκα λέξεις τις ζευγαρώνουν μέσω ενός relay που μπορείς να φιλοξενήσεις μόνος σου.`,"settings.help.instances.link":`Άνοιγμα Περιπτώσεων`,"settings.help.access.title":`Πρόσβαση και αντιμετώπιση προβλημάτων`,"settings.help.access.body":`Ένας κωδικός πρόσβασης κλειδώνει ολόκληρη τη διεπαφή, και η πρόσβαση μένει μόνο με cookie συνεδρίας. Η σελίδα Απομακρυσμένη πρόσβαση παραθέτει επίσης τις θύρες εισόδου συνδέσμων και τους τρόπους πρόσβασης που έχει αυτό το build και γιατί υπάρχει ο καθένας, ώστε να μπορείς να βρεις κάθε ανοιχτή θύρα που δεν περίμενες. Η σελίδα Διαγνωστικά φτιάχνει ένα αρχείο για επισύναψη σε αναφορά σφάλματος: έκδοση και στοιχεία build, τις τρέχουσες ρυθμίσεις χωρίς κανέναν κωδικό, τις πρόσφατες γραμμές καταγραφής αυτής της ίδιας της διεργασίας και πόσες goroutines τρέχουν.`,"settings.help.access.link1":`Άνοιγμα Απομακρυσμένης πρόσβασης`,"settings.help.access.link2":`Άνοιγμα Διαγνωστικών`,"settings.help.advanced.title":`Όλα τα υπόλοιπα`,"settings.help.advanced.body":`Κάθε ρύθμιση αυτού του build μπορεί να διαβαστεί και να αλλάξει με το εσωτερικό της όνομα στη σελίδα Για προχωρημένους. Αυτό περιλαμβάνει και μερικές που δεν έχουν ακόμα δικό τους στοιχείο ελέγχου πουθενά αλλού, όπως το πώς αντιμετωπίζεται ένας καθρέφτης ενός αρχείου που έχει ήδη κατέβει και τι γίνεται όταν μια λήψη θα κατέληγε σε όνομα που ήδη υπάρχει.`,"settings.help.advanced.link":`Άνοιγμα ρυθμίσεων Για προχωρημένους`,"task.mode.free":`Δωρεάν`,"task.mode.premium":`Premium`,"settings.about.title":`Σχετικά με το KnightLoader`,"settings.about.body":`Ένας ιππότης, μία σταυροφορία: προσεγμένα εργαλεία ανοιχτού κώδικα που δεν υπήρχαν στη μορφή που ήθελα, φτιαγμένα μέχρι να μη λείπει τίποτα. Όλα δωρεάν, χωρίς λογαριασμούς, χωρίς τηλεμετρία, χωρίς διαφημίσεις και χωρίς επί πληρωμή επίπεδα. Πουθενά αστερίσκος. Τίποτα αναγνώσιμο δεν φεύγει ποτέ από τα δικά σου τείχη. Σφυρηλατημένα τα βράδια και τα σαββατοκύριακα, με καρδιά και πείσμα.`,"settings.about.coffeeButton":`Κέρασέ με έναν καφέ`,"settings.about.crypto":`Κρύπτο`,"settings.about.paypal":`PayPal`,"settings.about.cryptoTitle":`Δωρεά με κρύπτο`,"settings.about.donateAppeal":`Ρίξε ένα νόμισμα στον ιππότη σου: καλύπτει μέρος των εξόδων και κρατά το έργο ζωντανό. Ό,τι φτιάχνω είναι δωρεάν και χωρίς διαφημίσεις.`,"settings.about.cryptoIntro":`Διάλεξε κρυπτονόμισμα και δίκτυο, μετά σάρωσε τον κωδικό ή αντίγραψε τη διεύθυνση.`,"settings.about.cryptoNetworks":`Δίκτυα`,"settings.about.cryptoNoTag":`Δεν χρειάζεται destination tag ούτε memo.`,"settings.about.coffeeIntro":`Η πληρωμή γίνεται μέσω Buy Me a Coffee. Δεν χρειάζεσαι λογαριασμό.`,"settings.about.paypalIntro":`Η πληρωμή γίνεται μέσω PayPal, με τον λογαριασμό σου στο PayPal ή με κάρτα χωρίς λογαριασμό.`,"settings.about.paypalFrequency":`Πόσο συχνά`,"settings.about.paypalOnce":`Μία φορά`,"settings.about.paypalMonthly":`Μηνιαία`,"settings.about.paypalYearly":`Ετήσια`,"settings.about.paypalAmount":`Ποσό`,"settings.about.paypalOtherAmount":`Άλλο ποσό`,"settings.about.paypalLoading":`Φόρτωση PayPal…`,"settings.about.paypalThanks":`Ευχαριστώ, η δωρεά σου έφτασε.`,"settings.about.paypalFailed":`Το PayPal δεν είναι διαθέσιμο αυτή τη στιγμή. Δοκίμασε ξανά αργότερα ή διάλεξε άλλο τρόπο.`,"common.copy":`Αντιγραφή`,"common.copied":`Αντιγράφηκε`,"settings.about.coffee":`Αν το KnightLoader κέρδισε τη θέση του στον διακομιστή ή στον υπολογιστή σου, ρίξε ένα νόμισμα στον ιππότη σου: βοηθά να καλυφθούν τα έξοδα και κρατά το έργο ζωντανό. Και κάνει την καρδιά αυτού του ιππότη να χτυπά λίγο πιο γρήγορα. Πιο κάτω υπάρχουν τρεις δρόμοι, διάλεξε αυτόν που σου ταιριάζει.`,"settings.about.report":`Προβλήματα, επιθυμίες ή προτάσεις; Άνοιξε ένα ζήτημα στο GitHub ή στείλε ένα email.`,"settings.about.version":`Έκδοση`,"settings.about.github":`GitHub`,"settings.about.mail":`Email`,"settings.about.mailSubject":`Σχόλια`,"settings.scripts.add":`Προσθήκη σεναρίου`,"settings.scripts.empty":`Δεν υπάρχουν ακόμη σενάρια`,"settings.scripts.emptyHint":`Ένα σενάριο τρέχει τη δική σου JavaScript όταν συμβαίνει κάτι, όπως όταν τελειώνει μια λήψη, όταν αποτυγχάνει μια λήψη ή όταν η ουρά μένει αδρανής. Μπορείς επίσης να το τρέξεις όποτε θέλεις, από τη «Δοκιμαστική εκτέλεση» εδώ ή από την επιλογή «Εκτέλεση σεναρίου» στο μενού δεξιού κλικ της λίστας λήψεων. Πρόσθεσε ένα για να ξεκινήσεις.`,"settings.scripts.loadFailed":`Δεν ήταν δυνατή η φόρτωση των σεναρίων. Αν αυτό το build δεν περιλαμβάνει ακόμα τη μηχανή αυτοματισμού, αυτή η σελίδα δεν έχει τίποτα να δείξει. Δοκίμασε ξανά όταν την περιλαμβάνει.`,"settings.scripts.name":`Όνομα`,"settings.scripts.namePlaceholder":`π.χ. Ειδοποίηση σε αποτυχία`,"settings.scripts.unnamed":`Ανώνυμο σενάριο {n}`,"settings.scripts.trigger":`Εκτελείται σε`,"settings.scripts.triggerHint":`Τι ξεκινά αυτό το σενάριο. Με το Χειροκίνητο τρέχει μόνο όταν το ζητήσεις: από τη «Δοκιμαστική εκτέλεση» παρακάτω ή από την επιλογή «Εκτέλεση σεναρίου» στο μενού δεξιού κλικ της λίστας λήψεων.`,"settings.scripts.trigger.manual":`Χειροκίνητο (μόνο κατ’ απαίτηση)`,"settings.scripts.trigger.taskDone":`Μια λήψη ολοκληρώνεται`,"settings.scripts.trigger.taskFailed":`Μια λήψη αποτυγχάνει`,"settings.scripts.trigger.queueIdle":`Η ουρά αδρανοποιείται`,"settings.scripts.use":`Ενεργοποίηση αυτού του σεναρίου`,"settings.scripts.code":`Κώδικας`,"settings.scripts.starter":`// Αυτό το σενάριο τρέχει με το συμβάν που επιλέχθηκε παραπάνω.
// Το log(...) γράφει μια γραμμή στην «Έξοδο» και το notify(message) στέλνει ειδοποίηση.
// Τα trigger και queue υπάρχουν πάντα· τα task, pkg, extraction, reconnect,
// account και captcha μόνο όταν τα φέρνει το συμβάν.
`,"settings.scripts.timeout":`Χρονικό όριο`,"settings.scripts.timeoutHint":`Πόση ώρα μπορεί να εκτελείται αυτό το σενάριο πριν σταματήσει. Μεταξύ 100 ms και 30 s· το 0 χρησιμοποιεί την προεπιλογή των 5000 ms.`,"settings.scripts.timeoutUnit":`ms`,"settings.scripts.saveFailed":`Δεν ήταν δυνατή η αποθήκευση: {error}`,"settings.scripts.remove":`Αφαίρεση`,"settings.scripts.removeNew":`Άκυρο`,"settings.scripts.removeFailed":`Δεν ήταν δυνατή η αφαίρεση: {error}`,"settings.scripts.unsaved":`Μη αποθηκευμένο`,"settings.scripts.run":`Δοκιμαστική εκτέλεση`,"settings.scripts.running":`Εκτελείται…`,"settings.scripts.runNeedsSaveHint":`Δώσε του ένα όνομα ή λίγο κώδικα για να δημιουργηθεί, μετά δοκίμασέ το εδώ.`,"settings.scripts.runDirtyHint":`Οι αλλαγές σου αποθηκεύονται ακόμα. Η δοκιμαστική εκτέλεση θα τις χρησιμοποιήσει σε λίγο.`,"settings.scripts.ranIn":`Εκτελέστηκε επιτυχώς σε {duration}`,"settings.scripts.runTimedOut":`Διακόπηκε: διήρκεσε περισσότερο από το χρονικό του όριο`,"settings.scripts.runFailed":`Απέτυχε: {error}`,"settings.scripts.output":`Έξοδος`,"task.runScript":`Εκτέλεση σεναρίου`,"task.runScriptUnnamed":`Ανώνυμο σενάριο`,"task.runScriptDone":`Το «{name}» εκτελέστηκε`,"task.runScriptFailed":`Το «{name}» απέτυχε: {error}`,"settings.access.relay.title":`Αναμεταδότης του έργου`,"settings.access.relay.body":`Το relay είναι ένας μεσάζων που κάνει όλες τις εγκαταστάσεις σου προσβάσιμες έξω από το οικιακό δίκτυο, άρα από παντού. Αυτό το παρέχει το έργο δωρεάν.`,"settings.access.relay.use":`Χρήση του αναμεταδότη του έργου`,"settings.access.relay.leadProject":`Λειτουργεί χωρίς ρυθμίσεις. Ό,τι λένε μεταξύ τους τα στιγμιότυπά σου είναι κρυπτογραφημένο, και το κλειδί το έχεις μόνο εσύ.`,"settings.access.relay.seesButton":`Τι βλέπει;`,"settings.access.relay.seesTip":`Δεν είναι ορατά στο relay: οι σύνδεσμοί σου, οι λήψεις σου, τα αρχεία σου και το διακριτικό πρόσβασής σου.

Είναι ορατά στο relay: οι διευθύνσεις IP των instances σου και πότε στέλνουν κάτι.

Αυτό δεν κρυπτογραφείται. Αν σε ενοχλεί, στήσε δικό σου relay.`,"settings.access.relay.seesAddress":`Ο αναμεταδότης του έργου τρέχει στο {address}.`,"settings.access.relay.none":`Χωρίς αναμεταδότη`,"settings.access.relay.noneHint":`Κανένα relay ενεργό. Στο ίδιο δίκτυο, δηλαδή στο σπίτι σου, οι εγκαταστάσεις εξακολουθούν να βρίσκονται μόνες τους. Ανάμεσα σε διαφορετικά δίκτυα δεν φτάνουν η μία στην άλλη, άρα δεν υπάρχει απομακρυσμένη πρόσβαση.`,"settings.access.relay.own":`Δικός σου αναμεταδότης`,"settings.access.relay.project":`Αναμεταδότης του έργου`,"settings.access.relay.whichHint":`Περνάει από {address}`,"settings.access.relay.savedProject":`Ο αναμεταδότης του έργου είναι ενεργός`,"settings.access.relay.savedOwn":`Ο δικός σου αναμεταδότης είναι ενεργός`,"settings.access.relay.savedOff":`Ο αναμεταδότης απενεργοποιήθηκε`,"settings.access.ownRelay.title":`Ο δικός σου αναμεταδότης`,"settings.access.ownRelay.body":`Τρέξε δικό σου relay αντί για αυτό του έργου.`,"settings.access.ownRelay.use":`Χρήση του δικού μου αναμεταδότη`,"settings.access.ownRelay.lead":`Δύο δρόμοι: αυτό το στιγμιότυπο αναλαμβάνει τον αναμεταδότη, ή δίνεις μια διεύθυνση.`,"settings.access.ownRelay.serveLabel":`Χρήση αυτής της εγκατάστασης ως relay`,"settings.access.ownRelay.serveHint":`Λειτουργεί μόνο αν αυτή η εγκατάσταση είναι προσβάσιμη από έξω, για παράδειγμα μέσω Nginx Proxy Manager και δικού σου domain.`,"settings.access.ownRelay.serveClients":`{count} συνδεδεμένα αυτή τη στιγμή.`,"settings.access.ownRelay.addressLabel":`Διεύθυνση`,"settings.access.ownRelay.addressPlaceholder":`π.χ. https://relay.mydomain.tld`,"settings.access.ownRelay.save":`Αποθήκευση`,"settings.access.ownRelay.everyInstance":`Αυτή η διεύθυνση ισχύει μόνο για αυτό το στιγμιότυπο. Καταχώρισέ την σε καθένα.`,"settings.access.ownRelay.containerLabel":`Ως ξεχωριστό κοντέινερ`,"settings.access.ownRelay.containerHint":`Αν κανένα από τα στιγμιότυπά σου δεν είναι προσβάσιμο απ' έξω, το relay πρέπει να βρίσκεται κάπου αλλού, στον διακομιστή σου ή σε ένα μικρό VPS. Εγκατάστησε το container από τα Unraid Community Applications ή με την παρακάτω εντολή.

Το container δεν χρειάζεται ρύθμιση: ξεκίνα το, γράψε τη διεύθυνσή του παραπάνω και τέλος. Δεν αποθηκεύει τίποτα, οπότε δεν υπάρχει τίποτα για αντίγραφο ασφαλείας.`,"settings.access.tokens.title":`Διακριτικά API`,"settings.access.tokens.intro":`Επώνυμα διαπιστευτήρια για ένα σενάριο, μια επέκταση περιηγητή ή ένα τηλέφωνο. Καθένα μπορεί να ανακληθεί ξεχωριστά, χωρίς να αλλάξει ο κοινόχρηστος κωδικός πρόσβασης που χρησιμοποιεί κάθε άλλος πελάτης.`,"settings.access.tokens.empty":`Δεν έχει εκδοθεί ακόμη κανένα διακριτικό.`,"settings.access.tokens.new":`Νέο διακριτικό`,"settings.access.tokens.namePlaceholder":`π.χ. το τηλέφωνό μου`,"settings.access.tokens.cancel":`Άκυρο`,"settings.access.tokens.create":`Δημιουργία`,"settings.access.tokens.creating":`Δημιουργία…`,"settings.access.tokens.created":`Δημιουργήθηκε`,"settings.access.tokens.lastUsed":`Τελευταία χρήση`,"settings.access.tokens.neverUsed":`ποτέ`,"settings.access.tokens.revoke":`Ανάκληση`,"settings.access.tokens.secretTitle":`Αντιγράψτε αυτό το διακριτικό τώρα`,"settings.access.tokens.secretWarning":`Αυτή είναι η μόνη φορά που εμφανίζεται αυτό το διακριτικό. Αποθηκεύεται ως μονόδρομος κατακερματισμός σε αυτήν την περίπτωση, οπότε αν χαθεί δεν υπάρχει τρόπος να το διαβάσετε ξανά, μόνο να το ανακαλέσετε και να δημιουργήσετε ένα νέο.`,"settings.access.tokens.copy":`Αντιγραφή`,"settings.access.tokens.copied":`Αντιγράφηκε`,"settings.access.tokens.done":`Τέλος`,"settings.access.tokens.howToUse":`Στείλτε το ως κεφαλίδα: Authorization: Bearer <token>`,"settings.access.tokens.createFailed":`Δεν ήταν δυνατή η δημιουργία του διακριτικού: {error}`,"settings.access.identity.title":`Ταυτότητα αυτής της παρουσίας`,"settings.access.identity.nameLabel":`Όνομα`,"settings.access.identity.namePlaceholder":`π.χ. Οικιακός διακομιστής`,"settings.access.identity.nameHint":`Προτείνεται πρώτο κατά τη σύζευξη και στον κωδικό QR παρακάτω, αντί για όποιο όνομα δίνει τυχαία το λειτουργικό σύστημα ή το περιβάλλον container σε αυτό το μηχάνημα. Προαιρετικό: άφησέ το κενό για να κρατήσεις εκείνο το όνομα.`,"settings.access.identity.domainsLabel":`Γνωστοί τομείς`,"settings.access.identity.domainsHint":`Κάθε domain απομνημονεύεται αυτόματα την πρώτη φορά που φτάνει αίτημα μέσω αυτού και παραμένει εδώ ακόμα κι όταν τα επόμενα αιτήματα έρχονται από την IP του LAN. Πρόσθεσε ένα domain με το χέρι αν είναι ήδη ρυθμισμένο αλλά δεν έχει έρθει ακόμα κανένα αίτημα μέσω αυτού. Μία πλήρης διεύθυνση ανά γραμμή, π.χ. https://kl.example.com.`,"settings.access.cardTitle":`Σύνδεση παρουσιών και απομακρυσμένη πρόσβαση`,"settings.access.phrase.body":`Μία φράση συνδέει κάθε KnightLoader που τρέχεις. Δημιούργησέ την εδώ και μετά επικόλλησέ την στα άλλα στιγμιότυπά σου. Δεν χρειάζεσαι λογαριασμό ή σύνδεση, και δεν υπάρχει τίποτα να ρυθμίσεις.`,"settings.access.phrase.noPasswordWarning":`Αυτό το στιγμιότυπο δεν έχει κωδικό. Η φράση φτάνει σε κάθε στιγμιότυπο που συνδέετε μαζί της, οπότε όποιος τη διαβάσει εδώ τα φτάνει όλα, όχι μόνο αυτό. Καλύτερα ορίστε πρώτα έναν κωδικό παραπάνω.`,"settings.access.phrase.activate":`Δημιουργία φράσης`,"settings.access.phrase.howStep1":`Σε αυτή την παρουσία πάτησε «{button}». Εμφανίζονται δώδεκα λέξεις.`,"settings.access.phrase.howStep2":`Άνοιξε το KnightLoader στο άλλο μηχάνημα, πήγαινε σε αυτή τη σελίδα, πάτησε «{button}» και πληκτρολόγησε τις δώδεκα λέξεις.`,"settings.access.phrase.howStep3":`Έτοιμο! Κάθε instance εμφανίζεται τώρα στην άλλη κάτω από «Instances» και μπορείς να χειριστείς οποιαδήποτε από οποιαδήποτε. Με ενεργό relay, τα instances σου είναι προσβάσιμα εκτός του δικτύου σου.`,"settings.access.phrase.howWhat":`Οι λέξεις είναι μυστικό, όχι διεύθυνση. Κάθε εγκατάσταση βγάζει από αυτές δύο κλειδιά: ένα για να βρει τις άλλες, ένα για την κρυπτογράφηση.

Για να βρεθούν, κάθε εγκατάσταση καλεί από μόνη της το ίδιο σημείο συνάντησης στο διαδίκτυο. Όποιος δείξει το ίδιο κλειδί, συνδέεται. Γι’ αυτό καμία εγκατάστασή σου δεν χρειάζεται να είναι προσβάσιμη από έξω.

Το σημείο συνάντησης δεν μπορεί να διαβάσει. Δεν βλέπει ποτέ τις λέξεις σου, και ό,τι περνά από εκεί είναι κρυπτογραφημένο με το δεύτερο κλειδί.`,"settings.access.phrase.statusDisconnected":`Μη συνδεδεμένο`,"settings.access.phrase.statusHintProject":`Συνδεδεμένο στο relay του έργου. Η απομακρυσμένη πρόσβαση είναι έτοιμη.`,"settings.access.phrase.statusHintOwn":`Συνδεδεμένο στο δικό σου relay. Η απομακρυσμένη πρόσβαση είναι έτοιμη.`,"settings.access.phrase.statusHintOff":`Κανένα relay ενεργό. Οι εγκαταστάσεις σου είναι προσβάσιμες μόνο στο τοπικό δίκτυο.`,"settings.access.phrase.statusHintLost":`Καμία επαφή με το relay. Το KnightLoader συνεχίζει να προσπαθεί. Ως τότε οι εγκαταστάσεις σου βρίσκονται μόνο στο τοπικό δίκτυο.`,"settings.access.phrase.statusConnected":`Συνδεδεμένο`,"settings.access.phrase.howButton":`Πώς λειτουργεί αυτό;`,"settings.access.phrase.joinButton":`Εισαγωγή φράσης`,"settings.access.phrase.joinPlaceholder":`Επικολλήστε τις δώδεκα λέξεις από το άλλο στιγμιότυπο`,"settings.access.phrase.joinConfirm":`Σύνδεση`,"settings.access.phrase.errChecksum":`Αυτή η φράση δεν είναι έγκυρη. Έλεγξε μήπως κάποια λέξη γράφτηκε λάθος ή μπήκε σε λάθος θέση.`,"settings.access.phrase.errUnknownWord":`Η λέξη {position} («{word}») δεν ανήκει στις αποδεκτές λέξεις.`,"settings.access.phrase.errWordCount":`Αυτές είναι {count} λέξεις. Μια φράση χρειάζεται {need}.`,"settings.access.phrase.errExists":`Αυτό το στιγμιότυπο έχει ήδη φράση. Αποχώρησε πρώτα από την ομάδα για να ξεκινήσεις νέα.`,"settings.access.phrase.yourPhrase":`Η φράση σύνδεσής σας`,"settings.access.phrase.pasteHint":`Επικολλήστε αυτές τις δώδεκα λέξεις σε κάθε άλλο στιγμιότυπο που θέλετε συνδεδεμένο.`,"settings.access.phrase.qrHint":`Ή σάρωσε το από την άλλη συσκευή αντί να το πληκτρολογήσεις.`,"settings.access.phrase.revealWhy":`Εισαγάγετε τον κωδικό αυτού του στιγμιότυπου για να εμφανιστεί ξανά η φράση. Ανοίγει κάθε στιγμιότυπο της ομάδας, όχι μόνο αυτό.`,"settings.access.phrase.revealConfirm":`Εμφάνιση`,"settings.access.phrase.showAgain":`Εμφάνιση φράσης`,"settings.access.phrase.hide":`Απόκρυψη της φράσης`,"settings.access.phrase.leave":`Αποχώρηση από την ομάδα`,"settings.browsertools.phoneTitle":`Εφαρμογή κινητού`,"settings.browsertools.phoneHint":`Η εφαρμογή KnightLoader για κινητά Android. Δείχνει και χειρίζεται τις λήψεις στα στιγμιότυπά σου και τους στέλνει συνδέσμους. Το APK είναι η έκδοση που φαίνεται στη γωνία.`,"settings.browsertools.storeAndroid":`Google Play`,"settings.browsertools.soon":`Σύντομα`,"settings.browsertools.download":`Λήψη`,"settings.browsertools.qrCode":`Κωδικός QR`,"settings.browsertools.desktopTitle":`Εφαρμογή επιφάνειας εργασίας`,"settings.browsertools.desktopHint":`Το KnightLoader ως πρόγραμμα στον υπολογιστή σου, με αυτή τη διεπαφή σε δικό της παράθυρο. Κατεβαίνει πάντα η πιο πρόσφατη έκδοση.`,"settings.browsertools.serverTitle":`Σε διακομιστή`,"settings.browsertools.serverHint":`Σε διακομιστή το KnightLoader συνεχίζει να κατεβάζει ενώ αυτός ο υπολογιστής είναι κλειστός. Εγκατάστησέ το από τα Unraid Community Applications, τρέξε το ως Docker container ή χτίσε το από τον πηγαίο κώδικα.`,"settings.browsertools.dockerHint":`Ένα κλικ αντιγράφει την εντολή που ξεκινά το container:`,"settings.browsertools.sourceZip":`Πηγαίος κώδικας.zip`,"settings.browsertools.installPwaLabel":`Ή εγκαταστήστε αυτή τη σελίδα ως εφαρμογή`,"settings.browsertools.install":`Εγκατάσταση`,"settings.browsertools.installIOS":`Σε iPhone ή iPad: ανοίξτε αυτήν τη σελίδα στο Safari, πατήστε Κοινοποίηση, και έπειτα «Προσθήκη στην Αρχική οθόνη».`,"settings.nav.browsertools":`Εφαρμογή`,"settings.browsertools.bookmarkletStep1":`Σύρε το κουμπί παρακάτω στη γραμμή σελιδοδεικτών του προγράμματος περιήγησής σου. Αποθηκεύεται όπως κάθε άλλος σελιδοδείκτης και δεν εγκαθίσταται τίποτα.`,"settings.browsertools.bookmarkletStep2":`Σε οποιαδήποτε σελίδα, κάνε κλικ πάνω του (επίλεξε πρώτα κείμενο αν θέλεις μόνο αυτό). Ανοίγει μια μικρή καρτέλα KnightLoader με τον σύνδεσμο της σελίδας, ή το επιλεγμένο κείμενο, ήδη συμπληρωμένο. Έλεγξέ το και πρόσθεσέ το από εκεί ως λήψη.`,"settings.browsertools.installLabel":`Πώς να την εγκαταστήσετε`,"settings.browsertools.installChromiumStep1":`Αποσυμπιέστε το ληφθέν αρχείο.`,"settings.browsertools.installChromiumStep2":`Ανοίξτε chrome://extensions (ή edge://extensions, brave://extensions).`,"settings.browsertools.installChromiumStep3":`Ενεργοποιήστε τη λειτουργία προγραμματιστή.`,"settings.browsertools.installChromiumStep4":`Επιλέξτε «Φόρτωση χωρίς συμπίεση» και επιλέξτε τον αποσυμπιεσμένο φάκελο.`,"settings.browsertools.installChromiumStep5":`Κάνε κλικ στο εικονίδιο του παζλ δίπλα στη γραμμή διευθύνσεων και καρφίτσωσε το KnightLoader. ο Chrome δεν βάζει μόνος του νέες επεκτάσεις στη γραμμή.`,"settings.browsertools.installFirefoxStep1":`Για μόνιμη εγκατάσταση: ανοίξτε το about:addons και κάντε κλικ στο εικονίδιο γραναζιού πάνω δεξιά.`,"settings.browsertools.installFirefoxStep2":`Επιλέξτε «Εγκατάσταση προσθέτου από αρχείο…» και επιλέξτε αυτό το αρχείο.`,"settings.browsertools.installFirefoxStep3":`Για μια γρήγορη δοκιμή, άνοιξε το about:debugging#/runtime/this-firefox και επίλεξε «Φόρτωση προσωρινού προσθέτου». Το πρόσθετο εξαφανίζεται όταν γίνει επανεκκίνηση του Firefox.`,"settings.browsertools.bookmarkletTitle":`Bookmarklet`,"settings.browsertools.bookmarkletLink":`Προσθήκη στο KnightLoader`,"settings.browsertools.copyCode":`Αντιγραφή του κώδικα αντ’ αυτού`,"settings.browsertools.copied":`Αντιγράφηκε.`,"settings.browsertools.extensionTitle":`Επέκταση περιηγητή`,"quickadd.title":`Προσθήκη στο KnightLoader`,"quickadd.manualLabel":`Σύνδεσμος (ή επικολλήστε πολλούς, έναν ανά γραμμή)`,"quickadd.manualHint":`Επικόλλησε έναν σύνδεσμο εδώ με το χέρι ή άνοιξε αυτή τη σελίδα από το bookmarklet ή από το μενού Κοινοποίηση της συσκευής σου.`,"quickadd.manualPlaceholder":`https://example.com/file.zip`,"quickadd.add":`Προσθήκη`,"quickadd.adding":`Προσθήκη…`,"quickadd.staged":`Προστέθηκε στον συλλέκτη.`,"quickadd.stagedNamed":`Το «{name}» προστέθηκε στον συλλέκτη.`,"quickadd.stagedCount":`Προστέθηκαν {n} σύνδεσμοι στον συλλέκτη.`,"quickadd.none":`Δεν προστέθηκε τίποτα. Κάθε σύνδεσμος εδώ ήταν ήδη στον συλλέκτη.`,"quickadd.failed":`Δεν ήταν δυνατή η προσθήκη αυτού: {error}`,"quickadd.undo":`Αναίρεση`,"quickadd.undone":`Αφαιρέθηκε.`,"quickadd.openCollector":`Άνοιγμα συλλέκτη`,"quickadd.toPeer":`Αποστολή στο «{name}».`,"quickadd.undoFailed":`Δεν ήταν δυνατή η αναίρεση. Είναι ακόμα εκεί. ({error})`,"quickadd.close":`Κλείσιμο παραθύρου`,"settings.system.lifecycleTitle":`Έξοδος & επανεκκίνηση`,"settings.system.quit":`Έξοδος`,"settings.system.restart":`Επανεκκίνηση`,"settings.system.quitConfirmTitle":`Έξοδος από το KnightLoader;`,"settings.system.restartConfirmTitle":`Επανεκκίνηση του KnightLoader;`,"settings.system.quitConfirmBody":`Η εργασία σε εξέλιξη ολοκληρώνεται πρώτα, έπειτα η διεργασία τερματίζεται. {note}`,"settings.system.confirmCancel":`Άκυρο`,"settings.system.confirmProceed":`Επιβεβαίωση`,"settings.system.unavailable":`Αυτό το build δεν έχει τρόπο να το κάνει αυτό από τον περιηγητή.`,"settings.system.lifecycleNoteContainer":`Αυτό είναι build για container. Η Έξοδος και η Επανεκκίνηση κάνουν εδώ το ίδιο: το αν η διεργασία θα ξεκινήσει ξανά το αποφασίζει αποκλειστικά η πολιτική επανεκκίνησης του container σου.`,"settings.system.lifecycleNoteDesktop":`Αυτό είναι το desktop build· η έξοδος και η επανεκκίνηση ολοκληρώνονται όπως ακριβώς και το κλείσιμο του παραθύρου.`,"settings.system.acting":`Εργασία σε εξέλιξη…`,"settings.system.shuttingDownTitle":`Τερματισμός`,"settings.system.shuttingDown":`Τερματισμός. Αν αυτή η περίπτωση επιστρέψει μόνη της, η σελίδα θα επανασυνδεθεί μόλις συμβεί αυτό· διαφορετικά κλείστε αυτήν την καρτέλα.`,"settings.system.actionFailed":`Δεν ήταν δυνατή η εκτέλεση αυτού: {error}`,"settings.system.backupButton":`Λήψη αντιγράφου ασφαλείας`,"settings.system.restoreButton":`Μεταφόρτωση αντιγράφου ασφαλείας`,"settings.system.restoreConfirmTitle":`Επαναφορά από αντίγραφο ασφαλείας;`,"settings.system.restoreConfirmBody":`Αυτό αντικαθιστά την τρέχουσα βάση δεδομένων και τις ρυθμίσεις με τα περιεχόμενα του «{name}». Αυτό δεν μπορεί να αναιρεθεί.`,"settings.system.restoring":`Επικύρωση και προετοιμασία…`,"settings.system.restoreFailed":`Δεν ήταν δυνατή η επαναφορά: {error}`,"settings.system.restoreStaged":`{status}`,"settings.system.loadFailed":`Δεν ήταν δυνατή η φόρτωση. Είναι προσβάσιμος ο διακομιστής;`,"settings.nav.resolvers":`Επιλυτές`,"settings.module.ytdlp":`yt-dlp`,"settings.resolvers.moduleUnavailable":`Η μονάδα δεν είναι διαθέσιμη`,"settings.resolvers.moduleUnavailableHint":`Όλα τα παρακάτω αποθηκεύονται κανονικά και ισχύουν μόλις το yt-dlp γίνει διαθέσιμο. Δεν χάνεται τίποτα από όσα αλλάζεις τώρα.`,"settings.resolvers.about":`Ρυθμίσεις για το backend του yt-dlp, που κατεβάζει από τους ιστότοπους πολυμέσων και streaming που υποστηρίζει το ίδιο το yt-dlp. Ποια υπηρεσία χειρίζεται καθόλου έναν σύνδεσμο (yt-dlp, λογαριασμός debrid ή το backend του JDownloader) το αποφασίζει η σειρά προτεραιότητας στη σελίδα Λογαριασμοί. Εδώ ορίζεις τι κάνει το yt-dlp όταν ένας σύνδεσμος έχει δοθεί σε αυτό.`,"settings.resolvers.quality":`Ποιότητα`,"settings.resolvers.videoFormat":`Μορφή βίντεο`,"settings.resolvers.qualityHint":`Ποιος επιλογέας -f χρησιμοποιείται κατά την εκκίνηση του yt-dlp. Η καλύτερη διαθέσιμη είναι η προεπιλογή του ίδιου του yt-dlp, και αυτό που χρησιμοποιούσε κάθε λήψη πριν υπάρξει αυτή η ρύθμιση.`,"settings.resolvers.quality.best":`Καλύτερη διαθέσιμη`,"settings.resolvers.quality.2160p":`Έως 2160p (4K)`,"settings.resolvers.quality.1440p":`Έως 1440p`,"settings.resolvers.quality.1080p":`Έως 1080p`,"settings.resolvers.quality.720p":`Έως 720p`,"settings.resolvers.quality.480p":`Έως 480p`,"settings.resolvers.quality.360p":`Έως 360p`,"settings.resolvers.quality.custom":`Προσαρμοσμένη συμβολοσειρά μορφής`,"settings.resolvers.customFormat":`Προσαρμοσμένη μορφή`,"settings.resolvers.customFormatHint":`Η δική του τιμή -f του yt-dlp, π.χ. bestvideo[height<=720]+bestaudio/best. Περνάει χωρίς έλεγχο· μια τιμή που απορρίπτει το yt-dlp αποτυγχάνει με το δικό του σφάλμα στην εργασία.`,"settings.resolvers.playlist":`Λήψη ολόκληρης της λίστας αναπαραγωγής όταν ένας σύνδεσμος οδηγεί σε μία`,"settings.resolvers.subtitles":`Υπότιτλοι`,"settings.resolvers.subtitleLangs":`Γλώσσες`,"settings.resolvers.subtitleLangsHint":`Η δική του τιμή --sub-langs του yt-dlp, π.χ. en,de. Κενό σημαίνει en ως προεπιλογή.`,"settings.resolvers.subtitleAuto":`Λήψη και αυτόματα δημιουργημένων υποτίτλων όταν δεν υπάρχει χειροκίνητο κομμάτι`,"settings.resolvers.outputTitle":`Όνομα αρχείου εξόδου`,"settings.resolvers.outputHint":`Το δικό του πρότυπο -o του yt-dlp. Κενό χρησιμοποιεί το ενσωματωμένο %(title)s.%(ext)s. Μπορεί να περιλαμβάνει υποφακέλους, π.χ. %(uploader)s/%(title)s.%(ext)s.`,"settings.nav.torrents":`Torrents`,"settings.module.torrents":`Torrents`,"settings.torrents.title":`Torrents`,"settings.torrents.seedingTitle":`Seeding`,"settings.torrents.seedRatio":`Στόχος αναλογίας seeding`,"settings.torrents.seedRatioHint":`Συνεχίζει το seeding ενός ολοκληρωμένου torrent μέχρι να έχει επιστραφεί στο σμήνος αυτό το ποσοστό σε σχέση με το μέγεθός του. 0 = χωρίς στόχο αναλογίας.`,"settings.torrents.seedDuration":`Στόχος διάρκειας seeding`,"settings.torrents.seedDurationHint":`Συνεχίζει το seeding ενός ολοκληρωμένου torrent για τόση ώρα μετά την ολοκλήρωση. 0 = χωρίς χρονικό όριο. Όποιος από τους δύο παραπάνω στόχους επιτευχθεί πρώτος σταματά το seeding.`,"settings.torrents.seedDurationUnit":`ώρες`,"settings.torrents.transferTitle":`Όριο μεταφοράς`,"settings.torrents.uploadLimit":`Όριο μεταφόρτωσης`,"settings.torrents.uploadLimitHint":`Περιορίζει πόσο γρήγορα ένα torrent στέλνει δεδομένα στο σμήνος κατά το seeding. 0 = απεριόριστο.`,"settings.torrents.portTitle":`Θύρα και προώθηση`,"settings.torrents.port":`Θύρα`,"settings.torrents.portHint":`Η θύρα στην οποία αυτή η παρουσία ακούει για συνδέσεις σμήνους. 0 αφήνει τη μηχανή torrent να διαλέξει μία.`,"settings.torrents.portRestartHint":`Η μηχανή φτιάχνει τον πελάτη torrent της μόνο μία φορά, οπότε μια νέα θύρα ισχύει μετά από επανεκκίνηση αυτού του στιγμιότυπου. Το αίτημα προς τον δρομολογητή για προώθηση λειτουργεί αμέσως, είτε ακούει ήδη κάποιο torrent σε αυτήν είτε όχι.`,"settings.torrents.portMapHint":`Ζητά από τον δρομολογητή να προωθήσει την παραπάνω θύρα σε αυτόν τον υπολογιστή μέσω UPnP, ώστε ομότιμοι πίσω από άλλον δρομολογητή να μπορούν και πάλι να τη φτάσουν. Δεν την υποστηρίζουν όλοι οι δρομολογητές, και κάποιοι δέχονται το αίτημα χωρίς αυτό να λειτουργεί πραγματικά.`,"settings.torrents.portMapButton":`Δοκιμή προώθησης UPnP`,"settings.torrents.portMapping":`Ερώτημα στον δρομολογητή…`,"settings.torrents.portMapNeedsPort":`Όρισε πρώτα μια θύρα παραπάνω πριν την προωθήσεις. Με 0 ο δρομολογητής δεν έχει πού να προωθήσει.`,"settings.torrents.portMapConfirmed":`Επιβεβαιώθηκε: η θύρα {port} έχει προωθηθεί και επαληθεύτηκε ως προσβάσιμη.`,"settings.torrents.portMapUnconfirmed":`Ο δρομολογητής δέχτηκε το αίτημα, αλλά δεν ήταν δυνατό να επιβεβαιωθεί ότι η προώθηση λειτουργεί. Κάποιοι δρομολογητές δέχονται το αίτημα σιωπηλά χωρίς να το εφαρμόσουν. Δοκίμασε έναν έλεγχο συνδεσιμότητας από έξω από το δίκτυο.`,"settings.torrents.portMapFailed":`Δεν ήταν δυνατή η προώθηση της θύρας: {error}`,"settings.torrents.portMapUnavailable":`Αυτή η έκδοση δεν προσφέρει ακόμη προώθηση θύρας.`,"settings.torrents.networkTitle":`Ανακάλυψη ομότιμων`,"settings.torrents.dht":`DHT`,"settings.torrents.dhtHint":`Βρίσκει ομότιμους χωρίς κανέναν tracker, χρησιμοποιώντας άλλους πελάτες BitTorrent ως κατανεμημένο ευρετήριο.`,"settings.torrents.pex":`Ανταλλαγή ομότιμων (PEX)`,"settings.torrents.pexHint":`Ανταλλάσσει γνωστούς ομότιμους με όσους είναι ήδη συνδεδεμένοι, ώστε ένα σμήνος με λίγους ομότιμους να βρίσκεται πιο γρήγορα.`,"settings.torrents.privateNote":`Ένα ιδιωτικό torrent απενεργοποιεί αυτόματα και τα δύο μόλις γίνουν γνωστά τα μεταδεδομένα του, ό,τι κι αν έχει οριστεί εδώ: αμέσως για ένα ανεβασμένο αρχείο .torrent ή μόλις φτάσουν από το σμήνος τα μεταδεδομένα ενός συνδέσμου magnet. Οι περισσότεροι ιδιωτικοί trackers αποκλείουν λογαριασμούς που χρησιμοποιούν οποιοδήποτε από τα δύο.`,"container.noJD":`είναι κρυπτογραφημένο, και μόνο ένα backend του JDownloader μπορεί να το ανοίξει. Δεν έχει ρυθμιστεί κανένα: όρισε το KL_JD σε έναν JDownloader που φτάνει αυτό το στιγμιότυπο και κάνε επανεκκίνηση.`,"container.jdOff":`είναι κρυπτογραφημένο, και μόνο το backend του JDownloader μπορεί να το ανοίξει. Η «Υποδομή JDownloader» είναι απενεργοποιημένη στη σελίδα Λειτουργικές μονάδες.`,"torrent.staging":`Προσθήκη…`,"torrent.staged":`Το {file} προστέθηκε στον συλλέκτη.`,"torrent.stagedIn":`Το {file} προστέθηκε στον συλλέκτη στο «{pkg}».`,"torrent.duplicate":`Το {file} υπάρχει ήδη στη λίστα.`,"torrent.onlyOne":`μπορεί να ελεγχθεί μόνο ένα .torrent τη φορά`,"torrent.tree.summary":`Επιλέχθηκαν {n} από {total} αρχεία ({size})`,"torrent.tree.private":`Ιδιωτικός tracker`,"torrent.tree.selectAll":`Επιλογή όλων`,"torrent.tree.selectNone":`Καμία επιλογή`,"torrent.tree.cancel":`Ακύρωση`,"torrent.tree.add":`Προσθήκη στον συλλέκτη`,"settings.torrents.notApplied":`Αυτό το build δεν εφαρμόζει ακόμη δύο από τις παρακάτω ρυθμίσεις. Το όριο μεταφόρτωσης αποθηκεύεται και ελέγχεται, αλλά η μηχανή δεν μπορεί να το εφαρμόσει σε μια λήψη που τρέχει. Ούτε τα DHT και PEX φτάνουν σε ένα κανονικό torrent: κάνει seeding με ενεργά και τα δύο, ό,τι κι αν έχει οριστεί εδώ. Ένα ιδιωτικό torrent λειτουργεί αλλιώς, όπως εξηγεί το (i) στην «Ανακάλυψη ομότιμων».`,"onboarding.step":`Βήμα {n} από {total}`,"onboarding.skip":`Παράλειψη`,"onboarding.back":`Πίσω`,"onboarding.next":`Επόμενο`,"onboarding.finish":`Τέλος`,"onboarding.welcome.title":`Καλώς όρισες στο KnightLoader`,"onboarding.welcome.body":`Το KnightLoader είναι ένας διαχειριστής λήψεων που φιλοξενείς μόνος σου. Επικόλλησε ή άφησε έναν σύνδεσμο και τον κατεβάζει το κατάλληλο backend: η ενσωματωμένη μηχανή για απλούς συνδέσμους αρχείων, το yt-dlp για σελίδες πολυμέσων, μια υπηρεσία debrid για hosters που ήδη πληρώνεις ή ένα headless JDownloader για όλα τα υπόλοιπα. Αυτή η σύντομη περιήγηση καλύπτει τη μία ρύθμιση που αξίζει να ελέγξεις πριν ξεκινήσεις.`,"onboarding.welcome.langLabel":`Γλώσσα διεπαφής`,"onboarding.folder.title":`Πού πρέπει να καταλήγουν τα αρχεία;`,"onboarding.folder.body":`Αυτός είναι ο φάκελος όπου γράφονται οι ολοκληρωμένες λήψεις. Πληκτρολόγησε μια διαδρομή ή αναζήτησε έναν φάκελο στον διακομιστή. Μπορείς να τον αλλάξεις ξανά οποτεδήποτε από τη σελίδα ρυθμίσεων Γενικά.`,"onboarding.accounts.title":`Premium hosters, όποτε τους θελήσεις`,"onboarding.accounts.body":`Η ουρά λειτουργεί και χωρίς κανέναν λογαριασμό. Όταν θέλεις πλήρη ταχύτητα σε έναν hoster ή μια υπηρεσία debrid που ήδη πληρώνεις, πρόσθεσε τα στοιχεία σύνδεσης στους Λογαριασμούς. Τίποτα από αυτά δεν χρειάζεται να ρυθμιστεί τώρα.`,"onboarding.accounts.link":`Άνοιγμα Λογαριασμών`,"onboarding.finished.title":`Είσαι έτοιμος`,"onboarding.finished.body":`Αυτό κλείνει την περιήγηση. Η σελίδα Βοήθειας στις Ρυθμίσεις έχει μια πλήρη παρουσίαση όλων όσων κάνει αυτή η έκδοση, και τα περισσότερα στοιχεία ελέγχου φέρουν τη δική τους εξήγηση πίσω από ένα εικονίδιο (i).`,"commands.openPalette":`Άνοιγμα παλέτας εντολών`,"commands.group.general":`Γενικά`,"commands.group.navigation":`Μετάβαση σε`,"commands.goOverview":`Μετάβαση στην Επισκόπηση`,"commands.goDownloads":`Μετάβαση στις Λήψεις`,"commands.goCollector":`Μετάβαση στον Συλλέκτη`,"commands.goInstances":`Μετάβαση στα Στιγμιότυπα`,"commands.goAccounts":`Μετάβαση στους Λογαριασμούς`,"commands.goSettings":`Μετάβαση στις Ρυθμίσεις`,"commands.group.settings":`Ρυθμίσεις`,"commands.group.queue":`Ουρά`,"commands.group.language":`Γλώσσα`,"commands.group.downloads":`Λήψεις`,"commands.group.collector":`Συλλέκτης συνδέσμων`,"commands.paletteLabel":`Παλέτα εντολών`,"commands.searchPlaceholder":`Πληκτρολόγησε μια εντολή…`,"commands.noResults":`Καμία εντολή δεν ταιριάζει`,"settings.nav.shortcuts":`Συντομεύσεις`,"settings.shortcuts.subtitle":`Κάθε εντολή με προεπιλεγμένη συντόμευση πληκτρολογίου, ομαδοποιημένη ανά περιοχή εφαρμογής. Άλλαξε μια αντιστοίχιση, ή επανάφερέ την στην προεπιλογή της.`,"settings.shortcuts.empty":`Καμία εντολή δεν έχει ακόμη προεπιλεγμένη συντόμευση.`,"settings.shortcuts.change":`Αλλαγή`,"settings.shortcuts.reset":`Επαναφορά`,"settings.shortcuts.resetAll":`Επαναφορά όλων στις προεπιλογές`,"settings.shortcuts.resetAllConfirmTitle":`Επαναφορά όλων των συντομεύσεων;`,"settings.shortcuts.resetAllConfirmBody":`Κάθε συντόμευση που έχει αλλάξει επιστρέφει στην προεπιλογή της. Αυτό δεν μπορεί να αναιρεθεί.`,"settings.shortcuts.resetAllConfirm":`Επαναφορά όλων`,"settings.shortcuts.captureTitle":`Πάτησε μια νέα συντόμευση για «{name}»`,"settings.shortcuts.captureHint":`Πάτησε έναν συνδυασμό πλήκτρων, ή Escape για ακύρωση.`,"settings.shortcuts.conflict":`Το «{combo}» χρησιμοποιείται ήδη από {command}.`,"settings.shortcuts.key.ctrl":`Ctrl`,"settings.shortcuts.key.alt":`Alt`,"dialog.dontShowAgain":`Να μην ξαναρωτηθεί`,"dialog.dontShowAgainHint":`Την επόμενη φορά θα γίνει αμέσως. Μπορείς να επαναφέρεις την ερώτηση στις Ρυθμίσεις, Εμφάνιση.`,"settings.dialogs.title":`Απενεργοποιημένες ερωτήσεις`,"settings.dialogs.hint":`Επιβεβαιώσεις που έχεις απενεργοποιήσει. Ενεργοποίησέ την ξανά και θα ρωτήσει πάλι.`,"settings.categories.listTitle":`Κατηγορίες`,"settings.categories.listHint":`Μια κατηγορία είναι ένα πακέτο προεπιλογών με ένα όνομα από πάνω: φάκελος, θέση στην ουρά, διακόπτης αποσυμπίεσης, όριο ταχύτητας και ο κανόνας για ένα αρχείο που υπάρχει ήδη. Διαλέγεις το όνομα μία φορά, όταν μπαίνουν οι σύνδεσμοι, αντί να απαντάς αυτές τις πέντε ερωτήσεις για κάθε παρτίδα. Κάθε πλαίσιο που αφήνεις κενό σημαίνει ότι αυτή η κατηγορία δεν έχει άποψη γι’ αυτό και ισχύει η ρύθμιση ένα επίπεδο πιο πάνω, οπότε μια μισογεμάτη κατηγορία αλλάζει μόνο ό,τι συμπλήρωσες. Το πολύ 64 από αυτές, γιατί αυτό εδώ είναι ένα μενού από το οποίο διαλέγεις.`,"settings.categories.name":`Όνομα`,"settings.categories.nameHint":`Πώς λέγεται αυτό το συρτάρι όπου κι αν προσφέρεται. Μετονόμασέ το όσο συχνά θέλεις: το κλειδί από κάτω δεν ακολουθεί, οπότε ό,τι έχει ήδη μπει εδώ μένει εδώ. Μια γραμμή εντελώς χωρίς όνομα χρειάζεται δικό της κλειδί, αλλιώς η αποθήκευση απορρίπτεται ακριβώς με αυτή την αιτιολογία.`,"settings.categories.id":`Κλειδί`,"settings.categories.idHint":`Η σταθερή ταυτότητα στην οποία δείχνει κάθε λήψη που μπαίνει εδώ. Σε μια νέα κατηγορία άφησέ το κενό: ο διακομιστής την παράγει από το όνομα μία φορά, στην αποθήκευση, και ποτέ ξανά. Τα κεφαλαία γίνονται πεζά, γράμματα και ψηφία μένουν, και κάθε άλλη ακολουθία χαρακτήρων γίνεται μία παύλα, οπότε το «Serien & Filme» αποθηκεύεται ως «serien-filme». Το να την αλλάξεις αργότερα δεν είναι μετονομασία, φτιάχνει ένα δεύτερο συρτάρι: οι λήψεις που μπήκαν με το παλιό κλειδί συνεχίζουν να δείχνουν σε ένα κλειδί στο οποίο δεν απαντά κανείς, συμπεριφέρονται ακριβώς σαν λήψεις που δεν μπήκαν ποτέ πουθενά, και επιστρέφουν τη μέρα που θα υπάρξει ξανά κατηγορία με αυτό το κλειδί.`,"settings.categories.dir":`Φάκελος`,"settings.categories.dirHint":`Πού καταλήγει μια λήψη που μπαίνει εδώ. Κενό σημαίνει ότι αυτή η κατηγορία δεν έχει άποψη και ισχύει ο γενικός φάκελος λήψεων. Μπορεί να είναι πρότυπο, όπως /media/serien/<jd:packagename>, και μόνο το κομμάτι πριν από την πρώτη μεταβλητή χρειάζεται να είναι πραγματικός φάκελος. Πρέπει να είναι απόλυτη διαδρομή, αλλιώς η αποθήκευση απορρίπτεται με την αιτιολογία, το ίδιο και όταν αυτό το στιγμιότυπο δεν μπορεί να δημιουργήσει τον φάκελο ή να γράψει μέσα του. Οι υποφάκελοι ανά πακέτο ισχύουν κανονικά από πάνω, οπότε το να μπει μια παρτίδα εδώ δεν τους απενεργοποιεί. Ένας κανόνας Packagizer που ονομάζει δικό του φάκελο κερδίζει αυτόν εδώ, γιατί εκείνος ο κανόνας κοίταξε τον ίδιο τον σύνδεσμο. Και ο φάκελος γράφεται πάνω στη λήψη τη στιγμή που ξεκινά: αν τον αλλάξεις εδώ, μετακομίζει ό,τι δεν έχει ξεκινήσει, και τίποτα από όσα τρέχουν.`,"settings.categories.priorityHint":`Από πού ξεκινά στην ουρά μια λήψη που μπαίνει εδώ. Ψηλότερη τρέχει νωρίτερα. Η «Καμία προτίμηση» είναι πραγματική απάντηση και δεν είναι το ίδιο με την «Προεπιλογή»: η προεπιλογή είναι η μεσαία θέση και θα τραβούσε πάλι προς τα κάτω έναν σύνδεσμο που ένας κανόνας είχε ήδη ανεβάσει, ενώ η καμία προτίμηση τον αφήνει ακριβώς όπως ήρθε. Το εύρος είναι αυτό που δέχεται η ίδια η ουρά, οπότε μια κατηγορία δεν μπορεί να δώσει σε μια λήψη θέση που δεν έχεις τρόπο να αναιρέσεις. Γράφεται μία φορά, τη στιγμή που ο σύνδεσμος μπαίνει σε ετοιμότητα, και ποτέ ξανά, οπότε μια λήψη που έχεις τραβήξει ψηλότερα στη λίστα μένει εκεί που την έβαλες.`,"settings.categories.extractHint":`Αν ένα αρχείο συμπίεσης που έρχεται σε αυτή την κατηγορία θα αποσυμπιεστεί. Η Κληρονόμηση αφήνει την απόφαση στη σελίδα Συμπιεσμένα αρχεία, κάτι που δεν είναι το ίδιο με το Ανενεργό: το Ανενεργό κρατά τα αρχεία συμπιεσμένα ακόμα κι όταν η γενική ρύθμιση λέει αποσυμπίεση, για παράδειγμα σε ένα συρτάρι μουσικής όπου το αρχείο συμπίεσης είναι το ίδιο το παραδοτέο. Ο διακόπτης της ίδιας της λήψης εξακολουθεί να υπερισχύει αυτού, γιατί εκεί ένας κανόνας ή ένας άνθρωπος έχει αποφασίσει για τη συγκεκριμένη λήψη.`,"settings.categories.speedLimit":`Όριο ταχύτητας (0 = χωρίς προτίμηση)`,"settings.categories.speedLimitHint":`Πόσο γρήγορα μπορεί να κατεβάζει μια λήψη που ανήκει εδώ. Το 0 σημαίνει ότι αυτή η κατηγορία δεν έχει άποψη και ισχύει το όριο όλου του στιγμιότυπου. Τίποτα δεν το επιβάλλει ακόμα: αυτό το build έχει έναν περιοριστή για όλη την εφαρμογή, μοιρασμένο στα backends, και καμία μερίδα ανά λήψη όπου να γραφτεί αυτός ο αριθμός. Η τιμή αποθηκεύεται και επιλύεται σωστά, και μετά τίποτα δεν τη χρησιμοποιεί. Προσφέρεται ήδη ώστε η ρύθμιση να μην αλλάξει μορφή αργότερα, όταν οι χρήστες θα έχουν ήδη αρχεία στον δίσκο.`,"settings.categories.collision":`Αν υπάρχει ήδη αρχείο`,"settings.categories.collisionHint":`Τι γίνεται όταν το αρχείο που πάει να γράψει μια λήψη αυτής της κατηγορίας υπάρχει ήδη. Η Κληρονόμηση παίρνει την απάντηση όλου του στιγμιότυπου από τις ρυθμίσεις λήψεων, και το κενό σημαίνει πραγματικά κληρονόμηση: δεν είναι ένα σιωπηλό «Διατήρηση και των δύο», οπότε μια κατηγορία χωρίς άποψη δεν μπορεί να παρακάμψει ένα στιγμιότυπο ρυθμισμένο σε παράλειψη. Η «Διατήρηση και των δύο» γράφει δίπλα ως «όνομα (2)», η «Παράλειψη» κρατά ό,τι υπάρχει και δεν γράφει τίποτα, η «Αντικατάσταση» το αδειάζει και γράφει από πάνω. Δεν υπάρχει «ρώτα με»: δεν θα υπήρχε κανείς να απαντήσει, και η λήψη θα έμενε στην ουρά για πάντα χωρίς να λέει τίποτα γιατί.`,"settings.downloads.diskReserve":`Περιθώριο ανά λήψη (GiB)`,"settings.downloads.diskReserveHint":`Χώρος που μένει ελεύθερος επιπλέον από όσα έχει ακόμη να φέρει μια λήψη. Μια λήψη ξεκινά μόνο αν χωρούν τα byte που της απομένουν συν αυτό το ποσό, οπότε έτσι απορρίπτεται μόνο μια λήψη που έτσι κι αλλιώς θα άδειαζε τον δίσκο. Είναι το μόνο από τα τρία που έρχεται αναμμένο, στο 0,5. Το 0 το σβήνει και αφήνει μία μόνο λήψη να γεμίσει τον δίσκο μέχρι το τελευταίο byte. Ένα αρχείο του οποίου το μέγεθος δεν το λέει ο πάροχος εξαιρείται μέχρι να έρθει το μέγεθος, συνήθως δευτερόλεπτα μετά την εκκίνηση.`,"settings.downloads.diskLowSpace":`Να μην ξεκινά τίποτα κάτω από (GiB)`,"settings.downloads.diskLowSpaceHint":`Ελεύθερος χώρος κάτω από τον οποίο δεν ξεκινά τίποτα καινούριο, όσο μεγάλο κι αν είναι και ακόμη κι όταν το μέγεθος είναι άγνωστο. Το 0 είναι σβηστό, και έτσι έρχεται: ο σωστός αριθμός εξαρτάται εντελώς από τον δίσκο, και ένα gigabyte δεν είναι τίποτα σε έναν πίνακα δεκαέξι terabyte και είναι το ένα τρίτο μιας κάρτας μνήμης. Οι λήψεις στην ουρά απλώς περιμένουν και ξεκινούν πάλι μόνες τους μόλις ελευθερωθεί χώρος. Αν βάλεις την τιμή διακοπής από κάτω ψηλότερα από αυτήν εδώ, αυτή εδώ ανεβαίνει μαζί της στην αποθήκευση, γιατί το «σταμάτα τα πάντα κάτω από X» σημαίνει ήδη «μην ξεκινάς τίποτα κάτω από X».`,"settings.downloads.diskCriticalSpace":`Διακοπή των πάντων κάτω από (GiB)`,"settings.downloads.diskCriticalSpaceHint":`Ελεύθερος χώρος κάτω από τον οποίο οι λήψεις που ήδη τρέχουν σταματούν και επιστρέφουν στην ουρά, με έλεγχο κάθε δεκαπέντε δευτερόλεπτα. Το 0 είναι σβηστό, και έτσι έρχεται. Αυτό κοστίζει περισσότερο από την τιμή εκκίνησης παραπάνω: μια μεταφορά που δεν μπορεί να συνεχιστεί χάνει ό,τι είχε ήδη φέρει, οπότε κράτησέ το για δίσκο που πραγματικά κοντεύει να γεμίσει. Αν το βάλεις ψηλότερα από την τιμή εκκίνησης, η τιμή εκκίνησης ανεβαίνει μαζί κατά την αποθήκευση. Ο αριθμός που γράφεις εδώ δεν χαμηλώνει ποτέ στα κρυφά.`,"settings.feeds.titleHint":`Ροές RSS και Atom που ακολουθεί αυτό το στιγμιότυπο. Καθεμία ανακτάται με δικό της χρονόμετρο, και μια νέα καταχώριση πηγαίνει στον συλλέκτη ακριβώς σαν επικολλημένος σύνδεσμος, οπότε ισχύουν κανονικά το φίλτρο συνδέσμων, η σάρωση σελίδων και ο Packagizer. Η πρώτη ανάκτηση μιας νέας συνδρομής δεν προσθέτει απολύτως τίποτα: ό,τι κουβαλά η ροή εκείνη τη στιγμή σημειώνεται ως ήδη γνωστό, ώστε να μη σου πέσει μονομιάς όλο το παλιό αρχείο ενός εκδότη. Προστίθεται μόνο ό,τι εμφανιστεί από εκεί και πέρα. Κενή λίστα σημαίνει ότι δεν ακολουθείται καμία ροή.`,"settings.feeds.url":`Διεύθυνση ροής`,"settings.feeds.urlHint":`Η διεύθυνση του εγγράφου RSS ή Atom, μόνο http ή https. Είναι επίσης αυτό που ταυτοποιεί τη συνδρομή: αν την αλλάξεις έχεις άλλη συνδρομή, μια που δεν ξέρει πια ποιες καταχωρίσεις έχει ήδη προσθέσει, οπότε ακόμη και η διόρθωση ενός τυπογραφικού λάθους την κάνει να διαβάσει τη ροή σαν καινούρια. Μια διεύθυνση που δεν διαβάζεται, ή που δεν ονομάζει κόμβο, ρίχνει ολόκληρη την αποθήκευση των ρυθμίσεων με τον αριθμό της γραμμής, αντί να εξαφανιστεί στα κρυφά. Δύο γραμμές με την ίδια διεύθυνση συγχωνεύονται στην πρώτη κατά την αποθήκευση.`,"settings.feeds.interval":`Έλεγχος κάθε (λεπτά)`,"settings.feeds.intervalHint":`Πόσο μένει ήσυχη αυτή η ροή ανάμεσα σε δύο ανακτήσεις. Άφησέ το στο 0 και ισχύει το συνηθισμένο ένα τέταρτο της ώρας. Ανάμεσα σε 1 και 10080, δηλαδή μία εβδομάδα, ο αριθμός παίρνεται όπως τον έγραψες. Κάτω από 1 ο διακομιστής τον ανεβάζει στο 1 χωρίς να το πει, πάνω από μία εβδομάδα τον ρίχνει πίσω στη μία εβδομάδα, και ο διορθωμένος αριθμός εμφανίζεται στο πεδίο μόλις γυρίσει η αποθήκευση. Το ένα λεπτό είναι το κατώτατο όριο, γιατί κάθε ανάκτηση είναι ένα αίτημα στον διακομιστή κάποιου άλλου, και ένας γρηγορότερος ρυθμός είναι ο τρόπος με τον οποίο ένα στιγμιότυπο τρώει αποκλεισμό της διεύθυνσής του. Η πρώτη ανάκτηση γίνεται αμέσως μετά την αποθήκευση και όχι μετά την πρώτη αναμονή, και ένα μικρότερο διάστημα ισχύει αμέσως αντί για το τέλος της αναμονής που μόλις μίκρυνες.`,"settings.feeds.filter":`Φίλτρο τίτλων`,"settings.feeds.filterHint":`Μια κανονική έκφραση που δοκιμάζεται πάνω στον τίτλο κάθε καταχώρισης, δηλαδή στο όνομα με το οποίο η καταχώριση εμφανίζεται και στον συλλέκτη. Άφησέ το κενό για να παίρνεις ό,τι δημοσιεύει η ροή. Αποφασίζει τι κατεβαίνει, όχι τι μένει στη μνήμη: οι καταχωρίσεις που διώχνει σημειώνονται έτσι κι αλλιώς ως ιδωμένες, οπότε ένα φίλτρο που θα ανοίξεις τον επόμενο μήνα φέρνει μόνο ό,τι εμφανιστεί από τότε και όχι όλο το τρέχον παράθυρο της ροής. Ένα μοτίβο που δεν είναι έγκυρο ρίχνει την αποθήκευση των ρυθμίσεων με τον αριθμό της γραμμής. Δεν πετιέται ποτέ για λογαριασμό σου, γιατί ένα πεταμένο φίλτρο είναι μια συνδρομή που μαζεύει σιωπηλά ολόκληρη τη ροή.`,"settings.feeds.dir":`Φάκελος λήψεων`,"settings.feeds.dirHint":`Πού καταλήγουν οι λήψεις αυτής της συνδρομής. Άφησέ το κενό και πηγαίνουν εκεί που πηγαίνουν κανονικά οι λήψεις. Ο φάκελος γράφεται πάνω στον σύνδεσμο αφού αυτός συλλεχθεί, όπως ακριβώς και ο φάκελος ενός αρχείου .crawljob που αφήνεις στον παρακολουθούμενο φάκελο, οπότε υπερισχύει ενός κανόνα Packagizer που διάλεξε φάκελο. Οι μεταβλητές διαδρομής δουλεύουν εδώ, και ο επιλογέας φακέλων κρατά το υπόλοιπο πρότυπο. Σε αντίθεση με τον κύριο φάκελο λήψεων, αυτός εδώ δεν ελέγχεται κατά την αποθήκευση: ένας φάκελος που δεν μπορεί να δημιουργηθεί φαίνεται μόνο όταν φτάσει πραγματικά μια καταχώριση, και τότε η λήψη κρατά τον κανονικό φάκελο.`,"settings.feeds.priority":`Προτεραιότητα`,"settings.feeds.priorityHint":`Με ποια προτεραιότητα ξεκινά κάθε λήψη από αυτή τη ροή. Άφησέ το στο «Χωρίς ορισμό» και η συνδρομή δεν λέει απολύτως τίποτα, οπότε αυτές οι λήψεις μπαίνουν στην ουρά όπως όλες οι άλλες. Οτιδήποτε άλλο γράφεται πάνω στον σύνδεσμο αφού αυτός συλλεχθεί, οπότε υπερισχύει ενός κανόνα Packagizer που όρισε προτεραιότητα. Ψηλότερη τρέχει νωρίτερα, αναδιατάσσει ό,τι περιμένει ακόμη και δεν στέλνει ποτέ πίσω στην ουρά μια λήψη που τρέχει. Αν ο φάκελος παραπάνω δεν μπορεί να χρησιμοποιηθεί, δεν εφαρμόζεται ούτε η προτεραιότητα, γιατί τα δύο γράφονται μαζί.`,"settings.hostRules.title":`Εξαιρέσεις ανά πάροχο`,"settings.hostRules.titleHint":`Μία γραμμή για κάθε πάροχο που χρειάζεται άλλους αριθμούς από αυτούς της σελίδας Λήψεις. Ένας πάροχος χωρίς γραμμή κρατά τις γενικές τιμές, οπότε ένας άδειος πίνακας δεν αλλάζει τίποτα. Μια γραμμή καλύπτει τον κόμβο που ονομάζεις και κάθε υποτομέα του: το rapidgator.net καλύπτει και το rg.rapidgator.net, και δεν καλύπτει το notrapidgator.net. Αν δύο γραμμές ταιριάζουν στον ίδιο σύνδεσμο, κερδίζει το μεγαλύτερο όνομα κόμβου.`,"settings.hostRules.pattern":`Πάροχος`,"settings.hostRules.patternHint":`Ο κόμβος για τον οποίο μιλά αυτή η γραμμή, για παράδειγμα rapidgator.net. Αποθηκεύεται με πεζά, χωρίς αρχικό «*.» και χωρίς τελεία στο τέλος, οπότε το «*.Rapidgator.net.» και το «rapidgator.net» είναι μία και η αυτή γραμμή. Μια γραμμή με κενό κόμβο πετιέται κατά την αποθήκευση, χωρίς μήνυμα.`,"settings.hostRules.maxPerHost":`Ταυτόχρονες λήψεις από αυτόν τον πάροχο (0 = γενική ρύθμιση)`,"settings.hostRules.maxPerHostHint":`Αντικαθιστά το «Ταυτόχρονες λήψεις ανά πάροχο» για αυτόν τον έναν πάροχο, προς τα πάνω όπως και προς τα κάτω: το 8 εδώ δουλεύει σε στιγμιότυπο του οποίου η γενική τιμή είναι 2. Δεν σε βγάζει ποτέ πάνω από τις «Ταυτόχρονες λήψεις» συνολικά, γιατί εκείνο το σύνολο ελέγχεται πρώτο και συμπληρώνεται νωρίτερα. Το 0 σημαίνει ότι αυτή η γραμμή δεν λέει τίποτα γι’ αυτό και ισχύει ο γενικός αριθμός. Πάνω από 64 ο διακομιστής αποθηκεύει 64.`,"settings.hostRules.chunks":`Συνδέσεις ανά λήψη από αυτόν τον πάροχο (0 = γενική ρύθμιση)`,"settings.hostRules.chunksHint":`Αντικαθιστά το «Συνδέσεις ανά λήψη» για αυτόν τον host, και σε αντίθεση με ένα όριο που αναφέρει μια υπηρεσία για έναν host, μπορεί να είναι μεγαλύτερο από τον γενικό αριθμό. Δύο πράγματα το περιορίζουν ακόμα: μια μεμονωμένη λήψη ή ένας κανόνας που όρισε δικό του αριθμό υπερισχύει αυτής της γραμμής, και μια υπηρεσία που ξέρει ότι ο host επιτρέπει μόνο δύο κατεβάζει ένα αισιόδοξο οκτώ πάλι στο δύο. Το 0 σημαίνει ότι ισχύει ο γενικός αριθμός. Το 16 είναι το μέγιστο που ανοίγει η μηχανή, ό,τι κι αν γράψεις.`,"settings.hostRules.retryDelay":`Αναμονή πριν από την πρώτη νέα προσπάθεια, σε δευτερόλεπτα (0 = το επίπεδο από πάνω)`,"settings.hostRules.retryDelayHint":`Πόσο μένει ήσυχη μια αποτυχημένη λήψη από αυτόν τον πάροχο πριν δοκιμαστεί ξανά. Από εκεί και πέρα η αναμονή διπλασιάζεται μέχρι το ανώτατο όριο από κάτω. Το 0 δεν σημαίνει «καμία αναμονή», αλλά δίνει την ερώτηση παρακάτω: πρώτα στον κανόνα για αυτό το είδος σφάλματος, μετά στην αναμονή ολόκληρου του στιγμιότυπου, και τελευταία στα ενσωματωμένα 15 δευτερόλεπτα. Βάλε μία ώρα εδώ για πάροχο που αποκλείει για μία ώρα, αντί να ξοδεύεις έξι απορριφθείσες προσπάθειες μέσα σε δέκα λεπτά και να τα παρατάς πριν τελειώσει ο αποκλεισμός.`,"settings.hostRules.retryMax":`Μεγαλύτερη αναμονή ανάμεσα σε προσπάθειες, σε δευτερόλεπτα (0 = το επίπεδο από πάνω)`,"settings.hostRules.retryMaxHint":`Εδώ σταματά ο διπλασιασμός. Το 0 μεταβιβάζει την ερώτηση όπως και η αναμονή παραπάνω και καταλήγει στα ενσωματωμένα 10 λεπτά. Ένα ανώτατο όριο κάτω από την πρώτη αναμονή δεν χρησιμοποιείται όπως το έγραψες: η εφαρμογή το ανεβάζει σιωπηλά σε εκείνη την αναμονή, γιατί αλλιώς ο αριθμός που έγραψες ως αναμονή δεν θα ήταν ποτέ η αναμονή. Η τιμή σου μένει στο πεδίο έτσι κι αλλιώς, οπότε ένα 60 εδώ δίπλα σε ένα 3600 παραπάνω εξακολουθεί να δείχνει 60 και συμπεριφέρεται ως 3600.`,"settings.hostRules.retryTries":`Προσπάθειες για αυτόν τον πάροχο (0 = γενική ρύθμιση)`,"settings.hostRules.retryTriesHint":`Πόσες φορές δοκιμάζεται καν μια αποτυχημένη λήψη από αυτόν τον πάροχο. Το 0 δεν σημαίνει «ποτέ»: δίνει την ερώτηση στον κανόνα για αυτό το είδος σφάλματος και μετά στις «Αυτόματες επαναλήψεις» της σελίδας Λήψεις. Χρησιμοποίησέ το για να δώσεις δέκα προσπάθειες σε έναν ασταθή πάροχο χωρίς να ανεβάσεις τον αριθμό για όλα τα υπόλοιπα. Καμία γραμμή δεν επιτρέπεται να ζητήσει πάνω από 20, το ίδιο ανώτατο όριο που έχει και ο γενικός αριθμός.`,"settings.hostRules.never":`Ποτέ νέα προσπάθεια σε αυτόν τον πάροχο`,"settings.hostRules.neverHint":`Μια λήψη από αυτόν τον hoster που αποτυγχάνει παραμερίζεται οριστικά, χωρίς χρονόμετρο. Αυτή είναι ξεχωριστή τελική κατάσταση και όχι «απέτυχε μετά από τρεις προσπάθειες», και η λίστα τις δείχνει διαφορετικά: αν αυξήσεις τον αριθμό προσπαθειών οπουδήποτε, διορθώνεται το δεύτερο και δεν αλλάζει τίποτα για αυτό. Κάθε επίπεδο μπορεί μόνο να το ενεργοποιήσει. Το Ανενεργό εδώ δεν αναιρεί ένα «ποτέ» που έχει ήδη ορίσει ο κανόνας για αυτό το είδος αποτυχίας, οπότε μια γραμμή μπορεί να είναι ανενεργή και η λήψη να μην ξαναδοκιμαστεί ποτέ.`,"settings.advanced.mirrorPolicy":`Πότε δύο σύνδεσμοι μετρούν ως το ίδιο αρχείο`,"settings.advanced.mirrorPolicyHint":`Αποφασίζει ποιος δεύτερος σύνδεσμος συγχωνεύεται ως αντίγραφο ενός που είναι ήδη στη λίστα. Το «Ποτέ» δεν συγχωνεύει απολύτως τίποτα. Το «Ίδιο όνομα αρχείου» πιάνει την ίδια κυκλοφορία επικολλημένη από πέντε παρόχους, ακόμη κι όταν αυτοί διαφωνούν για το μέγεθος, αλλά ενώνει επίσης δύο άσχετα αρχεία που λέγονται και τα δύο setup.exe. Το «Ίδιο όνομα και ίδιο μέγεθος», η προεπιλογή, θέλει να συμφωνούν και τα δύο, οπότε ένας σύνδεσμος του οποίου το μέγεθος δεν το έχει λύσει ακόμη κανείς δεν ενώνεται ποτέ. Το «Ίδιο άθροισμα ελέγχου» ενώνει μόνο με απόδειξη και χάνει σχεδόν τα πάντα, γιατί ένα άθροισμα ελέγχου σπάνια είναι γνωστό πριν φτάσει το αρχείο. Η ίδια διεύθυνση δύο φορές απορρίπτεται πάντα, ό,τι κι αν διαλέξεις, και τα μέρη ενός χωρισμένου συμπιεσμένου δεν ενώνονται ποτέ μεταξύ τους.`,"settings.advanced.keepMirrors":`Διατήρηση του αντιγράφου αντί για απόρριψη`,"settings.advanced.keepMirrorsHint":`Σβηστό, ένα αντίγραφο που συγχωνεύτηκε χάνεται στην επόμενη επανεκκίνηση. Αναμμένο, στήνεται ως δεύτερη γραμμή δίπλα στη λήψη που αντιγράφει, κρατιέται πίσω και επισημαίνεται ως αντίγραφό της. Από μόνο του δεν ξεκινά τίποτα: η γραμμή περιμένει μέχρι να την αποδεσμεύσεις με το χέρι, ή μέχρι να την αποδεσμεύσει ο διακόπτης από κάτω. Το τίμημα του να το αφήσεις αναμμένο είναι μια γραμμή παραπάνω για κάθε αντίγραφο, σε μια λίστα που είναι ήδη μεγάλη, γι’ αυτό η προεπιλογή είναι σβηστό. Ένα ακριβές διπλότυπο δεν κρατιέται ποτέ, ό,τι κι αν λέει αυτό εδώ.`,"settings.advanced.mirrorFailover":`Μετάβαση στο αντίγραφο όταν πεθάνει η λήψη`,"settings.advanced.mirrorFailoverHint":`Δεν κάνει τίποτα όσο ο διακόπτης από πάνω είναι σβηστός, γιατί τότε δεν υπάρχει παρκαρισμένο αντίγραφο για αποδέσμευση. Αναμμένο, μια λήψη που έχει αποτύχει οριστικά παραδίδει τον φάκελό της, το πακέτο της και την προτεραιότητά της στο παρκαρισμένο αντίγραφο, και εκείνο ξεκινά. Είναι σβηστό από προεπιλογή, γιατί η αποδέσμευση ξεκινά μεταφορά από πάροχο που δεν διάλεξες, με το τέμπο εκείνου του πάροχου, ίσως και με λογαριασμό που δεν έχεις, και τίποτα εδώ δεν μπορεί να σε ρωτήσει πρώτα. Ένας γεμάτος δίσκος και μια λήψη που ακύρωσες δεν το πυροδοτούν ποτέ. Η αποτυχημένη γραμμή μένει στη λίστα με τον δικό της λόγο ανέπαφο, και το αντίγραφο ξεκινά με φρέσκο μετρητή προσπαθειών αντί να κληρονομήσει τον νεκρό.`,"settings.advanced.onOffline":`Σύνδεσμοι που είναι ήδη γνωστοί ως μη διαθέσιμοι`,"settings.advanced.onOfflineHint":`Τι γίνεται με έναν σύνδεσμο που ένας έλεγχος έχει ήδη βρει ότι δεν υπάρχει πια, τη στιγμή που μια παρτίδα φεύγει από τον συλλέκτη. Το «Πρόσθεσέ τον έτσι κι αλλιώς» τον ξεκινά σαν να μην είχε ταιριάξει τίποτα, και είναι η μόνη απάντηση που δεν μπορεί ποτέ να χάσει σύνδεσμο εξαιτίας λάθος σήματος. Το «Άφησέ τον στον συλλέκτη», η προεπιλογή, δεν αλλάζει τίποτε άλλο στον σύνδεσμο, οπότε μια μεταγενέστερη επιβεβαίωση με άλλη απάντηση τον φτάνει ακόμα. Το «Πέταξέ τον» είναι η μόνη απάντηση εδώ που σβήνει κάτι. Το «Ρώτα με» ρωτά πραγματικά μόνο όταν επιβεβαιώνεις με το χέρι: η αυτόματη επιβεβαίωση, ο παρακολουθούμενος φάκελος και το Click'n'Load δεν έχουν κανέναν να απαντήσει, οπότε σε αυτά ο σύνδεσμος μένει στον συλλέκτη. Μια μεμονωμένη παρτίδα μπορεί να φέρει δική της απάντηση και να παρακάμψει αυτήν.`,"settings.advanced.reclaimTrust":`Πότε ένα αρχείο που βρίσκεται ήδη στον δίσκο μετρά ως η λήψη`,"settings.advanced.reclaimTrustHint":`Χρησιμοποιείται από το πέρασμα που ψάχνει για ήδη ολοκληρωμένα αρχεία πριν κατέβει οτιδήποτε, και που το ξεκινάς εσύ με το χέρι: δεν τρέχει ποτέ στην εκκίνηση, γιατί σε δέκα χιλιάδες εργασίες θα ήταν ένα πέρασμα του δίσκου μπροστά από μια ουρά που δεν υπάρχει ακόμη. Το «Άθροισμα ελέγχου που ταιριάζει» κλείνει μια εργασία μόνο με άθροισμα ελέγχου που επαληθεύτηκε, που είναι τίμιο και δεν κάνει τίποτα για τα πολλά αρχεία που έρχονται χωρίς δημοσιευμένο hash. Η «Μια καταγραφή ότι αυτή η λήψη το έγραψε», η προεπιλογή, δέχεται επιπλέον το ιστορικό αυτού του στιγμιότυπου, όταν αυτό λέει ότι ολοκλήρωσε αρχείο με ακριβώς αυτό το όνομα και ακριβώς αυτό το μήκος. Το «Το σωστό όνομα και το σωστό μέγεθος» δέχεται ένα αρχείο σε πλήρες μήκος χωρίς τίποτα άλλο από πίσω, και σε αυτό το build είναι παγίδα: η βιβλιοθήκη λήψεων δημιουργεί το αρχείο στο πλήρες τελικό του μέγεθος πριν φτάσει το πρώτο byte, οπότε μια μεταφορά που πέθανε στο δύο τοις εκατό φαίνεται ολοκληρωμένη. Ένα πιο κοντό αρχείο διαβάζεται πάντα ως αρχή, ένα άθροισμα ελέγχου που διαφωνεί κερδίζει πάντα, και τίποτα σε αυτό το πέρασμα δεν σβήνει, δεν μετακινεί και δεν αντικαθιστά τίποτα.`,"settings.advanced.retryTries":`Προσπάθειες ανά είδος σφάλματος`,"settings.advanced.retryTriesHint":`Πόσες προσπάθειες παίρνει μια λήψη όταν απέτυχε ακριβώς για αυτόν τον λόγο. Το 0 σημαίνει καμία άποψη και παίρνει στη θέση του τον γενικό αριθμό επαναλήψεων από τη σελίδα Λήψεις, και αυτό λέει κάθε γραμμή εδώ μέχρι να γράψεις κάτι μέσα της. Ένας κανόνας για έναν πάροχο υπερισχύει αυτού εδώ, και αυτό εδώ υπερισχύει του γενικού αριθμού, και τα τρία επιλύονται πεδίο προς πεδίο, οπότε το να γράψεις εδώ αριθμό προσπαθειών δεν φιμώνει και μια αναμονή που ορίστηκε αλλού. Μια αποθηκευμένη τιμή πάνω από 20 κόβεται στο 20 και μια αρνητική γίνεται 0. Η περίπτωση για την οποία υπάρχει αυτό είναι ένας πάροχος που αποκλείει για μία ώρα: έξι προσπάθειες μέσα σε δέκα λεπτά είναι έξι αρνήσεις, και εκείνη που θα είχε πετύχει δεν γίνεται ποτέ.`,"settings.downloads.workDir":`Φάκελος εργασίας`,"settings.downloads.workDirHint":`Πού γράφεται μια λήψη όσο ακόμα έρχεται. Το ολοκληρωμένο αρχείο μετακινείται μετά στον φάκελο λήψεων, αφού τελειώσουν ο έλεγχος checksum και τυχόν αποσυμπίεση, ώστε να μη φαίνεται ποτέ εκεί τίποτα μισοτελειωμένο. Κενό, όπως έρχεται από προεπιλογή, σημαίνει ότι οι λήψεις γράφονται απευθείας στον προορισμό τους. Όρισέ το όταν κάτι άλλο παρακολουθεί τον φάκελο λήψεων: ο mover του Unraid παίρνει ένα μισό αρχείο από την cache και το αντιγράφει στο array, και ένας σαρωτής βιβλιοθήκης προσθέτει ένα ημιτελές βίντεο, αποτυγχάνει να το παίξει μία φορά και δεν το ξανακοιτάζει. Μία σταθερή απόλυτη διαδρομή, χωρίς μεταβλητές: κάθε λήψη προς τον ίδιο προορισμό μοιράζεται αυτόν τον φάκελο, και ένα πρότυπο θα σκόρπιζε τα μέρη ενός αρχείου πολλών τόμων. Μια διαδρομή που δεν είναι απόλυτη απορρίπτεται κατά την αποθήκευση. Τα torrent και οι λήψεις που κατεβάζει άλλο πρόγραμμα δεν τον χρησιμοποιούν ποτέ.`,"settings.archives.moveTo":`Μετακίνηση των αποσυμπιεσμένων αρχείων σε`,"settings.archives.moveToHint":`Πού μετακινούνται τα αποσυμπιεσμένα αρχεία όταν τελειώσει η αποσυμπίεση. Άφησέ το κενό και μένουν εκεί όπου αποσυμπιέστηκαν. Δεν είναι ένα δεύτερο «Αποσυμπίεση σε»: εκεί γράφει η αποσυμπίεση, οπότε μια μισοτελειωμένη κυκλοφορία βρίσκεται σε εκείνον τον προορισμό όσο διαρκεί. Αυτό μετακινεί τα αρχεία μετά, ώστε να μη φαίνεται ποτέ τίποτα ημιτελές στον στόχο. Επίσης μετακινεί το περιεχόμενο και όχι τον φάκελο της κυκλοφορίας, οπότε το «Show.S01.COMPLETE.WEB/ep01.mkv» φτάνει ως «ep01.mkv», χωρίς τον φάκελο που δεν ζήτησε καμία βιβλιοθήκη. Εδώ επιτρέπονται μεταβλητές. Ένας κανόνας Packagizer που όρισε φάκελο για έναν συγκεκριμένο σύνδεσμο υπερισχύει αυτού.`,"settings.downloads.collision":`Αν το αρχείο υπάρχει ήδη`,"settings.downloads.collisionHint":`Τι κάνει μια λήψη όταν το όνομα που θέλει είναι ήδη πιασμένο στον φάκελο προορισμού. Η «Διατήρηση και των δύο» γράφει όνομα (2).ext δίπλα, η «Παράλειψη» κρατά το υπάρχον αρχείο και δεν ξεκινά ποτέ τη λήψη, η «Αντικατάσταση» το αντικαθιστά και είναι η μόνη από τις τρεις που μπορεί να σας κάνει να χάσετε ένα αρχείο που είχατε ήδη. Πρέπει να αποφασιστεί από πριν, γιατί μπροστά στον διακομιστή δεν κάθεται κανείς για να ερωτηθεί. Μόνο στον ενσωματωμένο λήπτη μπορεί να ειπωθεί ποιο όνομα να γράψει, και αυτός κατεβάζει επίσης ό,τι ξεκλειδώνει μια υπηρεσία debrid ή το TorBox. Το JDownloader και το yt-dlp ονομάζουν μόνα τους τα αρχεία τους, οπότε για τους συνδέσμους τους η «Παράλειψη» είναι η μόνη απάντηση που φτάνει καθόλου στο αρχείο.`,"settings.downloads.collisionAttempts":`Αριθμημένα ονόματα προς δοκιμή, το πολύ`,"settings.downloads.collisionAttemptsHint":`Αυτό το χρησιμοποιεί μόνο η «Διατήρηση και των δύο». Μετρά όνομα (2), όνομα (3) και ούτω καθεξής, και τα παρατά με σφάλμα όταν έχει δοκιμάσει τόσα. Το 0 σημαίνει το ενσωματωμένο όριο των 1000, όχι «χωρίς όριο»: ένας φάκελος που γεμίζει με χίλια αντίγραφα του ίδιου ονόματος δείχνει κάτι ανεξέλεγκτο κάπου αλλού, συνήθως έναν παρακολουθούμενο φάκελο που ξαναδιαβάζει την ίδια λίστα, και ένας μετρητής που δεν σταματά ποτέ το μετατρέπει σε κατάλογο που δεν μπορεί να ανοίξει κανείς. Κάθε τιμή πάνω από 1000 κατεβαίνει στο 1000 κατά την αποθήκευση.`,"settings.downloads.autoConfirmDelay":`Αναμονή πριν από την αυτόματη επιβεβαίωση (δευτερόλεπτα)`,"settings.downloads.autoConfirmDelayHint":`Πόσο περιμένει μια νέα παρτίδα στον συλλέκτη πριν επιβεβαιωθεί μόνη της. Αυτή είναι η ευκαιρία σου να της ρίξεις μια ματιά, να πετάξεις έναν σύνδεσμο ή να αλλάξεις τον φάκελο. Κάθε παρτίδα κάνει τη δική της αντίστροφη μέτρηση πάνω δεξιά, και το κουμπί διακοπής εκεί αφήνει τους συνδέσμους της στον συλλέκτη. Οι σύνδεσμοι που επιβεβαιώνεις ή αφαιρείς στο μεταξύ μένουν ανέγγιχτοι. Το 0 επιβεβαιώνει μια παρτίδα τη στιγμή που φτάνει. Μια νέα τιμή ισχύει και για αντίστροφες μετρήσεις που ήδη τρέχουν, οπότε αν ορίσεις 0 επιβεβαιώνονται αμέσως. Τίποτα από αυτά δεν γίνεται αν δεν είναι ενεργό το «Άμεση έναρξη των συνδέσμων που προστίθενται» στην ενότητα «Είσοδος συνδέσμων» παραπάνω, και αν το απενεργοποιήσεις σταματά κάθε αντίστροφη μέτρηση. Μία ημέρα είναι το ανώτατο: μια αντίστροφη μέτρηση είναι φτιαγμένη για να την παρακολουθείς όσο τρέχει, και οτιδήποτε μεγαλύτερο είναι ένα ψηφίο που ξέφυγε και όχι προτίμηση. Ένας αρνητικός αριθμός γίνεται 0 κατά την αποθήκευση.`,"settings.downloads.onDupes":`Σύνδεσμοι που έχεις ήδη`,"settings.downloads.onDupesHint":`Τι γίνεται με έναν σύνδεσμο που φεύγει από τον συλλέκτη και είναι ήδη στη λίστα σου. Το «Πρόσθεσέ τον έτσι κι αλλιώς» τον χειρίζεται όπως κάθε άλλο σύνδεσμο. Το «Άφησέ τον στον συλλέκτη» δεν τον επιβεβαιώνει και δεν αλλάζει τίποτε άλλο σε αυτόν, οπότε μια μεταγενέστερη επιβεβαίωση τον παίρνει κανονικά. Το «Πέταξέ τον» τον βγάζει από τη λίστα και είναι η μόνη απάντηση που πετά κάτι, γι' αυτό δεν είναι ποτέ η προεπιλογή. Το «Ρώτα με» ρωτά μόνο όταν κάποιος πάτησε πραγματικά Επιβεβαίωση: η αντίστροφη μέτρηση, ο παρακολουθούμενος φάκελος και το Click’n’Load δεν έχουν κανέναν να ρωτήσουν, οπότε σε αυτά ο σύνδεσμος μένει στον συλλέκτη. Μια μεμονωμένη παρτίδα μπορεί να το παρακάμψει· ό,τι ορίσεις εδώ ισχύει όταν δεν το κάνει.`,"settings.downloads.addAtTop":`Οι νέοι επιβεβαιωμένοι σύνδεσμοι μπαίνουν μπροστά στην ουρά`,"settings.downloads.addAtTopHint":`Μια παρτίδα που φεύγει από τον συλλέκτη παίρνει την επόμενη σειρά αντί να μπει πίσω από όλα όσα ήδη περίμεναν. Μετακινείται μέσα στη δική της βαθμίδα προτεραιότητας, ακριβώς εκεί όπου θα την έβαζε η «Μετακίνηση στην κορυφή», οπότε μια λήψη στην οποία έδωσες μεγαλύτερη προτεραιότητα τρέχει ακόμα πρώτη. Από προεπιλογή είναι ανενεργό, και τότε οι σύνδεσμοι μπαίνουν στο τέλος της ουράς. Ισχύει όπως κι αν επιβεβαιώθηκε η παρτίδα: με το χέρι, από την αντίστροφη μέτρηση ή από τον παρακολουθούμενο φάκελο.`,"settings.stall.enabled":`Σήμανση των λήψεων που σταματούν να προχωρούν`,"settings.stall.enabledHint":`Μια νεκρή σύνδεση δεν αποτυγχάνει και δεν σταματά. Η γραμμή λέει ακόμη ότι τρέχει, με 0 B/s, κρατά τη θέση της στις λήψεις, και το πρωί κάθεται εκεί με το ίδιο τρία τοις εκατό που είχε τα μεσάνυχτα. Με αυτό αναμμένο, μια μεταφορά που δεν έχει κουνήσει byte για τον χρόνο που ορίζεται από κάτω σημειώνεται στη λίστα ως κολλημένη. Η σήμανση δεν αλλάζει τίποτα στην ίδια τη λήψη, λέει μόνο αυτό που ισχύει ήδη. Σβηστό σημαίνει ότι δεν σημειώνεται ποτέ τίποτα.`,"settings.stall.timeout":`Χρόνος χωρίς byte (δευτερόλεπτα)`,"settings.stall.timeoutHint":`Πόσο επιτρέπεται σε μια λήψη που τρέχει να μην κουνά κανένα byte πριν μετρήσει ως κολλημένη. Τα 60 δευτερόλεπτα είναι η μικρότερη τιμή που υπάρχει, και οτιδήποτε χαμηλότερο ανεβαίνει στα 60 κατά την αποθήκευση: κάτω από ένα λεπτό, μια αλλαγή κομματιού, μια επανασύνδεση ή η αναμονή που επιβάλλει ο ίδιος ο πάροχος μοιάζουν ακριβώς με νεκρή σύνδεση, οπότε ένας μικρότερος χρόνος δεν θα έβρισκε κολλήματα, θα σημείωνε ολόκληρη την ουρά. Το ανώτατο όριο είναι μία ημέρα (86400 δευτερόλεπτα). Ένας σύνδεσμος που περιμένει captcha δεν μετράει ποτέ ως κολλημένος, και το ρολόι του ξαναρχίζει από το μηδέν μόλις απαντηθεί το captcha.`,"settings.stall.restart":`Επανεκκίνηση κολλημένης λήψης από την αρχή`,"settings.stall.restartHint":`Βάζει μια σημειωμένη λήψη πίσω στην ουρά και την ξεκινά από την αρχή. Έτσι πετιούνται τα byte που είχε ήδη φέρει η κολλημένη προσπάθεια, ακριβώς όπως σε μια επανεκκίνηση με το χέρι, και γι’ αυτό είναι δικός του διακόπτης και μένει σβηστός μέχρι να τον ανάψεις: η σήμανση είναι πληροφορία, η επανεκκίνηση είναι απόφαση. Τα torrent δεν ξεκινούν ποτέ ξανά από εδώ, ό,τι κι αν λέει αυτό, γιατί ένα torrent που δεν βρήκε ομότιμους θα έπαιρνε απλώς πάλι το ίδιο magnet, μείον όλα όσα είχε ήδη φέρει.`,"settings.stall.maxRestarts":`Επανεκκινήσεις ανά λήψη`,"settings.stall.maxRestartsHint":`Πόσες φορές επιτρέπεται να ξεκινήσει αυτόματα από την αρχή μία λήψη πριν την αφήσουν ήσυχη. Το 0 δεν σημαίνει απεριόριστες, σημαίνει 3, τον ενσωματωμένο αριθμό. Μόλις φτάσει το όριο, η λήψη κρατά τη σήμανσή της και μένει εκεί που είναι, ώστε να δεις εσύ ο ίδιος τι συμβαίνει, αντί να δουλεύει εκείνη όλη νύχτα τον ίδιο διακομιστή στο κενό. Ο διακομιστής δέχεται το πολύ 20, οτιδήποτε παραπάνω αποθηκεύεται ως 20. Ο μετρητής ανήκει στη λήψη και μηδενίζεται μόνο όταν αυτή ολοκληρωθεί.`,"settings.resolvers.audioFormat":`Μορφή ήχου`,"settings.resolvers.audioFormatHint":`Αν η πηγή έχει κομμάτι σε αυτή τη μορφή, αντιγράφεται, αλλιώς ο ήχος μετατρέπεται με το ffmpeg. Το «Αυτόματο» παίρνει το καλύτερο κομμάτι όπως είναι. Αυτό είναι μόνο η εφεδρική επιλογή: οι νέοι σύνδεσμοι παίρνουν τη μορφή ήχου από τις προεπιλογές παραλλαγών πιο κάτω, και η επιλογή στη γραμμή υπερισχύει και των δύο.`,"settings.resolvers.audioBitrate":`Ρυθμός bit ήχου`,"settings.resolvers.audioBitrateHint":`Σε ποιον ρυθμό κωδικοποιεί το ffmpeg όταν μετατρέπει, σε kbit/s. Το «Αυτόματο» δεν ορίζει στόχο και αφήνει την προεπιλογή του yt-dlp, περίπου 128 kbit/s, μεταβλητό. Ένα αντιγραμμένο κομμάτι κρατά τον δικό του ρυθμό bit. Αυτό είναι ανώτατο όριο: 320 από πηγή με 128 δεν ακούγονται καθόλου καλύτερα.`,"settings.resolvers.audioLang":`Ομιλούμενη γλώσσα`,"settings.resolvers.audioLangHint":`Περιορίζει μια γραμμή ήχου σε μία ομιλούμενη γλώσσα όταν η πηγή έχει πολλές, όπως συμβαίνει με την αυτόματη μεταγλώττιση του YouTube: χωρίς αυτό κερδίζει το κομμάτι που ακούγεται καλύτερα, και αυτό δεν είναι πάντα εκείνο που πραγματικά μιλιέται. Δύο γράμματα ή μια πλήρης ετικέτα όπως pt-BR. Ταιριάζει από την αρχή, οπότε το de πιάνει και το de-DE. Το κενό σημαίνει καμία προτίμηση. Μια πηγή που δεν δηλώνει γλώσσα ανά κομμάτι δεν αποτυγχάνει γι' αυτό: το αίτημα επιστρέφει στο συνηθισμένο καλύτερο κομμάτι.`,"settings.resolvers.music":`Σήμανση των λήψεων ήχου ως μουσική`,"settings.resolvers.musicHint":`Μετατρέπει τη γραμμή ήχου σε tagger: καλλιτέχνης, άλμπουμ, τίτλος και αριθμός κομματιού γράφονται μέσα στο αρχείο, τα αρχεία καταλήγουν σε φακέλους καλλιτέχνη και άλμπουμ με αριθμημένα ονόματα, και δίπλα τους αποθηκεύεται ένα cover.jpg. Χωρίς ετικέτες, δώδεκα αρχεία είναι δώδεκα άσχετα σινγκλ του Unknown Artist στο Jellyfin ή στο Navidrome, γιατί μια βιβλιοθήκη διαβάζει τις ετικέτες και όχι το όνομα αρχείου. Η μετονομασία γίνεται μόνο όσο το πεδίο για το όνομα αρχείου εξόδου παραπάνω είναι κενό: ένα πρότυπο που έγραψε κάποιος κερδίζει πάντα.`,"settings.resolvers.subtitleStrict":`Γραμμή υποτίτλων που δεν παρήγαγε αρχείο να μετρά ως σφάλμα`,"settings.resolvers.subtitleStrictHint":`Μια πηγή που δεν κουβαλά τη γλώσσα που ζήτησες το λέει ως προειδοποίηση, και αυτό το backend τρέχει το yt-dlp με τις προειδοποιήσεις σβηστές. Η εργασία λοιπόν τελειώνει καθαρά και κάθεται πράσινη πάνω από έναν άδειο φάκελο, και τίποτα δεν σου λέει ότι η γλώσσα δεν υπήρξε ποτέ διαθέσιμη. Με αυτό αναμμένο, μια γραμμή υποτίτλων που δεν έγραψε τίποτα γίνεται κόκκινη και ονομάζει τις γλώσσες που ζήτησε. Σβηστό από προεπιλογή, γιατί το άναμμά του κάνει να αποτυγχάνουν γραμμές που μια υπάρχουσα εγκατάσταση τις κλείνει πράσινες εδώ και μήνες.`,"settings.resolvers.embedMetadata":`Εγγραφή τίτλου, δημιουργού και ημερομηνίας μέσα στο αρχείο`,"settings.resolvers.embedMetadataHint":`Βάζει τον τίτλο, τον δημιουργό που το ανέβασε, την ημερομηνία και την περιγραφή της ίδιας της πηγής στο μπλοκ ετικετών του container. Αυτό είναι το πρώτο που διαβάζουν το Jellyfin και το Plex όταν δεν υπάρχει NFO δίπλα στο αρχείο. Μόνο γραμμές βίντεο και ήχου: η μικρογραφία, οι υπότιτλοι και η περιγραφή είναι επίτηδες ξεχωριστά αρχεία, και το να γράψεις ετικέτες μέσα τους θα ήταν αντίφαση.`,"settings.resolvers.embedThumbnail":`Ενσωμάτωση της εικόνας εξωφύλλου`,"settings.resolvers.embedThumbnailHint":`Επισυνάπτει τη μικρογραφία της ίδιας της πηγής ως εξώφυλλο μέσα στο αρχείο, ώστε και μια βιβλιοθήκη που δεν ψάχνει τίποτα μόνη της να δείχνει εικόνα. Μόνο γραμμές βίντεο και ήχου. Δεν αντικαθιστά τη γραμμή μικρογραφίας, που αποθηκεύει την ίδια εικόνα ως δικό της .jpg δίπλα στη λήψη.`,"settings.resolvers.embedChapters":`Ενσωμάτωση των σημαδιών κεφαλαίων`,"settings.resolvers.embedChaptersHint":`Γράφει τα σημάδια κεφαλαίων της ίδιας της πηγής μέσα στον container. Αυτό είναι που κάνει το κουμπί παράλειψης ενός player να πηδά στην επόμενη ενότητα, αντί για έναν σταθερό αριθμό δευτερολέπτων.`,"settings.resolvers.embedSubs":`Ενσωμάτωση των υποτίτλων στο βίντεο`,"settings.resolvers.embedSubsHint":`Φέρνει τις γλώσσες που ονομάζονται στην κάρτα υποτίτλων παραπάνω και τις βάζει μέσα στο αρχείο βίντεο, αντί να αφήνει αρχεία .srt δίπλα του. Μόνο γραμμές βίντεο: ένα εξαγόμενο αρχείο ήχου δεν έχει ροή υποτίτλων για να τις κουβαλήσει, και το yt-dlp απαντά σε τέτοιο αίτημα με μια προειδοποίηση που αυτό το backend δεν τυπώνει ποτέ. Χρησιμοποιεί την ίδια λίστα γλωσσών και τον ίδιο διακόπτη για τους αυτόματους υπότιτλους με τη γραμμή υποτίτλων, οπότε τα δύο δεν μπορούν ποτέ να διαφωνήσουν μεταξύ τους.`,"settings.resolvers.embedSplitChapters":`Αποθήκευση και ενός αρχείου ανά κεφάλαιο`,"settings.resolvers.embedSplitChaptersHint":`Γράφει ένα επιπλέον αρχείο ανά κεφάλαιο δίπλα στην πλήρη λήψη. Προσθέτει αρχεία αντί να αντικαθιστά το ολόκληρο, οπότε ένα δίωρο βίντεο με είκοσι κεφάλαια καταλήγει ως είκοσι ένα αρχεία.`,"settings.resolvers.embedNfo":`Εγγραφή αρχείου NFO δίπλα στη λήψη`,"settings.resolvers.embedNfoHint":`Αποθηκεύει ένα .nfo σε στιλ Kodi, Jellyfin και Plex δίπλα στο ολοκληρωμένο αρχείο, φτιαγμένο από τα δεδομένα που είχε ήδη μαζέψει το yt-dlp κατά την εξαγωγή. Μόνο γραμμές βίντεο και ήχου. Μια αποτυχημένη εγγραφή δεν ρίχνει ποτέ τη λήψη: το αρχείο πολυμέσων είναι έτσι κι αλλιώς πλήρες, και το συνοδευτικό εμφανίζεται ξανά αν η εργασία τρέξει άλλη μια φορά.`,"settings.resolvers.measure":`Μέτρηση του ολοκληρωμένου αρχείου`,"settings.resolvers.measureHint":`Ξαναδιαβάζει κάθε ολοκληρωμένη λήψη βίντεο ή ήχου με το ffprobe και καταγράφει τι περιέχει πραγματικά: διάρκεια, ανάλυση, codecs, πόσα κομμάτια ήχου. Τρέχει μία σύντομη τοπική διεργασία ανά λήψη, χωρίς πρόσβαση στο δίκτυο και χωρίς νέα εξάρτηση. Αυτό που πιάνει είναι μια λήψη που σταμάτησε νωρίς και ενώθηκε παρ' όλα αυτά, όπου ο κωδικός εξόδου είναι 0, το μέγεθος μοιάζει λογικό και η εικόνα σταματά στα είκοσι λεπτά. Αυτό που δεν μπορεί να πιάσει είναι μια ένωση που διακόπηκε στη μέση της εγγραφής, η οποία κρατά στην κεφαλίδα της την προβλεπόμενη διάρκεια, αλλά αυτή η περίπτωση συνήθως αποτυγχάνει έτσι κι αλλιώς φανερά από μόνη της.`,"settings.resolvers.measureShortPercent":`Μετράει ως κοντό κάτω από (ποσοστό)`,"settings.resolvers.measureShortPercentHint":`Πόσο από τη διάρκεια που ανακοίνωσε η πηγή πρέπει να περιέχει πραγματικά το αρχείο για να μη θεωρείται πια σύντομο, σε ποσοστό. Το 90 είναι η προεπιλογή, όχι το 99: μια πραγματική λήψη συχνά βγαίνει λίγο κάτω από τον ανακοινωμένο αριθμό, και ένα κατώφλι που χτυπά σε αυτές μαθαίνει σε όλους να το αγνοούν. Σε μια κομμένη ένωση λείπει το μισό, όχι το πέντε τοις εκατό. Κάθε τιμή εκτός του 1 έως 100 αποθηκεύεται ως 90 αντί να κολλήσει στο κοντινότερο άκρο. Δεν υπάρχει 0 για «μη διαμαρτύρεσαι ποτέ», γιατί η ειδοποίηση είναι ο λόγος που ενεργοποιείς τον έλεγχο.`,"settings.resolvers.measureFailOnShort":`Το κοντό αρχείο να μετρά ως σφάλμα αντί για προειδοποίηση`,"settings.resolvers.measureFailOnShortHint":`Ένα αρχείο κάτω από το κατώφλι παραπάνω καταλήγει ως ολοκληρωμένο και κουβαλά μια προειδοποίηση στη γραμμή του. Με αυτό αναμμένο γίνεται κόκκινο, κάτι που το κάνει να ξανατρέχει με ένα κλικ. Σβηστό από προεπιλογή, γιατί τα byte στον δίσκο είναι αληθινά και συχνά αξίζει να κρατηθούν.`,"settings.resolvers.live":`Αναγνώριση ζωντανών μεταδόσεων`,"settings.resolvers.liveHint":`Μια ζωντανή μετάδοση δεν έχει τέλος και δεν έχει συνολικό μέγεθος, οπότε χωρίς αυτό ένας σύνδεσμος προς μία φτάνει ως συνηθισμένη λήψη, με μπάρα προόδου φτιαγμένη από έναν αριθμό που δεν ξέρει κανείς, και σέρνεται προς ένα τέλος που δεν έρχεται ποτέ ενώ ο δίσκος γεμίζει. Με αυτό αναμμένο, μια τέτοια γραμμή δείχνει πόση ώρα καταγράφει ήδη και πόσο έχει φτάσει, και τα δύο όρια από κάτω μπορούν να τη φρενάρουν. Ελέγχει επίσης την ίδια την αναγνώριση: αφημένο σβηστό, οι λήψεις τρέχουν με ακριβώς τη μορφή προόδου και ακριβώς την ανάλυση που είχαν πάντα.`,"settings.resolvers.liveFromStart":`Έναρξη από την αρχή της μετάδοσης`,"settings.resolvers.liveFromStartHint":`Καταγράφει από την ίδια την αρχή της μετάδοσης, αντί να μπαίνει στο ζωντανό άκρο. Το yt-dlp το αναφέρει ως μόνο για YouTube και πειραματικό, και αγνοείται εντελώς για οτιδήποτε δεν είναι ζωντανό, οπότε εκεί που δεν ισχύει δεν κοστίζει τίποτα.`,"settings.resolvers.liveMaxMinutes":`Χρονικό όριο εγγραφής`,"settings.resolvers.liveMaxMinutesHint":`Σταματά μια εγγραφή μετά από τόσα λεπτά, μετρώντας από την πρώτη στιγμή που φτάνουν πραγματικά δεδομένα ροής και όχι από την έναρξη της εργασίας, οπότε η αναμονή για μια πρεμιέρα ή η μάχη με έναν έλεγχο anti-bot δεν τρώει από τον χρόνο. Το 0 σημαίνει χωρίς όριο. Το όριο είναι διάρκεια, όχι ώρα της ημέρας: το «σταμάτα στις 23:00» σε μια ροή που ξεκίνησε στις 22:00 είναι όριο μίας ώρας που σιωπηλά γίνεται είκοσι τρεις ώρες όταν ο ίδιος σύνδεσμος επικολληθεί τα μεσάνυχτα. Όταν φτάσει το όριο, η εγγραφή σταματά ομαλά, ώστε το αρχείο να ολοκληρωθεί και να παίζει, και η γραμμή καταλήγει ως ολοκληρωμένη με τον λόγο δίπλα της και όχι ως σφάλμα.`,"settings.resolvers.liveMaxMB":`Όριο μεγέθους εγγραφής`,"settings.resolvers.liveMaxMBHint":`Σταματά μια εγγραφή μόλις φτάσει τόσο υλικό, σε MiB. Το 0 σημαίνει κανένα όριο. Μετριέται ό,τι αναφέρει το yt-dlp ως κατεβασμένο, όχι το μέγεθος στον δίσκο: μια ζωντανή λήψη γράφεται ως προσωρινά κομμάτια, των οποίων το συνολικό μέγεθος δεν είναι ο αριθμός πάνω στον οποίο βάζει κανείς όριο. Όποιο από τα δύο όρια φτάσει πρώτο τερματίζει την εγγραφή, ήπια, και η γραμμή κλείνει ως ολοκληρωμένη με τον λόγο πάνω της.`,"settings.resolvers.cookies":`Χρήση αποθηκευμένων cookies σύνδεσης`,"settings.resolvers.cookiesHint":`Παραδίδει στο yt-dlp το cookies.txt που είναι αποθηκευμένο για έναν ιστότοπο, και αυτό είναι που περνά το «συνδέσου για να επιβεβαιώσεις ότι δεν είσαι bot» και τις πύλες ηλικίας. Το αρχείο δεν είναι ποτέ μέρος του εγγράφου ρυθμίσεων: ζει στον κρυπτογραφημένο χώρο διαπιστευτηρίων, γράφεται σε ένα προσωρινό αρχείο που μπορεί να διαβάσει μόνο αυτός ο διακομιστής, και εκείνο το αρχείο σβήνεται τη στιγμή που τελειώνει η διεργασία. Διακόπτης και όχι αυτόματο, γιατί το να στέλνεις μια συνδεδεμένη συνεδρία έχει συνέπειες: ένα όριο ρυθμού ή ένας αποκλεισμός πέφτει στον λογαριασμό, όχι στη διεύθυνση. Για έναν ιστότοπο χωρίς αποθηκευμένο αρχείο, αυτό δεν αλλάζει τίποτα εκεί.`,"settings.resolvers.variantDefaults":`Προεπιλογές παραλλαγών`,"settings.resolvers.presetsHint":`Κάθε σύνδεσμος yt-dlp γίνεται πέντε γραμμές: βίντεο, ήχος, μικρογραφία, υπότιτλοι και περιγραφή. Αυτός ο πίνακας αποφασίζει ανά ιστότοπο ποιες από αυτές δείχνει ο συλλέκτης και με ποια μορφή και ποιότητα ξεκινούν οι γραμμές βίντεο και ήχου. Αν απενεργοποιήσεις μια παραλλαγή, οι γραμμές της φεύγουν αμέσως, και από συνδέσμους που είναι ήδη στον συλλέκτη, και αν την ενεργοποιήσεις, επιστρέφουν. Μόλις ελεγχθεί ένας σύνδεσμος, οι γραμμές βίντεο και ήχου του περνούν στο δικό του κομμάτι που είναι πιο κοντά στην επιλογή. Ένας ιστότοπος χωρίς γραμμή εδώ παίρνει και τις πέντε στην καλύτερη ποιότητα. Η ποιότητα και η μορφή ήχου πιο πάνω σε αυτή τη σελίδα ισχύουν μόνο για γραμμές χωρίς δική τους επιλογή. Το γρανάζι σε ένα πακέτο στον συλλέκτη ανοίγει τις ίδιες ρυθμίσεις για τον hoster αυτού του πακέτου.`,"settings.module.categories":`Κατηγορίες`,"settings.module.feeds":`Συνδρομές σε ροές`,"settings.module.downloadclient":`Πελάτης λήψεων για Sonarr και Radarr`,"settings.downloads.collisionTitle":`Συγκρούσεις ονομάτων`,"settings.downloads.collectorTitle":`Συλλέκτης`,"settings.downloads.diskTitle":`Χώρος στον δίσκο`,"settings.downloads.diskHint":`Τρεις αριθμοί που κρατούν πίσω τις λήψεις πριν γεμίσει ο δίσκος. Και οι τρεις είναι ελεύθερα byte στον τόμο όπου γράφεται η λήψη, οπότε ένας φάκελος εργασίας σε άλλον δίσκο μετριέται σε εκείνον. Το μηδέν απενεργοποιεί έναν αριθμό. Δεν μπορεί να ερωτηθεί κάθε σύστημα πόσος χώρος είναι ελεύθερος, και όπου δεν υπάρχει απάντηση δεν κρατιέται τίποτα πίσω, γιατί μια προστασία που μπλοκάρει όταν δεν ξέρει θα σταματούσε ένα απολύτως υγιές μηχάνημα.`,"settings.stall.title":`Κόλλημα`,"settings.advanced.mirrorsTitle":`Αντίγραφα του ίδιου αρχείου`,"settings.advanced.offlineTitle":`Σύνδεσμοι που είναι ήδη νεκροί`,"settings.advanced.reclaimTitle":`Αρχεία που βρίσκονται ήδη στον δίσκο`,"settings.advanced.retryTitle":`Επαναλήψεις ανά είδος σφάλματος`,"settings.resolvers.audioTitle":`Ήχος`,"settings.resolvers.subtitlesTitle":`Υπότιτλοι`,"settings.resolvers.embedTitle":`Μέσα στο αρχείο`,"settings.resolvers.measureTitle":`Έλεγχος του ολοκληρωμένου αρχείου`,"settings.resolvers.liveTitle":`Ζωντανές μεταδόσεις`,"settings.resolvers.cookiesTitle":`Cookies σύνδεσης`,"settings.hostRules.add":`Προσθήκη παρόχου`,"settings.hostRules.remove":`Αφαίρεση`,"settings.hostRules.empty":`Κανένας πάροχος δεν έχει ακόμη δικούς του αριθμούς.`,"settings.hostRules.emptyHint":`Μέχρι να προσθέσεις έναν, όλα ακολουθούν τις τιμές της σελίδας Λήψεις.`,"settings.hostRules.duplicate":`Υπάρχει ήδη γραμμή για αυτόν τον πάροχο.`,"settings.feeds.add":`Προσθήκη συνδρομής`,"settings.feeds.remove":`Αφαίρεση`,"settings.feeds.empty":`Δεν υπάρχουν ακόμη συνδρομές.`,"settings.feeds.emptyHint":`Μια συνδρομή ελέγχει μόνη της μια ροή και βάζει ό,τι είναι νέο στον συλλέκτη.`,"settings.feeds.duplicate":`Αυτή η διεύθυνση είναι ήδη σε συνδρομή.`,"settings.categories.add":`Προσθήκη κατηγορίας`,"settings.categories.remove":`Αφαίρεση`,"settings.categories.empty":`Δεν υπάρχουν ακόμη κατηγορίες.`,"settings.categories.emptyHint":`Μια κατηγορία κρατά έναν φάκελο και μερικές προεπιλογές κάτω από ένα όνομα, ώστε να διαλέγεις το όνομα αντί να περιγράφεις ξανά το ίδιο πράγμα.`,"settings.categories.duplicate":`Υπάρχει ήδη κατηγορία με αυτό το όνομα.`,"settings.categories.full":`Ο πίνακας είναι γεμάτος στις {max} κατηγορίες.`,"settings.resolvers.presetAdd":`Προσθήκη παρόχου`,"settings.resolvers.presetRemove":`Αφαίρεση`,"settings.resolvers.presetsEmpty":`Κανένας πάροχος δεν έχει ακόμη δικές του προεπιλογές.`,"settings.resolvers.presetHost":`Πάροχος`,"settings.resolvers.presetHostHint":`Ο ιστότοπος στον οποίο ισχύουν αυτές οι προεπιλογές, για παράδειγμα youtube.com. Αποθηκεύεται με πεζά και χωρίς «www.» στην αρχή, και η επικόλληση ολόκληρης διεύθυνσης δουλεύει επίσης: κρατιέται μόνο ο host. Για τους μεγάλους ιστότοπους βίντεο, μια καταχώριση καλύπτει και τις άλλες διευθύνσεις τους: το youtube.com καλύπτει και τα youtu.be και m.youtube.com. Ένας hoster χωρίς καταχώριση εδώ ξεκινά με όλες τις παραλλαγές ενεργές, στην καλύτερη ποιότητα.`,"settings.resolvers.quality.4320p":`Έως 4320p (8K)`,"settings.resolvers.quality.240p":`Έως 240p`,"settings.resolvers.quality.144p":`Έως 144p`,"settings.downloads.confirm.include":`Πρόσθεσέ τον έτσι κι αλλιώς`,"settings.downloads.confirm.exclude":`Άφησέ τον στον συλλέκτη`,"settings.downloads.confirm.excludeAndRemove":`Πέταξέ τον`,"settings.downloads.confirm.ask":`Ρώτα με`,"settings.advanced.mirror.off":`Ποτέ`,"settings.advanced.mirror.filename-only":`Ίδιο όνομα αρχείου`,"settings.advanced.mirror.size-only":`Ίδιο μέγεθος`,"settings.advanced.mirror.filename-and-size":`Ίδιο όνομα και ίδιο μέγεθος`,"settings.advanced.mirror.filename-or-hash":`Ίδιο όνομα, ή ίδιο άθροισμα ελέγχου`,"settings.advanced.mirror.hash-only":`Ίδιο άθροισμα ελέγχου`,"settings.advanced.offline.include":`Πρόσθεσέ τον έτσι κι αλλιώς`,"settings.advanced.offline.exclude":`Άφησέ τον στον συλλέκτη`,"settings.advanced.offline.exclude-and-remove":`Πέταξέ τον`,"settings.advanced.offline.ask":`Ρώτα με`,"settings.advanced.reclaim.checksum":`Άθροισμα ελέγχου που ταιριάζει`,"settings.advanced.reclaim.record":`Μια καταγραφή ότι αυτή η λήψη το έγραψε`,"settings.advanced.reclaim.size":`Το σωστό όνομα και το σωστό μέγεθος`,"settings.categories.priorityNone":`Καμία προτίμηση`,"settings.feeds.priorityNone":`Χωρίς ορισμό`,"task.waiting.disk":`Περιμένει χώρο στον δίσκο`,"settings.feeds.status":`Κατάσταση`,"settings.feeds.statusPolling":`Ελέγχεται`,"settings.feeds.statusNotPolling":`Δεν ελέγχεται`,"settings.feeds.statusUnknown":`Δεν έχει ελεγχθεί ακόμη από τότε που ξεκίνησε ο διακομιστής`,"settings.feeds.lastPolled":`Τελευταίος έλεγχος`,"settings.feeds.lastPolledNever":`Δεν έχει ελεγχθεί ακόμη`,"settings.feeds.lastPolledHint":`Πότε κοιτάχτηκε τελευταία φορά αυτή η συνδρομή, είτε πέτυχε η ανάκτηση είτε όχι. Στην επανεκκίνηση του διακομιστή η ένδειξη χάνεται, ενώ ό,τι έχει ήδη προσθέσει η συνδρομή δεν χάνεται. Μια ροή που ακολουθείς εδώ και μήνες δείχνει έτσι ανέλεγκτη για τα λίγα δευτερόλεπτα μετά την επανεκκίνηση.`,"settings.feeds.pollFailed":`Ο τελευταίος έλεγχος απέτυχε`,"settings.feeds.notPolledReason":`Αυτή η συνδρομή δεν ελέγχεται καθόλου`,"settings.feeds.seededYes":`Έτοιμη, προστίθεται μόνο ό,τι είναι νέο`,"settings.feeds.seededNo":`Ο πρώτος έλεγχος δεν έχει γίνει ακόμη, και μέχρι τότε δεν προστίθεται τίποτα`,"settings.feeds.seededHint":`Ο πρώτος έλεγχος μιας νέας συνδρομής σημειώνει ό,τι κουβαλά η ροή εκείνη τη στιγμή και δεν προσθέτει τίποτα από αυτά, ώστε να μη σου πέσει μονομιάς όλο το παλιό αρχείο ενός εκδότη. Προστίθεται μόνο ό,τι εμφανιστεί από εκεί και πέρα.`,"settings.feeds.remembered":`{n} καταχωρίσεις σε μνήμη`,"settings.feeds.rememberedHint":`Πόσες καταχωρίσεις αναγνωρίζει ξανά αυτή η συνδρομή, ώστε να μην προστεθούν δεύτερη φορά όσο η ροή τις σερβίρει ακόμη. Το πολύ 500 ανά συνδρομή. Οι παλαιότερες φεύγουν πρώτες, και μια καταχώριση που είναι ακόμη στη ροή δεν είναι ποτέ ανάμεσά τους.`,"settings.feeds.test":`Δοκιμή`,"settings.feeds.testBusy":`Γίνεται ανάκτηση`,"settings.feeds.testHint":`Ανακτά αυτή τη διεύθυνση μία φορά και σου δείχνει τι υπάρχει μέσα, ώστε να δεις τους τίτλους πάνω στους οποίους δοκιμάζεται το φίλτρο σου. Μόνο διαβάζει: τίποτα δεν μπαίνει στον συλλέκτη και τίποτα δεν σημειώνεται ως ιδωμένο, οπότε μπορείς να το πατήσεις και για διεύθυνση που δεν έχεις αποθηκεύσει ακόμη.`,"settings.feeds.testResult":`Τι υπάρχει σε αυτή τη ροή`,"settings.feeds.testFeedName":`Όνομα ροής`,"settings.feeds.testNoName":`Αυτό το έγγραφο δεν δημοσιεύει όνομα`,"settings.feeds.testMatched":`{matched} από {total} καταχωρίσεις ταιριάζουν στο φίλτρο τίτλων`,"settings.feeds.testNoFilter":`Κανένα φίλτρο τίτλων, οπότε παίρνονται και οι {total} καταχωρίσεις`,"settings.feeds.testShowing":`Εμφανίζονται οι πρώτες {n}`,"settings.feeds.testMatchYes":`Παίρνεται`,"settings.feeds.testMatchNo":`Μένει εκτός`,"settings.feeds.testNoneMatch":`Τίποτα σε αυτή τη ροή δεν ταιριάζει στο φίλτρο τίτλων σου. Σύγκρινε τη γραφή με τους τίτλους παραπάνω.`,"settings.feeds.testEmpty":`Η διεύθυνση απάντησε, αλλά το έγγραφο δεν περιέχει καμία απολύτως καταχώριση. Έλεγξε αν είναι πράγματι ροή και όχι η σελίδα πάνω στην οποία βρίσκεται η ροή.`,"settings.feeds.testFailed":`Αυτή η ροή δεν μπόρεσε να διαβαστεί`,"settings.headerProfiles.title":`Προφίλ κεφαλίδων`,"settings.headerProfiles.hint":`Μερικοί ιστότοποι δίνουν ένα αρχείο μόνο σε συνδεδεμένο περιηγητή, ή μόνο όταν η κλήση έρχεται από μια δική τους σελίδα. Ένα προφίλ αποθηκεύει τις κεφαλίδες για έναν ακριβώς ιστότοπο, κρυπτογραφημένες όπως και τα διαπιστευτήριά σου, και το KnightLoader τις στέλνει μαζί με κάθε λήψη από αυτόν τον ιστότοπο.`,"settings.headerProfiles.empty":`Δεν υπάρχουν ακόμη προφίλ κεφαλίδων.`,"settings.headerProfiles.emptyHint":`Αξίζει ένα, μόλις μια λήψη δουλεύει μόνο όσο είσαι συνδεδεμένος στον περιηγητή.`,"settings.headerProfiles.add":`Προσθήκη προφίλ`,"settings.headerProfiles.name":`Όνομα προφίλ`,"settings.headerProfiles.nameHint":`Με αυτό το όνομα καλείς το προφίλ, σε έναν κανόνα Packagizer όπως και εδώ. Μόνο γράμματα, ψηφία και - _ ή .`,"settings.headerProfiles.namePlaceholder":`π.χ. forum`,"settings.headerProfiles.origin":`Ιστότοπος`,"settings.headerProfiles.originHint":`Επικόλλησε τη διεύθυνση της σελίδας από την οποία αντέγραψες τις κεφαλίδες. Άλλη θύρα, και http αντί για https, μετρούν ως άλλος ιστότοπος και χρειάζονται δικό τους προφίλ. Ένας υποτομέας δεν καλύπτεται από το προφίλ του τομέα του.`,"settings.headerProfiles.headers":`Κεφαλίδες`,"settings.headerProfiles.headerName":`Όνομα`,"settings.headerProfiles.headerValue":`Τιμή`,"settings.headerProfiles.valueStored":`Αποθηκευμένη`,"settings.headerProfiles.valueStoredHint":`Η τιμή μένει σε αυτό το στιγμιότυπο και δεν στέλνεται ποτέ πίσω σε αυτή τη σελίδα. Άφησε το πεδίο όπως είναι για να τη διατηρήσεις, ή γράψε νέα τιμή για να την αντικαταστήσεις.`,"settings.headerProfiles.error.originInvalid":`Αυτή δεν είναι διεύθυνση http ή https. Επικόλλησε τη διεύθυνση του ιστότοπου, για παράδειγμα https://forum.example.org.`,"settings.headerProfiles.error.originTaken":`Το προφίλ «{profile}» καλύπτει ήδη αυτόν τον ιστότοπο. Επεξεργάσου εκείνο ή διάγραψέ το πρώτα.`,"settings.headerProfiles.error.nameNeeded":`Κανένα προφίλ δεν καλύπτει ακόμη αυτόν τον ιστότοπο, οπότε δώσε όνομα σε αυτό.`,"settings.headerProfiles.error.nameInvalid":`Ένα όνομα προφίλ περιέχει μόνο γράμματα, ψηφία και - _ ή ., το πολύ 64 χαρακτήρες.`,"settings.headerProfiles.error.noHeaders":`Πρόσθεσε τουλάχιστον μία κεφαλίδα με τιμή ή διάγραψε το προφίλ.`,"settings.headerProfiles.addHeader":`Προσθήκη κεφαλίδας`,"settings.headerProfiles.removeHeader":`Αφαίρεση αυτής της κεφαλίδας`,"settings.headerProfiles.count":`{n} κεφαλίδες`,"settings.headerProfiles.save":`Αποθήκευση προφίλ`,"settings.headerProfiles.delete":`Διαγραφή προφίλ`,"settings.headerProfiles.deleteConfirm":`Να διαγραφεί το προφίλ {id}; Οι κεφαλίδες που κρατά χάνονται, και οι λήψεις από {origin} φεύγουν ξανά χωρίς αυτές.`,"settings.rules.action.category":`Κατηγορία`,"settings.rules.action.categoryHint":`Βάζει τους συνδέσμους που ταιριάζουν σε ένα από τα συρτάρια της λίστας Κατηγορίες πιο κάτω σε αυτή τη σελίδα, το οποίο φέρνει μαζί του δικό του φάκελο, δική του θέση στην ουρά, δικό του διακόπτη αποσυμπίεσης και δικό του κανόνα για ένα αρχείο που υπάρχει ήδη. Αν μείνει αμετάβλητο, κανένας κανόνας δεν έχει άποψη και ο σύνδεσμος μένει αταξινόμητος. Αν αυτός ο κανόνας ονομάζει και φάκελο λήψεων, κερδίζει εκείνος ο φάκελος και το συρτάρι δίνει και πάλι όλα τα υπόλοιπα. Το να ονομάσεις ένα συρτάρι που έχει διαγραφεί απορρίπτεται κατά την αποθήκευση, γιατί ένας κανόνας που δείχνει σε συρτάρι που δεν υπάρχει δεν κάνει απολύτως τίποτα σε κάθε σύνδεσμο που ταιριάζει, χωρίς καμία ειδοποίηση.`,"settings.rules.action.categoryNone":`Δεν υπάρχουν ακόμη κατηγορίες. Φτιάξε πρώτα μία στις Κατηγορίες πιο κάτω σε αυτή τη σελίδα, αλλιώς αυτός ο κανόνας θα έβαζε συνδέσμους σε ένα συρτάρι που δεν υπάρχει.`,"settings.rules.action.categoryMissing":`{id} (διαγραμμένη)`,"settings.resolvers.cookieJars":`Αποθηκευμένα αρχεία`,"settings.resolvers.cookieJarsHint":`Ένα αποθηκευμένο αρχείο δεν εμφανίζεται ποτέ ξανά: είναι μια ζωντανή συνδεδεμένη συνεδρία, οπότε ταξιδεύει μόνο προς μία κατεύθυνση, μέσα σε αυτόν τον διακομιστή. Για να αντικαταστήσεις ένα, επικόλλησε από πάνω του το νέο αρχείο.`,"settings.resolvers.cookieHost":`Ιστότοπος`,"settings.resolvers.cookieHostPlaceholder":`youtube.com, ή η διεύθυνση από την οποία εξήγαγες το αρχείο`,"settings.resolvers.cookieText":`cookies.txt`,"settings.resolvers.cookieTextPlaceholder":`Επικόλλησε εδώ την εξαγόμενη cookies.txt`,"settings.resolvers.cookieSave":`Αποθήκευση αρχείου`,"settings.resolvers.cookieRemove":`Αφαίρεση`,"settings.resolvers.cookieRemoveConfirm":`Να αφαιρεθεί το αποθηκευμένο αρχείο για {host}; Οι λήψεις από αυτόν τον ιστότοπο γίνονται τότε ξανά ανώνυμες.`,"settings.resolvers.cookieEmpty":`Κανένας ιστότοπος δεν έχει ακόμη αποθηκευμένο αρχείο.`,"settings.resolvers.cookieStored":`Αποθηκευμένο`,"detail.label":`Λεπτομέρειες εργασίας`,"detail.link":`Σύνδεσμος`,"detail.address":`Διεύθυνση`,"detail.addressHint":`Η διεύθυνση από την οποία ξεκίνησε αυτή η λήψη. Αυτό ζήτησε η εφαρμογή, και δεν είναι πάντα το σημείο από το οποίο ήρθαν τα byte: μέσω μιας υπηρεσίας debrid, ο πάροχος παρακάτω είναι ο ιστότοπος όπου βρίσκεται το αρχείο, και το backend είναι αυτό που το έφερε.`,"detail.copy":`Αντιγραφή`,"detail.copied":`Αντιγράφηκε`,"detail.copyFailed":`Δεν αντιγράφηκε τίποτα.`,"detail.origin":`Μπήκε μέσω`,"detail.originUnknown":`Δεν καταγράφηκε`,"detail.package":`Πακέτο`,"detail.noPackage":`Σε κανένα πακέτο`,"detail.onDisk":`Αυτή τη στιγμή στον δίσκο`,"detail.onDiskHint":`Πόσο μετρά το αρχείο στον δίσκο αυτό το δευτερόλεπτο, ρωτημένο από τον διακομιστή αντί να μετρηθεί εδώ. Μια λήψη που τρέχει μεγαλώνει από τη μια ματιά στην άλλη, και αυτό δεν είναι το μέγεθος που ανακοίνωσε ο πάροχος.`,"detail.mirrorOf":`Εφεδρικό αντίγραφο του`,"detail.times":`Χρονικές σημάνσεις`,"detail.timesHint":`Πότε έφτασε αυτός ο σύνδεσμος, πότε άλλαξε τελευταία φορά και πότε ολοκληρώθηκε. Δεν υπάρχει ώρα για το πότε ξεκίνησε η μεταφορά: η εφαρμογή δεν την κράτησε ποτέ πουθενά, και μια εικασία από τις άλλες τρεις θα ήταν ένας αριθμός πάνω στον οποίο ενεργεί κόσμος.`,"detail.nextTry":`Επόμενη προσπάθεια`,"detail.stalledSince":`Κολλημένο από`,"detail.retries":`Επαναλήψεις μέχρι τώρα`,"detail.retriesHint":`Πόσες φορές δοκιμάστηκε ξανά αυτή η λήψη μετά από σφάλμα. Μηδενίζεται τη στιγμή που η λήψη ολοκληρώνεται, οπότε μια ολοκληρωμένη γραμμή δείχνει μηδέν ακόμη κι όταν χρειάστηκαν τέσσερις γύροι. Πόσες προσπάθειες απομένουν δεν φαίνεται εδώ: το ανώτατο όριο εξαρτάται από την αιτία και από τον πάροχο, και αυτή η σελίδα δεν μπορεί να το υπολογίσει.`,"detail.stallRestarts":`Επανεκκινήσεις μετά από κόλλημα`,"detail.stallRestartsHint":`Πόσες φορές η επιτήρηση κολλημάτων ξεκίνησε από μόνη της ξανά αυτή τη λήψη. Μηδενίζεται μόλις η λήψη ολοκληρωθεί, ακριβώς όπως ο μετρητής από πάνω.`,"detail.failure":`Τι πήγε στραβά`,"detail.cause":`Αιτία`,"detail.message":`Τι είπε το backend`,"detail.messageHint":`Η πρόταση από αυτό που προσπάθησε να φέρει τη λήψη, λέξη προς λέξη και αμετάφραστη. Είναι το τρέχον σφάλμα και τίποτε άλλο: μια επανεκκίνηση το σβήνει, και τα προηγούμενα δεν κρατιούνται πουθενά.`,"detail.heldBack":`Κρατιέται πίσω από`,"detail.doing":`Κάνει αυτή τη στιγμή`,"detail.gaveUp":`Καμία νέα προσπάθεια`,"detail.gaveUpHint":`Εδώ σταματά επίτηδες, όχι επειδή εξαντλήθηκαν οι προσπάθειες: ένα captcha, ένας γεμάτος δίσκος, ή ένας κανόνας που λέει «ποτέ» για αυτόν τον πάροχο. Το να ανεβάσεις τον αριθμό των επαναλήψεων δεν αλλάζει τίποτα εδώ. Η ίδια η σήμανση δεν γράφεται στη βάση δεδομένων, οπότε μετά από επανεκκίνηση χάνεται, ενώ ο λόγος της μένει.`,"detail.rules":`Κανόνες που το διαμόρφωσαν`,"detail.rulesHint":`Οι κανόνες που ενεργοποιήθηκαν σε αυτόν τον σύνδεσμο καθώς ετοιμαζόταν, με τη σειρά που έτρεξαν. Κρατιούνται με το όνομά τους, οπότε ένας κανόνας που μετονομάστηκε από τότε δεν βρίσκεται πια, και ένας κανόνας που δεν είχε ποτέ όνομα κρατιέται με τη θέση που είχε τότε. Ένα κλικ τον ανοίγει στον επεξεργαστή κανόνων.`,"detail.openRule":`Άνοιγμα στον επεξεργαστή κανόνων`,"detail.noRules":`Κανένας κανόνας δεν άγγιξε αυτόν τον σύνδεσμο.`,"detail.player":`Αναπαραγωγή`,"detail.play":`Αναπαραγωγή εδώ`,"detail.playHint":`Παίζει το αρχείο απευθείας από αυτό το στιγμιότυπο, χωρίς να το κατεβάσεις δεύτερη φορά. Πριν πατήσεις αναπαραγωγή δεν φέρνεται τίποτα, και το αρχείο μένει εκεί που είναι.`,"detail.playPartial":`Αυτή η λήψη δεν έχει ολοκληρωθεί. Παίζει μόνο το κομμάτι που βρίσκεται ήδη στον δίσκο, δεν γίνεται να πηδήξεις πέρα από αυτό, και μερικά αρχεία δεν παίζουν απολύτως τίποτα πριν φτάσει το τελευταίο byte.`,"detail.playUnsupported":`Αυτός ο περιηγητής δεν μπορεί να παίξει αυτό το αρχείο. Άνοιξέ το ή αποθήκευσέ το από το μενού του δεξιού κλικ.`,"detail.playRemote":`Εδώ παίζουν μόνο αρχεία αυτού του στιγμιότυπου. Ένα άλλο στιγμιότυπο δίνει τα αρχεία του μονοκόμματα και χωρίς δυνατότητα μετακίνησης, και με αυτό δεν τα βγάζει πέρα ένα πρόγραμμα αναπαραγωγής.`,"detail.playNotLocal":`Αυτή τη λήψη την έφερε το JDownloader, οπότε το αρχείο βρίσκεται στον δίσκο εκείνης της διεργασίας και όχι σε αυτόν εδώ.`,"detail.playNoFile":`Δεν υπάρχει ακόμη τίποτα στον δίσκο για αναπαραγωγή.`,"detail.playRefused":`Ο διακομιστής δεν δίνει αυτό το αρχείο: {reason}`,"detail.playFailed":`Η αναπαραγωγή σταμάτησε: {reason}`,"detail.playClose":`Κλείσιμο του προγράμματος αναπαραγωγής`,"settings.rules.notFound":`Κανένας κανόνας εδώ δεν λέγεται «{name}». Μετονομάστηκε ή διαγράφηκε από τότε που προστέθηκε ο σύνδεσμος που τον ονομάζει.`,"notifications.title":`Ειδοποιήσεις`,"notifications.titleHint":`Αποφάσισε ανά συμβάν αν εμφανίζεται ως μήνυμα μέσα στην εφαρμογή, ως ειδοποίηση του λειτουργικού σου συστήματος, ή καθόλου. Μια ειδοποίηση συστήματος σε φτάνει μόνο όσο είναι ανοιχτή μια καρτέλα του KnightLoader, και η αθόρυβη λειτουργία παρακάτω ισχύει επιπλέον.`,"notifications.channel.app":`Μέσα στην εφαρμογή`,"notifications.channel.system":`Ειδοποίηση συστήματος`,"notifications.channel.silent":`Να μην εμφανίζεται τίποτα`,"notifications.event.downloadDone":`Η λήψη ολοκληρώθηκε`,"notifications.event.downloadDoneHint":`Κάθε λήψη που φτάνει ως το τέλος το λέει. Με διακόσια αρχεία στην ουρά, αυτά είναι διακόσια μηνύματα, οπότε σκέψου το δύο φορές πριν τα στείλεις στο σύστημα.`,"notifications.event.downloadFailed":`Η λήψη απέτυχε`,"notifications.event.downloadFailedHint":`Μια λήψη που τα παράτησε. Η αθόρυβη λειτουργία δεν την κρύβει ποτέ.`,"notifications.event.extractionDone":`Η αποσυμπίεση ολοκληρώθηκε`,"notifications.event.extractionDoneHint":`Ένα συμπιεσμένο αρχείο που αποσυμπιέστηκε ως το τέλος. Αυτό δεν αναφερόταν μέχρι τώρα πουθενά, γι’ αυτό ξεκινά στο «Να μην εμφανίζεται τίποτα».`,"notifications.event.extractionFailed":`Η αποσυμπίεση απέτυχε`,"notifications.event.extractionFailedHint":`Ένα συμπιεσμένο αρχείο που σταμάτησε χωρίς να τελειώσει. Συνήθως λείπει ο κωδικός, και τα αρχεία μένουν εκεί που είναι μέχρι να ασχοληθείς.`,"notifications.event.captchaWaiting":`Ένα captcha περιμένει`,"notifications.event.captchaWaitingHint":`Το παράθυρο του captcha ανοίγει σε αυτή την καρτέλα έτσι κι αλλιώς. Ξεκινά στο «Να μην εμφανίζεται τίποτα», γιατί εκείνο το παράθυρο είναι ήδη το μήνυμα όσο το κοιτάς. Βάλε το σε ειδοποίηση συστήματος και ένα captcha σε καρτέλα στο παρασκήνιο σε φτάνει πριν ο πάροχος πετάξει τη συνεδρία.`,"notifications.event.captchaFailed":`Το captcha απέτυχε`,"notifications.event.captchaFailedHint":`Κανείς δεν απάντησε εγκαίρως, ή η απάντηση δεν πέρασε. Η λήψη από πίσω μένει εκεί που είναι.`,"notifications.event.captchaResolved":`Το captcha απαντήθηκε αλλού`,"notifications.event.captchaResolvedHint":`Κάποιος σε άλλον περιηγητή, ή ένας αυτόματος λύτης, το απάντησε και το παράθυρο έκλεισε μόνο του.`,"notifications.systemUnavailable":`Οι ειδοποιήσεις συστήματος δεν είναι διαθέσιμες εδώ: ο περιηγητής σου τις προσφέρει μόνο μέσω HTTPS ή σε localhost. Όλα όσα βρίσκονται σε αυτή την κάρτα εξακολουθούν να εμφανίζονται μέσα στην εφαρμογή.`,"notifications.systemBlocked":`Ο περιηγητής σου μπλοκάρει τις ειδοποιήσεις για αυτή τη διεύθυνση. Οι γραμμές που είναι στο «Ειδοποίηση συστήματος» εμφανίζονται στη θέση τους μέσα στην εφαρμογή, μέχρι να τις επιτρέψεις ξανά στις ρυθμίσεις ιστοτόπου του περιηγητή σου.`,"notifications.systemNotGranted":`Ο περιηγητής δεν έδωσε την άδεια, οπότε αυτό το συμβάν μένει μέσα στην εφαρμογή. Διάλεξε ξανά «Ειδοποίηση συστήματος» για να ρωτηθεί άλλη μια φορά.`,"notifications.test":`Αποστολή δοκιμής`,"notifications.testBody":`Έτσι μοιάζει μια ειδοποίηση του KnightLoader.`,"captcha.waiting":`Ένα captcha για {host} περιμένει απάντηση.`,"archive.doneToast":`Το {name} αποσυμπιέστηκε.`,"archive.failedToast":`Η αποσυμπίεση του {name} απέτυχε.`,"settings.search.placeholder":`Αναζήτηση σε όλες τις ρυθμίσεις…`,"settings.search.hint":`Ψάχνει σε κάθε ενότητα των ρυθμίσεων: στα ονόματα των ενοτήτων, στους τίτλους των καρτών, στη λεζάντα δίπλα σε κάθε στοιχείο ελέγχου και στις εξηγήσεις πίσω από το (i). Αν διαλέξεις ένα αποτέλεσμα, ανοίγει εκείνη η ενότητα και επισημαίνεται η γραμμή. Δεν ψάχνει στις τιμές που έχεις ορίσει: γι’ αυτό υπάρχει το πλαίσιο στην καρτέλα Για προχωρημένους.`,"settings.search.clear":`Καθαρισμός αναζήτησης`,"settings.search.noMatch":`Δεν ταιριάζει τίποτα.`,"settings.search.results":`Αποτελέσματα αναζήτησης`,"settings.search.countOne":`1 αποτέλεσμα`,"settings.search.count":`{n} αποτελέσματα`,"settings.search.inHint":`βρέθηκε στο επεξηγηματικό κείμενο`,"settings.search.section":`Ενότητα`,"settings.search.rowHidden":`Το {card} είναι ανοιχτό. Εκείνη η γραμμή δεν φαίνεται αυτή τη στιγμή.`,"settings.search.command":`Αναζήτηση σε όλες τις ρυθμίσεις`,"views.label":`Αποθηκευμένες προβολές`,"views.save":`Αποθήκευση αυτής της προβολής`,"views.saveHint":`Μια προβολή είναι η αναζήτηση και τα φίλτρα που έχεις ορίσει αυτή τη στιγμή, αποθηκευμένα κάτω από ένα όνομα που δίνεις εσύ. Οι στήλες και η ταξινόμηση δεν ανήκουν σε αυτήν, εκείνες θυμούνται χωριστά.`,"views.saveTitle":`Ονομασία της προβολής`,"views.nameLabel":`Όνομα`,"views.namePlaceholder":`Μεγάλα αρχεία της περασμένης εβδομάδας`,"views.saveConfirm":`Αποθήκευση προβολής`,"views.overwriteConfirm":`Αντικατάσταση της προβολής`,"views.full":`Έχεις {n} αποθηκευμένες προβολές, και περισσότερες δεν κρατά αυτή η λίστα. Διάγραψε μία για να ελευθερωθεί θέση.`,"views.tooBig":`Αυτή η προβολή περιέχει περισσότερες τιμές φίλτρων από όσες μπορούν να αποθηκευτούν. Βγάλε την επιλογή από μερικές στην πλαϊνή γραμμή και αποθήκευσέ την ξανά.`,"views.manage":`Διαχείριση αποθηκευμένων προβολών`,"views.rename":`Μετονομασία`,"views.renameTitle":`Μετονομασία της προβολής`,"views.delete":`Διαγραφή`,"views.deleteTitle":`Να διαγραφεί η προβολή «{name}»;`,"views.deleteBody":`Μια προβολή είναι μόνο ένα όνομα για μια αναζήτηση και μερικά φίλτρα. Με τη διαγραφή δεν αλλάζει τίποτα στη λίστα και δεν αφαιρείται κανένας σύνδεσμος.`,"views.deleteConfirm":`Διαγραφή προβολής`,"views.clearAll":`Καθαρισμός της αναζήτησης και όλων των φίλτρων`,"views.clearAllHint":`Η αναζήτηση και τα φίλτρα μένουν ορισμένα όταν φύγεις από αυτή τη σελίδα και ξαναγυρίσεις, οπότε βρίσκεις πάλι τη λίστα που άφησες. Αυτό εδώ φέρνει πίσω ολόκληρη τη λίστα. Οι αποθηκευμένες προβολές μένουν όπως είναι.`,"disk.title":`Φάκελοι προορισμού`,"disk.hint":`Ελεύθερος και χρησιμοποιημένος χώρος σε κάθε φάκελο όπου μπορεί να καταλήξει μια λήψη, και πόσα έχει ακόμα να γράψει η ουρά στον καθένα. Τα νούμερα προέρχονται από την ίδια κλήση με την οποία ελέγχονται τα όρια δίσκου και είναι το πολύ λίγων δευτερολέπτων. Ελεύθερος και χρησιμοποιημένος δεν αθροίζονται πάντα στο μέγεθος του τόμου: ένα σύστημα αρχείων κρατά ένα κομμάτι για το σύστημα, και ένα όριο ανά χρήστη μπορεί να αφήνει σε αυτό το στιγμιότυπο λιγότερα από όσα έχει πραγματικά ο τόμος. Δύο φάκελοι στον ίδιο δίσκο δείχνουν ο καθένας εκείνον τον δίσκο, οπότε μην προσθέτεις ποτέ τις γραμμές μεταξύ τους.`,"disk.free":`Ελεύθερα`,"disk.used":`Κατειλημμένα`,"disk.size":`Μέγεθος τόμου`,"disk.queued":`Μένουν να γραφτούν`,"disk.queuedHint":`Τι θα πρόσθεταν σε αυτόν τον φάκελο οι λήψεις που εκκρεμούν ακόμη: το μέγεθος που ανακοίνωσε ο πάροχος, μείον όσα έχουν ήδη φτάσει. Μια λήψη της οποίας το μέγεθος δεν το λέει ο πάροχος μετρά εδώ ως μηδέν, οπότε ο αριθμός είναι κατώτατο όριο και ποτέ υπόσχεση, και γι’ αυτό μπορεί να γράφει μηδέν byte δίπλα σε μια σειρά από λήψεις. Οι λήψεις που έχεις απενεργοποιήσει μένουν απ’ έξω, ο ίδιος κανόνας που ακολουθούν και οι μετρητές κάτω από τη λίστα. Μια λήψη που ήδη τρέχει έχει συνήθως δεσμεύσει τον χώρο της στον δίσκο τη στιγμή που ξεκίνησε, οπότε τα byte της λείπουν ήδη από τον ελεύθερο χώρο δίπλα και δεν έρχονται από πάνω του.`,"disk.tasks":`{n} λήψεις`,"disk.unknown":`Αυτό το σύστημα δεν αναφέρει ελεύθερο χώρο`,"disk.unknownHint":`Δεν μπορεί να ερωτηθεί κάθε πυρήνας πόσος χώρος απομένει σε έναν τόμο, και αυτό το build δεν έχει κλήση για εκείνον στον οποίο τρέχει. Όπου λείπει η απάντηση, δεν κρατιέται τίποτα πίσω: οι λήψεις ξεκινούν σαν να μην είχε οριστεί όριο δίσκου. Αυτή η γραμμή υπάρχει για να μπορείς να το ξεχωρίσεις από έναν δίσκο που είναι πραγματικά γεμάτος.`,"disk.missing":`Δεν έχει δημιουργηθεί ακόμη`,"disk.missingHint":`Αυτόν τον φάκελο τον δημιουργεί όποιος γράψει μέσα του το πρώτο αρχείο, οπότε δεν υπάρχει ακόμη. Οι τιμές περιγράφουν το {path}, τον πλησιέστερο υπαρκτό φάκελο από πάνω του, και εκείνος βρίσκεται στον τόμο στον οποίο θα κατέληγε η λήψη.`,"disk.measured":`Μετρήθηκε στο {path}`,"disk.elsewhereHint":`Ο ίδιος ο φάκελος δεν μπόρεσε να μετρηθεί, οπότε μετρήθηκε ο πλησιέστερος από πάνω του που μπορούσε. Αν κάποια προσάρτηση δεν σηκώθηκε, αυτός μπορεί να είναι εντελώς άλλος δίσκος από εκείνον για τον οποίο προορίζεται η λήψη. Κοίτα τη διαδρομή πριν βγάλεις οποιοδήποτε συμπέρασμα από τους αριθμούς.`,"disk.sampled":`Διαβάστηκε πριν από {n} δευτερόλεπτα`,"disk.tight":`Η ουρά δεν χωράει`,"disk.tightHint":`Σε αυτόν τον φάκελο εκκρεμούν περισσότερα από όσα έχει ελεύθερα ο τόμος. Αυτή η γραμμή από μόνη της δεν σταματά τίποτα: οι λήψεις κρατιούνται πίσω μία μία, καθώς έρχεται η σειρά τους, σύμφωνα με τους αριθμούς στη σελίδα ρυθμίσεων Λήψεις, και μια λήψη της οποίας το μέγεθος δεν το ξέρει κανείς δεν μετρά εδώ καθόλου.`,"disk.truncated":`Δεν αναφέρονται όλοι οι φάκελοι`,"disk.truncatedHint":`Η ουρά στοχεύει σε περισσότερους φακέλους εκτός των ρυθμισμένων από όσους αξίζει να μετριούνται σε κάθε ανάγνωση, οπότε λείπουν εκείνοι με τα λιγότερα. Κάθε φάκελος που έχεις ρυθμίσει είναι πάντα εδώ.`,"disk.markLow":`Κάτω από εδώ δεν ξεκινά τίποτα καινούριο`,"disk.markStop":`Κάτω από εδώ σταματούν τα πάντα`,"disk.limits":`Ρύθμιση των ορίων δίσκου`,"disk.stripLabel":`Χώρος στους φακέλους προορισμού`,"disk.role.downloads":`Φάκελος λήψεων`,"disk.role.category":`Φάκελος κατηγορίας`,"disk.role.work":`Φάκελος εργασίας`,"disk.role.task":`Ορισμένος πάνω στην ίδια τη λήψη`,"settings.volume.title":`Ανώτατο όριο όγκου`,"settings.volume.titleHint":`Τι έχει κατεβάσει ολοκληρωμένο αυτό το στιγμιότυπο, μετρημένο πάνω σε ένα ανώτατο όριο που ορίζεις εσύ, ανά περίοδο. Μετριέται το μέγεθος που ανακοίνωσε ο πάροχος για κάθε ολοκληρωμένη λήψη. Ό,τι τελειώνει χωρίς δηλωμένο μέγεθος μετρά ως μηδέν, και ό,τι ανεβάζει ένα torrent δεν μετρά καθόλου. Είναι μια ανάγνωση των λήψεών σου, όχι μέτρηση της γραμμής σου: τα byte που κίνησε πραγματικά ο δρομολογητής σου δεν τα βλέπει εδώ κανείς.`,"settings.volume.cap":`Ανώτατο όριο ανά περίοδο (GB)`,"settings.volume.capHint":`Το 0 σημαίνει κανένα ανώτατο όριο: ο μετρητής συνεχίζει να τρέχει και δεν κρατιέται ποτέ τίποτα πίσω. Τα gigabyte εδώ είναι δεκαδικά, όπως δίνει τον όγκο ο πάροχος της σύνδεσής σου: τα 500 GB είναι 500.000.000.000 byte και όχι 465 GiB. Οι τιμές δίσκου πιο πάνω σε αυτή τη σελίδα είναι δυαδικά GiB, άλλη μονάδα για άλλη ερώτηση.`,"settings.volume.resetDay":`Ο μετρητής ξεκινά ξανά την ημέρα`,"settings.volume.resetDayHint":`Η ημέρα του μήνα κατά την οποία ο μετρητής επιστρέφει στο μηδέν, συνήθως η ημέρα που ανανεώνεται ο όγκος σου. Σε έναν μήνα πιο σύντομο από την ημέρα που διάλεξες, ξεκινά ξανά την τελευταία ημέρα εκείνου του μήνα και δεν γλιστρά ποτέ στον επόμενο. Μετριέται με το ρολόι του διακομιστή και όχι με εκείνο του περιηγητή σου, γιατί ο διακομιστής είναι που κρατά πίσω την ουρά.`,"settings.volume.action":`Όταν συμπληρωθεί το ανώτατο όριο`,"settings.volume.actionHint":`Μια μεταφορά που τρέχει ήδη δεν διακόπτεται ποτέ, όποια απάντηση κι αν διαλέξεις: αν σταματήσεις στη μέση του αρχείου, πετάς byte που έχεις ήδη ξοδέψει. Το «Μόνο ενημέρωση» δεν αλλάζει τίποτα και αφήνει τον μετρητή ως όλη τη λειτουργία. Το «Να μην ξεκινούν άλλες λήψεις» αφήνει όσα τρέχουν να τελειώσουν και κρατά την ουρά μέχρι να ξαναρχίσει ο μετρητής, και κάθε γραμμή σε αναμονή το λέει. Η «Επιβράδυνση των πάντων» κρατά την ουρά σε κίνηση με την ταχύτητα παρακάτω.`,"settings.volume.actionReport":`Μόνο ενημέρωση`,"settings.volume.actionPause":`Να μην ξεκινούν άλλες λήψεις`,"settings.volume.actionThrottle":`Επιβράδυνση των πάντων`,"settings.volume.throttle":`Ταχύτητα μετά το ανώτατο όριο`,"settings.volume.throttleHint":`Το όριο που ισχύει για το υπόλοιπο της περιόδου. Είναι ένα ανώτατο όριο δίπλα στα άλλα σου όρια και ποτέ στη θέση τους: ένα νυχτερινό παράθυρο ή ο αθόρυβος διακόπτης, που ζητούν λιγότερα, εξακολουθούν να κερδίζουν. Το 0 εδώ θα σήμαινε καθόλου όριο, δηλαδή το ίδιο με το να μην υπάρχει ανώτατο όριο, οπότε ο μικρότερος χρήσιμος αριθμός είναι το 1.`,"settings.volume.noCap":`Χωρίς ανώτατο όριο`,"settings.volume.used":`Κατέβηκαν σε αυτή την περίοδο`,"settings.volume.usedOf":`{used} από {cap}`,"settings.volume.resetsOn":`Ξεκινά ξανά στις {date}`,"settings.volume.reached":`Το ανώτατο όριο συμπληρώθηκε.`,"volume.title":`Όγκος λήψεων`,"volume.titleHint":`Ολοκληρωμένες λήψεις, αθροισμένες ανά ημέρα και ανά μήνα, από το ιστορικό λήψεων. Το ιστορικό έχει δικό του ανώτατο όριο και μπορεί να αδειάσει με το χέρι, οπότε οι μήνες που έχουν πέσει έξω από το τέλος του απλώς δεν είναι εδώ. Μια λήψη που ξεκίνησες ξανά μετρά μία φορά, την ημέρα που ολοκληρώθηκε τελευταία. Το ημερολόγιο είναι του διακομιστή, σε {zone}.`,"volume.range.days":`30 ημέρες`,"volume.range.months":`12 μήνες`,"volume.split.total":`Όλα`,"volume.split.host":`Ανά πάροχο`,"volume.split.backend":`Ανά backend`,"volume.other":`Όλα τα υπόλοιπα`,"volume.empty":`Σε αυτό το διάστημα δεν έχει ολοκληρωθεί ακόμη τίποτα.`,"volume.unsizedHint":`Σε {n} από αυτές τις λήψεις ο πάροχος δεν δήλωσε ποτέ μέγεθος. Δεν προσθέτουν τίποτα στο σύνολο, οπότε ο πραγματικός αριθμός είναι μεγαλύτερος από αυτόν που σχεδιάζεται εδώ.`,"volume.trimmedHint":`Το ιστορικό είναι στο δικό του όριο, οπότε ό,τι είναι παλαιότερο από την παλαιότερη εγγραφή του λείπει και από αυτή την καμπύλη. Ανέβασε το ανώτατο όριο του ιστορικού σε αυτή τη σελίδα αν θέλεις να βλέπεις πιο πίσω.`,"volume.meter":`Όγκος`,"volume.meterHint":`Όσα ολοκληρώθηκαν από τότε που ο μετρητής ξεκίνησε τελευταία φορά, σε σχέση με το ανώτατο όριο στη σελίδα ρυθμίσεων Λήψεις. Ο αριθμός αλλάζει όταν τελειώνει μια λήψη, όχι όσο τρέχει. Προκύπτει αθροίζοντας το ιστορικό λήψεων, οπότε αν αδειάσεις το ιστορικό μηδενίζεται και αυτός ο μετρητής.`,"task.waiting.volumeCap":`Περιμένει το ανώτατο όριο όγκου`,"task.waiting.module":`Λειτουργική μονάδα ανενεργή`,"task.reason.botCheck":`Έλεγχος για bot`,"task.reason.membersOnly":`Μόνο για μέλη`,"task.reason.geoBlocked":`Αποκλεισμένο εδώ`,"task.reason.drm":`DRM`,"task.reason.extractorBroken":`Ο ιστότοπος άλλαξε`,"events.title":`Συμβάντα`,"events.open":`Άνοιγμα της λίστας συμβάντων`,"events.titleHint":`Κάθε μήνυμα που σου δείχνει αυτό το παράθυρο καταλήγει και εδώ, οπότε μπορείς να διαβάσεις και ένα του οποίου η φούσκα έχει ήδη φύγει. Κρατιούνται τα τελευταία {max}, και σε κάθε φόρτωση της σελίδας η λίστα ξεκινά από την αρχή.`,"events.unread":`{n} μη αναγνωσμένα`,"events.empty":`Δεν έχει συμβεί ακόμη τίποτα`,"events.emptyHint":`Ό,τι σου αναφέρει στη συνέχεια το KnightLoader, θα βρίσκεται εδώ.`,"events.noMatch":`Τίποτα αυτού του είδους δεν υπάρχει στη λίστα`,"events.filterLabel":`Είδος`,"events.kind.downloads":`Λήψεις`,"events.kind.archives":`Συμπιεσμένα αρχεία`,"events.kind.captcha":`Captcha`,"events.kind.accounts":`Λογαριασμοί`,"events.kind.actions":`Ενέργειες`,"events.clear":`Άδειασμα της λίστας`,"events.jump":`Εμφάνιση της γραμμής`,"events.jumpGone":`Αυτή η λήψη δεν είναι πια στη λίστα`,"commands.openEvents":`Άνοιγμα της λίστας συμβάντων`,"settings.shortcuts.listTitle":`Πλήκτρα της λίστας`,"settings.shortcuts.listHint":`Αυτά ανήκουν στη λίστα λήψεων και στη λίστα του συλλέκτη και δεν μπορούν να πάρουν άλλη αντιστοίχιση. Λειτουργούν μόνο όσο μια γραμμή έχει την εστίαση, γι’ αυτό κανένα τους δεν παίρνει πλήκτρο από κάποια εντολή πιο πάνω.`,"keys.list.move":`Μετάβαση από γραμμή σε γραμμή`,"keys.list.moveKeep":`Μετάβαση χωρίς αλλαγή της επιλογής`,"keys.list.edges":`Μετάβαση στην πρώτη ή στην τελευταία γραμμή`,"keys.list.pick":`Προσθήκη της γραμμής στην επιλογή, ή αφαίρεσή της`,"keys.list.range":`Επέκταση της επιλογής ως τη γραμμή στην οποία πηγαίνεις`,"keys.list.properties":`Άνοιγμα των ιδιοτήτων του επιλεγμένου`,"keys.list.open":`Άνοιγμα ενός φακέλου, ή μετάβαση στον πρώτο σύνδεσμο μέσα του`,"keys.list.close":`Κλείσιμο ενός φακέλου, ή μετάβαση από έναν σύνδεσμο στον φάκελό του`,"keys.list.menu":`Άνοιγμα του μενού της γραμμής`,"settings.shortcuts.key.home":`Home`,"settings.shortcuts.key.end":`End`,"settings.shortcuts.key.delete":`Del`,"task.retry.pending":`Επανάληψη {n} από {max}, η επόμενη σε {countdown}`,"task.retry.pendingNoMax":`Επανάληψη {n}, η επόμενη σε {countdown}`,"task.retry.due":`Επανάληψη {n} από {max}, ξεκινά τώρα`,"task.retry.dueNoMax":`Επανάληψη {n}, ξεκινά τώρα`,"task.retry.compact":`{n}/{max} · {countdown}`,"task.retry.compactNoMax":`{n} · {countdown}`,"task.retry.exhausted":`Καμία επανάληψη πια, {n} από {max} χρησιμοποιήθηκαν`,"task.retry.exhaustedNoMax":`Καμία επανάληψη πια, {n} χρησιμοποιήθηκαν`,"task.retry.gaveUp":`Δεν θα δοκιμαστεί ξανά`,"task.retry.skip":`Επανάληψη τώρα`,"task.retry.skipDetail":`Ξεκινά τον σύνδεσμο αμέσως, αντί στο τέλος της αναμονής. Ο μετρητής συνεχίζει να τρέχει: αυτή είναι η επανάληψη που ήταν έτσι κι αλλιώς προγραμματισμένη, όχι μια επιπλέον.`,"task.retry.skipFailed":`Η επανάληψη δεν μπόρεσε να ξεκινήσει.`,"volume.rangeLabel":`Χρονικό διάστημα`,"volume.splitLabel":`Διαχωρισμός`,"failure.title":`Γιατί απέτυχε αυτό`,"failure.open":`Γιατί απέτυχε αυτό`,"failure.raw":`Τι είπε το backend`,"failure.rawHint":`Η γραμμή που τύπωσε το ίδιο το εργαλείο, αμετάβλητη και στα αγγλικά. Χρήσιμη όταν την ψάχνεις ή τη δηλώνεις κάπου. Η πρόταση από πάνω είναι η ερμηνεία αυτής της εφαρμογής.`,"failure.nothingToDo":`Τίποτα μέσα στο KnightLoader δεν αλλάζει αυτό εδώ.`,"failure.close":`Κλείσιμο`,"failure.botCheck.line":`Ο ιστότοπος θέλει συνδεδεμένη συνεδρία πριν δώσει το βίντεο.`,"failure.botCheck.hint":`Η αναμονή, μια πιο αργή λήψη ή μια άλλη ταυτότητα περιηγητή δεν αλλάζουν τίποτα εδώ. Μόνο cookies από περιηγητή στον οποίο είσαι πραγματικά συνδεδεμένος. Εξήγαγε την cookies.txt του ιστότοπου από εκείνον τον περιηγητή και επικόλλησέ την εδώ: φυλάσσεται στον κρυπτογραφημένο χώρο διαπιστευτηρίων, δίνεται στο yt-dlp ως αρχείο που μόνο αυτός ο διακομιστής μπορεί να διαβάσει, και διαγράφεται ξανά μόλις τελειώσει η λήψη.`,"failure.botCheck.action":`Αποθήκευση cookies για αυτόν τον ιστότοπο`,"failure.membersOnly.line":`Μόνο για μέλη, και η λήψη έφτασε χωρίς συνδρομή μέλους.`,"failure.membersOnly.hint":`Το yt-dlp φτάνει ως αυτός που λένε τα αποθηκευμένα cookies. Συνδέσου με τον λογαριασμό που έχει τη συνδρομή μέλους, εξήγαγε από εκείνον τον περιηγητή την cookies.txt του ιστότοπου και επικόλλησέ την. Χωρίς συνδρομή μέλους σε εκείνον τον λογαριασμό, τίποτα εδώ δεν αλλάζει την απάντηση.`,"failure.membersOnly.action":`Αποθήκευση cookies για αυτόν τον ιστότοπο`,"failure.geoBlocked.line":`Ο ιστότοπος δεν δίνει αυτό το βίντεο σε αυτή την περιοχή.`,"failure.geoBlocked.hint":`Τα cookies δεν βοηθούν: αποκλεισμένη είναι η διεύθυνση και όχι ο λογαριασμός. Το KnightLoader δεν μπορεί ούτε να στείλει μια λήψη του yt-dlp μέσα από μία από τις ονομασμένες συνδέσεις του, γιατί το yt-dlp τρέχει ως δική του διεργασία και παίρνει τον διαμεσολαβητή του από το περιβάλλον μέσα στο οποίο ξεκίνησε αυτός ο διακομιστής. Η λύση βρίσκεται λοιπόν έξω από αυτό το παράθυρο: ξεκίνα τον διακομιστή πίσω από ένα VPN, ή όρισε γι’ αυτόν τα HTTP_PROXY και HTTPS_PROXY.`,"failure.gone.line":`Η πηγή λέει ότι αυτό δεν υπάρχει πια.`,"failure.gone.hint":`Διαγράφηκε, κατέβηκε ή τέθηκε σε ιδιωτικό στην πηγή. Κανένας λογαριασμός και καμία νέα προσπάθεια δεν το φέρνει πίσω, και κάθε επόμενη προσπάθεια απλώς κάνει τον πάροχο να επαναλάβει την ίδια απάντηση. Η αφαίρεση βγάζει τη γραμμή από τη λίστα, ό,τι έχει ήδη κατέβει μένει στον δίσκο.`,"failure.gone.action":`Αφαίρεση αυτού του συνδέσμου`,"failure.drm.line":`Αυτό το βίντεο είναι κρυπτογραφημένο, και το yt-dlp δεν το αποκρυπτογραφεί.`,"failure.drm.hint":`Το DRM δεν είναι φράγμα που το προσπερνά μια σύνδεση ή μια άλλη διεύθυνση: τα δεδομένα φτάνουν κρυπτογραφημένα, και το κλειδί το παίρνει μόνο ένα πρόγραμμα αναπαραγωγής που εμπιστεύεται ο ιστότοπος. Δεν υπάρχει τίποτα να ρυθμίσεις γι’ αυτό. Οι άλλες γραμμές του ίδιου συνδέσμου, η μικρογραφία, η περιγραφή και οι υπότιτλοι, συνήθως δεν επηρεάζονται και μπορούν να μείνουν.`,"failure.drm.action":`Αφαίρεση αυτού του συνδέσμου`,"failure.extractorBroken.line":`Ο ιστότοπος άλλαξε, και το yt-dlp αυτής της έκδοσης δεν βγάζει πια έξω το βίντεο.`,"failure.extractorBroken.hint":`Το ίδιο το yt-dlp το είπε: δεν μπόρεσε να διαβάσει τη σελίδα και ζήτησε αναφορά σφάλματος. Σχεδόν πάντα ο ιστότοπος έχει μετακινήσει κάτι, και ένα νεότερο yt-dlp τα καταφέρνει ξανά μέσα σε λίγες ημέρες. Το yt-dlp βρίσκεται μέσα στην εικόνα του KnightLoader, οπότε ο δρόμος προς μια νεότερη έκδοση είναι μια νεότερη εικόνα και όχι ένα κουμπί εδώ μέσα: αυτός ο διακομιστής δεν επιτρέπεται να το αντικαταστήσει και, μέσα σε container, δεν θα είχε πού να βάλει ένα νέο αντίγραφο.`,"cookies.title":`Cookies για {host}`,"cookies.addTitle":`Αποθήκευση cookies για έναν ιστότοπο`,"cookies.add":`Προσθήκη ιστότοπου`,"cookies.save":`Αποθήκευση και νέα προσπάθεια`,"cookies.saved":`Τα cookies αποθηκεύτηκαν.`,"cookies.hostHint":`Το αρχείο αναζητείται με βάση αυτόν τον κόμβο και κάθε τομέα από πάνω του, από το πιο ειδικό προς το πιο γενικό, οπότε ένα αποθηκευμένο ως youtube.com είναι και αυτό που χρησιμοποιεί ένας σύνδεσμος του music.youtube.com. Ο διακομιστής γράφει το όνομα με πεζά, αφαιρεί ένα αρχικό www. και κόβει μια ολόκληρη επικολλημένη διεύθυνση στον ίδιο τον ιστότοπο, γι’ αυτό η λίστα μπορεί να τον ονομάζει λίγο διαφορετικά από ό,τι τον πληκτρολόγησες.`,"cookies.jarHint":`Επικόλλησε ό,τι σου δίνει ένας εξαγωγέας cookies, στη μορφή Netscape, μαζί με τις γραμμές σχολίων. Αποθηκεύεται ακριβώς όπως το επικολλάς: το να αναμορφώσεις ένα αρχείο που πάει να διαβάσει το yt-dlp είναι ο δρόμος για να δουλεύει σε ένα εργαλείο και στο άλλο όχι.`,"cookies.useStoredHint":`Ένας διακόπτης για ολόκληρο το στιγμιότυπο, όχι γι’ αυτόν τον σύνδεσμο: όσο είναι κλειστός, ένα αποθηκευμένο αρχείο δεν πηγαίνει πουθενά, και το να επικολλήσεις ένα εδώ δεν αλλάζει τίποτα. Ανήκει σε ό,τι κάνει η Αποθήκευση και δεν είναι ζωντανή ένδειξη της ρύθμισης: βλέπεις τι πρόκειται να αφήσει πίσω του αυτό το παράθυρο. Και είναι διακόπτης, όχι κάτι αυτόματο, γιατί μια συνδεδεμένη συνεδρία έχει συνέπειες: ένα όριο ή μια απαγόρευση χτυπά τον λογαριασμό και όχι τη διεύθυνση.`,"select.hidden":`από αυτά {n} μη ορατά`,"select.hiddenTip":`Στην επιλογή βρίσκονται και γραμμές που κρύβουν αυτή τη στιγμή η αναζήτηση, ένα φίλτρο ή ένα συμπτυγμένο πακέτο, και το Del τις παίρνει μαζί. Κάντε κλικ στον αριθμό για να φύγουν από την επιλογή και να μείνουν μόνο οι γραμμές που βλέπετε.`,"select.reduceKeep":`Διατήρηση μόνο των ορατών γραμμών`,"select.reduceKeepAria":`{n} επιλεγμένες γραμμές δεν είναι ορατές. Κάντε κλικ για να κρατήσετε μόνο τις ορατές.`,"select.reduceRemove":`Αφαίρεση μόνο των ορατών γραμμών`,"select.reduceRemoveAria":`{n} από τις γραμμές που πρόκειται να φύγουν δεν είναι ορατές. Κάντε κλικ για να αφαιρεθούν μόνο οι ορατές.`,"select.reduced":`Βγήκαν {n} γραμμές από την επιλογή.`,"remove.doneHidden":`Αφαιρέθηκαν {n} λήψεις. Οι {hidden} από αυτές δεν ήταν στην οθόνη.`,"settings.dbmaint.title":`Συντήρηση βάσης δεδομένων`,"settings.dbmaint.hint":`Η λίστα εργασιών, το ιστορικό λήψεων και η κατάσταση της διεπαφής βρίσκονται μαζί σε ένα αρχείο SQLite. Οι διαγραμμένες γραμμές ελευθερώνουν χώρο μέσα στο αρχείο, αλλά ποτέ πίσω στον δίσκο. Μετά από μερικά χρόνια το αρχείο είναι γι’ αυτό συχνά πολλαπλάσιο του περιεχομένου του. Ο έλεγχος διαβάζει κάθε σελίδα και λέει αν το αρχείο είναι ακόμη ακέραιο. Η συμπύκνωση το ξαναγράφει στο πραγματικό του μέγεθος. Και τα δύο τρέχουν πάνω στη ζωντανή βάση δεδομένων και κρατούν όσο διαρκούν κάθε άλλη εγγραφή σε αναμονή.`,"settings.dbmaint.storeSize":`Αρχείο βάσης δεδομένων`,"settings.dbmaint.storeSizeHint":`Η βάση δεδομένων, μαζί με ένα αρχείο journal δίπλα της, αν το SQLite κρατά αυτή τη στιγμή κάποιο ανοιχτό.`,"settings.dbmaint.reclaimable":`Ελεύθερο μέσα στο αρχείο`,"settings.dbmaint.reclaimableHint":`Χώρος που άφησαν πίσω τους οι διαγραμμένες γραμμές. Ανήκει ακόμη στο αρχείο πάνω στον δίσκο, και μόνο η συμπύκνωση τον δίνει πίσω. Ο αριθμός είναι κάτω όριο: στη συμπύκνωση ξαναπακετάρονται και οι μισογεμάτες σελίδες, οπότε συνήθως επιστρέφουν περισσότερα.`,"settings.dbmaint.settingsSize":`settings.json`,"settings.dbmaint.settingsMissing":`Δεν έχει γραφτεί ακόμη`,"settings.dbmaint.settingsMissingHint":`Αυτό το αρχείο γράφεται μόνο την πρώτη φορά που θα αποθηκεύσετε μια σελίδα ρυθμίσεων. Μέχρι τότε το στιγμιότυπο τρέχει με τις ενσωματωμένες προεπιλογές.`,"settings.dbmaint.inBundle":`Αυτά τα μεγέθη βρίσκονται και στο πακέτο διαγνωστικών. Οι διαδρομές όχι: το πακέτο πρέπει να μπορεί να επισυναφθεί σε μια δημόσια αναφορά σφάλματος.`,"settings.dbmaint.check":`Έλεγχος ακεραιότητας`,"settings.dbmaint.checkHint":`Διαβάζει κάθε σελίδα της βάσης δεδομένων και αναφέρει τι βρίσκει το SQLite. Γίνεται μόνο ανάγνωση, δεν αλλάζει τίποτα. Σε μεγάλο αρχείο αυτό παίρνει ώρα, και όσο τρέχει τίποτα άλλο δεν μπορεί να γράψει στη βάση δεδομένων.`,"settings.dbmaint.compact":`Συμπύκνωση`,"settings.dbmaint.compactHint":`Ξαναγράφει ολόκληρο το αρχείο στο πραγματικό του μέγεθος. Γι’ αυτό χρειάζεται χώρος για ένα πλήρες δεύτερο αντίγραφο της βάσης δεδομένων, και αυτό καταλήγει στον προσωρινό φάκελο, όχι στον φάκελο δεδομένων.`,"settings.dbmaint.analyze":`Ανανέωση στατιστικών ερωτημάτων`,"settings.dbmaint.analyzeHint":`Αφήνει το SQLite να μετρήσει ξανά τους πίνακες, ώστε να διαλέγει καλύτερα πλάνα για τα ερωτήματα της λίστας και του ιστορικού. Γίνεται γρήγορα και δεν αλλάζει δεδομένα. Τα ερωτήματα που ετοιμάστηκαν νωρίτερα κρατούν το παλιό τους πλάνο, οπότε η επίδραση είναι πλήρης το αργότερο μετά την επόμενη επανεκκίνηση.`,"settings.dbmaint.running":`Σε εξέλιξη…`,"settings.dbmaint.busy":`Κάτι τρέχει ήδη. Περιμένετε να τελειώσει.`,"settings.dbmaint.neverRun":`Σε αυτό το στιγμιότυπο δεν έχει τρέξει ακόμη τίποτα.`,"settings.dbmaint.lastRun":`Τελευταία εκτέλεση {when}, διήρκεσε {seconds} δευτ.`,"settings.dbmaint.checkOk":`Ακέραιο. Το SQLite διάβασε κάθε σελίδα και δεν βρήκε τίποτα.`,"settings.dbmaint.checkFailed":`Κατεστραμμένο. Το SQLite αναφέρει {n} προβλήματα.`,"settings.dbmaint.checkFailedHelp":`Μην κάνεις επανεκκίνηση του διακομιστή. Αρνείται εντελώς να ξεκινήσει με μια βάση δεδομένων που δεν μπορεί να ανοίξει, και ένα container ρυθμισμένο να επανεκκινείται μόνο του θα μπει τότε σε ατέρμονο κύκλο. Δοκίμασε πρώτα το κουμπί Λήψη αντιγράφου ασφαλείας στην ενότητα Αντίγραφο ασφαλείας και μεταφορά της σελίδας Γενικά και βάλε το αρχείο κάπου ασφαλές· σε μια σοβαρά κατεστραμμένη βάση δεδομένων μπορεί να αποτύχει κι αυτό. Αν αποτύχει, σταμάτησε τον διακομιστή και αντίγραψε το {path} κάπου αλλού με το χέρι πριν το αγγίξει οτιδήποτε άλλο, και μετά επανάφερε το τελευταίο καλό αντίγραφο ασφαλείας σου με το Μεταφόρτωση αντιγράφου ασφαλείας.`,"settings.dbmaint.compacted":`Πριν {before}, μετά {after}. {freed} ξανά στον δίσκο.`,"settings.dbmaint.compactedNothing":`Πριν και μετά {before}. Δεν υπήρχε τίποτα να επιστραφεί.`,"settings.dbmaint.analyzed":`Τα στατιστικά ανανεώθηκαν.`,"settings.dbmaint.failed":`Δεν ολοκληρώθηκε: {error}`,"settings.dbmaint.diskFullHelp":`Στη συμπύκνωση γράφεται πρώτα ένα πλήρες δεύτερο αντίγραφο της βάσης δεδομένων και μετά αντικαθίσταται το πρωτότυπο. Αυτό το αντίγραφο καταλήγει στον προσωρινό φάκελο, όχι στον φάκελο δεδομένων. Εδώ είναι ο {tmp}, με {free} ελεύθερα. Δείξτε με το TMPDIR σε έναν φάκελο στον ίδιο τόμο με τον φάκελο δεδομένων σας και δοκιμάστε ξανά.`,"settings.dbmaint.skippedBusy":`Η προγραμματισμένη εκτέλεση παραλείφθηκε επειδή έτρεχαν λήψεις.`,"settings.dbmaint.interval":`Να τρέχει από μόνη της`,"settings.dbmaint.intervalHint":`Σε μια υπάρχουσα εγκατάσταση είναι κλειστό, και μετά από ενημέρωση παραμένει κλειστό: τίποτα δεν αρχίζει να τρέχει από μόνο του μόνο και μόνο επειδή εγκαταστήσατε μια νέα έκδοση. Όταν το ανάψετε, η πρώτη εκτέλεση απέχει ένα ολόκληρο διάστημα, όχι τώρα αμέσως. Αν εκείνη τη στιγμή τρέχει κάποια λήψη, η εκτέλεση παραλείπεται και δεν μπαίνει σε αναμονή.`,"settings.dbmaint.intervalNever":`Μόνο με πάτημα κουμπιού`,"settings.dbmaint.interval30":`Κάθε 30 ημέρες`,"settings.dbmaint.interval90":`Κάθε 90 ημέρες`,"settings.dbmaint.interval180":`Κάθε 180 ημέρες`,"settings.dbmaint.nextRun":`Επόμενη εκτέλεση {when}.`,"settings.dbmaint.compactOnSchedule":`Συμπύκνωση και στην προγραμματισμένη εκτέλεση`,"settings.dbmaint.compactOnScheduleHint":`Κλειστό σημαίνει: η προγραμματισμένη εκτέλεση μόνο διαβάζει και αναφέρει. Η συμπύκνωση ξαναγράφει ολόκληρο το αρχείο και χρειάζεται γι’ αυτό χώρο για ένα δεύτερο αντίγραφό του στον προσωρινό τόμο. Μην το ανάβετε λοιπόν χωρίς να ξέρετε ότι αυτός ο χώρος υπάρχει. Το κουμπί Συμπύκνωση παραπάνω συμπυκνώνει πάντα όταν το πατάτε, ό,τι κι αν λέει εδώ.`,"settings.dbmaint.confirmTitle":`Συμπύκνωση της βάσης δεδομένων;`,"settings.dbmaint.confirmBody":`Το αρχείο ξαναγράφεται εξ ολοκλήρου από την αρχή. Μέχρι να τελειώσει αυτό, τίποτα άλλο δεν μπορεί να γράψει μέσα του, και στα {size} μπορεί να πάρει ώρα. Οι λήψεις συνεχίζονται, αλλά ό,τι αναφέρουν καταγράφεται μόνο μετά.`,"settings.dbmaint.loadFailed":`Δεν ήταν δυνατή η ανάγνωση του μεγέθους της βάσης δεδομένων. Είναι προσβάσιμος ο διακομιστής;`,"overview.speedWindow":`Χρονικό παράθυρο της καμπύλης`,"overview.speedWindow.minute":`Τελευταίο λεπτό`,"overview.speedWindow.hour":`Τελευταία ώρα`,"overview.speedGraphHint":`Το στιγμιότυπο καταγράφει το ίδιο αυτή την καμπύλη: μία τιμή ανά δευτερόλεπτο για τα τελευταία δύο λεπτά, μία ανά δέκα δευτερόλεπτα για την τελευταία ώρα. Γι’ αυτό, μετά την επαναφόρτωση της σελίδας, είναι ήδη γεμάτη αντί να ξεκινά επίπεδη. Η καταγραφή βρίσκεται μόνο στη μνήμη εργασίας: αν κάνετε επανεκκίνηση του KnightLoader, είναι άδεια, η καμπύλη ξεκινά πάλι ως επίπεδη γραμμή και γεμίζει με την πάροδο του χρόνου.`,"settings.diagnostics.speedSamples":`Καταγεγραμμένες τιμές ταχύτητας`,"settings.diagnostics.speedSamplesHint":`Από πόσες τιμές σχεδιάζεται αυτή τη στιγμή η καμπύλη ταχύτητας στην Επισκόπηση, σε σχέση με αυτό που κρατά το πολύ: πρώτα η καταγραφή των δύο λεπτών, μετά εκείνη της μίας ώρας. Αν και στις δύο υπάρχει μηδέν, δεν καταγράφει τίποτα, και η καμπύλη στην Επισκόπηση θα μείνει επίπεδη μέχρι να διορθωθεί αυτό. Μετά από κάθε επανεκκίνηση η καταγραφή ξεκινά άδεια, και στον δίσκο δεν γράφεται ποτέ.`,"settings.downloads.idleActionQuit":`Έξοδος από το KnightLoader`,"settings.downloads.idleActionCommand":`Εκτέλεση εντολής`,"settings.downloads.idleActionSuspend":`Αναστολή λειτουργίας αυτού του υπολογιστή`,"settings.downloads.idleDeploymentContainer":`Αυτό εδώ τρέχει μέσα σε κοντέινερ. Η διεργασία του είναι το PID 1 στον δικό της χώρο ονομάτων: η έξοδος σταματά το κοντέινερ και τίποτα άλλο, και τον υπολογιστή από κάτω δεν μπορεί να τον βάλει σε αναστολή, γιατί στην κατάσταση ρεύματος εκείνου του υπολογιστή δεν φτάνει τίποτα από μέσα από το κοντέινερ. Το αν το κοντέινερ ξαναέρχεται μετά την έξοδο το αποφασίζει ο κανόνας επανεκκίνησης που του έδωσες, όχι αυτή η ρύθμιση. Αν θέλεις να κοιμηθεί ο host, βάλε εδώ μια εντολή που φτάνει στον host.`,"settings.downloads.idleDeploymentDesktop":`Αυτή εδώ είναι η έκδοση για υπολογιστή, μπορεί λοιπόν να βάλει αυτόν τον υπολογιστή σε αναστολή. Η έξοδος δεν προσφέρεται εδώ, γιατί το παράθυρο και η περιοχή ειδοποιήσεων κλείνουν ήδη την εφαρμογή με καθαρό τρόπο.`,"settings.downloads.idleQuitHint":`Η Έξοδος αφήνει να ολοκληρωθεί ό,τι είναι ακόμα σε εξέλιξη και σταματά τη διεργασία, ακριβώς όπως το κουμπί Έξοδος στη σελίδα Γενικά. Αν θα ξεκινήσει ξανά μετά, το αποφασίζει η πολιτική επανεκκίνησης του container σου, όχι αυτή η ρύθμιση.`,"settings.downloads.idleSuspendHint":`Η αναστολή ζητά από το λειτουργικό σύστημα να βάλει αυτόν τον υπολογιστή σε εξοικονόμηση ενέργειας. Δουλεύει μόνο εκεί όπου το σύστημα αφήνει αυτή την εφαρμογή να ρωτήσει: στο Linux η διαχείριση δικαιωμάτων μπορεί να αρνηθεί, και τότε ο λόγος γράφεται κάτω από την τελευταία εκτέλεση.`,"settings.downloads.idleCommandProgram":`Πρόγραμμα`,"settings.downloads.idleCommandProgramHint":`Η πλήρης διαδρομή του προγράμματος που εκτελείται. Τρέχει απευθείας και όχι μέσω κελύφους, άρα μια διοχέτευση, μια ανακατεύθυνση ή δύο εντολές στη σειρά ανήκουν σε ένα αρχείο σεναρίου, στο οποίο δείχνεις από εδώ. Δεν αντικαθίσταται τίποτα μέσα του: ό,τι γράφεις εδώ, αυτό ακριβώς τρέχει.`,"settings.downloads.idleCommandArgs":`Ορίσματα`,"settings.downloads.idleCommandArgsHint":`Ένα ανά γραμμή, ώστε ένα όρισμα με κενό μέσα του να μένει ένα όρισμα.`,"settings.downloads.idleCommandTimeout":`Διακοπή μετά από (δευτερόλεπτα)`,"settings.downloads.idleCommandTimeoutHint":`Πόση ώρα επιτρέπεται να τρέχει το πρόγραμμα πριν σταματήσει. Το να σταματήσει δεν είναι το ίδιο με το να έχει αποτύχει: μια εντολή που βάζει έναν υπολογιστή σε αναστολή μπορεί να σκοτωθεί στον δρόμο και να έχει κάνει τη δουλειά της παρ’ όλα αυτά.`,"settings.downloads.idleCommandSecretHint":`Η γραμμή εντολών αποθηκεύεται σε απλό κείμενο στο settings.json και ταξιδεύει μέσα σε κάθε αντίγραφο ασφαλείας, οπότε κράτα έξω από αυτήν κωδικούς και διακριτικά: βάλ’ τα σε ένα αρχείο που το διαβάζει μόνο το πρόγραμμα. Από το πακέτο διαγνωστικών μένει έξω, και σε αυτή τη σελίδα δεν εμφανίζεται ξανά, γι’ αυτό το πλαίσιο παραπάνω είναι άδειο μόλις αποθηκευτεί κάτι.`,"settings.downloads.idleCommandStored":`Μια εντολή είναι αποθηκευμένη και δεν εμφανίζεται ξανά εδώ. Γράψε κάτι για να την αντικαταστήσεις.`,"settings.downloads.idleCommandStoredShort":`η αποθηκευμένη εντολή`,"settings.downloads.idleCommandVerify":`Πριν το κάνει η αντίστροφη μέτρηση`,"settings.downloads.idleCommandVerifyHint":`Ο έλεγχος μόνο εντοπίζει το πρόγραμμα και λέει τι βρήκε, οπότε το πάτημά του δεν κοστίζει τίποτα. Η εκτέλεση κάνει ακριβώς ό,τι θα έκανε η αντίστροφη μέτρηση, σε αυτό το στιγμιότυπο και τώρα αμέσως. Και τα δύο ρωτούν για ό,τι είναι αποθηκευμένο, αποθήκευσε λοιπόν πρώτα τη σελίδα: όσο κάτι εδώ είναι μη αποθηκευμένο, τα δύο κουμπιά μένουν σβηστά.`,"settings.downloads.idleCommandCheck":`Έλεγχος της εντολής`,"settings.downloads.idleCommandChecking":`Γίνεται έλεγχος…`,"settings.downloads.idleCommandCheckOk":`Βρέθηκε στο {path}. Καλείται ως: {argv}`,"settings.downloads.idleCommandRun":`Εκτέλεση τώρα`,"settings.downloads.idleCommandRunConfirm":`Έτσι τρέχει το {program} τώρα αμέσως, σε αυτό το στιγμιότυπο, ακριβώς όπως θα το έκανε η αντίστροφη μέτρηση.`,"settings.downloads.idleArmHint":`Αν αποθηκεύσεις αυτή τη σελίδα ενώ η ουρά είναι ήδη άδεια, η αντίστροφη μέτρηση ξεκινά αμέσως. Δεν περιμένει να τελειώσει η επόμενη παρτίδα.`,"idleAction.action.quit":`Γίνεται έξοδος`,"idleAction.action.command":`Η εντολή τρέχει`,"idleAction.action.suspend":`Ο υπολογιστής μπαίνει σε αναστολή`,"idleAction.lastRun":`Τελευταία εκτέλεση`,"idleAction.lastRunHint":`Από την τελευταία εκκίνηση αυτού του στιγμιότυπου. Εδώ τίποτα δεν επιβιώνει μιας επανεκκίνησης, οπότε μια έξοδος που πέτυχε δεν αφήνει καμία γραμμή: η καταχώριση έφυγε μαζί με τη διεργασία.`,"idleAction.lastRunNever":`Αυτό δεν έχει τρέξει ακόμη ποτέ.`,"idleAction.lastRunOk":`Έτρεξε στις {at} και δεν είχε τίποτα να αναφέρει.`,"idleAction.lastRunFailed":`Απέτυχε στις {at}.`,"idleAction.problem.empty":`Δεν έχει οριστεί πρόγραμμα, άρα δεν τρέχει τίποτα. Γράψε παραπάνω την πλήρη διαδρομή του προγράμματος.`,"idleAction.problem.notFound":`Το {program} δεν υπάρχει σε αυτό το στιγμιότυπο.`,"idleAction.problem.notFoundContainer":`Το {program} δεν υπάρχει μέσα σε αυτό το κοντέινερ. Εδώ υπάρχει μόνο ό,τι φέρνει μαζί του το image: κανένα systemd, κανένα curl, κανένα ssh, κανένα sudo. Βάλε την εντολή στον host και κάλεσέ την από εδώ, ή δείξε από εδώ σε ένα σενάριο που έχεις προσαρτήσει μέσα στο κοντέινερ.`,"idleAction.problem.notExecutable":`Το {path} υπάρχει, αλλά δεν εκτελείται. Βάλε του το δικαίωμα εκτέλεσης και φρόντισε ο χρήστης με τον οποίο τρέχει αυτή η διεργασία να μπορεί να το διαβάσει: στο κοντέινερ αυτός είναι το uid 1000, όχι ο root.`,"idleAction.problem.permission":`Το σύστημα αρνήθηκε: αυτή η διεργασία δεν επιτρέπεται να το κάνει. Στο κοντέινερ τρέχει ως uid 1000, χωρίς root και χωρίς καμία πρόσβαση στον host, οπότε ό,τι αλλάζει την κατάσταση ρεύματος του υπολογιστή πρέπει να γίνει στον ίδιο τον host.`,"idleAction.problem.timeout":`Το πρόγραμμα έτρεχε ακόμη μετά από {seconds} δευτερόλεπτα και σταμάτησε. Κάλλιστα μπορεί να έχει κάνει τη δουλειά του παρ’ όλα αυτά. Ανέβασε το όριο, αν η εντολή πρέπει να παίρνει περισσότερη ώρα.`,"idleAction.problem.exit":`Το πρόγραμμα σταμάτησε με κωδικό εξόδου {code}. Η δική του έξοδος: {output}`,"idleAction.problem.notSupported":`Αυτό το build δεν μπορεί να το εκτελέσει. Διάλεξε άλλη ενέργεια στο τέλος της ουράς.`,"idleAction.problem.suspendRefused":`Το σύστημα αρνήθηκε την αναστολή. Στο Linux συνήθως η διαχείριση δικαιωμάτων θέλει μια επιβεβαίωση που αυτή η εφαρμογή δεν μπορεί να δώσει: επίτρεψε την αναστολή για τον χρήστη σου, ή γύρνα στο «Εκτέλεση εντολής» και βάλε τον υπολογιστή σε αναστολή μέσα από δικό σου σενάριο.`,"idleAction.runFailed":`Η εντολή δεν μπόρεσε να ξεκινήσει.`,"idleAction.failedTitle":`Η ενέργεια στο τέλος της ουράς δεν πέτυχε`,"idleAction.openSettings":`Στη ρύθμιση`,"idleAction.dismiss":`Απόκρυψη`,"settings.transfer.cardTitle":`Αντίγραφο ασφαλείας και μεταφορά`,"settings.transfer.cardHint":`Και τα δύο αρχεία γράφονται εδώ και τα αποθηκεύει ο περιηγητής σου, δεν πηγαίνουν πουθενά αλλού. Κανένα από τα δύο δεν κουβαλά τα στοιχεία σύνδεσης debrid και hoster, τα προφίλ κεφαλίδων, τα κλειδιά captcha, τον κωδικό πρόσβασης για αυτή τη διεπαφή ή τα σενάριά σου: αυτά βρίσκονται κρυπτογραφημένα έξω από το settings.json, και ούτε το αρχείο τα παίρνει μαζί του, οπότε τα στήνεις ξανά στο νέο μηχάνημα.`,"settings.transfer.archiveLabel":`Όλη η εγκατάσταση`,"settings.transfer.archiveText":`Ένα αρχείο με όλα όσα έχει αυτό το μηχάνημα: τη βάση δεδομένων, τη λίστα λήψεων, το ιστορικό και τις ρυθμίσεις, μαζί με τους κωδικούς, γι’ αυτό κράτα το κάπου ιδιωτικά. Η επαναφορά τα αντικαθιστά όλα αυτά και ισχύει από την επόμενη εκκίνηση.`,"settings.transfer.settingsLabel":`Μόνο οι ρυθμίσεις`,"settings.transfer.settingsText":`Μόνο το settings.json: τα όρια της ουράς, οι φάκελοι, οι κανόνες, οι κατηγορίες και το χρονοδιάγραμμα. Στην εισαγωγή βλέπεις πρώτα κάθε κλειδί, γράφεται μόνο ό,τι τσεκάρεις και ισχύει αμέσως, χωρίς επανεκκίνηση.`,"settings.transfer.export":`Εξαγωγή ρυθμίσεων`,"settings.transfer.import":`Εισαγωγή ρυθμίσεων`,"settings.transfer.withSecrets":`Να συμπεριληφθούν οι αποθηκευμένοι κωδικοί`,"settings.transfer.withSecretsHint":`Αναμμένο: το αρχείο κουβαλά τον κωδικό του δρομολογητή, κάθε κωδικό διαμεσολαβητή και κάθε κωδικό συμπιεσμένου αρχείου σε απλό κείμενο. Σβηστό: αυτά τα πεδία φτάνουν άδεια στο άλλο μηχάνημα και τα πληκτρολογείς εκεί μία φορά. Και στις δύο περιπτώσεις μπορεί να κάθεται ένα μυστικό κάπου που δεν το αναγνωρίζει τίποτα εδώ: μια διεύθυνση ροής με κλειδί API μέσα της, ή ένας κωδικός γραμμένος μέσα σε ένα σενάριο επανασύνδεσης.`,"settings.transfer.previewTitle":`Τι να μεταφερθεί;`,"settings.transfer.previewFrom":`Από την έκδοση {version}, {date}`,"settings.transfer.previewSecretless":`Αυτό το αρχείο εξήχθη χωρίς κωδικούς. Οι γραμμές που σημειώνονται παρακάτω φτάνουν χωρίς τον δικό τους.`,"settings.transfer.colStored":`Εδώ τώρα`,"settings.transfer.colFile":`Στο αρχείο`,"settings.transfer.same":`Ίδιο`,"settings.transfer.unknownKey":`Αυτό το build δεν γνωρίζει αυτή τη ρύθμιση, οπότε δεν μπορεί να μεταφερθεί.`,"settings.transfer.identityKey":`Ανήκει σε αυτό το μηχάνημα και δεν μεταφέρεται ποτέ`,"settings.transfer.identityKeyHint":`Μέσω του αναγνωριστικού στιγμιότυπου μιλούν σε αυτό το μηχάνημα ο αναμεταδότης και κάθε ζευγαρωμένο αδελφό στιγμιότυπο. Δύο μηχανήματα με το ίδιο αναγνωριστικό συγκρούονται μέσα στην ίδια ομάδα, γι’ αυτό μένει εκεί όπου δημιουργήθηκε.`,"settings.transfer.noPassword":`Φτάνει χωρίς τον κωδικό του. Συμπλήρωσέ τον μετά.`,"settings.transfer.wholeList":`Αντικαθιστά ολόκληρη τη λίστα εδώ, γραμμή προς γραμμή`,"settings.transfer.newFolder":`Αυτόν τον φάκελο δεν τον έχει ακόμη εδώ. Στην αποθήκευση δημιουργείται, ακόμη και μέσα σε κοντέινερ όπου δεν κρέμεται αντίστοιχος τόμος.`,"settings.transfer.selectAll":`Όλα`,"settings.transfer.selectNone":`Κανένα`,"settings.transfer.selectChanged":`Μόνο ό,τι διαφέρει`,"settings.transfer.apply":`Μεταφορά {n}`,"settings.transfer.cancel":`Άκυρο`,"settings.transfer.applying":`Γίνεται μεταφορά…`,"settings.transfer.nothingSelected":`Δεν επιλέχθηκε τίποτα.`,"settings.transfer.applied":`{n} ρυθμίσεις μεταφέρθηκαν. Δεν έγινε καμία επανεκκίνηση.`,"settings.transfer.incomplete":`Εδώ λείπει ακόμη ένας κωδικός: {fields}`,"settings.transfer.incompleteReconnect":`ο κωδικός του δρομολογητή`,"settings.transfer.incompleteConnections":`οι κωδικοί των διαμεσολαβητών`,"settings.transfer.incompleteArchives":`οι κωδικοί των συμπιεσμένων αρχείων`,"settings.transfer.rulesUncompiled":`Μαζί με τις ρυθμίσεις ήρθαν κανόνες που αυτό το build δεν μπορεί να μεταγλωττίσει: {n}. Αποθηκεύονται αλλά δεν ενεργοποιούνται ποτέ. Δες τη σελίδα Κανόνες και κατηγορίες.`,"settings.transfer.parseFailed":`Αυτό δεν είναι εξαγωγή ρυθμίσεων: {reason}`,"settings.transfer.tooNew":`Αυτό το αρχείο γράφτηκε από την {version} και αυτός ο διακομιστής τρέχει την {running}. Ενημέρωσε πρώτα τον διακομιστή, μετά κάνε την εισαγωγή.`,"settings.transfer.applyFailed":`Δεν έγινε η μεταφορά: {error}`,"settings.transfer.group.queue":`Ουρά και ταχύτητα`,"settings.transfer.group.folders":`Φάκελοι`,"settings.transfer.group.archives":`Συμπιεσμένα αρχεία`,"settings.transfer.group.rules":`Κανόνες και κατηγορίες`,"settings.transfer.group.schedule":`Χρονοδιάγραμμα και αθόρυβη λειτουργία`,"settings.transfer.group.network":`Συνδέσεις και επανασύνδεση`,"settings.transfer.group.resolvers":`Backend`,"settings.transfer.group.look":`Εμφάνιση`,"settings.transfer.group.other":`Όλα τα υπόλοιπα`,"settings.mediahook.title":`Ειδοποίηση της βιβλιοθήκης πολυμέσων`,"settings.mediahook.hint":`Μια διεύθυνση που το KnightLoader καλεί μία φορά, μόλις το τελευταίο αρχείο ενός πακέτου φτάσει και μετακινηθεί στη θέση του. Είναι φτιαγμένη για μια σάρωση βιβλιοθήκης σε Jellyfin ή Plex, αλλά το πεδίο δεν ξέρει τίποτα ούτε για το ένα ούτε για το άλλο: καλεί τη διεύθυνση που γράφεις, με τη μέθοδο που διαλέγεις, και προσθέτει μία κεφαλίδα, αν δώσεις κάποια. Η τιμή της κεφαλίδας φυλάγεται κρυπτογραφημένη στον ίδιο χώρο με τα στοιχεία των λογαριασμών σου και δεν επιστρέφει ποτέ σε αυτή τη σελίδα. Δεν καλείται απολύτως τίποτα, όσο δεν έχεις αποθηκεύσει μια διεύθυνση και δεν την έχεις διαλέξει σε ένα συρτάρι στη σελίδα Κανόνες και κατηγορίες. Μια λήψη χωρίς όνομα πακέτου δεν πυροδοτεί ποτέ κλήση, γιατί δεν υπάρχει πακέτο του οποίου θα μπορούσε να είναι το τελευταίο αρχείο. Ούτε για ένα πακέτο που ολοκληρώνεται όσο ο διακομιστής επανεκκινείται γίνεται κλήση: το πρώτο πέρασμα σημειώνει τι είναι ήδη έτοιμο και δεν το ανακοινώνει.`,"settings.mediahook.empty":`Δεν έχει αποθηκευτεί ακόμη διεύθυνση.`,"settings.mediahook.emptyHint":`Μία αξίζει, μόλις ο διακομιστής πολυμέσων σου δεν αντιλαμβάνεται μόνος του τα νέα αρχεία.`,"settings.mediahook.add":`Προσθήκη διεύθυνσης`,"settings.mediahook.name":`Όνομα`,"settings.mediahook.nameHint":`Με αυτό το όνομα διαλέγεις τη διεύθυνση σε ένα συρτάρι στη σελίδα Κανόνες και κατηγορίες. Μόνο γράμματα, ψηφία και - _ ή . Αργότερα δεν αλλάζει, γιατί ένα συρτάρι δείχνει σε αυτήν μέσω αυτού του ονόματος.`,"settings.mediahook.url":`Διεύθυνση`,"settings.mediahook.urlHint":`Η πλήρης διεύθυνση που καλείται, http ή https, μαζί με host και θύρα. Διάβασέ την άλλη μια φορά πριν αποθηκεύσεις: ό,τι στέκει εδώ καλείται από αυτόν τον υπολογιστή. Η ίδια η διεύθυνση αποθηκεύεται σε απλό κείμενο στο settings.json και καταλήγει έτσι και στο πακέτο διαγνωστικών. Βάλε λοιπόν ένα διακριτικό παρακάτω στην κεφαλίδα και όχι στο τμήμα ερωτήματος της διεύθυνσης.`,"settings.mediahook.method":`Μέθοδος`,"settings.mediahook.methodHint":`GET ή POST. Ένα POST στέλνεται χωρίς σώμα. Το Jellyfin θέλει POST, το Plex θέλει GET, και αν δεν είσαι σίγουρος, η δοκιμαστική κλήση σού λέει τι δέχεται η άλλη πλευρά.`,"settings.mediahook.headerName":`Όνομα κεφαλίδας`,"settings.mediahook.headerNameHint":`Η μία κεφαλίδα που στέλνεται μαζί με την κλήση, στο Jellyfin για παράδειγμα X-Emby-Token. Άφησέ το κενό και δεν στέλνεται καμία επιπλέον κεφαλίδα.`,"settings.mediahook.headerValue":`Τιμή κεφαλίδας`,"settings.mediahook.headerValueHint":`Το διακριτικό που μπαίνει σε αυτή την κεφαλίδα. Φυλάγεται κρυπτογραφημένο στον ίδιο χώρο με τα στοιχεία των λογαριασμών σου, δεν γράφεται ποτέ στο settings.json και δεν στέλνεται ποτέ πίσω σε αυτή τη σελίδα.`,"settings.mediahook.valueStored":`Αποθηκευμένη`,"settings.mediahook.valueStoredHint":`Η τιμή μένει σε αυτό το στιγμιότυπο. Άφησε το πεδίο όπως είναι για να τη διατηρήσεις, ή γράψε νέα για να την αντικαταστήσεις. Αν αδειάσεις το πεδίο, η τιμή φεύγει.`,"settings.mediahook.goesTo":`Η κλήση πηγαίνει στο {host}`,"settings.mediahook.goesToForeign":`Αυτή η διεύθυνση δεν βρίσκεται στο δικό σου δίκτυο. Η κλήση φεύγει από αυτόν τον υπολογιστή, και η κεφαλίδα φεύγει μαζί της.`,"settings.mediahook.wait":`Αναμονή πριν την κλήση`,"settings.mediahook.waitHint":`Πόση ώρα αφήνεται ήσυχη αυτή η διεύθυνση μετά από ένα ολοκληρωμένο πακέτο, ώστε από είκοσι πακέτα που τελειώνουν μαζί να βγαίνει μία κλήση αντί για είκοσι. Μια σάρωση βιβλιοθήκης κοστίζει στον διακομιστή πολυμέσων πραγματική δουλειά, και μία που έρχεται ένα λεπτό αργότερα δεν σου κοστίζει τίποτα. Στο 0 η κλήση φεύγει μόλις τα αρχεία ενός πακέτου βρεθούν στη θέση τους, χωρίς να περιμένει άλλα.`,"settings.mediahook.waitImmediate":`Η κλήση φεύγει μόλις ένα πακέτο είναι έτοιμο, χωρίς να περιμένει άλλα.`,"settings.mediahook.error.nameInvalid":`Ένα όνομα περιέχει μόνο γράμματα, ψηφία και - _ ή ., το πολύ 64 χαρακτήρες.`,"settings.mediahook.save":`Αποθήκευση διεύθυνσης`,"settings.mediahook.delete":`Διαγραφή διεύθυνσης`,"settings.mediahook.deleteConfirm":`Να διαγραφεί η {name}; Η αποθηκευμένη τιμή της κεφαλίδας φεύγει μαζί, και από αυτή τη σελίδα δεν επαναφέρεται.`,"settings.mediahook.deleteInUse":`Η {name} είναι ακόμη επιλεγμένη σε {n} συρτάρια. Βάλε πρώτα εκείνα στο «Καμία ειδοποίηση», μετά διάγραψέ την.`,"settings.mediahook.usedBy":`Επιλεγμένη σε {n} συρτάρια`,"settings.mediahook.usedByNone":`Αποθηκευμένη, και δεν την καλεί ακόμη τίποτα`,"settings.mediahook.test":`Αποστολή δοκιμαστικής κλήσης`,"settings.mediahook.testRunning":`Γίνεται κλήση`,"settings.mediahook.lastCall":`Τελευταία κλήση`,"settings.mediahook.lastCallHint":`Τι έγινε την τελευταία φορά που κλήθηκε αυτή η διεύθυνση, μαζί με τις δοκιμαστικές κλήσεις. Κρατιέται μόνο στη μνήμη, οπότε μια επανεκκίνηση το σβήνει χωρίς να αλλάξει τίποτα στην ίδια τη διεύθυνση.`,"settings.mediahook.lastCallNever":`Δεν έχει κληθεί από την εκκίνηση αυτού του διακομιστή`,"settings.mediahook.answeredAfter":`Απάντησε {status} μετά από {duration}`,"settings.mediahook.failedAfter":`Απέτυχε μετά από {duration}`,"settings.mediahook.lastCallFor":`Για το πακέτο {name}`,"settings.mediahook.lastCallTest":`Δοκιμαστική κλήση`,"settings.mediahook.lastCallCoalesced":`Για {n} πακέτα που ολοκληρώθηκαν μαζί`,"settings.mediahook.problem.dns":`Το όνομα host δεν μπόρεσε να επιλυθεί. Έλεγξε τη γραφή, και βάλε τη διεύθυνση IP, αν αυτό το στιγμιότυπο δεν φτάνει στον διακομιστή ονομάτων του δικτύου σου.`,"settings.mediahook.problem.refused":`Σε αυτή τη θύρα δεν ακούει τίποτα. Έλεγξε τη θύρα, και έλεγξε αν ο διακομιστής πολυμέσων είναι προσβάσιμος από αυτό το κοντέινερ και όχι μόνο από τον δικό σου υπολογιστή.`,"settings.mediahook.problem.timeout":`Η άλλη πλευρά δέχτηκε τη σύνδεση και δεν απάντησε μέσα σε {seconds} δευτερόλεπτα. Η διεύθυνση μάλλον είναι σωστή, ο διακομιστής είναι απασχολημένος ή έχει κολλήσει.`,"settings.mediahook.problem.tls":`Η ασφαλής σύνδεση δεν στήθηκε. Ένα αυτοϋπογεγραμμένο πιστοποιητικό είναι ο συνηθισμένος λόγος. Βάλε http και την εσωτερική διεύθυνση, αν ο διακομιστής πολυμέσων βρίσκεται στο δικό σου δίκτυο.`,"settings.mediahook.problem.auth":`Ο διακομιστής απάντησε {status}: δεν δέχτηκε την κεφαλίδα. Έλεγξε το όνομα της κεφαλίδας και επικόλλησε ξανά το διακριτικό.`,"settings.mediahook.problem.notFound":`Ο διακομιστής απάντησε 404: η διεύθυνση είναι προσβάσιμη, αυτή τη διαδρομή όμως δεν την έχει. Έλεγξε τη διαδρομή, μαζί με το αναγνωριστικό βιβλιοθήκης, αν η διεύθυνση κουβαλά κάποιο.`,"settings.mediahook.problem.method":`Ο διακομιστής απάντησε 405: δεν δέχεται {method} σε αυτή τη διαδρομή. Άλλαξε τη μέθοδο και δοκίμασε ξανά.`,"settings.mediahook.problem.redirect":`Η διεύθυνση απάντησε {status} και δείχνει κάπου αλλού. Οι ανακατευθύνσεις δεν ακολουθούνται εδώ, γιατί η κεφαλίδα θα ταξίδευε μαζί τους στη νέα διεύθυνση. Γράψε τη διεύθυνση στην οποία δείχνει.`,"settings.mediahook.problem.server":`Ο διακομιστής απάντησε {status}. Αυτό είναι σφάλμα στην άλλη πλευρά και όχι σε αυτή τη διεύθυνση. Κοίτα στο αρχείο καταγραφής του ίδιου του διακομιστή πολυμέσων.`,"settings.mediahook.problem.proxy":`Η κλήση πέρασε από τον διαμεσολαβητή του HTTP_PROXY και δεν έφτασε. Βάλε τον host του διακομιστή πολυμέσων στο NO_PROXY και δοκίμασε ξανά.`,"settings.mediahook.problem.unknown":`Η κλήση δεν πέτυχε: {error}`,"settings.categories.notify":`Ειδοποίηση της βιβλιοθήκης πολυμέσων`,"settings.categories.notifyHint":`Ποια αποθηκευμένη διεύθυνση καλείται, μόλις ένα πακέτο που μπήκε σε αυτό το συρτάρι ολοκληρωθεί και τα αρχεία του βρεθούν στη θέση τους. Ένα πακέτο του οποίου οι σύνδεσμοι βρίσκονται σε δύο συρτάρια καλεί και τα δύο, μία φορά το καθένα. Στο «Καμία ειδοποίηση» αυτό το συρτάρι μένει σιωπηλό, και αυτό ακριβώς κάνει κάθε συρτάρι όσο δεν αλλάζεις κάτι.`,"settings.categories.notifyNone":`Καμία ειδοποίηση`,"settings.categories.notifyEmpty":`Δεν έχει αποθηκευτεί ακόμη διεύθυνση. Πρόσθεσε μία στη σελίδα Αυτοματοποίηση.`,"settings.categories.notifyMissing":`{id} (διαγράφηκε)`,"settings.module.eventtargets":`Προορισμοί συμβάντων`,"settings.eventTargets.titleHint":`Πού αναφέρει αυτό το στιγμιότυπο, όταν συμβαίνει κάτι: μια δική σου διεύθυνση, με μέθοδο, κεφαλίδες και σώμα που ορίζεις εσύ. Τίποτα δεν είναι προσυμπληρωμένο και τίποτα δεν είναι αναμμένο, μέχρι να το κάνεις εσύ, και μια αναφορά πηγαίνει μόνο στη διεύθυνση που στέκει στη γραμμή. Προσφέρονται τα ίδια συμβάντα στα οποία αντιδρά και ο επεξεργαστής σεναρίων.`,"settings.eventTargets.add":`Προσθήκη προορισμού`,"settings.eventTargets.empty":`Δεν υπάρχουν ακόμη προορισμοί.`,"settings.eventTargets.emptyHint":`Χωρίς προορισμό καμία αναφορά δεν φεύγει από αυτό το μηχάνημα. Πρόσθεσε έναν για να μαθαίνεις για ένα ολοκληρωμένο πακέτο, μια αποτυχημένη λήψη ή ένα captcha που περιμένει.`,"settings.eventTargets.remove":`Αφαίρεση`,"settings.eventTargets.name":`Όνομα`,"settings.eventTargets.nameHint":`Πώς λέγεται αυτός ο προορισμός στη λίστα, στην κατάσταση από κάτω και στην καταγραφή. Το όνομα δεν στέλνεται πουθενά, χρησιμοποίησέ το λοιπόν για να ξεχωρίζεις το κινητό σου από το δωμάτιο συνομιλίας σου.`,"settings.eventTargets.enabled":`Αποστολή σε αυτόν τον προορισμό`,"settings.eventTargets.enabledHint":`Είναι σβηστό μέχρι να το ανάψεις, και αυτό ισχύει για κάθε προορισμό που προσθέτεις. Όσο είναι σβηστό, η γραμμή κρατά όλα όσα πληκτρολόγησες και δεν στέλνει τίποτα. Έτσι μπορείς να χτίσεις έναν προορισμό με την ησυχία σου και να τον δοκιμάσεις, πριν ακούσει κανείς κάτι από αυτόν.`,"settings.eventTargets.url":`Διεύθυνση`,"settings.eventTargets.urlHint":`Η πλήρης διεύθυνση στην οποία πηγαίνει μια αναφορά, μόνο http ή https. Αυτός είναι ένας διακομιστής που ονομάζεις εσύ, όχι κάποιος που διαλέγει το KnightLoader, και όλα όσα υπάρχουν στο σώμα παρακάτω καταλήγουν εκεί. Ο host στέκει στη διπλωμένη γραμμή, ώστε να βλέπεις με μια ματιά πού αναφέρει ένας προορισμός. Οι μεταβλητές δουλεύουν και εδώ και κωδικοποιούνται για διεύθυνση. Αν η διεύθυνση ανακατευθύνει σε άλλον host, η κεφαλίδα Authorization πέφτει στον δρόμο, κάτι που συνήθως γυρίζει πίσω ως 401.`,"settings.eventTargets.method":`Μέθοδος`,"settings.eventTargets.methodHint":`GET, POST ή PUT. Το POST είναι αυτό που θέλουν και το ntfy και το Gotify και το Matrix. Το GET δεν στέλνει σώμα, οπότε το πρότυπο σώματος παρακάτω μένει τότε εκτός.`,"settings.eventTargets.headers":`Κεφαλίδες`,"settings.eventTargets.headersHint":`Μία κεφαλίδα ανά γραμμή, γραμμένη ως Όνομα: τιμή, όπως γράφονται και παντού αλλού. Εδώ μπαίνει ένα διακριτικό: Authorization: Bearer … για το Matrix, X-Title ή Priority για το ntfy. Μια τιμή αποθηκεύεται όπως ο κωδικός του δρομολογητή, στο settings.json σε αυτό το μηχάνημα, και δεν επιστρέφει ποτέ σε περιηγητή: εκεί βλέπεις οκτώ αστεράκια. Αν αλλάξεις τη διεύθυνση, η αποθηκευμένη τιμή απορρίπτεται αντί να μεταφερθεί στη νέα.`,"settings.eventTargets.body":`Πρότυπο σώματος`,"settings.eventTargets.bodyHint":`Τι στέλνεται, με τα σύμβολα κράτησης θέσης να συμπληρώνονται τη στιγμή που συμβαίνει το συμβάν. Άφησέ το κενό και στέλνονται μόνο οι κεφαλίδες. Οι τιμές κωδικοποιούνται ανάλογα με το Content-Type που όρισες στις κεφαλίδες, οπότε μέσα σε ένα σώμα JSON ένα όνομα αρχείου με εισαγωγικό κωδικοποιείται σωστά αντί να χαλάσει το έγγραφο.`,"settings.eventTargets.events":`Συμβάντα`,"settings.eventTargets.eventsHint":`Ποια συμβάντα πηγαίνουν σε αυτόν τον προορισμό. Στην αρχή δεν είναι τσεκαρισμένο τίποτα. Τρία από αυτά δηλώνονται ξανά μετά από μια επανεκκίνηση, γιατί ό,τι θυμούνται βρίσκεται στη μνήμη και όχι στον δίσκο: η ουρά δηλώνεται ως άδεια, κάθε captcha που περιμένει ακόμη δηλώνεται άλλη μία φορά, και κάθε λογαριασμός που έχει ήδη λήξει δηλώνεται άλλη μία φορά. Ένα ολοκληρωμένο πακέτο όχι, γιατί το πρώτο πέρασμα μετά την εκκίνηση σημειώνει μόνο την κατάσταση και δεν λέει τίποτα.`,"settings.eventTargets.eventsNone":`Δεν είναι τσεκαρισμένο τίποτα, αυτός ο προορισμός λοιπόν δεν στέλνει ποτέ τίποτα.`,"settings.eventTargets.eventsBurst":`Ένας σύνδεσμος που προστίθεται πυροδοτεί μία φορά ανά σύνδεσμο, διακόσιοι επικολλημένοι σύνδεσμοι είναι λοιπόν διακόσιες αναφορές. Ό,τι δεν χωράει στην ουρά απορρίπτεται και μετριέται παρακάτω, αντί να στοιβάζεται.`,"settings.eventTargets.replaysHint":`Αυτό το συμβάν δηλώνεται ξανά μετά από κάθε επανεκκίνηση, γιατί ό,τι θυμάται βρίσκεται στη μνήμη και όχι στον δίσκο.`,"settings.eventTargets.attempts":`Προσπάθειες παράδοσης`,"settings.eventTargets.attemptsHint":`Πόσες φορές δοκιμάζεται μία αναφορά πριν εγκαταλειφθεί. Το 0 σημαίνει ότι δεν λες τίποτα γι’ αυτό, τότε ισχύουν οι συνηθισμένες τρεις· ποιος αριθμός ισχύει αυτή τη στιγμή στέκει δίπλα στο πλαίσιο. Ανάμεσα σε 1 και 5. Μια άρνηση από την άλλη πλευρά, ένα λάθος διακριτικό ή μια διαδρομή που δεν υπάρχει, δεν επαναλαμβάνεται καθόλου, γιατί μια δεύτερη προσπάθεια δεν το αλλάζει αυτό, και ο λόγος στέκει στην κατάσταση από κάτω. Όσο μια αναφορά περιμένει, τίποτα δεν καταλήγει στον δίσκο. Ένας προορισμός που έλειπε όλη τη νύχτα δεν έχει λοιπόν τίποτα να αναπληρώσει όταν επιστρέψει.`,"settings.eventTargets.attemptsDefault":`Το 0 σημαίνει τρεις`,"settings.eventTargets.timeout":`Χρονικό όριο (δευτερόλεπτα)`,"settings.eventTargets.timeoutHint":`Πόση ώρα επιτρέπεται να πάρει μία προσπάθεια. Το 0 σημαίνει ότι δεν λες τίποτα γι’ αυτό, τότε ισχύουν δεκαπέντε δευτερόλεπτα. Ανάμεσα σε 1 και 60. Ένας διακομιστής push που απαντά αργά κρατά αυτόν τον προορισμό τόση ώρα δεσμευμένο, και ό,τι περιμένει πίσω του περιμένει μαζί.`,"settings.eventTargets.placeholders":`Μεταβλητές`,"settings.eventTargets.placeholdersHint":`Τα ονόματα που μπορείς να γράψεις στη διεύθυνση, σε μια κεφαλίδα ή στο σώμα, το καθένα με δύο σύμβολα τοις εκατό γύρω από το όνομα. Έρχονται από τον διακομιστή, αυτή η λίστα είναι λοιπόν ό,τι πραγματικά συμπληρώνει αυτό το build. Ένα όνομα που δεν το γνωρίζει αυτό το build το αφήνει όπως το πληκτρολόγησες, ώστε ένα τυπογραφικό λάθος να φαίνεται στην αναφορά αντί να εξαφανίζεται σιωπηλά. Ένα όνομα που το γνωρίζει, αλλά που αυτό το συμβάν δεν το κουβαλά, μένει κενό.`,"settings.eventTargets.placeholderUnused":`Κανένα από τα συμβάντα που τσεκάρισες παραπάνω δεν κουβαλά {name}, σε κάθε αναφορά αυτού του προορισμού η μεταβλητή μένει λοιπόν κενή.`,"settings.eventTargets.leavesTheBox":`Κάθε αναφορά αυτού του προορισμού φεύγει από αυτό το μηχάνημα και πηγαίνει στο {host}.`,"settings.eventTargets.test":`Αποστολή δοκιμής`,"settings.eventTargets.testBusy":`Γίνεται αποστολή`,"settings.eventTargets.testHint":`Αυτό στέλνει πραγματικά μία αναφορά στη διεύθυνση παραπάνω, αμέσως, με τις τιμές αυτής της γραμμής και ένα επινοημένο συμβάν. Δεν είναι δοκιμή στα ξηρά: το κινητό σου δονείται, και το δωμάτιο συνομιλίας σου το βλέπει. Η απάντηση στέκει εκεί όπως ήρθε πίσω, ώστε να μπορείς να διαβάσεις μια άρνηση αντί να τη μαντεύεις. Μια αποθηκευμένη τιμή κεφαλίδας συμπληρώνεται για το αίτημα και μετά εμφανίζεται ως οκτώ αστεράκια, γιατί αυτός ο περιηγητής δεν την είδε ποτέ.`,"settings.eventTargets.testResult":`Η απάντηση που ήρθε πίσω`,"settings.eventTargets.testSent":`Τι στάλθηκε`,"settings.eventTargets.took":`Διήρκεσε {duration}`,"settings.eventTargets.testTruncated":`Η απάντηση είναι μεγαλύτερη. Εδώ στέκουν μόνο οι πρώτοι {n} χαρακτήρες.`,"settings.eventTargets.testEmptyBody":`Η απάντηση δεν είχε σώμα, αυτό είναι φυσιολογικό σε έναν διακομιστή push.`,"settings.eventTargets.testNoAnswer":`Δεν ήρθε καμία απάντηση.`,"settings.eventTargets.status":`Κατάσταση`,"settings.eventTargets.statusUnknown":`Από την εκκίνηση του διακομιστή δεν έφυγε τίποτα προς αυτόν τον προορισμό. Αυτό δεν σημαίνει ότι δεν έφυγε ποτέ τίποτα.`,"settings.eventTargets.lastAttempt":`Τελευταία προσπάθεια`,"settings.eventTargets.lastOk":`Τελευταία που έφτασε`,"settings.eventTargets.lastOkNever":`Από την εκκίνηση του διακομιστή δεν έχει φτάσει τίποτα.`,"settings.eventTargets.sentCount":`{n} παραδόθηκαν από την εκκίνηση του διακομιστή`,"settings.eventTargets.dropped":`{n} απορρίφθηκαν επειδή η ουρά ήταν γεμάτη`,"settings.eventTargets.droppedHint":`Ένα κύμα που φτάνει πιο γρήγορα απ’ ό,τι το δέχεται αυτός ο προορισμός απορρίπτεται αντί να φυλαχτεί. Το να φυλαχτεί θα σήμαινε να ξοδεύεται μνήμη για αναφορές που όταν φτάσουν είναι προ πολλού παλιές. Αν αυτός ο αριθμός συνεχίζει να ανεβαίνει, ο προορισμός είναι πολύ αργός για τα συμβάντα που τσεκάρισες.`,"settings.eventTargets.problem.noUrl":`Σε αυτή τη γραμμή δεν στέκει διεύθυνση, δεν μπορεί λοιπόν να σταλεί τίποτα. Γράψε μία παραπάνω.`,"settings.eventTargets.problem.badUrl":`Η διεύθυνση δεν διαβάζεται ως διεύθυνση http ή https. Έλεγξε το σχήμα και τον host.`,"settings.eventTargets.problem.badMethod":`Αυτό το build στέλνει GET, POST και PUT και τίποτα άλλο. Πάρε ένα από τα τρία.`,"settings.eventTargets.problem.badTemplate":`Μια μεταβλητή δεν έκλεισε. Καθεμία γράφεται με δύο σύμβολα τοις εκατό και στις δύο πλευρές του ονόματος.`,"settings.eventTargets.problem.unknownTrigger":`Ένα από τα συμβάντα σε αυτή τη γραμμή δεν είναι συμβάν που πυροδοτεί αυτό το build. Βγάλ’ το και διάλεξε ένα από τη λίστα.`,"settings.eventTargets.problem.dns":`Ο host δεν μπόρεσε να επιλυθεί από αυτό το στιγμιότυπο. Ένα κοντέινερ έχει συχνά δική του υπηρεσία ονομάτων, μια διεύθυνση στην οποία φτάνει ο δικός σου υπολογιστής δεν τη φτάνει λοιπόν αυτόματα και αυτό το μηχάνημα.`,"settings.eventTargets.problem.refused":`Εκεί δεν ακούει τίποτα. Έλεγξε τη θύρα και αν η υπηρεσία τρέχει καθόλου.`,"settings.eventTargets.problem.tls":`Το πιστοποιητικό δεν έγινε δεκτό. Συνήθως φταίει ένα αυτοϋπογεγραμμένο πιστοποιητικό στον δικό σου διακομιστή. Στο δικό σου δίκτυο βάλε http, ή δώσε αυτό το πιστοποιητικό σε αυτό το κοντέινερ.`,"settings.eventTargets.problem.timeout":`Η άλλη πλευρά δεν απάντησε μέσα στο χρονικό όριο. Ανέβασε το όριο παραπάνω, ή στείλε σε κάτι πιο γρήγορο.`,"settings.eventTargets.problem.auth":`Η άλλη πλευρά απέρριψε τα διαπιστευτήρια. Έλεγξε το διακριτικό στις κεφαλίδες, και θυμήσου ότι μια ανακατεύθυνση σε άλλον host πετά την κεφαλίδα Authorization στον δρόμο.`,"settings.eventTargets.problem.notFound":`Η άλλη πλευρά δεν γνωρίζει αυτή τη διαδρομή. Στο ntfy το θέμα ανήκει στη διεύθυνση, στο Matrix το αναγνωριστικό δωματίου.`,"settings.eventTargets.problem.rejected":`Η άλλη πλευρά διάβασε το αίτημα και το απέρριψε. Η απάντηση παρακάτω είναι η δική της διατύπωση και λέει περισσότερα απ’ ό,τι θα μπορούσε μια κατάταξη εδώ.`,"settings.eventTargets.problem.rateLimited":`Η άλλη πλευρά αρνείται προς το παρόν, επειδή έφτασαν πολλά μαζί. Βγάλε τα πιο θορυβώδη συμβάντα, ή στείλε στον δικό σου διακομιστή αντί σε δημόσιο.`,"settings.eventTargets.problem.server":`Η άλλη πλευρά απάντησε με δικό της σφάλμα. Δοκιμάστηκε τόσες φορές όσες επιτρέπει αυτή η γραμμή, το επόμενο μέρος που κοιτάς είναι λοιπόν το δικό της αρχείο καταγραφής.`,"settings.scripts.trigger.linkAdded":`Ένας σύνδεσμος προστίθεται`,"settings.scripts.trigger.packageDone":`Ένα πακέτο ολοκληρώνεται`,"settings.scripts.trigger.extractDone":`Ένα συμπιεσμένο αρχείο ολοκληρώνει την αποσυμπίεση`,"settings.scripts.trigger.checksumFailed":`Ένα άθροισμα ελέγχου δεν ταιριάζει`,"settings.scripts.trigger.reconnectDone":`Μια επανασύνδεση έτρεξε`,"settings.scripts.trigger.accountExpired":`Ένας λογαριασμός έληξε`,"settings.scripts.trigger.captchaPending":`Ένα captcha περιμένει`,"settings.nav.health":`Κατάσταση`,"settings.module.metrics":`Διεύθυνση μετρήσεων για σύστημα παρακολούθησης`,"settings.health.title":`Κατάσταση αυτή τη στιγμή`,"settings.health.titleHint":`Αυτή η σελίδα μόνο διαβάζει. Τίποτα πάνω της δεν ξεκινά, δεν σταματά και δεν αλλάζει κάτι, και αν την αφήσεις ανοιχτή δεν αλλάζει ούτε αυτό κάτι. Οι τιμές ανακτώνται κάθε δέκα δευτερόλεπτα. Αν μια ανάκτηση αποτύχει, μένει η τελευταία μέτρηση αντί να αδειάσει η σελίδα. Τα μέρη που πρέπει να ρωτηθούν μοιράζονται για μισό λεπτό. Ό,τι στέκει εδώ μπορεί λοιπόν να είναι μέχρι και τριάντα δευτερόλεπτα πίσω από τις γραμμές στη σελίδα Λήψεις.`,"settings.health.version":`Έκδοση`,"settings.health.uptime":`Τρέχει εδώ και`,"settings.health.uptimeHint":`Πόση ώρα τρέχει αυτή η διεργασία, όχι πόση ώρα τρέχει το μηχάνημα. Ένα κοντέινερ που ξαναξεκίνησε πριν από μία ώρα αρχίζει εδώ πάλι από το μηδέν, ό,τι κι αν λέει ο host. Η ημερομηνία δίπλα του είναι το ρολόι του ίδιου του διακομιστή, όχι του περιηγητή σου.`,"settings.health.startedAt":`Ξεκίνησε`,"settings.health.sampled":`Διαβάστηκε πριν από {n} δευτερόλεπτο(α)`,"settings.health.loadFailed":`Δεν ήταν δυνατή η φόρτωση της κατάστασης. Είναι προσβάσιμος ο διακομιστής;`,"settings.health.oldHealthHint":`Η παλιά διεύθυνση /api/health δεν έχει αλλάξει και απαντά ακόμα «ok» όσο τρέχει αυτή η διεργασία, ό,τι κι αν λέει αυτή η σελίδα. Μένει έτσι επειδή τη διαβάζουν ο έλεγχος υγείας του ίδιου του container, η γέφυρα Click'n'Load και η αναζήτηση στιγμιότυπων στο δίκτυό σου από την εφαρμογή του κινητού, και μια απάντηση διαφορετική από «ok» εκεί θα σήμαινε το container ως μη υγιές και θα έκανε το κινητό να σταματήσει να βρίσκει αυτό το στιγμιότυπο. Σε αυτή τη σελίδα αναφέρεται ένα σφάλμα· εκείνη η διεύθυνση λέει μόνο αν ακούει κάτι.`,"health.state.ok":`Λειτουργεί`,"health.state.degraded":`Λειτουργεί, αλλά με ένα σφάλμα`,"health.state.failed":`Δεν λειτουργεί`,"health.state.unused":`Δεν είναι σε λειτουργία εδώ`,"health.state.unknown":`Δεν μπορεί να ελεγχθεί εδώ`,"settings.health.parts":`Μέρη`,"settings.health.partsHint":`Μία γραμμή για κάθε μέρος της εφαρμογής που μπορεί να αποτύχει μόνο του. Ένα μέρος που δεν έχεις ρυθμίσει ποτέ σε αυτό το στιγμιότυπο το λέει αντί να μετρά ως σφάλμα, και ένα μέρος για το οποίο αυτό το build δεν μπορεί να ρωτήσει το λέει επίσης. Η ανάγνωση μιας γραμμής δεν αλλάζει τίποτα: ένα μέρος που λέει ότι δεν λειτουργεί αποτυγχάνει ήδη εδώ και λίγο καιρό, και εδώ απλώς το μαθαίνεις.`,"health.part.store":`Βάση δεδομένων`,"health.part.queue":`Ουρά`,"health.part.disk":`Φάκελοι προορισμού`,"health.part.jd":`Υποδομή JDownloader`,"health.part.ytdlp":`yt-dlp`,"health.part.accounts":`Λογαριασμοί hoster`,"health.part.feeds":`Συνδρομές σε ροές`,"health.part.relay":`Αναμεταδότης`,"health.part.captcha":`Captcha`,"health.remedy.store.failed":`Η βάση δεδομένων δεν απάντησε. Οι λήψεις συνεχίζονται, αλλά γι’ αυτές δεν καταγράφεται τίποτα πια. Μια επανεκκίνηση θα έχανε λοιπόν όλα όσα άλλαξαν από τότε. Δες αν ο φάκελος δεδομένων είναι ακόμη προσαρτημένος και ακόμη εγγράψιμος.`,"health.remedy.jd.unreachable":`Το KL_JD ονομάζει μια διεύθυνση στην οποία αυτό το στιγμιότυπο δεν φτάνει αυτή τη στιγμή. Δες αν το κοντέινερ JDownloader τρέχει και αν η θύρα API του απαντά από εδώ. Οι σύνδεσμοι που μόνο το JDownloader μπορεί να φέρει μένουν στο μεταξύ στην ουρά και δεν έχουν αποτύχει.`,"health.remedy.jd.notWired":`Το JDownloader απαντά ξανά, αλλά αυτή η διεργασία καλωδίωσε τα backend της κατά την εκκίνηση και τότε δεν το είχε. Κάνε επανεκκίνηση του KnightLoader, ώστε να το παραλάβει.`,"health.remedy.ytdlp.missing":`Κατά την εκκίνηση δεν βρέθηκε κανένα yt-dlp (KL_YTDLP, ή «yt-dlp» στο PATH). Οι σελίδες πολυμέσων αποτυγχάνουν τότε με το σφάλμα της ίδιας της σελίδας, αντί να ανοίγουν σε παραλλαγές. Για να βρεθεί, χρειάζεται επανεκκίνηση.`,"health.remedy.disk.low":`Ένας φάκελος προορισμού βρίσκεται κάτω από το όριο που έβαλες στη σελίδα Λήψεις. Εκεί δεν ξεκινά τίποτα καινούριο, μέχρι να υπάρξει ξανά χώρος ή μέχρι να κατεβάσεις το όριο. Ό,τι ήδη τρέχει δεν το σταματά αυτό το όριο.`,"health.remedy.disk.elsewhere":`Ένας φάκελος δεν είναι εκεί, γι’ αυτό οι αριθμοί περιγράφουν τον πλησιέστερο φάκελο από πάνω του. Αν μια προσάρτηση δεν ανέβηκε, αυτός είναι ένας εντελώς άλλος δίσκος. Δες τη διαδρομή, πριν πιστέψεις τους αριθμούς.`,"health.remedy.accounts.benched":`Τουλάχιστον ένας λογαριασμός hoster αφήνεται ήσυχος μετά από ένα σφάλμα. Δοκιμάζεται από μόνος του άλλη μία φορά, όταν περάσει η αναμονή, και η αναμονή διπλασιάζεται κάθε φορά. Πήγαινε στους Λογαριασμούς και πάτα Ανανέωση στη γραμμή, αν θέλεις να το μάθεις τώρα.`,"health.remedy.accounts.invalid":`Τουλάχιστον ένας λογαριασμός hoster απορρίφθηκε. Ένα νέο κλειδί ή μια ανανεωμένη συνδρομή βοηθά, η αναμονή όχι.`,"health.remedy.feeds.failing":`Σε τουλάχιστον μία συνδρομή απέτυχε η τελευταία ανάκτηση. Ποια και γιατί, στέκει στη σελίδα Λήψεις δίπλα στη ροή και στις γραμμές καταγραφής στη σελίδα Διαγνωστικά.`,"health.remedy.relay.down":`Μια διεύθυνση αναμεταδότη είναι αποθηκευμένη και η σύνδεση δεν στέκει. Αυτό το στιγμιότυπο ξαναπροσπαθεί από μόνο του, και τοπικά όλα λειτουργούν ως συνήθως. Μόνο από έξω δεν είναι αυτή τη στιγμή προσβάσιμο.`,"health.remedy.captcha.waiting":`Ένα backend σταμάτησε και ρωτά έναν άνθρωπο. Πίσω του δεν κινείται τίποτα, μέχρι να απαντήσει κάποιος.`,"settings.health.tasks":`Λήψεις αυτή τη στιγμή`,"settings.health.tasksHint":`Μια αποτύπωση της λίστας όπως είναι τώρα, όχι μέτρηση μέσα στον χρόνο, οπότε κανένας από αυτούς τους αριθμούς δεν λέει πόσο συχνά απέτυχε κάτι. Το «Απέτυχαν» μετρά τις γραμμές που βρίσκονται στη λίστα με σφάλμα: πέφτει όταν τις καθαρίζεις και όταν η λίστα τακτοποιείται μετά από τις ημέρες που όρισες, και ανεβαίνει ξανά όταν κάτι καινούργιο πάει στραβά.`,"settings.health.diskWhere":`Πόσο χώρο έχουν οι φάκελοι προορισμού το δείχνει η σελίδα Λήψεις.`,"settings.health.running":`Σε εξέλιξη`,"settings.health.waiting":`Σε αναμονή`,"settings.health.failed":`Απέτυχαν`,"settings.health.waitingWhy":`Γιατί περιμένουν`,"settings.health.failedWhy":`Τι πήγε στραβά`,"settings.health.nothingWaiting":`Τίποτα δεν κρατιέται πίσω.`,"settings.health.nothingFailed":`Στη λίστα δεν έχει αποτύχει τίποτα.`,"settings.health.scrapeHint":`Ανοίγει μια δεύτερη διεύθυνση που δίνει τις ίδιες τιμές ως απλό κείμενο, στη μορφή που διαβάζουν το Prometheus και τα εργαλεία που φτιάχτηκαν σαν αυτό. Ανακτάται, δεν στέλνεται ποτέ: τίποτα δεν φεύγει από αυτό το μηχάνημα, όσο δεν έρχεται εδώ η δική σου παρακολούθηση να το ζητήσει. Όσο αυτό είναι σβηστό, η διεύθυνση δεν υπάρχει καν και απαντά με 404, ακριβώς όπως κάθε άλλη διεύθυνση που δεν έχει αυτή η εφαρμογή. Σε στιγμιότυπο με κωδικό, η ανάκτηση χρειάζεται ένα από τα διακριτικά API σου, και αυτό μπορεί να το μάθει κάθε συλλέκτης μετρήσεων. Ένας τέτοιος συλλέκτης δεν στέλνει κεφαλίδα προέλευσης και γι’ αυτό περνά. Μια καρτέλα περιηγητή σε άλλη διεύθυνση στέλνει, και απορρίπτεται όταν δεν ταιριάζει με τη διεύθυνση αυτού του στιγμιότυπου. Μέσα στο κείμενο στέκουν οι διαδρομές των φακέλων προορισμού σου. Δώσ’ το λοιπόν μόνο εκεί όπου θα έδινες και τα ίδια τα ονόματα των φακέλων.`,"settings.health.scrapeUrl":`Διεύθυνση μετρήσεων`,"settings.health.scrapeCopy":`Αντιγραφή διεύθυνσης`,"settings.health.scrapeCopied":`Η διεύθυνση αντιγράφηκε`,"settings.health.scrapeOffHint":`Αυτή η διεύθυνση δεν απαντά τίποτα όσο ο διακόπτης από πάνω είναι σβηστός.`,"settings.diagnostics.systemTitle":`Πληροφορίες συστήματος`,"settings.diagnostics.fileTitle":`Αρχείο καταγραφής`,"settings.diagnostics.fileOn":`Εγγραφή της καταγραφής σε αρχείο`,"settings.diagnostics.fileOnHint":`Σβηστό μέχρι να το ανάψεις, και καμία ενημέρωση δεν σου το ανάβει. Αναμμένο, αυτό το στιγμιότυπο γράφει κάθε γραμμή που καταγράφει σε ένα αρχείο μέσα στον φάκελο δεδομένων του, ώστε μια κατάρρευση από προχθές να διαβάζεται ακόμη μετά από επανεκκίνηση. Μια γραμμή καταγραφής μπορεί να ονομάζει τη διεύθυνση μιας ροής στην οποία είσαι συνδρομητής, οπότε αντιμετώπισε το αρχείο ως δικό σου. Στο κοντέινερ οι ίδιες γραμμές πάνε ήδη στα docker logs, το αρχείο είναι αυτό που μένει όταν εκείνα έχουν κυλήσει παρακάτω.`,"settings.diagnostics.fileSize":`Μέγεθος ανά αρχείο`,"settings.diagnostics.fileSizeHint":`Μόλις το αρχείο φτάσει σε αυτό το μέγεθος, μετονομάζεται και ξεκινά ένα καινούριο.`,"settings.diagnostics.fileKeep":`Παλιά αρχεία που κρατιούνται`,"settings.diagnostics.fileKeepHint":`Πόσα μετονομασμένα αρχεία μένουν δίπλα σε αυτό που γράφεται. Το μηδέν κρατά μόνο το τρέχον αρχείο· δεν απενεργοποιεί την καταγραφή.`,"settings.diagnostics.fileWhere":`Πού βρίσκεται`,"settings.diagnostics.fileWhereHint":`Σταθερό, ώστε ένα τυπογραφικό λάθος σε μια διαδρομή να μην μπορεί να σταματήσει την καταγραφή. Όρισε το KL_LOG_DIR πριν ξεκινήσεις την εφαρμογή, για να το βάλεις σε άλλον δίσκο.`,"settings.diagnostics.fileStateOff":`Δεν γράφεται`,"settings.diagnostics.fileStateOn":`{size} από {max} σε χρήση`,"settings.diagnostics.fileProblem":`Το αρχείο καταγραφής δεν γράφεται: {error}`,"settings.diagnostics.fileProblemHint":`Έλεγξε αν το {path} υπάρχει και αν ο λογαριασμός με τον οποίο τρέχει αυτή η διεργασία επιτρέπεται να γράψει εκεί. Στο Unraid αυτό συνήθως σημαίνει ότι ο φάκελος ανήκει στον root, ενώ το κοντέινερ τρέχει ως άλλος χρήστης. Τίποτα άλλο δεν σταμάτησε: οι τελευταίες {n} γραμμές βρίσκονται ακόμη στη μνήμη και συνεχίζουν να μπαίνουν στο πακέτο διαγνωστικών.`,"settings.diagnostics.fileProblemSpace":`Σε εκείνον τον τόμο είναι ακόμη {free} ελεύθερα.`,"settings.diagnostics.fileProblemSpaceUnknown":`Πόσος χώρος έχει μείνει σε εκείνον τον τόμο δεν διαβάζεται σε αυτό το σύστημα.`,"settings.diagnostics.fileCurrent":`Τρέχον αρχείο`,"settings.diagnostics.fileOlder":`Παλαιότερο αρχείο {n}`,"settings.diagnostics.fileEmpty":`Δεν έχει γραφτεί ακόμη τίποτα.`,"settings.diagnostics.fileDownload":`Λήψη`,"settings.diagnostics.logSearch":`Αναζήτηση στις γραμμές`,"settings.diagnostics.logSearchHint":`Απλό κείμενο, χωρίς μπαλαντέρ, κεφαλαία και πεζά μετρούν το ίδιο. Ψάχνει στις γραμμές που είναι φορτωμένες εδώ, όχι στα παλαιότερα αρχεία. Για να ψάξεις ένα ολόκληρο αρχείο, κατέβασέ το.`,"settings.diagnostics.logSource":`Πηγή`,"settings.diagnostics.logSourceAll":`Όλες οι πηγές`,"settings.diagnostics.logSourceOther":`Υπόλοιπες γραμμές`,"settings.diagnostics.logSourceHint":`Από ποιο μέρος της εφαρμογής προέρχεται μια γραμμή, διαβασμένο στην αρχή της ίδιας της γραμμής. Οι γραμμές που δεν ονομάζουν μέρος στέκουν στις «Υπόλοιπες γραμμές». Κατά βαρύτητα δεν γίνεται φιλτράρισμα: σε αυτή την εφαρμογή καμία γραμμή δεν κρατά κάτι τέτοιο.`,"settings.diagnostics.logFollow":`Παρακολούθηση νέων γραμμών`,"settings.diagnostics.logFollowHint":`Ρωτά κάθε δύο δευτερόλεπτα τι έχει έρθει από την τελευταία φορά και πηδά στην πιο πρόσφατη γραμμή. Σβηστό, η προβολή μένει εκεί που είναι, ώστε να μη σου ξεφεύγει κάτι όσο το διαβάζεις.`,"settings.diagnostics.logMatches":`{shown} από {total} γραμμές`,"settings.diagnostics.logNoMatches":`Καμία γραμμή εδώ δεν το περιέχει αυτό.`,"settings.diagnostics.logGap":`Ανάμεσα σε δύο ερωτήματα έπεσαν έξω {n} γραμμές. Ήρθαν περισσότερες απ’ όσες χωρούν οι {cap} γραμμές στη μνήμη. Άναψε το αρχείο καταγραφής, για να διατηρούνται.`,"settings.diagnostics.logTaskOnly":`Μόνο αυτή η λήψη`,"settings.diagnostics.logTaskClear":`Να φαίνονται ξανά όλες οι λήψεις`,"settings.diagnostics.logTaskChip":`Να φαίνονται μόνο οι γραμμές που ονομάζουν αυτή τη λήψη`,"detail.log.title":`Καταγραφή για αυτή τη λήψη`,"detail.log.hint":`Οι γραμμές που κατέγραψε αυτό το στιγμιότυπο και ονομάζουν αυτή τη λήψη με το αναγνωριστικό της.`,"detail.log.empty":`Για αυτή τη λήψη δεν καταγράφηκε τίποτα.`,"detail.log.emptyHint":`Δεν κρατά κάθε γραμμή σε ποια λήψη ανήκει. Μια λήψη μπορεί λοιπόν να έχει πρόβλημα χωρίς να εμφανιστεί εδώ ούτε μία γραμμή. Ολόκληρη η καταγραφή στέκει στη σελίδα Διαγνωστικά.`,"detail.log.openDiagnostics":`Άνοιγμα ολόκληρης της καταγραφής`,"detail.log.remote":`Η καταγραφή μένει στο στιγμιότυπο που την έγραψε. Για μια λήψη που τρέχει σε άλλο μηχάνημα δεν υπάρχει λοιπόν εδώ τίποτα να δεις.`,"settings.owner.identityTitle":`Ως ποιος γράφει αυτό το στιγμιότυπο`,"settings.owner.identityHint":`Κάθε αρχείο που δημιουργεί αυτό το στιγμιότυπο παίρνει αυτόν τον κάτοχο και αυτά τα δικαιώματα, και ό,τι ξεκινά το ίδιο επίσης: yt-dlp, ffmpeg και το ενσωματωμένο JDownloader. Στο κοντέινερ η ταυτότητα ορίζεται τη στιγμή που ξεκινά το κοντέινερ, από τον λογαριασμό με τον οποίο ξεκίνησε, και τίποτα σε αυτή τη σελίδα δεν μπορεί να την αλλάξει.`,"settings.owner.uid":`Χρήστης`,"settings.owner.gid":`Ομάδα`,"settings.owner.umask":`Umask`,"settings.owner.umaskUnknown":`Αυτός ο πυρήνας δεν τη δίνει`,"settings.owner.asked":`Ζητήθηκε`,"settings.owner.envIgnored":`Το {name}={value} είναι ορισμένο, αλλά κανείς μέσα σε αυτό το image δεν διαβάζει τη μεταβλητή. Την ταυτότητα την ορίζει ο λογαριασμός με τον οποίο ξεκίνησε το κοντέινερ, και αυτός είναι ο {owner}.`,"settings.owner.envHow":`Αν θέλεις να τρέχει με άλλον λογαριασμό, δήλωσέ τον στην εντολή εκκίνησης: --user <uid>:<gid>. Στο Unraid αυτό πάει στα Extra Parameters, και το κοντέινερ πρέπει να δημιουργηθεί ξανά για να πιάσει.`,"settings.owner.desktopNote":`Η εφαρμογή επιφάνειας εργασίας τρέχει με τον δικό σου λογαριασμό. Τα PUID, PGID και UMASK είναι ρυθμίσεις κοντέινερ και εδώ δεν κάνουν τίποτα.`,"settings.owner.noOwners":`Σε αυτό το σύστημα τα αρχεία δεν έχουν κατόχους, δεν υπάρχει λοιπόν τίποτα να συγκριθεί. Αυτό δεν είναι σφάλμα.`,"settings.owner.checkTitle":`Έλεγχος φακέλων`,"settings.owner.checkHint":`Εδώ γράφεται πραγματικά ένα αρχείο και ένας υποφάκελος σε κάθε φάκελο, μετά διαβάζεται πίσω σε ποιον ανήκουν και ποιος άλλος μπορεί να τα διαβάσει, και τα δύο αφαιρούνται ξανά. Αυτό πρέπει να μετρηθεί και δεν επιτρέπεται να υπολογιστεί: ένας κοινόχρηστος φάκελος μπορεί να φέρνει δικούς του κανόνες δικαιωμάτων, και ένας φάκελος με ορισμένο set-group-id δίνει άλλη ομάδα από αυτή που έχει αυτή η διεργασία. Ο έλεγχος τρέχει από μόνος του αφού αποθηκεύσεις έναν αλλαγμένο φάκελο, και κάθε φορά που πατάς το κουμπί.`,"settings.owner.run":`Έλεγχος φακέλων τώρα`,"settings.owner.running":`Γίνεται έλεγχος…`,"settings.owner.never":`Δεν έχει ελεγχθεί ακόμη.`,"settings.owner.checkedAt":`Τελευταίος έλεγχος {time}.`,"settings.owner.checkFailed":`Ο έλεγχος δεν έτρεξε: {error}`,"settings.owner.role.downloads":`Φάκελος λήψεων`,"settings.owner.role.work":`Φάκελος εργασίας`,"settings.owner.role.category":`Φάκελος κατηγορίας`,"settings.owner.role.watch":`Παρακολουθούμενος φάκελος`,"settings.owner.v.ok":`Τα αρχεία φτάνουν εδώ ως {fileOwner} με {fileMode}, οι νέοι υποφάκελοι με {subdirMode}, και ο ίδιος ο φάκελος ανήκει στον {dirOwner}. Σε αυτό δεν ξεχωρίζει τίποτα.`,"settings.owner.v.ownerMismatch":`Τα αρχεία φτάνουν εδώ ως {fileOwner}, ο φάκελος όμως ανήκει στον {dirOwner}. Η ανάγνωση συνήθως λειτουργεί ακόμη, η μετονομασία, η μετακίνηση και η διαγραφή από άλλον λογαριασμό όχι, και ό,τι περιμένει ότι ο φάκελος κατέχει το περιεχόμενό του θεωρεί αυτά τα αρχεία ξένα.`,"settings.owner.v.groupUnreadable":`Τα αρχεία φτάνουν εδώ με {fileMode}, οπότε μπορεί να τα ανοίξει μόνο ο {fileOwner}. Ό,τι τρέχει με άλλον λογαριασμό βλέπει τα ονόματα και τίποτα άλλο.`,"settings.owner.v.dirUnreadable":`Οι νέοι υποφάκελοι φτάνουν εδώ με {subdirMode}. Εκεί μέσα δεν μπαίνει κανείς εκτός από τον {fileOwner}, ό,τι κι αν επιτρέπουν τα αρχεία μέσα τους, και κάθε λήψη καταλήγει σε έναν τέτοιο φάκελο.`,"settings.owner.v.notWritable":`Αυτό το στιγμιότυπο δεν μπορεί να γράψει εδώ καθόλου: {detail}`,"settings.owner.v.missing":`Ο φάκελος δεν υπάρχει. Θα δημιουργηθεί την πρώτη φορά που θα γραφτεί κάτι μέσα του.`,"settings.owner.v.unknown":`Σε αυτό το σύστημα τα αρχεία δεν έχουν κατόχους, εδώ δεν υπάρχει λοιπόν τίποτα να συγκριθεί. Αυτό δεν είναι σφάλμα.`,"settings.owner.fix.user":`Ξεκίνα το κοντέινερ με τον λογαριασμό στον οποίο ανήκει ο φάκελος: --user {dirUid}:{dirGid} στην εντολή εκκίνησης. Στο Unraid αυτό πάει στα Extra Parameters.`,"settings.owner.fix.chown":`Ή δώσε αντ’ αυτού τον φάκελο, πάνω στον host: chown -R {uid}:{gid} {dir}`,"settings.owner.fix.mask":`Σε αυτό δεν μπορεί να αλλάξει τίποτα αυτό το στιγμιότυπο. Η μάσκα έρχεται από ό,τι ξεκίνησε το κοντέινερ, και ένας προσαρτημένος κοινόχρηστος φάκελος μπορεί να επιβάλει τη δική του με μια επιλογή umask, file_mode ή dir_mode. Διόρθωσέ το εκεί όπου είναι προσαρτημένος ο φάκελος.`,"settings.owner.fix.recreate":`Μια αλλαγμένη εντολή εκκίνησης χρειάζεται κοντέινερ που δημιουργείται ξανά. Η επανεκκίνηση δεν αρκεί: η ταυτότητα ορίζεται τη στιγμή που ξεκινά.`,"settings.owner.fix.past":`Τα ήδη κατεβασμένα αρχεία κρατούν τον κάτοχο με τον οποίο γράφτηκαν. Ό,τι αλλάζεις ισχύει για ό,τι έρχεται μετά, για τα υπόλοιπα χρειάζεσαι την παραπάνω εντολή.`,"settings.selftest.title":`Αυτοέλεγχος`,"settings.selftest.hint":`Όλα όσα μπορεί να μάθει αυτό το στιγμιότυπο για τον εαυτό του: το backend του JDownloader, το yt-dlp, τους φακέλους σου, τις συνδέσεις σου σε debrid, τον αναμεταδότη και το ρολόι. Όλα τρέχουν σε αυτό το μηχάνημα. Το μόνο που φεύγει από αυτό είναι οι συνδέσεις debrid, που πηγαίνουν στους παρόχους που έχεις ρυθμίσει.`,"settings.selftest.run":`Εκκίνηση αυτοελέγχου`,"settings.selftest.running":`Γίνεται έλεγχος…`,"settings.selftest.pending":`Περιμένει`,"settings.selftest.never":`Δεν έχει τρέξει ακόμη.`,"settings.selftest.lastRun":`Τελευταία εκτέλεση {when}.`,"settings.selftest.startFailed":`Ο αυτοέλεγχος δεν μπόρεσε να ξεκινήσει: {error}`,"settings.selftest.status.pass":`Εντάξει`,"settings.selftest.status.warn":`Δες το`,"settings.selftest.status.fail":`Χαλασμένο`,"settings.selftest.status.skipped":`Δεν έχει στηθεί`,"settings.selftest.status.unknown":`Δεν διαπιστώνεται`,"settings.selftest.jd":`Υποδομή JDownloader`,"settings.selftest.jd.ok":`Προσβάσιμο, αναθεώρηση {version}.`,"settings.selftest.jd.provisioningOff":`Η αυτόματη εγκατάσταση του backend είναι απενεργοποιημένη και δεν έχει οριστεί διεύθυνση, οπότε δεν υπάρχει backend για σύνδεση.`,"settings.selftest.jd.missing":`Δεν υπάρχει διεύθυνση backend. Τα κρυπτογραφημένα DLC και οι σύνδεσμοι container απορρίπτονται.`,"settings.selftest.jd.missingAdvice":`Αυτό το build ξεκινά κανονικά κατά την εκκίνηση το δικό του JDownloader χωρίς περιβάλλον εργασίας και συμπληρώνει μόνο του το KL_JD. Το ότι είναι άδειο σημαίνει: αυτή η εκκίνηση πήγε στραβά. Ψάξε στην καταγραφή πιο κάτω για "JD provisioning failed", ή όρισε το KL_JD σε ένα δικό σου JDownloader.`,"settings.selftest.jd.unreachable":`Το {address} δεν απάντησε.`,"settings.selftest.jd.unreachableAdvice":`Η διεύθυνση είναι αποθηκευμένη, αλλά δεν ακούει τίποτα σε αυτήν. Έλεγξε ότι το backend τρέχει και ότι η θύρα του 3128 είναι προσβάσιμη μέσα από αυτό το container, όχι μόνο από τον host.`,"settings.selftest.jd.noVersion":`Απαντά, αλλά δεν λέει ποια αναθεώρηση είναι.`,"settings.selftest.ytdlp":`yt-dlp`,"settings.selftest.ytdlp.ok":`{version}, ηλικίας {days} ημερών.`,"settings.selftest.ytdlp.aging":`Το {version} είναι {days} ημερών.`,"settings.selftest.ytdlp.old":`Το {version} είναι {days} ημερών. Οι μεγάλες σελίδες βίντεο συνήθως το χαλούν μέσα σε λίγες εβδομάδες.`,"settings.selftest.ytdlp.oldAdvice":`Στο κοντέινερ το yt-dlp έρχεται από το πακέτο Alpine που ήταν τρέχον όταν χτίστηκε το image, και δεν ενημερώνεται ποτέ μόνο του. Πάρε νεότερο image, ή προσάρτησε ένα δικό σου yt-dlp μέσα στο κοντέινερ και δείξε με το KL_YTDLP σε αυτό.`,"settings.selftest.ytdlp.missing":`Δεν βρέθηκε, γι’ αυτό οι σελίδες πολυμέσων αποτυγχάνουν με το σφάλμα του ίδιου του hoster.`,"settings.selftest.ytdlp.missingAdvice":`Δείξε με το KL_YTDLP στο εκτελέσιμο, ή βάλε το yt-dlp στο PATH. Η αναζήτηση γίνεται μία μόνο φορά κατά την εκκίνηση, οπότε ένα που εγκαθιστάς τώρα χρησιμοποιείται μόνο μετά από επανεκκίνηση.`,"settings.selftest.ytdlp.undated":`Το {version} δεν μοιάζει με ημερομηνία, οπότε η ηλικία του δεν κρίνεται.`,"settings.selftest.folders":`Φάκελος λήψεων και φάκελος εργασίας`,"settings.selftest.folders.allOk":`Κάθε φάκελος που ελέγχθηκε υπάρχει και δέχεται εγγραφή.`,"settings.selftest.folders.someBad":`Σε τουλάχιστον έναν φάκελο υπάρχει κάτι να δεις.`,"settings.selftest.folders.none":`Δεν μπόρεσε να μετρηθεί κανένας φάκελος καθόλου.`,"settings.selftest.folders.ok":`Στο {dir} γίνεται εγγραφή, {free} ελεύθερα.`,"settings.selftest.folders.notWritable":`Στο {dir} δεν γίνεται εγγραφή.`,"settings.selftest.folders.notWritableAdvice":`Αυτή η διεργασία τρέχει ως uid {uid}. Δες σε ποιον ανήκει αυτός ο φάκελος πάνω στον host και αν αυτό το uid επιτρέπεται να γράψει μέσα του.`,"settings.selftest.folders.missing":`Το {dir} δεν υπάρχει ακόμη, γι’ αυτό οι αριθμοί περιγράφουν το {measured}.`,"settings.selftest.folders.missingAdvice":`Αυτό είναι φυσιολογικό για έναν φάκελο στον οποίο δεν έχει γραφτεί ακόμη τίποτα, και η πρώτη λήψη τον δημιουργεί. Αν όμως το {measured} είναι η ρίζα του τόμου, λείπει η προσάρτηση που περίμενες, και η λήψη καταλήγει μέσα στο κοντέινερ αντί για τον δίσκο σου.`,"settings.selftest.folders.low":`Μόνο {free} απομένουν στο {dir}, κάτω από τα {mark} στα οποία σταματά η ουρά.`,"settings.selftest.folders.noMark":`{free} ελεύθερα στο {dir}. Δεν έχεις ορίσει σταθερό όριο, οπότε η ουρά κρατά πίσω μόνο μια λήψη που έτσι κι αλλιώς δεν χωράει.`,"settings.selftest.folders.unknown":`Σε αυτή την πλατφόρμα δεν μπορεί να ζητηθεί πόσος χώρος υπάρχει στο {dir}.`,"settings.selftest.accounts":`Συνδέσεις debrid`,"settings.selftest.accounts.none":`Δεν έχει στηθεί κανένας λογαριασμός debrid, δεν υπήρχε λοιπόν τίποτα να ελεγχθεί.`,"settings.selftest.accounts.allOk":`Και οι {n} συνδέσεις έγιναν δεκτές.`,"settings.selftest.accounts.someFailed":`{bad} από {n} συνδέσεις απορρίφθηκαν.`,"settings.selftest.accounts.rowOk":`{label}: έγινε δεκτή, {hosts} hoster.`,"settings.selftest.accounts.rowFailed":`{label}: απορρίφθηκε.`,"settings.selftest.accounts.rowGone":`{label}: Το κλειδί αφαιρέθηκε ενώ έτρεχε ο έλεγχος.`,"settings.selftest.accounts.rowUnknownService":`{label}: Αυτό το build δεν γνωρίζει αυτή την υπηρεσία.`,"settings.selftest.accounts.advice.invalid":`Ο πάροχος λέει ότι αυτό το κλειδί είναι λάθος ή έχει ανακληθεί. Βοηθά μόνο ένα νέο κλειδί.`,"settings.selftest.accounts.advice.expired":`Το κλειδί είναι εντάξει, η συνδρομή όχι. Ανανέωσέ την στον πάροχο.`,"settings.selftest.accounts.advice.temp":`Μπορεί να είναι ένα όριο, μια βλάβη στον πάροχο ή η δική σου γραμμή. Δοκιμάζεται από μόνο του άλλη μία φορά.`,"settings.selftest.accounts.advice.error":`Ο πάροχος αναφέρει κάτι που δεν το λύνει ούτε νέο κλειδί ούτε αναμονή, για παράδειγμα έναν αποκλεισμό της διεύθυνσής σου.`,"settings.selftest.accounts.readOnlyHint":`Αυτός ο έλεγχος δεν αλλάζει τίποτα στη δρομολόγηση. Μια σύνδεση που αποτυγχάνει εδώ αναφέρεται και δεν τίθεται στην άκρη: ένας αυτοέλεγχος με πεσμένη γραμμή δεν επιτρέπεται να ακινητοποιήσει κάθε λογαριασμό για το επόμενο τέταρτο της ώρας.`,"settings.selftest.relay":`Αναμεταδότης`,"settings.selftest.relay.off":`Έχεις σβήσει τον αναμεταδότη, δεν κλήθηκε λοιπόν τίποτα.`,"settings.selftest.relay.notSetUp":`Η απομακρυσμένη πρόσβαση δεν στήθηκε ποτέ εδώ, δεν καλείται λοιπόν κανένας αναμεταδότης.`,"settings.selftest.relay.ownNoAddress":`Είναι επιλεγμένος δικός σου αναμεταδότης και δεν υπάρχει ορισμένη διεύθυνση, δεν καλείται λοιπόν τίποτα.`,"settings.selftest.relay.badSecret":`Το αποθηκευμένο μυστικό σύνδεσης δεν διαβάζεται. Δώσε ξανά τη φράση σύνδεσης.`,"settings.selftest.relay.connected":`Συνδέθηκε με {address}.`,"settings.selftest.relay.notConnected":`Το {address} είναι αποθηκευμένο και η σύνδεση δεν στέκει.`,"settings.selftest.relay.notConnectedAdvice":`Είτε ο αναμεταδότης δεν είναι αυτή τη στιγμή προσβάσιμος, είτε απέρριψε το κλειδί. Ξαναπροσπαθεί από μόνος του. Αν δεν ανέβει καθόλου, έλεγξε τη διεύθυνση και δώσε ξανά τη φράση σύνδεσης.`,"settings.selftest.clock":`Ρολόι και ζώνη ώρας`,"settings.selftest.clock.ok":`Αυτό το μηχάνημα λέει {time}, ζώνη {zone}.`,"settings.selftest.clock.skew":`Αυτό το μηχάνημα και ο περιηγητής σου απέχουν {skew}.`,"settings.selftest.clock.skewAdvice":`Ένα από τα δύο πάει λάθος, και αυτή η εφαρμογή δεν μπορεί να πει ποιο. Ένα ρολόι τόσο εκτός κάνει τα πιστοποιητικά TLS να φαίνονται άκυρα και οδηγεί στην απόρριψη των διακριτικών debrid. Έλεγξε πρώτα το ρολόι του host, το κοντέινερ παίρνει την ώρα του από εκεί.`,"settings.selftest.clock.utc":`Η ζώνη ώρας είναι UTC, και έχεις στημένο χρονοδιάγραμμα.`,"settings.selftest.clock.utcAdvice":`Το χρονοδιάγραμμα τρέχει με την τοπική ώρα αυτού του μηχανήματος, και χωρίς ορισμένο TZ αυτή είναι η UTC. Ένα παράθυρο που έβαλες στις 22:00 ξεκινά τότε στις 22:00 UTC, δηλαδή στο Βερολίνο τον χειμώνα στις 23:00 και το καλοκαίρι τα μεσάνυχτα. Ξεκίνα το κοντέινερ με TZ, για παράδειγμα TZ=Europe/Berlin, και κάνε του επανεκκίνηση.`,"settings.selftest.clock.noZoneDB":`Το TZ ονομάζει {zone}, και η βάση ζωνών ώρας δεν διαβάστηκε, γι’ αυτό κάθε ώρα σε αυτή τη διεργασία πέφτει πίσω στην UTC.`,"settings.selftest.torrentPort":`Θύρα torrent`,"settings.selftest.torrentPort.noPort":`Η μηχανή torrent διαλέγει μόνη της τη θύρα της, και αυτό το build δεν μπορεί να διαβάσει ποια πήρε.`,"settings.selftest.torrentPort.noPortAdvice":`Όρισε σταθερή θύρα στη σελίδα Torrents. Χωρίς αυτήν δεν υπάρχει τίποτα να προωθηθεί και τίποτα να ελεγχθεί, και οι ομότιμοι πίσω από άλλον δρομολογητή σε φτάνουν μόνο όταν συνδεθούν πρώτοι.`,"settings.selftest.torrentPort.notChecked":`Η θύρα {port} είναι ορισμένη. Δεν ρωτήθηκε τίποτα έξω από αυτό το δίκτυο, γι’ αυτό δεν είναι γνωστό αν είναι ανοιχτή από έξω.`,"settings.selftest.torrentPort.notCheckedAdvice":`Αυτό μπορεί να το απαντήσει μόνο ένα μηχάνημα έξω από το δίκτυό σου, και αυτή η εφαρμογή δεν επικοινωνεί με κανένα που δεν διάλεξες εσύ. Το κουμπί UPnP στη σελίδα Torrents ζητά από τον δρομολογητή σου να προωθήσει τη θύρα και σου λέει αν μπόρεσε να το επιβεβαιώσει. Μια θύρα που αποθηκεύεται μετά το πρώτο torrent αυτής της εκτέλεσης ισχύει μόνο μετά από επανεκκίνηση.`,"settings.selftest.proxy.title":`Αντίστροφος διαμεσολαβητής`,"settings.selftest.proxy.hint":`Τι λένε ο περιηγητής σου και αυτό το στιγμιότυπο για ακριβώς το ίδιο αίτημα. Αυτά τα τέσσερα είναι που πάνε στραβά πίσω από Nginx Proxy Manager και Traefik, και τα τρία από τα τέσσερα αποτυγχάνουν εντελώς χωρίς μήνυμα σφάλματος.`,"settings.selftest.proxy.desktopSkip":`Η έκδοση επιφάνειας εργασίας σερβίρει μόνη της τη διεπαφή της και δεν έχει διαμεσολαβητή μπροστά της, δεν υπάρχει λοιπόν εδώ τίποτα να συγκριθεί.`,"settings.selftest.proxy.host":`Κεφαλίδα Host`,"settings.selftest.proxy.host.ok":`Ο περιηγητής σου και αυτό το στιγμιότυπο συμφωνούν ότι ο host είναι {host}.`,"settings.selftest.proxy.host.rewritten":`Ο περιηγητής σου ζήτησε {browser}, σε αυτό το στιγμιότυπο ειπώθηκε {server}.`,"settings.selftest.proxy.host.rewrittenAdvice":`Ο διαμεσολαβητής σου αντικαθιστά την κεφαλίδα Host. Αυτό το στιγμιότυπο συγκρίνει το Origin του περιηγητή σου με το Host, γι’ αυτό κάθε εγγραφή απορρίπτεται με 403 και η ζωντανή προβολή δεν ανοίγει ποτέ, ενώ η ίδια η σελίδα φορτώνει κανονικά και φαίνεται μια χαρά. Στο Traefik άσε το passHostHeader αναμμένο. Στο nginx βάλε proxy_set_header Host $host.`,"settings.selftest.proxy.proto":`Προωθημένο πρωτόκολλο`,"settings.selftest.proxy.proto.ok":`Ο διαμεσολαβητής λέει https, και ακριβώς σε αυτό βρίσκεται ο περιηγητής σου.`,"settings.selftest.proxy.proto.direct":`Έφτασες σε αυτό το στιγμιότυπο απευθείας, δεν υπάρχει λοιπόν διαμεσολαβητής που θα έπρεπε να ανακοινώσει κάτι.`,"settings.selftest.proxy.proto.missing":`Ο περιηγητής σου είναι σε https, και ο διαμεσολαβητής δεν το πέρασε παρακάτω.`,"settings.selftest.proxy.proto.missingAdvice":`Χωρίς X-Forwarded-Proto αυτό το στιγμιότυπο πιστεύει ότι το έφτασες μέσω απλού http. Ο κωδικός QR και οι διευθύνσεις σύζευξης στη σελίδα Απομακρυσμένη πρόσβαση προσφέρουν τότε συνδέσμους http://, και ένα container που δίνεται στον JDownloader ανακτάται μέσω http. Στο nginx βάλε proxy_set_header X-Forwarded-Proto $scheme. Το Traefik και το Caddy το ορίζουν μόνα τους.`,"settings.selftest.proxy.prefix":`Πρόθεμα διαδρομής`,"settings.selftest.proxy.prefix.underPath":`Αυτό το στιγμιότυπο σερβίρεται κάτω από {path}.`,"settings.selftest.proxy.ws":`Αναβάθμιση WebSocket`,"settings.selftest.proxy.ws.ok":`Η ζωντανή σύνδεση άνοιξε.`,"settings.selftest.proxy.ws.failed":`Η ζωντανή σύνδεση δεν άνοιξε.`,"settings.selftest.proxy.ws.failedAdvice":`Αυτό είναι το πιο συχνό σφάλμα πίσω από διαμεσολαβητή, και τίποτα άλλο δεν σου το δείχνει: η εφαρμογή ξανασυνδέεται σιωπηλά ξανά και ξανά, η λίστα απλώς δεν κουνιέται πια, και μόνο μια επαναφόρτωση της σελίδας δείχνει κάτι νέο. Στο nginx η location χρειάζεται proxy_http_version 1.1, proxy_set_header Upgrade $http_upgrade και proxy_set_header Connection "upgrade". Ο Nginx Proxy Manager έχει στον host έναν διακόπτη Websockets Support. Το Traefik και το Caddy δεν χρειάζονται τίποτα.`,"settings.diagnostics.startupTitle":`Αναφορά εκκίνησης`,"settings.diagnostics.startupHint":`Τι έλεγξε αυτό το στιγμιότυπο μία φορά κατά την εκκίνηση: τα προγράμματα που καλεί, κάθε φάκελο όπου μπορεί να καταλήξει μια λήψη και το ρολόι με το οποίο διαβάζεται ένα χρονοπρόγραμμα. Είναι μια μέτρηση, οπότε τίποτα εδώ δεν κρατά πίσω μια λήψη ούτε εμποδίζει τον διακομιστή να ξεκινήσει. Στην εκκίνηση γίνεται μόνο έλεγχος· η δοκιμή εγγραφής γίνεται όταν πατάς «Έλεγχος ξανά».`,"settings.diagnostics.startupTakenAt":`Ελέγχθηκε στις {when}, λίγο μετά την εκκίνηση αυτού του στιγμιότυπου.`,"settings.diagnostics.startupJustChecked":`Μόλις τώρα ελέγχθηκε. Το πακέτο που κατεβάζεις κουβαλά ακόμη τη μέτρηση της εκκίνησης, γιατί αυτή είναι που χρειάζεται μια αναφορά σφάλματος.`,"settings.diagnostics.startupRunning":`Ο έλεγχος τρέχει ακόμη. Ένας φάκελος σε κοινόχρηστο χώρο που έχει πάψει να απαντά κρατά όσο κρατά και ο ίδιος ο κοινόχρηστος χώρος για να τα παρατήσει.`,"settings.diagnostics.startupOff":`Ο έλεγχος είναι απενεργοποιημένος για αυτό το στιγμιότυπο (KL_STARTUP_CHECK=0). Δεν κοιτάχτηκε τίποτα, και αυτό δεν είναι το ίδιο με το «όλα εντάξει».`,"settings.diagnostics.startupNotRun":`Αυτό το build δεν έτρεξε ποτέ τον έλεγχο. Τρέχει στον διακομιστή και στην εφαρμογή επιφάνειας εργασίας.`,"settings.diagnostics.startupStatOnly":`Στην εκκίνηση έγινε μόνο ανάγνωση: σε κανέναν φάκελο δεν γράφτηκε κάτι. Ένας φάκελος με «Εντάξει» υπάρχει λοιπόν, αλλά δεν έχει γραφτεί μέσα του.`,"settings.diagnostics.startupNothingWrong":`Εδώ δεν υπάρχει τίποτα να γίνει.`,"settings.diagnostics.startupRecheck":`Έλεγχος ξανά`,"settings.diagnostics.startupRechecking":`Γίνεται έλεγχος…`,"settings.diagnostics.startupRecheckHint":`Τρέχει τους ίδιους ελέγχους τώρα και γράφει αυτή τη φορά ένα μικρό δοκιμαστικό αρχείο σε κάθε φάκελο που υπάρχει, το οποίο διαγράφεται ξανά μετά. Στην εκκίνηση αυτό δεν γίνεται, γιατί μια εγγραφή σε φάκελο πάνω στο array ξυπνά τον δίσκο στον οποίο βρίσκεται, και αυτό σε κάθε επανεκκίνηση. Το πακέτο που κατεβάζεις κρατά τη μέτρηση της εκκίνησης, γιατί αυτή είναι που χρειάζεται μια αναφορά σφάλματος.`,"settings.diagnostics.startupRecheckFailed":`Ο νέος έλεγχος απέτυχε: {error}`,"settings.diagnostics.startupNearest":`πλησιέστερος υπάρχων φάκελος: {measured}`,"settings.diagnostics.verdict.ok":`Εντάξει`,"settings.diagnostics.verdict.warn":`Δες το`,"settings.diagnostics.verdict.fail":`Μη χρησιμοποιήσιμο`,"settings.diagnostics.verdict.skipped":`Εδώ δεν χρειάζεται`,"settings.diagnostics.check.data":`Κατάλογος δεδομένων`,"settings.diagnostics.check.java":`Java`,"settings.diagnostics.check.ytdlp":`yt-dlp`,"settings.diagnostics.check.ffmpeg":`ffmpeg`,"settings.diagnostics.check.ffprobe":`ffprobe`,"settings.diagnostics.check.clock":`Ζώνη ώρας και τοπική ώρα`,"settings.diagnostics.role.downloads":`Φάκελος λήψεων`,"settings.diagnostics.role.work":`Φάκελος εργασίας`,"settings.diagnostics.role.category":`Φάκελος κατηγορίας`,"settings.diagnostics.role.extract":`Φάκελος αποσυμπίεσης`,"settings.diagnostics.role.extractMove":`Φάκελος προορισμού μετά την αποσυμπίεση`,"settings.diagnostics.role.watch":`Παρακολουθούμενος φάκελος`,"settings.diagnostics.fix.missing":`Ο φάκελος δεν υπάρχει. Ο πλησιέστερος από πάνω του που υπάρχει είναι ο {measured}. Σε ένα μηχάνημα που προσαρτά κοινόχρηστο φάκελο, αυτό συνήθως σημαίνει ότι ο κοινόχρηστος φάκελος δεν είναι προσαρτημένος, και γι' αυτό αυτός ο έλεγχος δεν δημιουργεί τον φάκελο: ένας φάκελος που φτιάχνεται κάτω από μια προσάρτηση που λείπει παίρνει τις λήψεις στη θέση της, και αυτές χάνονται με την επόμενη ενημέρωση του container.`,"settings.diagnostics.fix.denied":`Ο φάκελος υπάρχει, αλλά αυτό το στιγμιότυπο δεν επιτρέπεται να γράψει μέσα του. Στο κοντέινερ το KnightLoader τρέχει ως uid 1000, ο φάκελος πρέπει λοιπόν να ανήκει σε αυτόν τον χρήστη ή σε ομάδα στην οποία ανήκει εκείνος.`,"settings.diagnostics.fix.readonly":`Το σύστημα αρχείων κάτω από αυτόν τον φάκελο είναι προσαρτημένο μόνο για ανάγνωση. Αυτό δεν το αλλάζει αυτό το στιγμιότυπο, πρέπει να αλλάξει η προσάρτηση.`,"settings.diagnostics.fix.full":`Στον τόμο στον οποίο βρίσκεται αυτός ο φάκελος δεν υπάρχει άλλος χώρος.`,"settings.diagnostics.fix.notRemoved":`Το δοκιμαστικό αρχείο γράφτηκε, αλλά δεν διαγράφηκε ξανά. Μια λήψη θα έφτανε εδώ και δεν θα μπορούσε ποτέ μετά να μετονομαστεί ή να παραμεριστεί. Δες το δικαίωμα διαγραφής του φακέλου, όχι το δικαίωμα εγγραφής.`,"settings.diagnostics.fix.notADir":`Σε αυτή τη διαδρομή βρίσκεται αρχείο, όχι φάκελος.`,"settings.diagnostics.fix.timeout":`Ο φάκελος δεν απάντησε εγκαίρως και αφέθηκε ήσυχος. Ένας κοινόχρηστος χώρος του οποίου ο διακομιστής είναι σβηστός συμπεριφέρεται ακριβώς έτσι, και ένας σε δίκτυο που έχει χαθεί επίσης.`,"settings.diagnostics.fix.dataDenied":`Αυτός είναι ο ένας φάκελος χωρίς τον οποίο δεν τα βγάζει πέρα το στιγμιότυπο: η βάση δεδομένων, οι ρυθμίσεις και ο κρυπτογραφημένος χώρος λογαριασμών βρίσκονται εδώ. Οι λήψεις προς το παρόν συνεχίζονται, και η επόμενη αποθήκευση χάνεται.`,"settings.diagnostics.fix.javaMissing":`Δεν βρέθηκε Java. Η εικόνα του container περιέχει μία, αλλά η εφαρμογή επιφάνειας εργασίας όχι, οπότε σε έναν υπολογιστή η Java πρέπει να είναι εγκατεστημένη, στο PATH ή στο JAVA_HOME. Χωρίς αυτήν το ιδιωτικό JDownloader δεν ξεκινά και ένας κρυπτογραφημένος σύνδεσμος container (.dlc, .ccf, .rsdf) δεν ανοίγει καθόλου. Εγκαταστήστε Java ή στρέψτε το KL_JD σε ένα JDownloader που τρέχει αλλού.`,"settings.diagnostics.fix.javaNotNeeded":`Αυτό το στιγμιότυπο δεν ξεκινά δική του διεργασία Java: είτε το KL_JD δείχνει σε ένα JDownloader που τρέχει αλλού, είτε το ιδιωτικό είναι σβηστό με KL_PROVISION_JD=0.`,"settings.diagnostics.fix.ytdlpMissing":`Το yt-dlp δεν βρέθηκε (KL_YTDLP, ή «yt-dlp» στο PATH). Οι σελίδες πολυμέσων αποτυγχάνουν τότε με το σφάλμα της ίδιας της σελίδας, αντί να κατεβαίνουν.`,"settings.diagnostics.fix.ffmpegMissing":`Το ffmpeg δεν βρέθηκε. Το yt-dlp το χρειάζεται για να ενώσει τις χωριστές ροές εικόνας και ήχου που παραδίδουν οι περισσότερες σελίδες. Μια λήψη μένει τότε στη μία από τις δύο ή γυρίζει χωρίς ήχο.`,"settings.diagnostics.fix.ffprobeMissing":`Το ffprobe δεν βρέθηκε. Το χρησιμοποιεί μόνο ο έλεγχος διάρκειας ενός ολοκληρωμένου βίντεο, όλα τα άλλα τρέχουν χωρίς αυτό.`,"settings.diagnostics.fix.notRunnable":`Βρέθηκε στο {subject}, αλλά δεν έτρεξε: {error}`,"settings.diagnostics.fix.appearedLate":`Τρέχει τώρα, αλλά δεν υπήρχε όταν ξεκίνησε αυτό το στιγμιότυπο, οπότε δεν του ανατίθεται ακόμη τίποτα. Κάνε επανεκκίνηση για να το παραλάβει.`,"settings.diagnostics.fix.utcFallback":`Το TZ είναι στο {subject}, αυτό το στιγμιότυπο όμως δεν μπόρεσε να φορτώσει εκείνη τη ζώνη και έπεσε σιωπηλά πίσω στην UTC. Μέχρι να διορθωθεί αυτό, κάθε παράθυρο χρονοδιαγράμματος τρέχει σε UTC. Έλεγξε τη γραφή απέναντι στη λίστα ζωνών («Europe/Berlin») και αν το image έχει καθόλου βάση ζωνών.`,"settings.diagnostics.fix.noZoneDatabase":`Σε αυτό το σύστημα δεν υπάρχει βάση ζωνών, οι ώρες διαβάζονται λοιπόν εντελώς χωρίς αλλαγές θερινής ώρας. Ένα νυχτερινό παράθυρο κρατά τη χειμερινή του ώρα όλο το καλοκαίρι, και κανείς δεν ειδοποιεί όταν φτάσει η στιγμή.`,"settings.diagnostics.fix.tzUnset":`Το TZ δεν έχει οριστεί και δεν βρέθηκε τοπική ώρα, οπότε αυτό το στιγμιότυπο τρέχει σε UTC. Λειτουργεί, αλλά ένα παράθυρο χρονοπρογράμματος γραμμένο ως 23:00 σημαίνει τότε 23:00 UTC, όχι 23:00 εκεί που βρίσκεσαι.`,"settings.resolvers.toolsTitle":`Εργαλεία`,"settings.resolvers.toolsHint":`Το yt-dlp διαβάζει τη σελίδα πολυμέσων, το ffmpeg ενώνει τις ροές που βγαίνουν από εκεί. Και τα δύο είναι ξεχωριστά προγράμματα που ξεκινά το KnightLoader, κανένα τους δεν βρίσκεται μέσα σε αυτό το build. Γι’ αυτό αξίζει να ξέρεις τις εκδόσεις τους: ένα ξεπερασμένο yt-dlp είναι ο πιο συχνός λόγος που ένας σύνδεσμος πολυμέσων, ο οποίος τον περασμένο μήνα δούλευε ακόμη, ξαφνικά δεν δουλεύει πια.`,"settings.resolvers.toolsInUse":`Σε χρήση`,"settings.resolvers.toolsNotFound":`Δεν βρέθηκε`,"settings.resolvers.toolsFrom.managed":`Δικό του αντίγραφο του KnightLoader`,"settings.resolvers.toolsFrom.env":`KL_YTDLP`,"settings.resolvers.toolsFrom.path":`Βρέθηκε στο PATH`,"settings.resolvers.toolsFrom.none":`Πουθενά`,"settings.resolvers.toolsYtdlpMissingHint":`Χωρίς yt-dlp δεν υπάρχει καθόλου backend πολυμέσων: ένας σύνδεσμος προς σελίδα βίντεο απορρίπτεται με το σφάλμα της ίδιας της σελίδας αντί να κατέβει. Στο κοντέινερ έρχεται από το πακέτο yt-dlp του image, στην επιφάνεια εργασίας το εγκαθιστάς μόνος σου και το βάζεις είτε στο PATH είτε δείχνεις σε αυτό με το KL_YTDLP. Το κουμπί από κάτω φέρνει ένα δικό του αντίγραφο, αν δεν γίνεται τίποτα από τα δύο.`,"settings.resolvers.toolsFfmpegMissingHint":`Χωρίς ffmpeg το yt-dlp δεν μπορεί να ενώσει τις χωριστές ροές εικόνας και ήχου που παραδίδουν οι περισσότερες σελίδες: η λήψη καταλήγει τότε στον δίσκο ως βουβή ροή βίντεο ή αποτυγχάνει εντελώς. Χωρίς ffprobe, η «Μέτρηση του ολοκληρωμένου αρχείου» πιο πάνω σε αυτή τη σελίδα δεν μετρά τίποτα και δεν λέει τίποτα γι’ αυτό. Στο κοντέινερ και τα δύο έρχονται από το πακέτο ffmpeg που βρίσκεται μέσα στο image, στην επιφάνεια εργασίας τα εγκαθιστάς μόνος σου και τα βάζεις στο PATH.`,"settings.resolvers.toolsShadowed":`Τρέχει το δικό του αντίγραφο του KnightLoader. Όσο αυτό βρίσκεται εκεί, το KL_YTDLP και το PATH δεν ξεκινούν: στη θέση του θα έμπαινε το {path}, και αυτό αναφέρει {version}.`,"settings.resolvers.toolsShadowedOlder":`Προσοχή: το αντίγραφο που ανέκτησε το KnightLoader ({current}) είναι παλαιότερο από εκείνο που υπάρχει ούτως ή άλλως σε αυτό το μηχάνημα ({system}, στο {path}). Μια ενημέρωση του κοντέινερ φέρνει μαζί της νεότερο yt-dlp, το δικό σου αντίγραφο δεν ακολουθεί. Ανάκτησε ένα καινούριο, ή γύρνα πίσω στο αντίγραφο του συστήματος.`,"settings.resolvers.toolsManagedBroken":`Στο {path} είναι καταχωρημένο ένα αντίγραφο που ανακτήθηκε, και αυτό δεν ξεκινά. Αντ’ αυτού τρέχει η εφεδρική επιλογή που φαίνεται από πάνω. Ανάκτησέ το ξανά, ή γύρνα πίσω στο αντίγραφο του συστήματος.`,"settings.resolvers.toolsActions":`Διατήρηση του yt-dlp ενημερωμένου`,"settings.resolvers.toolsActionsHint":`Η ανάκτηση κατεβάζει το yt-dlp από το github.com, το ελέγχει απέναντι στο αρχείο SHA2-256SUMS της ίδιας έκδοσης, το ξεκινά μία φορά για να δει αν τρέχει καθόλου σε αυτό το μηχάνημα, και μόνο τότε το βάζει δίπλα στα δεδομένα σου, από όπου το ξεκινά το KnightLoader. Μέχρι εκείνο το τελευταίο βήμα συνεχίζει να τρέχει το αντίγραφο που είχες ήδη, και το yt-dlp του συστήματός σου δεν αγγίζεται ποτέ.`,"settings.resolvers.toolsCheck":`Ερώτηση στο GitHub`,"settings.resolvers.toolsChecking":`Γίνεται ερώτηση στο GitHub…`,"settings.resolvers.toolsFetch":`Ανάκτηση αυτής της έκδοσης`,"settings.resolvers.toolsFetching":`Γίνεται ανάκτηση και έλεγχος…`,"settings.resolvers.toolsRevert":`Επιστροφή στο αντίγραφο του συστήματος`,"settings.resolvers.toolsReverting":`Γίνεται αφαίρεση…`,"settings.resolvers.toolsSame":`Το {version} είναι εγκατεστημένο, και αυτή είναι η πιο πρόσφατη δημοσιευμένη έκδοση.`,"settings.resolvers.toolsNewer":`Δημοσιευμένο είναι το {latest}, εγκατεστημένο είναι το {current}.`,"settings.resolvers.toolsOlder":`Εγκατεστημένο είναι το {current}, και αυτό είναι νεότερο από την πιο πρόσφατη δημοσιευμένη έκδοση ({latest}). Εδώ δεν υπάρχει τίποτα να γίνει.`,"settings.resolvers.toolsUnknown":`Δημοσιευμένο είναι το {latest}, εγκατεστημένο είναι το {current}. Ποιο από τα δύο είναι νεότερο δεν βγαίνει από τις δύο ενδείξεις έκδοσης, γι’ αυτό εδώ δεν διατυπώνεται κανένας ισχυρισμός.`,"settings.resolvers.toolsCheckFailed":`Δεν μπόρεσε να γίνει ερώτηση στο GitHub: {error}`,"settings.resolvers.toolsFetched":`Το {version} βρίσκεται στη θέση του και τρέχει.`,"settings.resolvers.toolsFetchFailed":`Δεν αντικαταστάθηκε τίποτα. {error}`,"settings.resolvers.toolsReverted":`Το αντίγραφο που είχε ανακτηθεί έφυγε. Τρέχει ξανά το {path}.`,"settings.resolvers.toolsAutoCheck":`Ερώτηση στο GitHub για την έκδοση του yt-dlp κατά το άνοιγμα αυτής της σελίδας`,"settings.resolvers.toolsAutoCheckHint":`Ένα αίτημα στο api.github.com σε κάθε φόρτωση αυτής της σελίδας, τίποτα παραπάνω: δεν κατεβαίνει τίποτα και δεν αντικαθίσταται τίποτα, χωρίς να πατήσεις εσύ το κουμπί. Σβηστό από προεπιλογή, γιατί ένα μηχάνημα που το τρέχεις ο ίδιος δεν πρέπει να τηλεφωνεί από μόνο του προς τα έξω, πριν το επιτρέψεις.`,"settings.diagnostics.toolsMissing":`δεν βρέθηκε`,"settings.eventTargets.problem.redirect":`Η διεύθυνση απαντά με ανακατεύθυνση, και αυτό το στιγμιότυπο δεν την ακολουθεί. Κάθε τιμή κεφαλίδας σε αυτή τη γραμμή θεωρείται μυστικό, και μια ανακατεύθυνση σε άλλον host θα την παρέδιδε σε όποιον έχει εκείνον τον host. Άνοιξε τη διεύθυνση σε έναν περιηγητή, δες πού καταλήγει, και γράψε εδώ εκείνη τη διεύθυνση.`,"auth.twoFactor.title":`Έλεγχος ταυτότητας δύο παραγόντων`,"auth.twoFactor.hint":`Ένας εξαψήφιος κωδικός από εφαρμογή ταυτοποίησης, πέρα από τον κωδικό πρόσβασης. Στέκεται δίπλα στον κωδικό και δεν τον αντικαθιστά ποτέ. Αυτή η εγκατάσταση δεν έχει λογαριασμούς χρηστών, οπότε δεν υπάρχει κανείς άλλος να την ξεκλειδώσει για σένα: κράτα τους κωδικούς ανάκτησης αλλού από το τηλέφωνο που παράγει τους κωδικούς. Αν χαθούν και τα δύο, τρέξε στο μηχάνημα knightloader -reset-2fa, ή σταμάτα το KnightLoader και σβήσε τις εγγραφές totp και recovery από το αρχείο auth.json στον φάκελο δεδομένων. Ο κωδικός πρόσβασης συνεχίζει να δουλεύει και στις δύο περιπτώσεις.`,"auth.twoFactor.on":`Ενεργός`,"auth.twoFactor.off":`Ανενεργός`,"auth.twoFactor.needsPassword":`Βάλε πρώτα κωδικό πρόσβασης. Ο δεύτερος παράγοντας προστατεύει έναν κωδικό, άρα πρέπει να υπάρχει.`,"auth.twoFactor.beforeYouStart":`Η ρύθμιση τελειώνει με οκτώ κωδικούς ανάκτησης, που εμφανίζονται μία φορά και ποτέ ξανά. Έχε κάπου να τους σημειώσεις πριν ξεκινήσεις.`,"auth.twoFactor.enable":`Ρύθμιση`,"auth.twoFactor.scan":`Σάρωσε αυτό με την εφαρμογή ταυτοποίησής σου.`,"auth.twoFactor.qrLabel":`Κωδικός QR που προσθέτει αυτή την εγκατάσταση σε εφαρμογή ταυτοποίησης`,"auth.twoFactor.secretManual":`Ή πληκτρολόγησέ το με το χέρι`,"auth.twoFactor.confirmLabel":`Εξαψήφιος κωδικός από την εφαρμογή`,"auth.twoFactor.confirm":`Ενεργοποίηση`,"auth.twoFactor.codesTitle":`Σημείωσέ τους τώρα`,"auth.twoFactor.codesHint":`Αυτή είναι η μόνη φορά που εμφανίζονται. Ο καθένας ισχύει μία φορά, στη θέση ενός κωδικού από την εφαρμογή, και είναι το μόνο που σε ξαναβάζει μέσα αν χαθεί το τηλέφωνο.`,"auth.twoFactor.codesAck":`Τους σημείωσα`,"auth.twoFactor.recoveryLeft":`Απομένουν {n} κωδικοί ανάκτησης.`,"auth.twoFactor.disable":`Απενεργοποίηση`,"auth.twoFactor.disablePrompt":`Δώσε έναν κωδικό για απενεργοποίηση`,"auth.twoFactor.signInHint":`Δώσε τον κωδικό από την εφαρμογή ταυτοποίησής σου, ή έναν από τους κωδικούς ανάκτησης.`,"auth.twoFactor.verify":`Συνέχεια`,"auth.twoFactor.codeWrong":`Αυτός ο κωδικός δεν έγινε δεκτός.`,"auth.passkey.title":`Κλειδιά πρόσβασης`,"auth.passkey.hint":`Ένα κλειδί που κρατά το τηλέφωνο, ο φορητός σου ή ένα κλειδί ασφαλείας σε συνδέει χωρίς να πληκτρολογήσεις τον κωδικό. Είναι ένας επιπλέον δρόμος μέσα: ο κωδικός εξακολουθεί να ισχύει, και η αφαίρεση όλων των κλειδιών δεν κλειδώνει κανέναν έξω. Ένα κλειδί πρόσβασης ανήκει στη διεύθυνση όπου δημιουργήθηκε, οπότε ένα που καταχωρήθηκε μέσω διαμεσολαβητή δεν δουλεύει στη διεύθυνση του τοπικού δικτύου, ούτε το αντίστροφο.`,"auth.passkey.registered":`{n} καταχωρημένα`,"auth.passkey.none":`Κανένα καταχωρημένο`,"auth.passkey.needsPassword":`Βάλε πρώτα κωδικό πρόσβασης. Το κλειδί πρόσβασης είναι δεύτερος δρόμος προς μια σύνδεση, άρα πρέπει να υπάρχει.`,"auth.passkey.unavailableTitle":`Τα κλειδιά πρόσβασης χρειάζονται όνομα κόμβου, και αυτή η σελίδα είναι ανοιχτή σε διεύθυνση IP.`,"auth.passkey.unavailableReason":`Ένα κλειδί πρόσβασης δένεται σε έναν τομέα, οπότε οι φυλλομετρητές αρνούνται όλη την ανταλλαγή σε γυμνή διεύθυνση, και την αρνούνται ξανά σε πιστοποιητικό που δεν εμπιστεύονται. Φτάσε στο KnightLoader μέσω αντίστροφου διαμεσολαβητή με πραγματικό όνομα και έγκυρο πιστοποιητικό, άνοιξέ το εκεί, και καταχώρησε το κλειδί σε εκείνη τη διεύθυνση.`,"auth.passkey.noBrowserTitle":`Αυτός ο φυλλομετρητής δεν προσφέρει κλειδιά πρόσβασης.`,"auth.passkey.noBrowserReason":`Με αυτή την εγκατάσταση δεν υπάρχει κανένα πρόβλημα. Άνοιξέ την σε σύγχρονο φυλλομετρητή, ή σε συσκευή που μπορεί να κρατήσει κλειδί πρόσβασης, και το κουμπί θα εμφανιστεί εδώ.`,"auth.passkey.add":`Ρύθμιση`,"auth.passkey.create":`Δημιουργία`,"auth.passkey.nameLabel":`Όνομα`,"auth.passkey.nameHint":`Το διαλέγεις εσύ, για να ξεχωρίζεις τα κλειδιά σου αργότερα. Για τον φυλλομετρητή δεν σημαίνει τίποτα.`,"auth.passkey.namePlaceholder":`π.χ. το τηλέφωνό μου`,"auth.passkey.defaultName":`Κλειδί πρόσβασης`,"auth.passkey.usableHere":`Δουλεύει σε αυτή τη διεύθυνση`,"auth.passkey.otherAddress":`Καταχωρημένο για {host}`,"auth.passkey.notSynced":`χωρίς συγχρονισμό σε μπρελόκ κλειδιών`,"auth.passkey.lastUsed":`τελευταία χρήση {when}`,"auth.passkey.rename":`Μετονομασία`,"auth.passkey.saveName":`Αποθήκευση`,"auth.passkey.remove":`Αφαίρεση`,"auth.passkey.removeTitle":`Αφαίρεση αυτού του κλειδιού πρόσβασης;`,"auth.passkey.removeBody":`Το {name} δεν θα σε συνδέει πια. Ο κωδικός πρόσβασης εξακολουθεί να δουλεύει.`,"auth.passkey.added":`Το κλειδί πρόσβασης προστέθηκε.`,"auth.passkey.removed":`Το κλειδί πρόσβασης αφαιρέθηκε.`,"auth.passkey.signIn":`Σύνδεση με κλειδί πρόσβασης`,"auth.passkey.signInFailed":`Αυτό το κλειδί πρόσβασης δεν σε συνέδεσε.`,"auth.passkey.error.expired":`Η ρύθμιση κράτησε πολύ. Ξεκίνα την ξανά.`,"auth.passkey.error.otherAddress":`Αυτή η ρύθμιση ξεκίνησε σε άλλη διεύθυνση. Άνοιξε το KnightLoader στη διεύθυνση όπου πρέπει να δουλεύει το κλειδί και ξεκίνα ξανά εκεί.`,"settings.stall.reconnect":`Άνοιγμα νέων συνδέσεων για κολλημένη λήψη`,"settings.stall.reconnectHint":`Κλείνει τις συνδέσεις μιας σημασμένης λήψης και ανοίγει νέες που ζητούν το υπόλοιπο του αρχείου. Η λήψη κρατά ό,τι έχει ήδη πάρει και τη θέση της, γι’ αυτό είναι ενεργό μέχρι να το απενεργοποιήσετε. Ένας διακομιστής που μπορεί να στείλει το αρχείο μόνο ολόκληρο το στέλνει ξανά από την αρχή. Χωρίς αυτό, μια λήψη της οποίας ο διακομιστής σταματά να απαντά στη μέση του αρχείου μένει στα 0 B/s μέχρι να την παύσει κάποιος. Όσο η λήψη μένει ακίνητη, αυτό επαναλαμβάνεται κάθε φορά που λήγει ο χρόνος που ορίστηκε παραπάνω. Αν είναι ενεργή και η «Επανεκκίνηση κολλημένης λήψης από την αρχή», μια λήψη που μένει ακίνητη τόσο και μετά τις νέες συνδέσεις ξεκινά από την αρχή. Νέες συνδέσεις παίρνουν μόνο οι λήψεις της ενσωματωμένης μηχανής, μαζί με debrid και TorBox. Το JDownloader και το yt-dlp φροντίζουν μόνα τους τις συνδέσεις τους, και σε ένα torrent χωρίς ομότιμους οι νέες συνδέσεις δεν βοηθούν, οπότε αυτές μόνο σημαίνονται.`,"props.backend":`Υπηρεσία`,"props.backendAuto":`Αυτόματα`,"props.backendHint":`Ποια υπηρεσία κατεβάζει αυτούς τους συνδέσμους. Το «Αυτόματα» παίρνει την πρώτη στη σειρά προτεραιότητας της σελίδας Λογαριασμοί που μπορεί να δεχτεί τον σύνδεσμο αυτή τη στιγμή. Ένας καρφιτσωμένος σύνδεσμος πηγαίνει μόνο σε αυτή την υπηρεσία και αποτυγχάνει με την αιτία όταν η υπηρεσία δεν μπορεί να τον δεχτεί. Μια λήψη σε εξέλιξη κρατά την υπηρεσία της. Μια σε παύση αλλάζει όταν τη συνεχίσετε και ξεκινά εκεί από την αρχή.`,"settings.globalSpeedLimit":`Όριο ταχύτητας (0 = ∞)`,"rename.menu":`Μετονομασία…`,"rename.confirm":`Μετονομασία`,"rename.linkTitle":`Μετονομασία συνδέσμου`,"rename.packageTitle":`Μετονομασία πακέτου`,"rename.whenDone":`Αυτή η λήψη είναι ακόμη σε εξέλιξη. Το αρχείο παίρνει το νέο όνομα μόλις τελειώσει.`,"rename.unpacking":`Αυτό το αρχείο αποσυμπιέζεται. Θα μπορεί να μετονομαστεί μόλις τελειώσει η αποσυμπίεση.`,"rename.remote":`Το backend JDownloader κατεβάζει αυτό το αρχείο στο δικό του μηχάνημα και το ονομάζει μόνο του, οπότε δεν μπορεί να μετονομαστεί από εδώ.`,"rename.torrent":`Ένα torrent ονομάζει μόνο του τα αρχεία του, οπότε δεν μπορεί να μετονομαστεί.`,"rename.volume":`Αυτό το αρχείο είναι ένα μέρος ενός αρχειοθέτη πολλών τόμων. Τα μέρη κρατούν τα ονόματά τους, αλλιώς ο αρχειοθέτης δεν θα μπορούσε να αποσυμπιεστεί.`,"rename.separator":`Ένα όνομα δεν μπορεί να περιέχει / ή \\.`,"rename.empty":`Ένα όνομα δεν μπορεί να είναι κενό.`,"rename.dots":`Ένα όνομα χρειάζεται κάτι περισσότερο από τελείες.`,"rename.exists":`Σε αυτόν τον φάκελο υπάρχει ήδη αρχείο με όνομα «{name}». Το KnightLoader δεν το αντικαθιστά.`,"archive.unpackingAt":`Αποσυμπίεση {percent}`,"archive.unpacked":`Αποσυμπιέστηκε`,"archive.tally":`Αποσυμπιέστηκαν {done} από {total} αρχειοθέτες`,"columns.variant.convertTo":`Μετατροπή σε`,"settings.browsertools.desktopArchHint":`Τα Windows και το Linux έχουν δύο εκδόσεις το καθένα: x64 για τους περισσότερους υπολογιστές και ARM64 για υπολογιστές με επεξεργαστή ARM, όπως φορητούς με τσιπ Snapdragon. Αν το πρόγραμμα περιήγησης λέει ποιον επεξεργαστή έχει αυτός ο υπολογιστής, τα πλακίδια δίνουν την κατάλληλη έκδοση, αλλιώς την x64. Τα κουμπιά δίπλα δίνουν την άλλη. Η εφαρμογή για macOS τρέχει σε Intel και σε Apple silicon.`,"settings.resolvers.presetFormatsUnknown":`Το KnightLoader δεν ξέρει ακόμη ποιες μορφές προσφέρει το {host}, οπότε τα μενού τις προσφέρουν όλες. Μόλις ελεγχθεί ένας σύνδεσμος από το {host}, προσφέρουν τις μορφές που βρέθηκαν στους συνδέσμους που έχουν ελεγχθεί ως τώρα, και το μενού ήχου παραθέτει από κάτω τις άλλες στις οποίες μπορεί να γίνει μετατροπή.`,"settings.transfer.colArrives":`Υιοθετείται ως`,"settings.transfer.colArrivesHint":`Η έκδοση που έγραψε αυτό το αρχείο εννοούσε κάτι άλλο με αυτή την τιμή. Το KnightLoader την υιοθετεί όπως θα τη διάβαζε μια ενημέρωση.`,"rename.linkHint":`Το όνομα με το οποίο αποθηκεύεται το αρχείο. Μια λήψη που έχει ήδη τελειώσει μετονομάζεται και στον δίσκο, ώστε η λίστα και ο φάκελος να συμφωνούν. Ένα όνομα δεν είναι διαδρομή, οπότε τα / και \\ δεν επιτρέπονται.`,"rename.packageHint":`Αν ο φάκελος λήψεων έχει το όνομα του πακέτου, παίρνει κι αυτός το νέο όνομα, εφόσον τίποτα από το πακέτο δεν έχει αρχίσει να κατεβαίνει. Ένα όνομα δεν είναι διαδρομή, οπότε τα / και \\ δεν επιτρέπονται.`,"rename.keepsFolder":`Μέρος αυτού του πακέτου έχει ήδη κατέβει ή κατεβαίνει. Αν ο φάκελός του έχει το όνομα του πακέτου, ο φάκελος κρατά το όνομά του και μετονομάζεται μόνο το πακέτο.`,"quick.speedWindowHint":`Πόσο πίσω φτάνει η καμπύλη ταχύτητας στη γραμμή, από 10 δευτερόλεπτα έως μία ώρα. Μέχρι δύο λεπτά σχεδιάζει μία μέτρηση ανά δευτερόλεπτο, πέρα από αυτό μία κάθε δέκα δευτερόλεπτα.`,"settings.access.tokens.rights":`Δικαιώματα`,"settings.access.tokens.rightsHint":`Τι μπορεί να κάνει μια εφαρμογή με αυτό το διακριτικό. Η «Πλήρης πρόσβαση» μπορεί να κάνει τα πάντα, μαζί με τις ρυθμίσεις και τον κωδικό πρόσβασης. Για το Sonarr και το Radarr αρκεί η «Προσθήκη και ανάγνωση». Όταν αυτά καθαρίζουν μια ολοκληρωμένη λήψη, εκείνη μένει στη λίστα σου, εκτός αν το διακριτικό έχει και «Έλεγχο». Η «Μόνο ανάγνωση» βλέπει τις λήψεις σου και δεν αλλάζει τίποτα.`,"settings.access.tokens.preset.full":`Πλήρης πρόσβαση`,"settings.access.tokens.preset.addRead":`Προσθήκη και ανάγνωση`,"settings.access.tokens.preset.read":`Μόνο ανάγνωση`,"settings.access.tokens.preset.custom":`Προσαρμοσμένο`,"settings.access.tokens.scope.read":`Ανάγνωση`,"settings.access.tokens.scope.readHint":`Προβολή των λήψεων, της ουράς, του ιστορικού και των στατιστικών.`,"settings.access.tokens.scope.add":`Προσθήκη`,"settings.access.tokens.scope.addHint":`Προσθήκη συνδέσμων, torrents, αρχείων NZB και containers.`,"settings.access.tokens.scope.control":`Έλεγχος`,"settings.access.tokens.scope.controlHint":`Παύση, συνέχιση, αφαίρεση και αναδιάταξη λήψεων, καθώς και απάντηση σε captcha.`,"settings.access.tokens.scope.admin":`Διαχείριση`,"settings.access.tokens.scope.adminHint":`Αλλαγή ρυθμίσεων, λογαριασμών, διακριτικών και στιγμιότυπων, καθώς και ανάγνωση των αρχείων καταγραφής.`,"settings.modules.detail.downloadclientNoAddReadToken":`Κανένα διακριτικό API δεν μπορεί να προσθέτει και να διαβάζει, οπότε το Sonarr και το Radarr απορρίπτονται. Δημιούργησε ένα με «Προσθήκη και ανάγνωση» στη σελίδα Απομακρυσμένη πρόσβαση.`,"settings.modules.detail.downloadclientNoAddReadTokenNoSubfolders":`Κανένα διακριτικό API δεν μπορεί να προσθέτει και να διαβάζει, οπότε το Sonarr και το Radarr απορρίπτονται. Δημιούργησε ένα με «Προσθήκη και ανάγνωση» στη σελίδα Απομακρυσμένη πρόσβαση. Επιπλέον το «Κάθε πακέτο σε δικό του υποφάκελο» είναι ανενεργό, οπότε όλες οι λήψεις καταλήγουν σε έναν φάκελο και η εισαγωγή δεν μπορεί να τις ξεχωρίσει.`,"settings.modules.detail.metricsNoReadToken":`Αυτό το στιγμιότυπο έχει κωδικό πρόσβασης αλλά κανένα διακριτικό API που να μπορεί να διαβάζει, οπότε ένα σύστημα παρακολούθησης απορρίπτεται. Δημιούργησε ένα με «Μόνο ανάγνωση» στη σελίδα Απομακρυσμένη πρόσβαση.`,"settings.selftest.proxy.prefix.root":`Αυτό το στιγμιότυπο σερβίρεται στη ρίζα του {host}.`,"settings.selftest.proxy.prefix.mismatch":`Ο διαμεσολαβητής σου σερβίρει αυτό το στιγμιότυπο κάτω από {path}, αλλά το στιγμιότυπο είναι ρυθμισμένο για {base}.`,"settings.selftest.proxy.prefix.mismatchAdvice":`Αυτό το στιγμιότυπο βάζει τη διαδρομή του μπροστά από κάθε αρχείο και κάθε κλήση που ζητά η σελίδα, οπότε πρέπει να είναι η διαδρομή που χρησιμοποιεί ο διαμεσολαβητής σου. Όρισε το KL_BASE_PATH σε αυτή τη διαδρομή, ή άφησε το KL_BASE_PATH χωρίς τιμή και άφησε να αποφασίσει η κεφαλίδα X-Forwarded-Prefix του διαμεσολαβητή σου. Μετρά μόνο μια απλή διαδρομή, όπως /kl, και δεν μπορεί να ξεκινά με /api ή /relay.`,"settings.modules.detail.downloadclientReadyBoth":`Προσβάσιμο ως SABnzbd στο {sabnzbd} και ως qBittorrent στο {qbittorrent}. Στο Sonarr ή στο Radarr όρισε το URL Base σε «{sabnzbdBase}» ή «{qbittorrentBase}» και χρησιμοποίησε ένα από τα διακριτικά API αυτού του στιγμιότυπου ως API key ή ως κωδικό του qBittorrent.`,"captcha.unsolvableTurnstile":`Το KnightLoader δεν μπορεί να εμφανίσει μόνο του μια πρόκληση Cloudflare Turnstile, οπότε μόνο ένας επιλυτής από τις ρυθμίσεις Captcha μπορεί να την απαντήσει. Το «Άκυρο» παραλείπει αυτό το captcha.`,"captcha.solverWaiting":`Ένας επιλυτής αναλαμβάνει σε {time}.`,"captcha.solverWaitingHint":`Παρακολουθείς, οπότε οι επιλυτές περιμένουν πρώτα τη δική σου απάντηση. Αν φύγεις από αυτή την καρτέλα ή τελειώσει ο χρόνος, αναλαμβάνει ο πρώτος επιλυτής στη σειρά σου.`,"captcha.solverSolving":`Ο επιλυτής {solver} λύνει αυτό το captcha.`,"captcha.solverSolvingHint":`Μπορείς ακόμα να το απαντήσεις μόνος σου. Ισχύει η απάντηση που φτάνει πρώτη.`,"captcha.solverStopped":`Κανένας επιλυτής δεν μπόρεσε να αναλάβει αυτό το captcha.`,"captcha.solverUnsupported":`Ο επιλυτής {solver} δεν λύνει αυτό το είδος captcha.`,"captcha.solverRefused":`Ο επιλυτής {solver} αρνήθηκε: {reason}`,"settings.captcha.whenTitle":`Πότε ξεκινούν οι επιλυτές`,"settings.captcha.onlyUnwatched":`Μόνο όταν δεν κοιτάζει κανείς`,"settings.captcha.wait":`Αναμονή απάντησης (δευτερόλεπτα)`,"settings.captcha.waitHint":`Πόση ώρα περιμένουν οι επιλυτές, όσο κάποιος κοιτάζει, πριν αναλάβουν έτσι κι αλλιώς. Δεν περιμένουν ποτέ πάνω από τον μισό χρόνο που απομένει στο captcha, ώστε ένας επιλυτής να προλαβαίνει ακόμα να το απαντήσει. Από 10 έως 600 δευτερόλεπτα.`,"captcha.solverStoppedTaken":`Ο επιλυτής {solver} ανέλαβε αυτό το captcha, αλλά δεν έστειλε απάντηση.`,"captcha.solverNotPassedOn":`Ο επιλυτής {solver} μπορεί να το χρεώσει έτσι κι αλλιώς, γι’ αυτό το KnightLoader δεν το στέλνει και σε άλλον επιλυτή. Μπορείς ακόμα να το απαντήσεις μόνος σου.`,"captcha.solverNoAnswer":`Ο επιλυτής {solver} το ανέλαβε, αλλά δεν ήρθε απάντηση.`,"captcha.solverGaveUp":`Ο επιλυτής {solver} το ανέλαβε και μετά τα παράτησε: {reason}`,"captcha.solverFailed":`Ο επιλυτής {solver} δεν ήταν προσβάσιμος.`,"settings.captcha.onlyUnwatchedHint":`Ανενεργό: οι επιλυτές ξεκινούν μόλις φτάσει ένα captcha, ταυτόχρονα με το παράθυρο captcha. Ενεργό: όσο κάποιος κοιτάζει, έρχεται πρώτα το παράθυρο captcha και οι επιλυτές περιμένουν. Κάποιος κοιτάζει όσο μια καρτέλα περιηγητή με το KnightLoader είναι σε πρώτο πλάνο ή το παράθυρο της εφαρμογής επιφάνειας εργασίας είναι στην οθόνη, και όσο η εφαρμογή κινητού έχει αυτό το στιγμιότυπο ανοιχτό σε πρώτο πλάνο ή μια άλλη εφαρμογή διαβάζει συνεχώς τη λίστα captcha του. Μια καρτέλα στο παρασκήνιο και ένα παράθυρο ελαχιστοποιημένο ή στην περιοχή ειδοποιήσεων δεν μετράνε, και μια κλειστή σελίδα παύει να μετρά μετά από λίγα δευτερόλεπτα. Μόλις δεν κοιτάζει πια κανείς ή ο χρόνος παρακάτω τελειώσει χωρίς απάντηση, αναλαμβάνει ο πρώτος επιλυτής στη σειρά.`,"settings.accounts.freeTitle":`Δωρεάν λήψεις`,"settings.accounts.premiumOnly":`Μόνο Premium`,"settings.accounts.premiumOnlyHint":`Έναν σύνδεσμο hoster που δεν μπορεί να κατεβάσει κανένας από τους λογαριασμούς σου τον παίρνει ο JDownloader, που τον κατεβάζει δωρεάν: αργά, με αναμονές και captcha. Με ενεργό το «Μόνο Premium», ο σύνδεσμος περιμένει αντί γι’ αυτό στην ουρά και λέει γιατί· το ίδιο και μια δωρεάν λήψη που έβαλες σε παύση. Ξεκινά μόνος του μόλις προσθέσεις στοιχεία σύνδεσης για αυτόν τον hoster ή μια υπηρεσία debrid που τον υποστηρίζει. Μια κατηγορία μπορεί να το αποφασίσει αλλιώς για τους δικούς της συνδέσμους.`,"settings.categories.premiumOnly":`Μόνο Premium`,"settings.categories.premiumOnlyHint":`Αν ένας σύνδεσμος που μπαίνει εδώ και θα μπορούσε να κατέβει μόνο δωρεάν περιμένει αντί γι’ αυτό έναν λογαριασμό. Η «Κληρονόμηση» ακολουθεί τον διακόπτη «Μόνο Premium» στη σελίδα ρυθμίσεων Λογαριασμοί. Το «Ενεργό» κρατά πίσω τέτοιους συνδέσμους ακόμα κι όταν αυτός ο διακόπτης είναι ανενεργός. Το «Ανενεργό» αφήνει αυτή την κατηγορία να κατεβάζει δωρεάν ακόμα κι όταν εκείνος είναι ενεργός.`,"settings.hostRules.preferHint":`Ποιο backend παίρνει πρώτο τους συνδέσμους από αυτόν τον πάροχο. Το «Αυτόματα» κρατά τη σειρά προτεραιότητας της σελίδας Λογαριασμοί. Αν το backend που διαλέγεις δεν μπορεί να δεχτεί έναν σύνδεσμο, επειδή δεν υποστηρίζει αυτόν τον πάροχο ή ο λογαριασμός του δεν είναι διαθέσιμος αυτή τη στιγμή, ο σύνδεσμος συνεχίζει κανονικά προς τα κάτω στη σειρά προτεραιότητας. Δεν πηγαίνει ποτέ σε backend που απενεργοποίησες παρακάτω. Μια λήψη που καρφίτσωσες σε ένα backend στις ιδιότητές της μένει σε εκείνο το backend.`,"settings.hostRules.backends":`Backends για αυτόν τον πάροχο`,"settings.hostRules.backendsHint":`Οι σύνδεσμοι από αυτόν τον πάροχο δεν πηγαίνουν ποτέ σε backend που απενεργοποιείς εδώ, όπου κι αν βρίσκεται στη σειρά προτεραιότητας. Μια λήψη σε παύση που ξεκίνησε εκεί περνά στο επόμενο backend όταν τη συνεχίσεις και ξεκινά από την αρχή. Αν δεν μείνει κανένα backend που να μπορεί να δεχτεί έναν σύνδεσμο, ο σύνδεσμος αποτυγχάνει και λέει ότι αποκλείστηκε εδώ. Μια λήψη που καρφίτσωσες σε ένα backend στις ιδιότητές της πηγαίνει εκεί έτσι κι αλλιώς. Το backend που επιλέχθηκε παραπάνω δεν εμφανίζεται στη λίστα: αυτό ρωτιέται πρώτο.`,"task.waiting.premium":`Περιμένει λογαριασμό Premium`,"settings.downloads.keepAwake":`Να μένει ξύπνιος ο υπολογιστής κατά τη λήψη`,"settings.downloads.keepAwakeContainerHint":`Δεν υπάρχει σε αυτή την έκδοση. Μόνο η εφαρμογή επιφάνειας εργασίας μπορεί να κρατήσει έναν υπολογιστή ξύπνιο· το μηχάνημα όπου τρέχει ένα container αποφασίζει μόνο του πότε κοιμάται.`,"settings.modules.detail.eventprogramsOff":`Ανενεργό. Κανένα συμβάν δεν ξεκινά πρόγραμμα, και ένα πρόγραμμα που τρέχει ήδη ολοκληρώνεται.`,"settings.modules.detail.programsEnabled":`{n} ενεργά προγράμματα`,"settings.modules.detail.programsEnabledOne":`1 ενεργό πρόγραμμα`,"settings.module.eventprograms":`Προγράμματα συμβάντων`,"settings.eventPrograms.titleHint":`Δικά σου προγράμματα που ξεκινά αυτό το στιγμιότυπο όταν συμβαίνει κάτι, για παράδειγμα ένα σενάριο που τακτοποιεί μια ολοκληρωμένη λήψη. Το καθένα ξεκινά απευθείας, χωρίς κέλυφος, και παίρνει το συμβάν στα ορίσματά του και σε μεταβλητές περιβάλλοντος. Δεν τρέχει τίποτα μέχρι να ενεργοποιήσεις ένα πρόγραμμα.`,"settings.eventPrograms.add":`Προσθήκη προγράμματος`,"settings.eventPrograms.newName":`Πρόγραμμα {n}`,"settings.eventPrograms.empty":`Δεν υπάρχουν ακόμη προγράμματα.`,"settings.eventPrograms.emptyHint":`Πρόσθεσε ένα για να τρέχει ένα δικό σου σενάριο όταν ολοκληρώνεται μια λήψη, ένα πακέτο είναι πλήρες ή ένα συμπιεσμένο αρχείο έχει αποσυμπιεστεί.`,"settings.eventPrograms.remove":`Αφαίρεση`,"settings.eventPrograms.name":`Όνομα`,"settings.eventPrograms.nameHint":`Πώς λέγεται το πρόγραμμα σε αυτή τη λίστα και στην καταγραφή. Η καταγραφή δεν δείχνει ποτέ τη διαδρομή του προγράμματος ή τα ορίσματά του.`,"settings.eventPrograms.enabled":`Εκτέλεση αυτού του προγράμματος`,"settings.eventPrograms.enabledHint":`Ανενεργό για κάθε πρόγραμμα που προσθέτεις. Όσο είναι ανενεργό, η γραμμή κρατά ό,τι πληκτρολόγησες και δεν τρέχει τίποτα.`,"settings.eventPrograms.program":`Πρόγραμμα`,"settings.eventPrograms.programHint":`Η πλήρης διαδρομή του προγράμματος ή του σεναρίου. Ξεκινά απευθείας, όχι μέσω κελύφους. Αν θέλεις κέλυφος, γράψε εδώ το ίδιο το κέλυφος, για παράδειγμα /bin/sh, και βάλε τη γραμμή εντολών σου στα ορίσματα. Μετά την αποθήκευση, το πρόγραμμα και τα ορίσματά του δεν εμφανίζονται ξανά εδώ, όπως και η εντολή στο τέλος της ουράς, γιατί ένα όρισμα μπορεί να περιέχει διακριτικό.`,"settings.eventPrograms.args":`Ορίσματα`,"settings.eventPrograms.placeholdersHint":`Ονόματα που μπορείς να γράψεις στα ορίσματα, με δύο σύμβολα τοις εκατό σε κάθε πλευρά. Τα πρώτα πέντε έχουν τις ίδιες τιμές με τις μεταβλητές περιβάλλοντος παρακάτω. Τα υπόλοιπα είναι αυτά που χρησιμοποιούν οι προορισμοί συμβάντων.`,"settings.eventPrograms.env":`Μεταβλητές περιβάλλοντος`,"settings.eventPrograms.eventsHint":`Ποια συμβάντα ξεκινούν αυτό το πρόγραμμα. Στην αρχή δεν είναι τσεκαρισμένο τίποτα.`,"settings.eventPrograms.eventsBurst":`Η προσθήκη ενός συνδέσμου ξεκινά αυτό το πρόγραμμα μία φορά ανά σύνδεσμο, οπότε διακόσιοι επικολλημένοι σύνδεσμοι το τρέχουν διακόσιες φορές. Ό,τι δεν χωράει στην ουρά απορρίπτεται και μετριέται παρακάτω.`,"settings.eventPrograms.eventsNone":`Δεν είναι τσεκαρισμένο τίποτα, αυτό το πρόγραμμα λοιπόν δεν τρέχει ποτέ.`,"settings.eventPrograms.timeout":`Διακοπή μετά από (δευτερόλεπτα)`,"settings.eventPrograms.parallel":`Ταυτόχρονα`,"settings.eventPrograms.parallelHint":`Πόσες εκτελέσεις αυτού του προγράμματος μπορούν να γίνονται ταυτόχρονα, από 1 έως 4. Με 1, κάθε συμβάν περιμένει την προηγούμενη εκτέλεση, οπότε το πρόγραμμα βλέπει τα συμβάντα με τη σειρά που συνέβησαν.`,"settings.eventPrograms.status":`Κατάσταση`,"settings.eventPrograms.statusHint":`Τι έχει δει ο διακομιστής από την εκκίνησή του. Τίποτα από αυτά δεν αποθηκεύεται στον δίσκο. Αν τα συμβάντα φτάνουν πιο γρήγορα απ’ ό,τι τα χειρίζεται το πρόγραμμα, ό,τι ξεπερνά τα 256 σε αναμονή απορρίπτεται και μετριέται εδώ.`,"settings.eventPrograms.statusUnknown":`Δεν έχει τρέξει τίποτα από την εκκίνηση του διακομιστή. Αυτό δεν σημαίνει ότι δεν έτρεξε ποτέ τίποτα.`,"settings.eventPrograms.checkOk":`Το πρόγραμμα βρέθηκε.`,"settings.eventPrograms.lastRun":`Τελευταία εκτέλεση {when}, στο συμβάν «{event}».`,"settings.eventPrograms.lastRunOk":`Τελείωσε κανονικά μετά από {duration}.`,"settings.eventPrograms.output":`Έξοδος: {output}`,"settings.eventPrograms.runCount":`{n} εκτελέσεις από την εκκίνηση του διακομιστή, {failed} από αυτές απέτυχαν.`,"settings.eventPrograms.dropped":`{n} συμβάντα απορρίφθηκαν επειδή υπήρχαν πάρα πολλά σε αναμονή.`,"settings.downloads.keepAwakeHint":`Όσο τρέχει μια λήψη, και όσο μετά ελέγχεται, αποσυμπιέζεται, μετακινείται ή παραδίδεται σε ένα πρόγραμμα συμβάντων, ο υπολογιστής δεν πέφτει σε αναστολή. Μετρά και μια λήψη που περιμένει την επόμενη προσπάθειά της. Η οθόνη μπορεί πάντως να σβήσει. Μόλις τελειώσουν όλα αυτά, ο υπολογιστής πέφτει ξανά σε αναστολή κανονικά.`,"settings.transfer.incompleteEventPrograms":`οι γραμμές εντολών των προγραμμάτων συμβάντων`,"settings.eventPrograms.argsHint":`Ένα ανά γραμμή. Κάθε γραμμή φτάνει στο πρόγραμμα ως ένα όρισμα με συμπληρωμένα τα σύμβολα κράτησης θέσης, και κανένα κέλυφος δεν τη διαβάζει: ένα όνομα αρχείου που περιέχει $( ) ή ; φτάνει ακριβώς με αυτούς τους χαρακτήρες. Ένα αρχείο .bat ή .cmd παίρνει κάθε όρισμα σε εισαγωγικά, οπότε εκεί διάβασέ το ως "%~1". Αν το πρόγραμμα είναι κέλυφος, χρησιμοποίησε τις μεταβλητές περιβάλλοντος αντί για σύμβολα κράτησης θέσης, σε διπλά εισαγωγικά, όπως "$KL_FILE", ώστε το κέλυφος να μη διαβάσει ένα όνομα αρχείου ως εντολή.`,"settings.eventPrograms.envHint":`Κάθε εκτέλεση τις παίρνει, κενές όπου το συμβάν δεν έχει κάτι γι’ αυτές. Το KL_FILE είναι το αρχείο της λήψης και το KL_FOLDER ο φάκελος όπου βρίσκεται. Για ένα ολοκληρωμένο πακέτο, το KL_FOLDER είναι ο φάκελος όπου πήγαν τα περισσότερα αρχεία του· για ένα αποσυμπιεσμένο αρχείο, ο φάκελος όπου αποσυμπιέστηκε. Μια αποτυχημένη αποσυμπίεση ξεκινά κι αυτή το πρόγραμμα, με το KL_EXTRACT_OK σε false. Αν χρησιμοποιείς φάκελο εργασίας, μια ολοκληρωμένη λήψη ή ένα πακέτο περιμένει μέχρι να μετακινηθούν τα αρχεία του από εκεί, το πολύ 15 λεπτά. Οι δικές ρυθμίσεις KL_ αυτού του στιγμιότυπου, μαζί με τα κλειδιά υπηρεσιών, δεν μεταβιβάζονται ποτέ.`,"settings.eventPrograms.timeoutHint":`Πόσο μπορεί να διαρκέσει μία εκτέλεση πριν σταματήσει, από 5 έως 3600 δευτερόλεπτα. Ό,τι ξεκίνησε το πρόγραμμα σταματά μαζί του.`,"settings.eventPrograms.runCountOne":`1 εκτέλεση από την εκκίνηση του διακομιστή.`,"settings.eventPrograms.droppedOne":`1 συμβάν απορρίφθηκε επειδή υπήρχαν πάρα πολλά σε αναμονή.`,"settings.torrents.filesTitle":`Επιλογή αρχείων`,"settings.torrents.minFileSize":`Ελάχιστο μέγεθος αρχείου`,"settings.torrents.minFileSizeHint":`Τα μικρότερα αρχεία παραλείπονται, όπως αρχεία .nfo και σύντομα δείγματα. 0 = χωρίς ελάχιστο.`,"settings.torrents.includeFiles":`Μόνο αυτά τα αρχεία`,"settings.torrents.includeFilesHint":`Μία κανονική έκφραση ανά γραμμή, που συγκρίνεται με τη διαδρομή του αρχείου μέσα στο torrent, όπως το «ταιριάζει σε μοτίβο» σε έναν κανόνα Packagizer. Ένα αρχείο πρέπει να ταιριάζει σε μία από αυτές για να κατέβει. Τα πεζά και τα κεφαλαία μετράνε· ξεκίνα ένα μοτίβο με (?i) για να αγνοούνται.`,"settings.torrents.excludeFiles":`Ποτέ αυτά τα αρχεία`,"settings.torrents.excludeFilesHint":`Μία κανονική έκφραση ανά γραμμή, που συγκρίνεται όπως στο πλαίσιο δίπλα. Ένα αρχείο που ταιριάζει παραλείπεται, για παράδειγμα (?i)sample ή \\.(nfo|exe)$.`,"settings.torrents.trackersTitle":`Trackers`,"settings.torrents.extraTrackers":`Επιπλέον trackers`,"settings.torrents.trackerList":`Λίστα trackers`,"settings.torrents.trackerListHint":`Η διεύθυνση μιας δημόσιας λίστας με έναν tracker ανά γραμμή, όπως το trackers_best.txt του ngosang. Ανακτάται το πολύ μία φορά τη μέρα και οι trackers της προστίθενται όπως οι παραπάνω. Αν μια ανάκτηση αποτύχει, παραμένει σε χρήση η λίστα από την τελευταία επιτυχημένη ανάκτηση.`,"settings.torrents.trackerListFetched":`{n} trackers, ανακτήθηκαν {when}`,"settings.torrents.trackerListFetching":`Ανάκτηση της λίστας…`,"settings.torrents.trackerListPending":`Δεν έχει ανακτηθεί ακόμη.`,"settings.torrents.trackerListFailed":`Η τελευταία ανάκτηση απέτυχε: {error}`,"settings.torrents.bannedTrackers":`Αποκλεισμένοι trackers`,"collector.toastStartHeld":`{n} σύνδεσμοι κρατούνται πίσω και δεν ξεκίνησαν.`,"torrent.held":`Το {file} κρατήθηκε πίσω: {reason}`,"collector.filtered.heldSummary":`{n} σύνδεσμοι κρατήθηκαν πίσω`,"collector.filtered.heldInfo":`Σύνδεσμοι που απέρριψε ένας κανόνας του φίλτρου συνδέσμων, και torrents που δηλώνονται σε αποκλεισμένο tracker. Κρατιούνται εδώ και όχι στη λίστα παραπάνω, ώστε με ένα φίλτρο που δουλεύει ο συλλέκτης να μη φαίνεται γεμάτος σκουπίδια. Δεν χάθηκε τίποτα. Η «Επαναφορά» βάζει έναν σύνδεσμο πίσω και τον αφήνει να περάσει τον κανόνα ή τον αποκλεισμό που τον σταμάτησε, για όταν αυτός αποδείχθηκε πολύ πλατύς. Το «Καθάρισμα» τον διαγράφει. Έτσι κι αλλιώς, δεν έχει κατέβει κανένα αρχείο.`,"collector.filtered.toastHeldBack":`Ετοιμάστηκαν {n} σύνδεσμοι· {held} κρατήθηκαν πίσω`,"collector.filtered.toastAllHeldBack":`Δεν ετοιμάστηκε τίποτα: {held} σύνδεσμοι κρατήθηκαν πίσω`,"settings.torrents.filesHint":`Διαλέγει ποια αρχεία ενός torrent κατεβαίνουν όταν δεν τα διάλεξε κανείς με το χέρι. Για έναν σύνδεσμο magnet αυτό γίνεται μόλις φτάσει η λίστα αρχείων του. Ένα .torrent ανοίγει τη λίστα αρχείων του με αυτή την επιλογή ήδη τσεκαρισμένη, και ισχύει αν προσθέσεις το torrent χωρίς να την αλλάξεις. Ό,τι τσεκάρεις ή ξετσεκάρεις εσύ κερδίζει πάντα. Αν δεν έμενε τίποτα, κατεβαίνουν όλα τα αρχεία. Μια κατηγορία μπορεί να έχει αντί γι’ αυτό δική της επιλογή αρχείων.`,"settings.torrents.extraTrackersHint":`Μία διεύθυνση tracker ανά γραμμή, που προστίθεται στα torrents ώστε να βρίσκουν περισσότερους ομότιμους. Ένα .torrent σημειωμένο ως ιδιωτικό δεν τους παίρνει ποτέ. Ένας σύνδεσμος magnet λέει αν είναι ιδιωτικός μόνο όταν φτάσει η λίστα αρχείων του, και τότε οι trackers έχουν ήδη προστεθεί, οπότε ούτε ένα magnet του οποίου η δική του διεύθυνση tracker περιέχει passkey δεν παίρνει κανέναν. Ένας ιδιωτικός tracker που σε αναγνωρίζει από τη διεύθυνση IP σου και όχι από passkey δεν εντοπίζεται έτσι: άφησε αυτό το πεδίο κενό αν παίρνεις συνδέσμους magnet από τέτοιον.`,"settings.torrents.bannedTrackersHint":`Ένα όνομα host ή μια διεύθυνση tracker ανά γραμμή· μετράνε και οι υποτομείς του. Ένα torrent που δηλώνεται σε έναν από αυτούς δεν προστίθεται: ο συλλέκτης το κρατά πίσω με τον λόγο, όπως έναν σύνδεσμο που απορρίπτει το φίλτρο συνδέσμων. Αν το επαναφέρεις εκεί, περνά τη γραμμή που το σταμάτησε, όχι όμως μια γραμμή που θα προσθέσεις αργότερα. Ένας αποκλεισμένος tracker δεν προστίθεται επίσης ποτέ ως επιπλέον tracker.`,"detail.heldBecause":`Λόγος κράτησης`,"settings.categories.torrentFiles":`Επιλογή αρχείων torrent`,"settings.categories.torrentFilesHint":`Ποια αρχεία ενός torrent που μπαίνει εδώ κατεβαίνουν όταν δεν τα τσέκαρε κανείς με το χέρι. Η «Κληρονόμηση» χρησιμοποιεί την επιλογή αρχείων της σελίδας Torrents. Η «Δική της» την αντικαθιστά για αυτή την κατηγορία, για παράδειγμα σε μια κατηγορία μουσικής όπου τα μικρά αρχεία είναι το ίδιο το άλμπουμ. Ισχύει όταν ξεκινά το torrent, οπότε καλύπτει και ένα torrent που έβαλε εδώ ένας κανόνας Packagizer. Τα αρχεία που τσεκάρεις εσύ κερδίζουν πάντα.`,"settings.categories.torrentFilesOwn":`Δική της`,"settings.watchDirFilesHint":`Τα αρχεία που αφήνονται εδώ παραλαμβάνονται αυτόματα: λίστες συνδέσμων (.txt, .crawljob, .magnet), αρχεία .torrent, containers (.dlc, .ccf, .rsdf) και αρχεία .nzb.`,"container.usenet":`Το {file} πήγε στο {service}. Τα αρχεία του εμφανίζονται εδώ μόλις το {service} τα φέρει από το Usenet.`,"settings.help.intake.watchFiles":`Ένας παρακολουθούμενος φάκελος παραλαμβάνει ό,τι αφήνεται μέσα του: λίστες συνδέσμων (.txt, .crawljob, .magnet), αρχεία .torrent, containers (.dlc, .ccf, .rsdf) και αρχεία .nzb.`,"container.nzbTooBig":`είναι μεγαλύτερο από {max}, το μέγιστο που επιτρέπεται για ένα .nzb`,"container.noUsenet":`είναι .nzb, και αυτά τα φέρνει από το Usenet ένας λογαριασμός TorBox ή Premiumize.me. Κανένας από τους λογαριασμούς σου δεν μπορεί να το κάνει: πρόσθεσε έναν στους Λογαριασμούς.`,"activity.usenet":`Usenet`,"settings.help.intake.nzb":`An .nzb, uploaded here or sent by Sonarr or Radarr, goes to your TorBox or Premiumize.me account, which fetches it from Usenet. Its files then download like any other link. TorBox takes .nzb files only on plans that include Usenet. KnightLoader finds out when TorBox turns down the first one, and that .nzb fails unless a Premiumize.me account takes it.`,"task.remote":`Λήψη στο {service}`,"task.remoteSeeds":`Seeds: {n}`,"accounts.routing.orderHintTorrents":`Οι σύνδεσμοι magnet και τα αρχεία .torrent πηγαίνουν είτε στο «Torrent και magnet», τον ενσωματωμένο πελάτη, είτε σε μια υπηρεσία debrid που δέχεται torrents, ανάλογα με το ποιο βρίσκεται ψηλότερα στη λίστα.`,"accounts.routing.tip.torrent":`Ο ενσωματωμένος πελάτης torrent. Αν μια υπηρεσία debrid που δέχεται torrents βρίσκεται πάνω από αυτή τη γραμμή, τους συνδέσμους magnet και τα αρχεία .torrent τα κατεβάζει εκείνη αντί γι’ αυτόν.`,"settings.torrents.debridTitle":`Μέσω υπηρεσίας debrid`,"settings.torrents.debridHint":`Τα TorBox, Real-Debrid, AllDebrid, Premiumize.me και Debrid-Link μπορούν να κατεβάζουν συνδέσμους magnet και αρχεία .torrent αντί για τον ενσωματωμένο πελάτη. Η υπηρεσία κατεβάζει το torrent στους δικούς της διακομιστές και το KnightLoader φέρνει μετά τα αρχεία από εκεί όπως κάθε άλλο σύνδεσμο. Από αυτό το μηχάνημα δεν γίνεται καθόλου seeding και η διεύθυνσή σου δεν εμφανίζεται ποτέ σε σμήνος, οπότε δεν χρειάζεται ανοιχτή θύρα. Ένα torrent που έχει ήδη η υπηρεσία είναι έτοιμο αμέσως. Η σειρά προτεραιότητας στη σελίδα Λογαριασμοί αποφασίζει αν πρώτα έρχεται μια υπηρεσία debrid ή ο ενσωματωμένος πελάτης. Ένα torrent από ιδιωτικό tracker μένει πάντα στον ενσωματωμένο πελάτη. Η επιλογή αρχείων αυτής της σελίδας ισχύει και εδώ: τα Real-Debrid και Debrid-Link κατεβάζουν μόνο αυτά τα αρχεία, και από τις άλλες υπηρεσίες έρχονται εδώ μόνο αυτά.`,"accounts.col.import":`Εισαγωγή`,"task.remoteHint":`Το {service} το κατεβάζει στους δικούς του διακομιστές και έχει μέχρι στιγμής {percent}. Τα αρχεία έρχονται εδώ μόλις τα έχει όλα.`,"settings.modules.detail.torrentsOffDebrid":`Ανενεργό. Τα torrents που τρέχουν συνεχίζουν και κάνουν seeding κανονικά. Τα νέα πηγαίνουν σε μια υπηρεσία debrid που δέχεται torrents.`,"collector.filtered.origin.account":`λογαριασμός debrid`,"accounts.importAccount":`Εισαγωγή από {account}`,"accounts.importHint":`Το KnightLoader διαβάζει τη λίστα της υπηρεσίας μία φορά το λεπτό και φέρνει ό,τι προστέθηκε εκεί από τη στιγμή που το ενεργοποίησες: torrents, και από τα TorBox και Premiumize.me επίσης λήψεις web και Usenet. Καταλήγουν στον συλλέκτη συνδέσμων όπως κάθε άλλος σύνδεσμος και κατεβαίνουν μέσω αυτού του λογαριασμού. Ό,τι πρόσθεσε το ίδιο το KnightLoader δεν έρχεται εδώ. Η υπηρεσία δεν λέει ποιος πρόσθεσε μια λήψη, οπότε έρχεται και ό,τι προσθέτει μια άλλη εφαρμογή με τον ίδιο λογαριασμό. Άφησέ το ανενεργό για λογαριασμό που χρησιμοποιεί επίσης το rdt-client ή ένα δεύτερο KnightLoader. Μόλις τα αρχεία μιας λήψης βρεθούν εδώ ή όταν την αφαιρέσεις εδώ, η λήψη διαγράφεται στην υπηρεσία, εκτός αν στις Ρυθμίσεις, Torrents έχεις ορίσει να μένουν εκεί οι λήψεις. Μια παύλα σημαίνει ότι η υπηρεσία δεν έχει λίστα που μπορεί να διαβάσει το KnightLoader.`,"settings.torrents.keepOnService":`Διατήρηση λήψεων στην υπηρεσία debrid`,"settings.torrents.keepOnServiceHint":`Όταν αυτό είναι ανενεργό, το KnightLoader διαγράφει ένα torrent από την υπηρεσία debrid μόλις βρεθούν εδώ όλα τα αρχεία του, και κάνει το ίδιο με μια λήψη που εισήχθη από τον λογαριασμό, ώστε να μη συσσωρεύεται τίποτα εκεί και να μην εξαντλούνται τα όρια του λογαριασμού. Αν αφαιρέσεις εδώ μια εισαγμένη λήψη πριν ολοκληρωθεί, διαγράφεται και εκεί. Όταν είναι ενεργό, μένουν και τα δύο στην υπηρεσία, για παράδειγμα για να τα κάνεις stream από εκεί αργότερα. Ένα torrent που πρόσθεσε το KnightLoader διαγράφεται σε κάθε περίπτωση αν το αφαιρέσεις πριν ολοκληρωθεί, ενώ ένα που είχε ήδη ο λογαριασμός δεν διαγράφεται ποτέ.`};export{e as el};